    // The handle owns secrets (seed + DB key, inside OpenWallet) — pinned
    // non-Clone/non-Debug at compile time so a host can never duplicate or log a
    // live wallet handle.
    static_assertions::assert_not_impl_any!(Wallet: Clone, std::fmt::Debug);
    // Shareable across async tasks (the host requirement).
    static_assertions::assert_impl_all!(Wallet: Send, Sync);

    use crate::checkpoints;

    /// No-op progress reporter for the `sync_once` tests asserting cancel / fault /
    /// completion behavior; the dedicated progress test uses a recording reporter.
    const NOOP_PROGRESS: &(dyn Fn(sync::ScanProgress) + Sync) = &|_: sync::ScanProgress| {};

    /// Multi-batch fixture geometry (the batch size shrank 1_000 → 100, so
    /// these tests derive their chain from the constant instead of hardcoding the
    /// old 1_000-block boundaries): birthday-anchored base + exactly one full
    /// batch + 1 extra block ⇒ ALWAYS two batches, whatever the batch size.
    const FIX_BASE: u32 = 280_000;
    const FIX_TIP: u32 = FIX_BASE + crate::constants::SYNC_BATCH_BLOCKS;

    fn test_vault() -> Arc<dyn KeychainPort> {
        Arc::new(TestVault::new(VaultTier::Tee))
    }

    fn cfg(
        db_dir: &std::path::Path,
        network: Network,
        persistence: SeedPersistence,
    ) -> WalletConfig {
        WalletConfig {
            db_dir: db_dir.to_path_buf(),
            network,
            endpoint: LightServerEndpoint::new("https://zec.rocks:443").expect("endpoint"),
            endpoint_auth: None,
            tor: TorPolicy::Off,
            seed_persistence: persistence,
            birthday: None,
            broadcast_jitter: JitterPolicy::None,
            // FR-27 is opt-in: the default test wallet has NO read scope, so
            // every existing test also asserts the verb stays closed by default.
            machine_memo_prefixes: Vec::new(),
            // P3-13: no offered list — the default plus a custom entry.
            sync_servers: Vec::new(),
        }
    }

    fn raw_seed() -> SeedSource {
        SeedSource::raw_bytes(Zeroizing::new(vec![0x24; 32]).to_vec()).expect("valid seed")
    }

    // The implementer's drive of the `TorState` stream on a real handle (stage
    // S1 `truth`): a child module so it can use the fixtures above, in its own
    // file (`src/wallet/tests/truth_probes.rs`, where an inline module's child
