    #[tokio::test]
    #[cfg(feature = "swap")]
    async fn host_custody_lapsed_zombie_deposit_purges_at_the_drain_and_frees_the_guard() {
        // THE review-BLOCKER chain, end-to-end on the exact tier it bricked. A host-custody
        // deposit whose at-execute sign missed (nothing staged) sits `Queued`; its deadline
        // lapses; pre-fold NO background pass could ever delete it (Phase 2 pulls the seed
        // BEFORE `prepare_queued`'s gate — `SeedRequired` first, every pass) — and the
        // one-deposit-in-flight guard then refused every future swap FOREVER, with no user
        // remedy (deposits are excluded from cancel). The seedless Phase-1.5 purge is the
        // fix: deadline + clock decide, no seed needed, so the guard's "self-clears with
        // the quote lifetime" claim is true at EVERY custody tier.
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let w = create_none_then_reopen_with_port(
            dir.path(),
            &vault,
            FR12_SENTINEL_SEED,
            Some(Arc::new(crate::seed::testing::UnavailableSeedPort) as Arc<dyn WalletSeedPort>),
        )
        .await;
        let amount = Zatoshis::new(250_000).expect("amount");

        // The zombie: an ALREADY-LAPSED deadline (plausible clock, Nov 2023) — the sign-half
        // fails at `acquire_seed` BEFORE any gate could run, so the row lands `Queued` with a
        // dead deadline (the pre-fold forever-state).
        w.send_deposit_now(transparent_test_addr(), amount, 1_700_000_100, None)
            .await
            .expect("durable-first: Ok, the deposit stays Queued (sign missed, gate unreached)");
        assert_eq!(
            {
                let g = w.inner.aux_db.lock().expect("aux db");
                crate::intent_store::list_queued(&g).expect("list").len()
            },
            1,
            "the zombie is durably Queued",
        );

        // The guard is armed by the zombie: a NEW swap (live deadline) is refused.
        let err = w
            .send_deposit_now(transparent_test_addr(), amount, 1_900_000_000, None)
            .await
            .expect_err("the zombie holds the one-deposit-in-flight guard");
        assert!(matches!(err, WalletError::SwapDepositInFlight));

        // ONE background pass — no seed staged, no signing capability exercised — purges it.
        let summary = w
            .resubmit_queued_sends(&sync::CancelToken::new())
            .await
            .expect("the drain runs seedlessly");
        assert_eq!(
            summary.deposit_expired, 1,
            "the lapsed zombie is purged by Phase 1.5 (counted deposit_expired)",
        );
        assert!(
            {
                let g = w.inner.aux_db.lock().expect("aux db");
                crate::intent_store::list_queued(&g)
                    .expect("list")
                    .is_empty()
            },
            "the zombie row is gone",
        );

        // And the guard is FREED: the next swap's deposit enqueues normally.
        w.send_deposit_now(transparent_test_addr(), amount, 1_900_000_000, None)
            .await
            .expect("a new deposit enqueues once the zombie is purged — swap un-bricked");
        w.close().await.expect("close");
    }

    #[tokio::test]
    async fn resubmit_broadcast_phase_holds_a_deposit_that_lapsed_mid_pass() {
        // §4.4 deferred-broadcast rule 3 (W-swap-4-a-3): the Phase-1/2 gates judge the
        // PASS-START clock, but the network send happens at END of pass — after unbounded
        // proving and behind earlier groups in the budget queue — so a deposit that was
        // live at pass start can be dead at the send moment. The phase re-gates on a
        // fresh per-group clock (frozen here via the test seam: a mid-pass lapse cannot
        // be staged against the real clock inside one test-speed pass): the lapsed group
        // is HELD (counted `deposit_held`, its bytes never reach the broadcast
        // machinery), a still-live deposit proceeds.
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let w = Wallet::create_with_vault(
            cfg(dir.path(), Network::Test, SeedPersistence::SealedKeychain),
            raw_seed(),
            Arc::clone(&vault),
        )
        .await
        .expect("create");

        let mut summary = ResubmitSummary::default();
        let cancel = sync::CancelToken::new();
        w.broadcast_outbound(
            vec![
                // Lapsed at broadcast time (deadline ≤ frozen now + margin): held — the
                // garbage tx bytes prove nothing downstream ever touches them.
                OutboundGroup::starting(vec![vec![0xAA; 16]], Some(1_800_000_000)),
                // LIVE control (empty group): the gate proceeds; zero txs to attempt.
                OutboundGroup::starting(Vec::new(), Some(1_900_000_000)),
            ],
            &mut summary,
            &cancel,
            Some(1_850_000_000), // frozen broadcast clock: past the first, before the second
        )
        .await;
        assert_eq!(
            summary.deposit_held, 1,
            "the mid-pass-lapsed deposit is held, the live one proceeds",
        );
        assert_eq!(
            summary.attempted, 0,
            "the held group's bytes never reached the broadcast machinery",
        );
        w.close().await.expect("close");
    }

    #[tokio::test]
    async fn the_drain_carries_continues_into_the_broadcast_phase() {
        // F01 (plan §2.3 items 3-4; the crypto audit's MEDIUM on the built diff): the rule-3
        // re-gate and the per-leg check must read the group's `continues`, or an accepted-but-
        // unmined tx0 is held as a START 150 s before the deadline and the deposit strands. A
        // continuing group passes the gate and reaches the broadcast machinery (the test
        // endpoint is unreachable, so it counts as attempted, not accepted); the SAME group
        // as a start is held. One clock (the seam) governs both gates.
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let mut config = cfg(dir.path(), Network::Test, SeedPersistence::SealedKeychain);
        config.broadcast_jitter = JitterPolicy::None;
        let w = Wallet::create_with_vault(config, raw_seed(), Arc::clone(&vault))
            .await
            .expect("create");
        let deadline = 1_900_000_000_i64;
        let now = Some((deadline - 150) as u64);
        let cancel = sync::CancelToken::new();

        let mut summary = ResubmitSummary::default();
        w.broadcast_outbound(
            vec![OutboundGroup {
                txs: vec![vec![0xAA; 16]],
                deposit_deadline: Some(deadline),
                continues: vec![true],
            }],
            &mut summary,
            &cancel,
            now,
        )
        .await;
        assert_eq!(
            (summary.deposit_held, summary.attempted),
            (0, 1),
            "a continuing leg inside the start margin goes out"
        );

        let mut summary = ResubmitSummary::default();
        w.broadcast_outbound(
            vec![OutboundGroup::starting(
                vec![vec![0xAA; 16]],
                Some(deadline),
            )],
            &mut summary,
            &cancel,
            now,
        )
        .await;
        assert_eq!(
            (summary.deposit_held, summary.attempted),
            (1, 0),
            "the same leg as a start is held"
        );
        w.close().await.expect("close");
    }

