    #[test]
    fn deadline_first_orders_tagged_groups_before_untagged_preserving_fifo() {
        // W-swap-4-a-4: the broadcast queue serves deadline-tagged deposit groups first
        // (earliest deadline first) and preserves FIFO within each class — the stable
        // sort's whole contract. Groups are distinguished by their (garbage) bytes.
        let mut outbound: Vec<OutboundGroup> = vec![
            OutboundGroup::starting(vec![vec![1]], None),
            OutboundGroup::starting(vec![vec![2]], Some(2_000_000_000)),
            OutboundGroup::starting(vec![vec![3]], None),
            OutboundGroup::starting(vec![vec![4]], Some(1_900_000_000)),
            OutboundGroup::starting(vec![vec![5]], None),
            OutboundGroup::starting(vec![vec![6]], Some(1_900_000_000)), // equal tag: FIFO after group 4
        ];
        order_deadline_first(&mut outbound);
        let order: Vec<u8> = outbound.iter().map(|g| g.txs[0][0]).collect();
        assert_eq!(
            order,
            vec![4, 6, 2, 1, 3, 5],
            "earliest deadlines first (FIFO on ties), untagged last in FIFO order",
        );
    }

