    // ── inc-2d-ffi: the send-from-URI bridge lowering (propose_uri / queue_send_uri /
    // send_by_id) ──────────────────────────────────────────────────────────────────────
    //
    // These wrap the BUILT propose/queue_send/send by lowering the host's ZIP-321 URI (the
    // §2.4 lossless token) with the wallet's OWN network — the FFI entry points (the bridge
    // passes the URI/id raw). The faithful-lowering + error-routing gates (network authority,
    // malformed, oversize, donation-form, teardown ordering, token-by-id consume) are proven
    // here on a REAL handle; the funded propose→sign→broadcast stays E2E-owed (the
    // `data_api::testing` harness funds only a `LocalNetwork` DB).

    async fn ffi_wallet(dir: &std::path::Path, network: Network) -> Wallet {
        let w = Wallet::create_with_vault(
            cfg(dir, network, SeedPersistence::SealedKeychain),
            raw_seed(),
            test_vault(),
        )
        .await
        .expect("create");
        // The §3.2 consensus gate is upstream of every FFI-surface gate these
        // tests assert; a hand-built wallet has never run a pass.
        w.seed_current_consensus_for_test();
        w
    }

    /// PROBE: a fresh restore against an HONEST endpoint must
    /// not be refused. Spend-before-sync depends on it, and a false refusal here
    /// would be the mirror image of the outage — the wallet lying in the other
    /// direction.
    #[tokio::test]
    async fn a_fresh_wallet_against_an_honest_endpoint_is_not_refused() {
        use crate::sync::testing::FakeChain;
        let dir = tempfile::tempdir().expect("tempdir");
        let w = ffi_wallet(dir.path(), Network::Test).await;
        {
            let aux = w.inner.aux_db.lock().expect("aux");
            aux.execute("DELETE FROM consensus_verdict", [])
                .expect("clear");
        }
        // Honest endpoint, real tip. This wallet has scanned nothing yet.
        let mut honest = FakeChain::to_tip(281_000);
        w.evaluate_consensus(&mut honest).await.expect("evaluate");

        let verdict = w
            .consensus_status()
            .await
            .expect("status")
            .verdict
            .expect("a verdict was recorded");
        assert!(
            verdict.permits_signing(),
            "an honest endpoint must not make a fresh wallet unsendable, got {verdict:?}"
        );
        w.close().await.expect("close");
    }

    /// INC-008 (`evals/incidents.tsv`) — the grace anchor is CLAMPED.
    ///
    /// The anchor is the endpoint's claimed tip at the last signing-capable
    /// verdict, and the row survives a rescan. Unclamped, an endpoint reporting
    /// `block_height = u64::MAX` earns `Behind` (its branch matches ours at any
    /// height past Nu6_2), pinning the anchor at `u32::MAX` forever — after
    /// which every `Unknown` computes a grace distance of zero and signs
    /// indefinitely. §6.3 claims no reading of that field buys an adversary
    /// more time; this is what makes that true.
    ///
    /// The fix shipped WITHOUT this test. The incident registry
    /// (`evals/check.py`) is what noticed the gap.
    #[tokio::test]
    async fn a_hostile_block_height_cannot_pin_the_grace_anchor() {
        use crate::sync::testing::FakeChain;
        let dir = tempfile::tempdir().expect("tempdir");
        let w = ffi_wallet(dir.path(), Network::Test).await;

        // An endpoint claiming an absurd tip. Its self-reported branch is
        // whatever our params compute at that height, so it is internally
        // consistent — the shape that would earn `Behind` and write the anchor
        // if the tip were believed.
        let mut liar = FakeChain::to_tip(u64::MAX);
        w.evaluate_consensus(&mut liar)
            .await
            .expect("the verdict is recorded");

        let snap = w.consensus_status().await.expect("status");
        // THE INVARIANT: whatever verdict this produced, the endpoint cannot
        // have written itself an unbounded grace anchor. Either no anchor (the
        // verdict was not signing-capable) or one bounded by what we have
        // actually scanned plus a reorg margin — this wallet has scanned
        // nothing, so that bound is small.
        assert!(
            snap.grace_anchor_tip
                .is_none_or(|a| a.value() <= crate::constants::REORG_MAX_BLOCKS),
            "a hostile tip wrote an anchor of {:?} — unclamped, u32::MAX here \
             grants unlimited grace forever, and the row survives a rescan",
            snap.grace_anchor_tip
        );
        // And lying upward buys no permission either.
        assert_ne!(
            snap.verdict,
            Some(crate::consensus::ConsensusCompatibility::Current),
            "an endpoint claiming an impossible tip must not read as Current"
        );
        w.close().await.expect("close");
    }

    /// §8 gate 2 — `recovery_paths_survive_staleness`.
    ///
    /// §1.5 promises a stale build never stands between a user and their keys.
    /// This is the row where a wrong answer is worst: a user whose app cannot
    /// send is exactly the user who may need to move their wallet elsewhere.
    #[tokio::test]
    async fn recovery_paths_survive_staleness() {
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        // A MNEMONIC wallet, so `reveal_mnemonic` has something to reveal —
        // the raw-bytes fixture would pass this test vacuously.
        let w = Wallet::create_with_vault(
            cfg(dir.path(), Network::Test, SeedPersistence::SealedKeychain),
            SeedSource::generate(),
            Arc::clone(&vault),
        )
        .await
        .expect("create");
        w.seed_unsupported_consensus_for_test();

        assert!(
            w.reveal_mnemonic().is_ok(),
            "the recovery phrase must be readable while Unsupported"
        );
        assert!(
            w.export_ufvk().await.is_ok(),
            "the viewing key must be exportable while Unsupported"
        );
        // ANTI-VACUITY: the same handle really is refusing to sign, so this
        // test is observing the staleness state and not an unstale wallet.
        assert!(
            matches!(
                w.propose(one_payment(Some(40_000))).await,
                Err(WalletError::NetworkUpgradeUnsupported { .. })
            ),
            "the fixture must actually be stale"
        );
        w.close().await.expect("close");
    }

    /// §8 gate 6 — `cold_start_offline_refuses_signing_but_allows_queueing`.
    ///
    /// A wallet that has NEVER evaluated a verdict is the state §2 could not
    /// represent in the draft. Signing fail-closed there is the whole reason
    /// the type has a `None` arm; queueing stays open or offline-first dies.
    #[tokio::test]
    async fn cold_start_offline_refuses_signing_but_allows_queueing() {
        let dir = tempfile::tempdir().expect("tempdir");
        let w = ffi_wallet(dir.path(), Network::Test).await;
        // Undo the fixture's convenience verdict: this test is ABOUT having none.
        {
            let aux = w.inner.aux_db.lock().expect("aux");
            aux.execute("DELETE FROM consensus_verdict", [])
                .expect("clear the verdict");
        }
        assert!(
            w.consensus_status()
                .await
                .expect("status")
                .verdict
                .is_none(),
            "the premise: this wallet has never evaluated a verdict"
        );

        // GRACE-1 (§4p item 2): the refusal is ITS OWN type — "not synced yet",
        // never "the network was upgraded" (nothing is known either way, and an
        // update fixes nothing). The property is unchanged: fail-closed.
        assert!(
            matches!(
                w.propose(one_payment(Some(40_000))).await,
                Err(WalletError::ConsensusNotEvaluated)
            ),
            "never having checked is not a reason to sign"
        );
        assert!(
            w.queue_send(one_payment(Some(40_000))).await.is_ok(),
            "but composing offline must still work — the drain applies the \
             verdict when connectivity returns"
        );
        w.close().await.expect("close");
    }

    /// §8 gate 6 — `offline_returns_last_verdict_with_age_never_current`.
    ///
    /// The cold read must hand back what was actually last seen, with when it
    /// was seen — never a fabricated `Current`, which is the §0 failure in the
    /// shape of an API response.
    #[tokio::test]
    async fn offline_returns_last_verdict_with_age_never_current() {
        let dir = tempfile::tempdir().expect("tempdir");
        let w = ffi_wallet(dir.path(), Network::Test).await;
        w.seed_unsupported_consensus_for_test();

        let snap = w.consensus_status().await.expect("status");
        assert!(
            matches!(
                snap.verdict,
                Some(crate::consensus::ConsensusCompatibility::Unsupported { .. })
            ),
            "the last verdict is returned verbatim, got {:?}",
            snap.verdict
        );
        assert_ne!(
            snap.verdict,
            Some(crate::consensus::ConsensusCompatibility::Current),
            "and it is NEVER upgraded to Current on the way out"
        );
        assert!(
            snap.evaluated_at_unix.is_some(),
            "with the instant it was taken, so a host can render its age"
        );
        w.close().await.expect("close");
    }

    /// §8 gate 2 — `behind_wallet_is_not_told_to_update_the_app`.
    ///
    /// A wallet mid-restore is BEHIND, not stale. Refusing it would kill
    /// spend-before-sync; telling it to update the app would be an
    /// unactionable instruction for a perfectly current binary.
    #[tokio::test]
    async fn behind_wallet_is_not_told_to_update_the_app() {
        let dir = tempfile::tempdir().expect("tempdir");
        let w = ffi_wallet(dir.path(), Network::Test).await;
        {
            let aux = w.inner.aux_db.lock().expect("aux");
            crate::consensus_stamp::record(
                &aux,
                &crate::consensus::ConsensusCompatibility::Behind {
                    scanned_tip: BlockHeight::new(1_200_000),
                    claimed_tip: BlockHeight::new(3_400_000),
                },
                BlockHeight::new(3_400_000),
                1_757_000_000,
            )
            .expect("record Behind");
        }
        // It signs: the consensus gate has no quarrel with a lagging scan.
        assert!(
            !matches!(
                w.propose(one_payment(Some(40_000))).await,
                Err(WalletError::NetworkUpgradeUnsupported { .. })
            ),
            "a Behind wallet must never be refused by the consensus gate"
        );
        // And the sync surface does not qualify its reading either.
        assert!(
            w.consensus_status()
                .await
                .expect("status")
                .verdict
                .expect("verdict")
                .permits_signing(),
            "Behind permits signing by construction"
        );
        w.close().await.expect("close");
    }

    /// `ironwood-nu63-support.md` §8 gate 2 —
    /// `stale_binary_refuses_every_signing_path`.
    ///
    /// The draft spec gated `propose()` alone; three of the four signing paths
    /// do not go through it. This pins the §3.2 site table at the wallet API:
    /// every verb that can reach a signature refuses while `Unsupported`, and
    /// the §1.5 read/recovery capabilities keep working beside them.
    ///
    /// COVERAGE, stated honestly: the interactive propose verbs and the queued
    /// drain are asserted here on an unfunded handle. The sweep and reclaim
    /// doors are covered by the type system rather than this test — they take a
    /// `SigningPermit` by value at `create_signed_core`, so they cannot compile
    /// without asking — and by the funded harness in `send.rs`.
    #[tokio::test]
    async fn stale_binary_refuses_every_signing_path() {
        let dir = tempfile::tempdir().expect("tempdir");
        let w = ffi_wallet(dir.path(), Network::Test).await;
        w.seed_unsupported_consensus_for_test();

        // (1) propose
        assert!(
            matches!(
                w.propose(one_payment(Some(40_000))).await,
                Err(WalletError::NetworkUpgradeUnsupported { .. })
            ),
            "propose must refuse"
        );
        // (2) propose_uri — the same door reached through a ZIP-321 string.
        let uri = "zcash:tmEZhbWHTpdKMw5it8YDspUXSMGQyFwovpU?amount=0.0004";
        assert!(
            matches!(
                w.propose_uri(uri).await,
                Err(WalletError::NetworkUpgradeUnsupported { .. })
            ),
            "propose_uri must refuse"
        );
        // (3) propose_shield — shielding SPENDS.
        assert!(
            matches!(
                w.propose_shield().await,
                Err(WalletError::NetworkUpgradeUnsupported { .. })
            ),
            "propose_shield must refuse"
        );
        // (4) the queued drain: the row is left QUEUED and counted, never
        // signed, never deleted.
        let id = w
            .queue_send(one_payment(Some(40_000)))
            .await
            .expect("queueing is deliberately still allowed");
        let parked = w.list_parked_sends().await.expect("list");
        let row = parked
            .iter()
            .find(|p| p.id == id.value())
            .expect("the queued row survives");
        assert_eq!(
            row.signing_block,
            Some(crate::state::SigningBlock::NetworkUpgrade),
            "and the row SAYS why it is not going — the app-update block, this being `Unsupported`"
        );

        // §1.5: reading and recovery are untouched by a signing refusal — this
        // is the half that keeps a refusal honest rather than a lockout.
        assert!(
            w.snapshot().await.is_ok(),
            "balance/state must still read while stale"
        );
        assert!(
            w.current_address().await.is_ok(),
            "receive must still work while stale"
        );
        // This fixture is a RAW-BYTES wallet, so there is no mnemonic to reveal
        // and the honest assertion is about the CAUSE, not success: whatever
        // recovery answers, it must never be the consensus refusal. Staleness
        // must not stand between a user and their keys — that is the case where
        // they need them most.
        assert!(
            !matches!(
                w.reveal_mnemonic(),
                Err(WalletError::NetworkUpgradeUnsupported { .. })
            ),
            "seed backup must NEVER be blocked by staleness"
        );
        w.close().await.expect("close");
    }

    /// `ironwood-nu63-support.md` §3.2 / §8 gate 2 — THE offline-first
    /// asymmetry, and the reason the gate is not simply "refuse everything".
    ///
    /// A build that cannot transact on this network refuses to PROPOSE (so the
    /// user hears it before any proving time is spent) but still lets a payment
    /// be composed and QUEUED. Gating the queue would break composing with zero
    /// connectivity, which is a product invariant; the verdict is applied at
    /// the drain, where the signature actually happens.
    #[tokio::test]
    async fn queue_send_still_works_while_unsupported() {
        let dir = tempfile::tempdir().expect("tempdir");
        let w = ffi_wallet(dir.path(), Network::Test).await;
        w.seed_unsupported_consensus_for_test();

        // PROPOSE is refused, typed, before anything is built.
        match w.propose(one_payment(Some(40_000))).await {
            Err(WalletError::NetworkUpgradeUnsupported { .. }) => {}
            other => panic!("a stale build must refuse to propose, got {other:?}"),
        }

        // QUEUEING still works — this is the offline-first path.
        let id = w
            .queue_send(one_payment(Some(40_000)))
            .await
            .expect("composing and queueing must survive a stale build");
        let parked = w.list_parked_sends().await.expect("list");
        assert!(
            parked.iter().any(|p| p.id == id.value()),
            "the queued intent is durable and visible, not silently dropped"
        );

        // Anti-vacuity: the SAME calls on a current build propose fine, so this
        // test is detecting the verdict and not some unrelated refusal.
        w.seed_current_consensus_for_test();
        if let Err(WalletError::NetworkUpgradeUnsupported { .. }) =
            w.propose(one_payment(Some(40_000))).await
        {
            panic!("a current build must not be refused by the consensus gate");
        }
        w.close().await.expect("close");
    }

    #[tokio::test]
    async fn queue_send_uri_lowers_a_uri_to_the_same_intent_as_queue_send() {
        // §8 (inc-2d-ffi): the FFI offline path. A ZIP-321 URI the host composed is lowered
        // with the wallet's OWN network and persisted as the EXACT same intent `queue_send`
        // would store — the lossless-token crossing round-trips byte-for-byte (DRY: a queued
        // FFI send can never drift from a typed one).
        let dir = tempfile::tempdir().expect("tempdir");
        let w = ffi_wallet(dir.path(), Network::Test).await;

        let uri =
            crate::payment_uri::encode_payment_uri(&one_payment(Some(100_000))).expect("encode");
        let id = w.queue_send_uri(&uri).await.expect("queue_send_uri");
        assert!(id.value() > 0, "a real rowid");

        let queued = {
            let guard = w.inner.aux_db.lock().expect("aux db");
            crate::intent_store::list_queued(&guard).expect("list")
        };
        assert_eq!(queued.len(), 1, "exactly one queued intent");
        assert_eq!(queued[0].id, id);
        assert_eq!(queued[0].uri, uri, "stores the host's exact ZIP-321 URI");
        w.close().await.expect("close");
    }

