    #[tokio::test]
    async fn queue_send_uri_round_trips_a_multi_recipient_memo_bearing_near_max_uri() {
        // §8 (inc-2d-ffi): REAL-WORLD-EDGE fidelity through the FFI URI crossing. A sender's
        // form can compose several legs at once, attach a human memo, and (a whale) move a
        // near-MAX_MONEY amount. The PROPOSE-from-URI fidelity test would be the ideal place to
        // assert amount/recipient/memo survive note selection — but `propose`/`propose_uri` run
        // `propose_core` over the wallet DB, which fail-closes `ProposeFailed` on an UNFUNDED
        // wallet (the `data_api::testing` harness funds only a `LocalNetwork` DB, never a real
        // `Wallet`), so that route is E2E-owed (recorded below). What IS deterministically
        // buildable here is the OFFLINE `queue_send_uri` route: it lowers the URI and persists
        // the intent with NO funds, so we can prove the lossless-token crossing preserves every
        // leg's amount + recipient + memo by re-parsing the STORED URI. Integer zatoshis only.
        use crate::memo::{Memo, Payment};
        use crate::money::Zatoshis;

        let dir = tempfile::tempdir().expect("tempdir");
        let w = ffi_wallet(dir.path(), Network::Test).await;

        // a near-MAX_MONEY shielded leg with a memo + a smaller second shielded leg. Both
        // recipients are SAPLING (shielded) so the memo is permitted (a memo to a transparent
        // recipient is a typed reject — not the path under test). MAX-1 keeps headroom for the
        // second leg's amount under the per-request supply bound the parser re-checks.
        let big = crate::constants::MAX_MONEY_ZAT - 1_000_000;
        let memo_text = "coffee with an émoji ☕ and a snowman ☃";
        let request = PaymentRequest {
            payments: vec![
                Payment::new(
                    sapling_test_addr(),
                    Some(Zatoshis::new(big).expect("big in range")),
                    Memo::text(memo_text).expect("valid text memo"),
                    None,
                    None,
                )
                .expect("leg 0"),
                Payment::new(
                    sapling_test_addr(),
                    Some(Zatoshis::new(250_000).expect("small in range")),
                    Memo::Empty,
                    None,
                    None,
                )
                .expect("leg 1"),
            ],
        };
        let uri = crate::payment_uri::encode_payment_uri(&request).expect("encode multi-leg");

        let id = w.queue_send_uri(&uri).await.expect("queue_send_uri");
        assert!(id.value() > 0, "a real rowid");

        // read back the STORED URI and re-parse it with the wallet's network — the persisted
        // token must reconstruct EVERY leg's amount + recipient + memo byte-for-byte.
        let stored_uri = {
            let guard = w.inner.aux_db.lock().expect("aux db");
            let queued = crate::intent_store::list_queued(&guard).expect("list");
            assert_eq!(queued.len(), 1, "exactly one queued intent");
            assert_eq!(queued[0].id, id);
            queued[0].uri.clone()
        };
        let reparsed =
            crate::payment_uri::parse_payment_uri(&stored_uri, Network::Test).expect("re-parse");
        assert_eq!(reparsed.payments.len(), 2, "both legs survive the crossing");

        // leg 0: the near-max amount + the unicode memo are preserved exactly
        assert_eq!(
            reparsed.payments[0].amount.map(Zatoshis::zat),
            Some(big),
            "the near-MAX_MONEY amount round-trips exact (integer zatoshis, no clamp)"
        );
        assert_eq!(
            reparsed.payments[0].recipient.encoded(),
            sapling_test_addr().encoded(),
            "recipient 0 address round-trips"
        );
        match &reparsed.payments[0].memo {
            Memo::Text(t) => assert_eq!(t, memo_text, "the unicode memo round-trips byte-for-byte"),
            other => panic!("leg 0 memo must round-trip as Text, got {other:?}"),
        }

        // leg 1: the smaller amount + empty memo
        assert_eq!(
            reparsed.payments[1].amount.map(Zatoshis::zat),
            Some(250_000),
            "recipient 1 amount round-trips"
        );
        assert!(
            matches!(reparsed.payments[1].memo, Memo::Empty),
            "leg 1 carries no memo"
        );
        w.close().await.expect("close");

        // E2E-OWED (spec §8 register): the PROPOSE-from-URI money fidelity — that the same
        // multi-leg/memo/near-max URI lowered through `propose_uri` yields a `SendProposal`
        // whose total/fee/change + per-recipient amounts match — needs a FUNDED real `Wallet`,
        // which no bridge/core unit can build (note selection fail-closes `ProposeFailed`
        // unfunded). It rides the on-device GA e2e, not this harness.
    }

