    #[tokio::test]
    async fn a_switch_emits_the_sync_server_span_with_kind_and_outcome_and_never_a_custom_host() {
        // Gate 5 (`sync-server-picker.md` §5): ONE `wallet.sync_server` record
        // per outcome, carrying `kind` and `outcome` (and `id` for a
        // predefined entry — public config); the custom HOST appears in no
        // captured field, ever (§5.4 — a URL the user typed). And the
        // stop-join precedes the row: the loop's `loop_stop` is captured
        // BEFORE the switch's `switched` — `a_switch_stops_and_joins_the_loop
        // _before_the_row_is_written`, folded here because both are one
        // capture of one switch.
        use crate::tracing_guard::{CaptureLayer, CapturedEvents};
        use tracing_subscriber::layer::SubscriberExt;
        crate::tracing_guard::force_wallet_callsites_enabled();
        let sink = CapturedEvents::default();
        let subscriber = tracing_subscriber::registry().with(CaptureLayer::new(sink.clone()));
        let _guard = tracing::subscriber::set_default(subscriber);

        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let mut c = cfg(dir.path(), Network::Test, SeedPersistence::SealedKeychain);
        // An endpoint nothing listens on: the loop starts, dials, stalls —
        // and is then STOPPED by the switch, which is the ordering under test.
        c.endpoint = LightServerEndpoint::new("https://127.0.0.1:1").expect("endpoint");
        let w = Wallet::create_with_vault(c, raw_seed(), Arc::clone(&vault))
            .await
            .expect("create");
        w.start_sync().expect("start the loop");
        // ADR-0568: a KEYED custom choice — neither the key's value nor its
        // header name may reach a field either.
        let w = switched_via_honest_oracle(
            w,
            keyed("https://secret-host.example:443", "secret-key-value-77"),
            Network::Test,
        )
        .await;

        let records = sink.records_of("wallet.sync_server");
        let switched = records
            .iter()
            .find(|r| r.iter().any(|(k, v)| k == "outcome" && v == "switched"))
            .unwrap_or_else(|| panic!("no switched record; captured {records:?}"));
        assert!(
            switched
                .iter()
                .any(|(k, v)| k == "server_kind" && v == "custom"),
            "the record names the KIND; got {switched:?}"
        );
        let all = sink.fields();
        assert!(
            !all.iter().any(|(_, v)| v.contains("secret-host")),
            "the custom host leaked into a log field: {all:?}"
        );
        assert!(
            !all.iter()
                .any(|(_, v)| v.contains("secret-key-value-77") || v.contains("x-api-key")),
            "the user's key or its header leaked into a log field: {all:?}"
        );
        crate::tracing_guard::assert_5_4_clean(&all);
        // Order: the loop stopped before the switch completed.
        let pos = |wanted: &str| {
            all.iter()
                .position(|(k, v)| k == "outcome" && v == wanted)
                .unwrap_or_else(|| panic!("no outcome={wanted}; captured {all:?}"))
        };
        assert!(
            pos("loop_stop") < pos("switched"),
            "the loop must be stopped and joined before the switch lands"
        );
        assert!(
            matches!(w.inner.sync.status(), SyncStatus::Idle),
            "the new session's loop is not running until the host starts it"
        );
        w.close().await.expect("close");
    }

    #[tokio::test]
    async fn a_switch_to_the_current_server_writes_the_row_and_keeps_the_session_and_its_streak() {
        // The security review's MEDIUM (folded): a switch that resolves to
        // the server already in use — by `same_server`, so a port-less
        // spelling of the default counts — writes the row (the choice is
        // remembered) and updates the status, and does NOT rebuild: the same
        // `Inner`, the same `SyncController`, the same rewinding streak. A
        // rebuild would forgive a misbehaving server's report at zero cost.
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let w = Wallet::create_with_vault(
            cfg(dir.path(), Network::Test, SeedPersistence::SealedKeychain),
            raw_seed(),
            Arc::clone(&vault),
        )
        .await
        .expect("create");
        let inner_before: *const Inner = Arc::as_ptr(&w.inner);
        // A choice that spells the default WITHOUT the port: one server.
        let w = switched_via_honest_oracle(w, custom("https://zec.rocks"), Network::Test).await;
        assert!(
            std::ptr::eq(Arc::as_ptr(&w.inner), inner_before),
            "the SAME Inner (and so the same controller and streak) survives"
        );
        let s = w.sync_server_status();
        assert_eq!(s.effective.as_str(), "https://zec.rocks:443");
        assert_eq!(s.choice, Some(custom("https://zec.rocks")));
        assert_eq!(s.fallback, None);
        {
            let aux = w.inner.aux_db.lock().expect("aux db");
            assert_eq!(
                sync_server::read(&aux),
                sync_server::StoredChoice::Custom {
                    url: "https://zec.rocks".to_owned(),
                    key: None,
                },
                "the row is written even though nothing rebuilt"
            );
        }
        // Default onto the default: the row is deleted, still no rebuild.
        let w = switched_via_honest_oracle(w, SyncServerChoice::Default, Network::Test).await;
        assert!(std::ptr::eq(Arc::as_ptr(&w.inner), inner_before));
        assert_eq!(w.sync_server_status().choice, None);
        {
            let aux = w.inner.aux_db.lock().expect("aux db");
            assert_eq!(sync_server::read(&aux), sync_server::StoredChoice::Absent);
        }
        w.close().await.expect("close");
    }

