    #[tokio::test]
    async fn a_switch_onto_the_same_server_with_a_new_key_rebuilds() {
        // ADR-0568: only the key changed — the session's clients carry the
        // OLD key, so keeping them would keep sending it. The switch rebuilds
        // and the new session sends the new key; the row holds the new key.
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let w = Wallet::create_with_vault(
            cfg(dir.path(), Network::Test, SeedPersistence::SealedKeychain),
            raw_seed(),
            Arc::clone(&vault),
        )
        .await
        .expect("create");
        let w = switched_via_honest_oracle(
            w,
            keyed("https://mine.example:443", "old-key-1"),
            Network::Test,
        )
        .await;
        assert_eq!(w.inner.endpoint_auth, Some(user_key("old-key-1")));
        let inner_before: *const Inner = Arc::as_ptr(&w.inner);
        let w = switched_via_honest_oracle(
            w,
            keyed("https://mine.example:443", "new-key-2"),
            Network::Test,
        )
        .await;
        assert!(
            !std::ptr::eq(Arc::as_ptr(&w.inner), inner_before),
            "a new key is a new session"
        );
        assert_eq!(
            w.inner.endpoint_auth,
            Some(user_key("new-key-2")),
            "the rebuilt session sends the NEW key"
        );
        // And dropping the key on the same server rebuilds too, keyless.
        let w =
            switched_via_honest_oracle(w, custom("https://mine.example:443"), Network::Test).await;
        assert_eq!(w.inner.endpoint_auth, None, "the old key is not kept");
        {
            let aux = w.inner.aux_db.lock().expect("aux db");
            assert_eq!(
                sync_server::read(&aux),
                sync_server::StoredChoice::Custom {
                    url: "https://mine.example:443".to_owned(),
                    key: None,
                }
            );
        }
        w.close().await.expect("close");
    }

