    #[tokio::test]
    async fn the_probe_and_the_switch_send_the_custom_key() {
        // ADR-0568 at the wallet: the probe resolves the user's key with the
        // URL (`resolve_choice` — what `probe_endpoint` hands the client), and
        // the switched session's `endpoint_auth` — what every client it builds
        // sends (`net/grpc.rs`'s auth rows pin the header on the wire) — is
        // the user's key, not the default's.
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let w = Wallet::create_with_vault(
            cfg(dir.path(), Network::Test, SeedPersistence::SealedKeychain),
            raw_seed(),
            Arc::clone(&vault),
        )
        .await
        .expect("create");
        let choice = keyed("https://mine.example:443", "probe-key-3");
        let (endpoint, auth) = w.resolve_choice(&choice).expect("resolves");
        assert_eq!(endpoint.as_str(), "https://mine.example:443");
        assert_eq!(
            auth,
            Some(user_key("probe-key-3")),
            "the probe sends the key"
        );
        // A key on plaintext is refused before anything is dialed.
        assert!(matches!(
            w.resolve_choice(&keyed("http://127.0.0.1:9067", "probe-key-3")),
            Err(WalletError::InvalidEndpointAuth { .. })
        ));
        let w = switched_via_honest_oracle(w, choice, Network::Test).await;
        assert_eq!(w.inner.endpoint_auth, Some(user_key("probe-key-3")));
        w.close().await.expect("close");
    }

