    #[tokio::test]
    async fn restore_over_a_complete_wallet_is_already_exists_not_clobber() {
        // THE money edge (real-world): a user with a funded, backed-up wallet
        // fat-fingers a DIFFERENT recovery phrase into the restore screen at the
        // same dbDir. The restore (a `SeedSource::Mnemonic`, the inbound crossing's
        // exact core path) must be REJECTED as `WalletAlreadyExists` — never seal a
        // new seed over the old one — and the original wallet must survive
        // BYTE-IDENTICAL (same default address ⇒ same funds reachable). This pins
        // the non-clobber for the restore source specifically (the store-level
        // `create_or_repair` Complete→AlreadyExists holds for any source; this
        // proves it end-to-end through the handle with a mistyped restore).
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();

        // The original wallet, restored from a known phrase; record its address.
        let original = Wallet::create_with_vault(
            cfg(dir.path(), Network::Main, SeedPersistence::SealedKeychain),
            SeedSource::mnemonic(VECTOR_PHRASE_24.to_owned(), None),
            Arc::clone(&vault),
        )
        .await
        .expect("create the original wallet");
        let addr_before = original.current_address().await.expect("address before");
        original.close().await.expect("close original");

        // A DIFFERENT valid phrase (the 12-word zero-entropy vector) at the SAME
        // dir — the fat-finger. It is a fully valid BIP39 phrase, so it passes
        // `resolve_seed` and reaches the Complete→AlreadyExists gate (proving the
        // rejection is the store-state check, not a coincidental seed failure).
        const DIFFERENT_PHRASE_12: &str = "abandon abandon abandon abandon abandon abandon \
             abandon abandon abandon abandon abandon about";
        let clobber_attempt = Wallet::create_with_vault(
            cfg(dir.path(), Network::Main, SeedPersistence::SealedKeychain),
            SeedSource::mnemonic(DIFFERENT_PHRASE_12.to_owned(), None),
            Arc::clone(&vault),
        )
        .await;
        assert!(
            matches!(clobber_attempt, Err(WalletError::WalletAlreadyExists)),
            "restoring a different phrase over a completed wallet must not clobber"
        );

        // The original is untouched: reopen and confirm the SAME address (the
        // sealed seed is the original's, not the fat-fingered one).
        let reopened = Wallet::open_with_vault(
            cfg(dir.path(), Network::Main, SeedPersistence::SealedKeychain),
            Arc::clone(&vault),
        )
        .await
        .expect("reopen the original wallet");
        let addr_after = reopened.current_address().await.expect("address after");
        assert_eq!(
            addr_before.encoded(),
            addr_after.encoded(),
            "the original wallet's address (and thus its funds) survived the restore attempt"
        );
        reopened.close().await.expect("close reopened");
    }

