    #[tokio::test]
    async fn current_address_is_the_g7_unified_address_and_matches_derivation() {
        // §3.1: a SealedKeychain wallet's default address is a Unified address with
        // a shielded receiver (memo-capable, NOT transparent-only), and it equals
        // the audited `derive_default_address` for the same seed (the handle adds no
        // divergent derivation — it wraps the audited path).
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let seed_bytes = vec![0x24u8; 32];

        let w = Wallet::create_with_vault(
            cfg(dir.path(), Network::Main, SeedPersistence::SealedKeychain),
            SeedSource::raw_bytes(seed_bytes.clone()).expect("seed"),
            Arc::clone(&vault),
        )
        .await
        .expect("create");

        let addr = w.current_address().await.expect("address");
        assert_eq!(addr.kind(), crate::memo::AddressKind::Unified);
        assert!(
            addr.memo_capable(),
            "the default UA must carry a shielded receiver"
        );
        assert!(!addr.transparent_only(), "G7: never a transparent-only UA");
        // identical to the audited offline derivation for the same seed
        let expected = derive_default_address(Network::Main, &seed_bytes).expect("derive");
        assert_eq!(addr.encoded(), expected);
        // deterministic across calls
        let again = w.current_address().await.expect("address again");
        assert_eq!(again.encoded(), addr.encoded());

        w.close().await.expect("close");
    }

