    #[tokio::test]
    async fn export_ufvk_matches_the_offline_derivation_and_views_the_same_account() {
        // #397 §3.7 D1: the sanctioned export equals the audited offline
        // derivation for the same seed (the handle adds no divergent path),
        // carries the network HRP, and — the D2 import guarantee — decodes to
        // a UFVK that views the SAME account (identical default UA).
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let seed_bytes = vec![0x24u8; 32];

        let w = Wallet::create_with_vault(
            cfg(dir.path(), Network::Main, SeedPersistence::SealedKeychain),
            SeedSource::raw_bytes(seed_bytes.clone()).expect("seed"),
            Arc::clone(&vault),
        )
        .await
        .expect("create");

        let exported = w.export_ufvk().await.expect("export");
        assert!(exported.starts_with("uview1"), "mainnet UFVK HRP");
        let usk = derive_spending_key(Network::Main, &seed_bytes).expect("usk");
        assert_eq!(
            exported,
            crate::derivation::encode_ufvk(Network::Main, &usk.to_unified_full_viewing_key()),
            "export equals the audited offline derivation"
        );
        // The export artifact views the exporter's account: decode → default
        // UA parity with the wallet's own receive address.
        let decoded = zcash_keys::keys::UnifiedFullViewingKey::decode(
            &::zcash_protocol::consensus::MAIN_NETWORK,
            &exported,
        )
        .expect("export artifact decodes");
        let addr = w.current_address().await.expect("address");
        assert_eq!(
            crate::derivation::default_address_from_ufvk(Network::Main, &decoded)
                .expect("address from decoded UFVK"),
            addr.encoded(),
            "decoded UFVK views the exporter's account"
        );
        // deterministic across calls
        assert_eq!(w.export_ufvk().await.expect("again"), exported);
        w.close().await.expect("close");
    }

