    #[tokio::test]
    async fn watch_only_create_converges_over_an_account_less_remnant() {
        // #397 (review CONVERGED M2/M6): a marker-Complete watch-only store
        // with no account (the crash window between the completion marker and
        // the eager import) is HEALED by re-running `create_watch_only` with
        // the same artifact — and a DIFFERENT artifact over an existing
        // account is refused `WalletAlreadyExists` (never silently kept).
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        // Build the source exports (twin A and a DIFFERENT twin B).
        let mk_export = |seed: u8| {
            let vault = Arc::clone(&vault);
            async move {
                let src = tempfile::tempdir().expect("src");
                let w = Wallet::create_with_vault(
                    cfg(src.path(), Network::Main, SeedPersistence::SealedKeychain),
                    SeedSource::raw_bytes(vec![seed; 32]).expect("seed"),
                    Arc::clone(&vault),
                )
                .await
                .expect("twin");
                let e = w.export_ufvk().await.expect("export");
                w.close().await.expect("close");
                e
            }
        };
        let export_a = mk_export(0x11).await;
        let export_b = mk_export(0x22).await;

        // Build the GENUINE crash-window remnant (code review M1): a
        // marker-Complete watch-only store with NO account — exactly the state
        // a kill between `create_or_repair`'s completion marker and the eager
        // `ensure_account_ufvk` leaves. Provision the store directly, WITHOUT
        // the account import.
        {
            let lock = WalletLock::acquire(dir.path()).expect("lock");
            let intent = ProvisionIntent {
                network: Network::Main,
                persistence: PersistenceKind::WatchOnly,
                seed: None,
                repair_mode: RepairMode::NoSeed,
                freshly_generated_at: None,
            };
            store::create_or_repair(&lock, &*vault, &intent).expect("provision account-less");
            // Prove the remnant is account-less (the `None` branch of the
            // converge's UFVK-equality guard) BEFORE the heal.
            let open = store::open(&lock, &*vault, Network::Main).expect("open remnant");
            assert!(
                account::account_ufvk_encoding(&open.db, Network::Main)
                    .expect("read")
                    .is_none(),
                "the remnant has no account yet — the crash window",
            );
        }
        assert!(
            Wallet::exists(dir.path().to_path_buf())
                .await
                .expect("exists"),
            "the store is marker-Complete",
        );

        // Re-running `create_watch_only` with the artifact HEALS the remnant —
        // accepts the Complete store and imports the missing account (the
        // documented crash-window repair path), NOT `WalletAlreadyExists`.
        let w = Wallet::create_watch_only_with_vault(
            cfg(dir.path(), Network::Main, SeedPersistence::SealedKeychain),
            &export_a,
            BlockHeight::new(2_000_000),
            Arc::clone(&vault),
        )
        .await
        .expect("heal the account-less remnant");
        let addr = w
            .current_address()
            .await
            .expect("addr")
            .encoded()
            .to_string();
        w.close().await.expect("close");

        // Re-running AGAIN with the SAME artifact converges idempotently (now
        // the account EXISTS — the `Some(existing)` equality-guard arm passes).
        let w2 = Wallet::create_watch_only_with_vault(
            cfg(dir.path(), Network::Main, SeedPersistence::SealedKeychain),
            &export_a,
            BlockHeight::new(2_000_000),
            Arc::clone(&vault),
        )
        .await
        .expect("converge with same artifact");
        assert_eq!(w2.current_address().await.expect("addr").encoded(), addr);
        w2.close().await.expect("close");

        // A DIFFERENT artifact over the existing account is refused — never
        // gaslight the caller by keeping the old key.
        assert!(matches!(
            Wallet::create_watch_only_with_vault(
                cfg(dir.path(), Network::Main, SeedPersistence::SealedKeychain),
                &export_b,
                BlockHeight::new(2_000_000),
                Arc::clone(&vault),
            )
            .await,
            Err(WalletError::WalletAlreadyExists)
        ));
    }

    #[tokio::test]
    async fn current_transparent_address_is_the_external_receiver_and_matches_derivation() {
        // §3.3a Recv-2 (ADR-0528): a SealedKeychain wallet's transparent receive address is the
        // external-scope (m/44'/coin'/0'/0/0) P2PKH receiver, equal to the audited
        // `derive_transparent_receive_address` for the same seed (the handle wraps the audited
        // path, adds no divergent derivation), deterministic, DISTINCT from the shielded UA, and
        // DISTINCT from a fresh refund address (external index 1 — the collision the index-0
        // reservation removes).
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let seed_bytes = vec![0x24u8; 32];

        let w = Wallet::create_with_vault(
            cfg(dir.path(), Network::Main, SeedPersistence::SealedKeychain),
            SeedSource::raw_bytes(seed_bytes.clone()).expect("seed"),
            Arc::clone(&vault),
        )
        .await
        .expect("create");

        let taddr = w
            .current_transparent_address()
            .await
            .expect("transparent address");
        let expected =
            crate::derivation::derive_transparent_receive_address(Network::Main, &seed_bytes)
                .expect("derive");
        assert_eq!(taddr, expected);
        assert!(taddr.starts_with("t1"), "mainnet transparent P2PKH HRP");
        let ua = w.current_address().await.expect("ua");
        assert_ne!(
            taddr,
            ua.encoded(),
            "transparent receive address must differ from the shielded UA"
        );
        // the receive address is external index 0; refunds start at index 1 — never the same
        let refund1 =
            crate::derivation::derive_transparent_refund_address(Network::Main, &seed_bytes, 1)
                .expect("refund 1");
        assert_ne!(
            taddr, refund1,
            "the receive address must differ from a refund address"
        );
        // deterministic across calls
        let again = w
            .current_transparent_address()
            .await
            .expect("transparent address again");
        assert_eq!(again, taddr);

        w.close().await.expect("close");
    }

