    #[tokio::test]
    async fn current_transparent_address_after_import_reads_stored_account_path() {
        // §8 (re-review real-world-edge fold): after account import, `current_transparent_address`
        // reads the DB account UFVK (the PRODUCTION path once sync has run) and the t-addr
        // byte-equals the offline derivation — and SURVIVES a close+reopen unchanged. Without
        // this, a SealedKeychain wallet would still go green via the held-seed FALLBACK even if
        // the DB read were broken (the shielded `current_address_after_import_*` precedent).
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let seed_bytes = vec![0x24u8; 32];

        let w = Wallet::create_with_vault(
            cfg(dir.path(), Network::Test, SeedPersistence::SealedKeychain),
            SeedSource::raw_bytes(seed_bytes.clone()).expect("seed"),
            Arc::clone(&vault),
        )
        .await
        .expect("create");
        w.import_account(testnet_birthday()).await.expect("import");

        let expected =
            crate::derivation::derive_transparent_receive_address(Network::Test, &seed_bytes)
                .expect("derive");
        // Prove the DB ACCOUNT path is LIVE (not the seed fallback masking a broken read): read
        // the stored-account transparent address directly (no seed) and assert it equals the
        // offline derivation.
        let from_db = {
            let guard = w.inner.db.lock().expect("db mutex");
            account::account_transparent_address(&guard.db, Network::Test).expect("db read")
        };
        assert_eq!(
            from_db.as_deref(),
            Some(expected.as_str()),
            "the stored-account UFVK yields the transparent receiver with NO seed, == offline derivation"
        );
        let post = w
            .current_transparent_address()
            .await
            .expect("post-import transparent address");
        assert_eq!(
            post, expected,
            "current_transparent_address prefers the DB path"
        );
        w.close().await.expect("close");

        // close + reopen: the address must be byte-identical (no loss across the SQLCipher reopen)
        let w2 = Wallet::open_with_vault(
            cfg(dir.path(), Network::Test, SeedPersistence::SealedKeychain),
            Arc::clone(&vault),
        )
        .await
        .expect("reopen");
        let after_reopen = w2
            .current_transparent_address()
            .await
            .expect("transparent address after reopen");
        assert_eq!(
            after_reopen, expected,
            "the transparent receive address must survive a close+reopen unchanged"
        );
        w2.close().await.expect("close");
    }

    #[tokio::test]
    async fn current_transparent_address_none_persistence_succeeds_after_account_import() {
        // §8 (re-review real-world-edge fold): the host's production flow is None-persistence (no
        // seed at rest). Once the account is imported (provision-time, when the seed is
        // transiently available), `current_transparent_address` MUST serve the address from the
        // stored UFVK with NO seed — never a `SeedRequired`. A regression here = the user cannot
        // see their transparent receive address at all. We import the account directly (the seed
        // is gone from a None-persistence handle, so `import_account` can't; this stands in for
        // the create-time provision that DID have the seed).
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let seed_bytes = vec![0x24u8; 32];

        let w = Wallet::create_with_vault(
            cfg(dir.path(), Network::Test, SeedPersistence::None),
            SeedSource::raw_bytes(seed_bytes.clone()).expect("seed"),
            Arc::clone(&vault),
        )
        .await
        .expect("create none-mode");
        {
            let mut guard = w.inner.db.lock().expect("db mutex");
            account::ensure_account(&mut guard.db, &seed_bytes, &testnet_birthday())
                .expect("provision-time account import");
        }
        let expected =
            crate::derivation::derive_transparent_receive_address(Network::Test, &seed_bytes)
                .expect("derive");
        let addr = w
            .current_transparent_address()
            .await
            .expect("None-persistence + account ⇒ address from the UFVK, no seed");
        assert_eq!(
            addr, expected,
            "a synced None-persistence wallet serves the transparent address from the stored UFVK"
        );
        w.close().await.expect("close");
    }

    #[tokio::test]
    async fn current_transparent_address_concurrent_calls_return_identical_result() {
        // §8 (re-review real-world-edge fold): the receive screen can fire several reads at once
        // (a platform-resume rebuild). Each call takes + releases the db lock independently; N
        // concurrent calls must all succeed and return the SAME address (no torn read, no
        // deadlock). Each `current_transparent_address` delegates to `spawn_blocking`, so these
        // genuinely contend on the wallet-db mutex.
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let w = Wallet::create_with_vault(
            cfg(dir.path(), Network::Test, SeedPersistence::SealedKeychain),
            raw_seed(),
            Arc::clone(&vault),
        )
        .await
        .expect("create");
        w.import_account(testnet_birthday()).await.expect("import");
        let (a, b, c, d) = tokio::join!(
            w.current_transparent_address(),
            w.current_transparent_address(),
            w.current_transparent_address(),
            w.current_transparent_address(),
        );
        let a = a.expect("a");
        let b = b.expect("b");
        let c = c.expect("c");
        let d = d.expect("d");
        assert!(a.starts_with("tm"), "testnet transparent P2PKH");
        assert_eq!(a, b, "concurrent reads must agree");
        assert_eq!(b, c, "concurrent reads must agree");
        assert_eq!(c, d, "concurrent reads must agree");
        w.close().await.expect("close");
    }

    // ── reveal_mnemonic — the SANCTIONED outbound key-material read (§3.1) ──────

    /// The canonical BIP39 24-word vector (Trezor #1, entropy 0x00×32), reused
    /// from the derivation KATs. Checksum-valid; the last word is `art`.
    const VECTOR_PHRASE_24: &str = "abandon abandon abandon abandon abandon abandon \
         abandon abandon abandon abandon abandon abandon abandon abandon abandon \
         abandon abandon abandon abandon abandon abandon abandon abandon art";

    fn join_words(words: &[Zeroizing<String>]) -> String {
        words
            .iter()
            .map(|w| w.as_str())
            .collect::<Vec<_>>()
            .join(" ")
    }

    #[tokio::test]
    async fn reveal_mnemonic_returns_the_bip39_vector_words_in_order() {
        // VECTOR-FIRST (crypto-rules): reveal returns EXACTLY the stored phrase's
        // words, in order — the §3.1 backup contract. A SealedKeychain wallet
        // created from the canonical vector phrase reveals those 24 words verbatim.
        let dir = tempfile::tempdir().expect("tempdir");
        let w = Wallet::create_with_vault(
            cfg(dir.path(), Network::Main, SeedPersistence::SealedKeychain),
            SeedSource::mnemonic(VECTOR_PHRASE_24.to_owned(), None),
            test_vault(),
        )
        .await
        .expect("create from vector phrase");

        let words = w.reveal_mnemonic().expect("reveal");
        let expected: Vec<&str> = VECTOR_PHRASE_24.split_whitespace().collect();
        assert_eq!(words.len(), 24, "24-word phrase");
        assert_eq!(
            words.iter().map(|w| w.as_str()).collect::<Vec<_>>(),
            expected,
            "reveal must return the stored words, in BIP39 index order"
        );
        w.close().await.expect("close");
    }

    #[tokio::test]
    async fn reveal_mnemonic_round_trips_a_generated_wallet() {
        // MONEY property: the revealed words are the REAL backup — re-creating a
        // wallet from them reconstructs the SAME wallet (byte-equal default UA).
        // A reveal that dropped/reordered/altered a word would silently hand the
        // user an un-restorable backup (funds lost on device loss). createGenerated
        // (OsRng) → reveal → re-create from the words → identical address.
        let dir_a = tempfile::tempdir().expect("tempdir a");
        let original = Wallet::create_with_vault(
            cfg(dir_a.path(), Network::Main, SeedPersistence::SealedKeychain),
            SeedSource::generate(),
            test_vault(),
        )
        .await
        .expect("create generated");

        let words = original.reveal_mnemonic().expect("reveal");
        assert_eq!(words.len(), 24, "generated wallets keep 24 words");
        let addr_original = original.current_address().await.expect("address");

        // Re-create from the revealed words (no passphrase) at a fresh dir.
        let dir_b = tempfile::tempdir().expect("tempdir b");
        let restored = Wallet::create_with_vault(
            cfg(dir_b.path(), Network::Main, SeedPersistence::SealedKeychain),
            SeedSource::mnemonic(join_words(&words), None),
            test_vault(),
        )
        .await
        .expect("re-create from revealed words");
        let addr_restored = restored.current_address().await.expect("address");

        assert_eq!(
            addr_original.encoded(),
            addr_restored.encoded(),
            "the revealed words must reconstruct the exact wallet"
        );
        original.close().await.expect("close a");
        restored.close().await.expect("close b");
    }

