    // ── REAL-WORLD MESSY-INPUT EDGES (mobile paste / autocorrect / soft-keyboard) ──
    //
    // These CHARACTERIZE what `bip39::Mnemonic::parse_in_normalized` actually does
    // with the messy phrases a user hits restoring on a phone (paste from a password
    // manager, a stray autocorrect-inserted space, a soft-keyboard that capitalizes
    // the first word). They tell the host restore UI what it MUST pre-normalize and
    // what it can leave to the audited crate. The behavior is OBSERVED + PINNED here,
    // not assumed — a bip39 bump that changes it fails THESE tests, in CI, before a
    // user is stranded on a restore screen.

    /// Restore a SealedKeychain wallet from `phrase` (no passphrase) at a fresh dir
    /// and return its default UA — the byte-equal-or-not comparison surface for the
    /// whitespace/case characterizations. Asserts the create succeeded (an invalid
    /// phrase would panic the `expect`, surfacing as the test message, not a silent
    /// pass). The handle is closed before returning so the temp dir's lock frees.
    async fn restore_address(phrase: &str) -> String {
        let dir = tempfile::tempdir().expect("tempdir");
        let w = Wallet::create_with_vault(
            cfg(dir.path(), Network::Main, SeedPersistence::SealedKeychain),
            SeedSource::mnemonic(phrase.to_owned(), None),
            test_vault(),
        )
        .await
        .expect("restore from the phrase under test");
        let addr = w
            .current_address()
            .await
            .expect("address")
            .encoded()
            .to_owned();
        w.close().await.expect("close");
        addr
    }

    #[tokio::test]
    async fn restore_tolerates_messy_inter_word_whitespace() {
        // THE PASTE EDGE: a phrase pasted from a password manager / notes app can
        // carry double spaces, a stray tab, or a wrapped newline BETWEEN words (never
        // inside a word). `parse_in_normalized` splits on Unicode whitespace runs, so
        // a phrase with collapsed-equivalent whitespace derives the IDENTICAL wallet —
        // same address, same funds. CHARACTERIZED: this is the audited crate's
        // behavior, so the host need NOT collapse inter-word whitespace itself (though
        // the convert layer's `Vec<String>` join already single-spaces the common
        // path; this proves the messier single-string shape is safe too).
        let clean = restore_address(VECTOR_PHRASE_24).await;
        // the SAME 24 words, but with a double space, a tab, and a newline injected
        // between words (the abandon×23 + art vector — word boundaries preserved).
        let messy = "abandon  abandon\tabandon abandon\nabandon abandon abandon abandon \
                     abandon abandon abandon abandon abandon abandon abandon abandon \
                     abandon abandon abandon abandon abandon abandon abandon art";
        let messy_addr = restore_address(messy).await;
        assert_eq!(
            clean, messy_addr,
            "extra inter-word whitespace must derive the SAME wallet (same funds)"
        );
    }

    #[tokio::test]
    async fn restore_tolerates_leading_and_trailing_whitespace() {
        // The soft-keyboard / paste edge: a leading or trailing space (or padding)
        // on the WHOLE phrase. `parse_in_normalized` ignores surrounding whitespace,
        // so a padded phrase restores to the SAME address — the host need not trim
        // the phrase ends. CHARACTERIZED + PINNED.
        let clean = restore_address(VECTOR_PHRASE_24).await;
        let padded = format!("   {VECTOR_PHRASE_24}   ");
        let padded_addr = restore_address(&padded).await;
        assert_eq!(
            clean, padded_addr,
            "leading/trailing whitespace must derive the SAME wallet (same funds)"
        );
    }

    #[tokio::test]
    async fn restore_rejects_uppercase_words_so_the_host_must_lowercase() {
        // ★ THE LOAD-BEARING UI QUESTION: does `parse_in_normalized` accept
        // mixed/upper case? CHARACTERIZED ANSWER — NO. The BIP39 English word list is
        // lowercase; `parse_in_normalized` does NOT case-fold, so an uppercase word is
        // an `UnknownWord` carrying its INDEX (never silently re-cased). A soft
        // keyboard that auto-capitalizes the FIRST word (`"Abandon …"`) therefore makes
        // an otherwise-correct backup fail to restore.
        //
        // ⇒ HOST CONTRACT (restore UI): the host MUST lowercase every word BEFORE
        //   crossing the FFI `restore`. The SDK does NOT case-fold for it — that is a
        //   deliberate audited-crate behavior (a typed reject, never a wrong wallet),
        //   so the fix lives in the UI's input normalization, asserted here so a future
        //   bip39 change that started case-folding (or a host that stopped lowercasing)
        //   is caught by a failing test, not a stranded user.
        let dir = tempfile::tempdir().expect("tempdir");
        // first word capitalized by autocorrect; second SHOUTED; rest correct.
        let cased = "Abandon ABANDON abandon abandon abandon abandon abandon abandon \
                     abandon abandon abandon abandon abandon abandon abandon abandon \
                     abandon abandon abandon abandon abandon abandon abandon art";
        match Wallet::create_with_vault(
            cfg(dir.path(), Network::Main, SeedPersistence::SealedKeychain),
            SeedSource::mnemonic(cased.to_owned(), None),
            test_vault(),
        )
        .await
        {
            Ok(_) => panic!(
                "uppercase words restored a wallet — bip39 began case-folding; \
                 the host's lowercase-before-restore contract may now be redundant \
                 (update this characterization + the restore-UI doc deliberately)"
            ),
            // index 0 is the first (capitalized) word — the §6.1 index-only error.
            Err(WalletError::InvalidMnemonic {
                word_index: Some(0),
            }) => {}
            Err(other) => panic!(
                "expected InvalidMnemonic at word_index 0 for an uppercase word, got {}",
                other.code()
            ),
        }
    }

    #[tokio::test]
    async fn reveal_mnemonic_refuses_on_a_closing_or_wiped_wallet() {
        // SECURITY (the key crossing's lifecycle gate): `require_open()` runs FIRST,
        // so a wallet that WOULD reveal (SealedKeychain + a stored phrase) still
        // refuses once it is tearing down — Closing ⇒ WalletBusy, Wiped ⇒
        // InvalidState. A crypto-shredded (Wiped, post-kill-switch §6.3) wallet must
        // NEVER hand back the seed words. The generic require_open table test exists;
        // this pins it THROUGH reveal — the path a dropped `require_open` line would
        // silently regress into a seed leak.
        use crate::lifecycle::LifecyclePhase;
        let dir = tempfile::tempdir().expect("tempdir");
        let w = Wallet::create_with_vault(
            cfg(dir.path(), Network::Main, SeedPersistence::SealedKeychain),
            SeedSource::mnemonic(VECTOR_PHRASE_24.to_owned(), None),
            test_vault(),
        )
        .await
        .expect("create with phrase");
        // sanity: it WOULD reveal while Open — so the rejections below are the
        // lifecycle gate, not a missing phrase.
        assert_eq!(w.reveal_mnemonic().expect("reveal while open").len(), 24);

        w.inner
            .lifecycle
            .transition(LifecyclePhase::Closing)
            .expect("→ Closing");
        assert!(
            matches!(
                w.reveal_mnemonic(),
                Err(WalletError::WalletBusy {
                    phase: LifecyclePhase::Closing
                })
            ),
            "reveal on a closing wallet is WalletBusy, never the words"
        );

        w.inner
            .lifecycle
            .transition(LifecyclePhase::Wiped)
            .expect("→ Wiped");
        assert!(
            matches!(
                w.reveal_mnemonic(),
                Err(WalletError::InvalidState {
                    phase: LifecyclePhase::Wiped
                })
            ),
            "a crypto-shredded wallet NEVER reveals the seed words"
        );
        drop(w);
    }

    #[tokio::test]
    async fn reveal_mnemonic_survives_a_close_and_reopen() {
        // REVEAL AFTER RESTART — SealedKeychain's whole purpose (§2.2/§4.2a). On
        // close the held phrase is dropped/zeroized; on the NEXT open it must be
        // RE-HELD by unsealing the stored blob (resolve_seed → seal → store →
        // unseal → Inner.seed → reveal). The other reveal tests all read a freshly
        // CREATED wallet's held phrase; THIS pins the round-trip a user hits every
        // time they reopen the app to view their recovery phrase — the path whose
        // failure mode is "your backup button shows nothing after a restart". Same
        // vault across the lifetime (the wrap key lives in it).
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let expected: Vec<&str> = VECTOR_PHRASE_24.split_whitespace().collect();

        let w = Wallet::create_with_vault(
            cfg(dir.path(), Network::Main, SeedPersistence::SealedKeychain),
            SeedSource::mnemonic(VECTOR_PHRASE_24.to_owned(), None),
            Arc::clone(&vault),
        )
        .await
        .expect("create");
        assert_eq!(
            w.reveal_mnemonic()
                .expect("reveal at create")
                .iter()
                .map(|w| w.as_str())
                .collect::<Vec<_>>(),
            expected
        );
        w.close().await.expect("close");

        // Reopen the now-completed wallet — the phrase is re-held via unseal.
        let reopened = Wallet::open_with_vault(
            cfg(dir.path(), Network::Main, SeedPersistence::SealedKeychain),
            Arc::clone(&vault),
        )
        .await
        .expect("reopen");
        assert_eq!(
            reopened
                .reveal_mnemonic()
                .expect("reveal after reopen")
                .iter()
                .map(|w| w.as_str())
                .collect::<Vec<_>>(),
            expected,
            "the recovery phrase must survive a close→reopen (reveal-after-restart)"
        );
        reopened.close().await.expect("close again");
    }

    #[tokio::test]
    async fn reveal_mnemonic_survives_restart_for_a_generated_wallet() {
        // `Generate` is a DISTINCT `resolve_seed` code path from `Mnemonic` (the
        // phrase is built from OsRng entropy via `from_entropy_in().to_string()`,
        // not `parse_in_normalized`) AND it is the PRODUCTION create path
        // (createGenerated). A regression that sealed the phrase only for the
        // `Mnemonic` arm would pass every other test yet lose a generated wallet's
        // backup after the first app restart — the worst money bug in this slice.
        // So pin the generated-wallet restart explicitly: same words AND same
        // wallet identity (default UA) across close→reopen.
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();

        let w = Wallet::create_with_vault(
            cfg(dir.path(), Network::Main, SeedPersistence::SealedKeychain),
            SeedSource::generate(),
            Arc::clone(&vault),
        )
        .await
        .expect("create generated");
        let words_at_create: Vec<String> = w
            .reveal_mnemonic()
            .expect("reveal at create")
            .iter()
            .map(|w| w.to_string())
            .collect();
        assert_eq!(words_at_create.len(), 24);
        let addr_at_create = w
            .current_address()
            .await
            .expect("address")
            .encoded()
            .to_owned();
        w.close().await.expect("close");

        let reopened = Wallet::open_with_vault(
            cfg(dir.path(), Network::Main, SeedPersistence::SealedKeychain),
            Arc::clone(&vault),
        )
        .await
        .expect("reopen");
        let words_after: Vec<String> = reopened
            .reveal_mnemonic()
            .expect("reveal after reopen")
            .iter()
            .map(|w| w.to_string())
            .collect();
        let addr_after = reopened
            .current_address()
            .await
            .expect("address")
            .encoded()
            .to_owned();
        assert_eq!(
            words_after, words_at_create,
            "a generated wallet's recovery phrase must survive a restart"
        );
        assert_eq!(
            addr_after, addr_at_create,
            "and the wallet identity is unchanged across the restart"
        );
        reopened.close().await.expect("close again");
    }

