    #[tokio::test]
    async fn current_address_after_import_equals_offline_derivation() {
        // §8 (the crypto audit S16 forward-owed): after account import,
        // `current_address` reads the DB account UFVK and the UA byte-equals the
        // offline `derive_default_address` for the same seed — the {account 0,
        // Require/Require/Omit, default diversifier} triple. Import is idempotent.
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let seed_bytes = vec![0x24u8; 32];

        let w = Wallet::create_with_vault(
            cfg(dir.path(), Network::Test, SeedPersistence::SealedKeychain),
            SeedSource::raw_bytes(seed_bytes.clone()).expect("seed"),
            Arc::clone(&vault),
        )
        .await
        .expect("create");

        // before import: the offline shortcut (SealedKeychain held seed)
        let pre = w.current_address().await.expect("pre-import address");

        w.import_account(testnet_birthday()).await.expect("import");
        w.import_account(testnet_birthday())
            .await
            .expect("re-import is a no-op");

        // Prove the DB ACCOUNT path is LIVE — not the seed fallback masking a broken
        // read. Read the stored-account UFVK directly (no seed involved); it must be
        // present and equal the offline derivation. Without this, `current_address`
        // in SealedKeychain mode would still go green via the held-seed fallback even
        // if import were a silent no-op (crypto audit S20 test-tightness fold).
        let expected = derive_default_address(Network::Test, &seed_bytes).expect("derive");
        // test-only: a std Mutex lock + sync DB read directly in an async test body
        // is acceptable for a fast assertion; production async fns NEVER do this —
        // they delegate every lock+DB op to `spawn_blocking` (see `current_address`).
        let from_db = {
            let guard = w.inner.db.lock().expect("db mutex");
            account::account_default_address(&guard.db, Network::Test).expect("db read")
        };
        assert_eq!(
            from_db.as_deref(),
            Some(expected.as_str()),
            "the stored-account UFVK yields the default UA with NO seed — and it equals \
             the offline derivation (equality by construction, §3.2b)"
        );

        // and `current_address` (which prefers the DB path) returns that same UA
        let post = w.current_address().await.expect("post-import address");
        assert_eq!(
            post.encoded(),
            expected,
            "current_address reads the stored account"
        );
        assert_eq!(
            pre.encoded(),
            post.encoded(),
            "the offline shortcut already matched the account it would import"
        );
        w.close().await.expect("close");
    }

