    #[tokio::test]
    async fn provision_resolves_birthday_and_imports_account() {
        // §8 (end-to-end, §3.2f): `provision_account` resolves the birthday from
        // the BUNDLED frontier (a fake oracle — NO live frontier, NO real network)
        // and imports account 0; the stored UA byte-equals the offline derivation.
        // Idempotent (a second provision is a no-op via the import guard).
        use crate::provision::testing::FakeOracle;
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let seed_bytes = vec![0x24u8; 32];

        let w = Wallet::create_with_vault(
            cfg(dir.path(), Network::Test, SeedPersistence::SealedKeychain),
            SeedSource::raw_bytes(seed_bytes.clone()).expect("seed"),
            Arc::clone(&vault),
        )
        .await
        .expect("create");

        // no account before provisioning
        let pre = {
            let g = w.inner.db.lock().expect("db mutex");
            account::account_default_address(&g.db, Network::Test).expect("db read")
        };
        assert!(pre.is_none(), "no account before provisioning");
        // (#356-F4 wiring pin) a supplied-seed create is a possible RESTORE —
        // it must never carry a creation stamp end-to-end.
        assert_eq!(w.inner.created_at, None, "a raw-bytes create never stamps");

        let mut oracle = FakeOracle::honest(Network::Test, 3_000_000);
        w.provision_account(&mut oracle, None)
            .await
            .expect("provision");
        w.provision_account(&mut oracle, None)
            .await
            .expect("re-provision is a no-op");

        // the provisioned account UA equals the offline derivation (the account
        // was imported at the bundle-resolved birthday — birthday doesn't affect
        // the UA, which derives from the UFVK).
        let expected = derive_default_address(Network::Test, &seed_bytes).expect("derive");
        let from_db = {
            let g = w.inner.db.lock().expect("db mutex");
            account::account_default_address(&g.db, Network::Test).expect("db read")
        };
        assert_eq!(
            from_db.as_deref(),
            Some(expected.as_str()),
            "provisioned account UA == offline derivation (no live frontier touched)"
        );
        w.close().await.expect("close");
    }

    #[tokio::test]
    async fn provision_partial_rpc_failure_writes_no_account_then_retry_converges() {
        // §8 (unstable-network 3-lens): the most common real-world first-sync flow.
        // A mid-provision RPC fault (identity OK, tip FAILS) surfaces typed Sync AND
        // writes NO account (the DB write happens strictly after a full resolve); a
        // retry on the healed link converges to exactly ONE correct account.
        use crate::provision::testing::FakeOracle;
        use crate::state::StallReason;
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let seed_bytes = vec![0x24u8; 32];
        let w = Wallet::create_with_vault(
            cfg(dir.path(), Network::Test, SeedPersistence::SealedKeychain),
            SeedSource::raw_bytes(seed_bytes.clone()).expect("seed"),
            Arc::clone(&vault),
        )
        .await
        .expect("create");

        // identity succeeds, the SECOND call (tip) faults → typed Sync, no account
        let mut oracle = FakeOracle::honest(Network::Test, 3_000_000);
        oracle.tip_err = Some(crate::net::grpc::GrpcError::Timeout {
            stall: StallReason::EndpointUnreachable,
        });
        let r = w.provision_account(&mut oracle, None).await;
        assert!(
            matches!(r, Err(WalletError::Sync { .. })),
            "partial failure is typed Sync, got {r:?}"
        );
        let after_fail = {
            let g = w.inner.db.lock().expect("db mutex");
            account::account_default_address(&g.db, Network::Test).expect("db read")
        };
        assert!(after_fail.is_none(), "a failed provision writes NO account");

        // the link heals (tip_err auto-cleared via take()): retry converges
        w.provision_account(&mut oracle, None)
            .await
            .expect("retry on the healed link provisions");
        let expected = derive_default_address(Network::Test, &seed_bytes).expect("derive");
        let healed = {
            let g = w.inner.db.lock().expect("db mutex");
            account::account_default_address(&g.db, Network::Test).expect("db read")
        };
        assert_eq!(
            healed.as_deref(),
            Some(expected.as_str()),
            "retry converges to exactly one correct account"
        );
        w.close().await.expect("close");
    }

