    #[tokio::test]
    async fn restore_shaped_repair_over_a_fresh_remnant_clears_the_stamp() {
        // §8 (crypto audit MED-1, probe-proven pre-fix): a FreshRawBytes
        // create killed AFTER DbProvisioned leaves the stamp durable. The
        // documented doubt-recovery — retry the create with the PLAIN restore
        // shape — must deliver FULL restore semantics: the repair completion
        // CLEARS the inherited stamp (the downgrade un-stamp), so the wallet
        // is unstamped, stays lazy, and the first-sync birthday takes the
        // ACTIVATION floor — never the aborted attempt's ~creation floor
        // (pre-fix the probe measured ~stamp, ~2.7M blocks of pre-stamp
        // history invisible plus the #387 restore sweep suppressed).
        use crate::provision::testing::FakeOracle;
        use crate::store::{ProvisionStep, provision_with};
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let intent = ProvisionIntent {
            network: Network::Test,
            persistence: PersistenceKind::None,
            seed: None,
            repair_mode: RepairMode::NoSeed,
            freshly_generated_at: Some(1_751_000_000),
        };
        let mut hook = |step: ProvisionStep| -> Result<(), WalletError> {
            if step == ProvisionStep::DbProvisioned {
                Err(WalletError::Io(std::io::Error::other("kill")))
            } else {
                Ok(())
            }
        };
        let _ = provision_with(dir.path(), &*vault, &intent, &mut hook);

        // The host stopped attesting: plain restore-shaped retry.
        let w = Wallet::create_with_vault(
            cfg(dir.path(), Network::Test, SeedPersistence::None),
            SeedSource::raw_bytes(vec![0x55u8; 32]).expect("valid"),
            Arc::clone(&vault),
        )
        .await
        .expect("restore-shaped retry completes via NoSeed repair");
        assert!(
            w.inner.created_at.is_none(),
            "the downgrade repair cleared the aborted fresh attempt's stamp"
        );
        assert!(
            !w.account_exists().await.expect("account_exists"),
            "restore semantics restored — no eager import"
        );
        assert!(!w.inner.freshly_generated, "handle is restore-shaped");

        // End-to-end: the lazy first-sync birthday takes the ACTIVATION floor,
        // not the dead stamp's estimate (the money assertion the audit probe
        // measured failing pre-fix).
        let mut oracle = FakeOracle::honest(Network::Test, 3_000_000);
        let birthday = provision::resolve_birthday(
            &mut oracle,
            Network::Test,
            None,
            w.inner.freshly_generated,
            w.inner.created_at,
        )
        .await
        .expect("lazy resolve");
        assert_eq!(
            u32::from(birthday.height()),
            checkpoints::activation_height(Network::Test) + 1,
            "unstamped restore floors at activation — the full-history scan"
        );
        w.close().await.expect("close");
    }

