    // ── Recv-2b transparent UTXO detection (§3.3a) ────────────────────────────────

    /// A scripted [`sync::TransparentUtxoSource`] — returns canned records (or a transport fault)
    /// with NO live gRPC, and records the addresses it was queried with (so a test can assert the
    /// refresh polls the RIGHT address — the wallet's own receive address).
    struct FakeUtxoSource {
        records: Vec<crate::transparent::TransparentUtxoRecord>,
        fail: bool,
        calls: usize,
        last_addresses: Vec<String>,
    }

    impl FakeUtxoSource {
        fn ok(records: Vec<crate::transparent::TransparentUtxoRecord>) -> Self {
            Self {
                records,
                fail: false,
                calls: 0,
                last_addresses: Vec::new(),
            }
        }
        fn failing() -> Self {
            Self {
                records: Vec::new(),
                fail: true,
                calls: 0,
                last_addresses: Vec::new(),
            }
        }
    }

    #[async_trait::async_trait]
    impl sync::TransparentUtxoSource for FakeUtxoSource {
        async fn address_utxos(
            &mut self,
            addresses: Vec<String>,
            _start_height: u64,
        ) -> Result<Vec<crate::transparent::TransparentUtxoRecord>, crate::net::grpc::GrpcError>
        {
            self.calls += 1;
            self.last_addresses = addresses;
            if self.fail {
                Err(crate::net::grpc::GrpcError::Transport {
                    stall: StallReason::EndpointUnreachable,
                })
            } else {
                Ok(self.records.clone())
            }
        }
    }

    /// The raw scriptPubKey bytes that pay `addr` — built from the AUDITED
    /// `TransparentAddress::script()` (so the test never hand-rolls a script).
    fn script_paying(addr: &zcash_transparent::address::TransparentAddress) -> Vec<u8> {
        zcash_transparent::address::Script::from(addr.script()).0.0
    }

    /// Decode the wallet's encoded receive t-address back to a typed `TransparentAddress` (to
    /// build the paying script the fake endpoint returns).
    fn decode_taddr(s: &str) -> zcash_transparent::address::TransparentAddress {
        match zcash_keys::address::Address::decode(&zcash_protocol::consensus::TEST_NETWORK, s) {
            Some(zcash_keys::address::Address::Transparent(t)) => t,
            other => panic!("expected a transparent address, got {other:?}"),
        }
    }

    /// Provision a wallet, sync once over `FakeChain` (records the chain tip — `put` needs it),
    /// and return the wallet plus its decoded transparent receive address.
    async fn synced_wallet_with_taddr(
        dir: &std::path::Path,
        vault: &Arc<dyn KeychainPort>,
    ) -> (
        Wallet,
        String,
        zcash_transparent::address::TransparentAddress,
    ) {
        use crate::sync::CancelToken;
        use crate::sync::testing::FakeChain;
        let w = wallet_with_chain_account(dir, vault).await;
        let mut client = FakeChain::to_tip(281_000);
        let cancel = CancelToken::new();
        w.sync_once(&mut client, &cancel, NOOP_PROGRESS)
            .await
            .expect("sync records the chain tip");
        // `sync_once` is the SCAN half; production reaches it through
        // `run_engine_pass`, which evaluates the consensus verdict first. A
        // test driving `sync_once` directly skips that, so give the handle the
        // verdict a really-synced wallet would hold.
        w.seed_current_consensus_for_test();
        let addr = w
            .current_transparent_address()
            .await
            .expect("receive t-address");
        let taddr = decode_taddr(&addr);
        (w, addr, taddr)
    }

    // ── §3.3 tx-enhancement (memo recovery) ──────────────────────────────────────

    /// A scripted [`crate::enhance::TransactionFetcher`] — counts its calls with NO live gRPC, so
    /// a test can assert an empty backlog never touches the network. The full fetch→decrypt→memo
    /// ride needs a real scanned receive + a real full tx (device-gated); the §4.6 parse/validate
    /// + the filter/bound/deferral + the drain-loop runtime are unit-tested directly in `enhance.rs`.
    #[derive(Default)]
    struct FakeFetcher {
        calls: usize,
    }

    #[async_trait::async_trait]
    impl crate::enhance::TransactionFetcher for FakeFetcher {
        async fn fetch_transaction(
            &mut self,
            _txid: zcash_protocol::TxId,
        ) -> Result<Option<crate::enhance::FetchedTransaction>, crate::net::grpc::GrpcError>
        {
            self.calls += 1;
            Ok(None)
        }
    }

    #[tokio::test]
    async fn enhance_transactions_is_a_silent_no_op_on_an_empty_backlog() {
        // A synced wallet with no received SHIELDED notes has no enhancement/get-status request;
        // any transparent `TransactionsInvolvingAddress` request is DEFERRED. So the bounded
        // batch is empty: nothing is attempted, the network is never touched, and the §5.4 span
        // stays silent (`did_work() == false`). Proves the real method's wiring + the transparent
        // deferral end-to-end on the common idle path (the full fetch→decrypt ride is device-gated).
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let (w, _, _) = synced_wallet_with_taddr(dir.path(), &vault).await;
        let mut fetcher = FakeFetcher::default();
        let ticks = Mutex::new(0usize);
        let out = w
            .enhance_transactions(&mut fetcher, &|| *ticks.lock().expect("ticks") += 1)
            .await
            .expect("enhance");
        assert_eq!(
            out,
            crate::enhance::EnhancementOutcome::default(),
            "no txid-keyed requests ⇒ nothing attempted",
        );
        assert!(
            !out.did_work(),
            "an empty batch does no work (the span stays silent)"
        );
        assert_eq!(fetcher.calls, 0, "an empty backlog never hits the network");
        assert_eq!(
            *ticks.lock().expect("ticks"),
            0,
            "the watchdog-liveness tick never fires on an idle/empty backlog",
        );
    }

    #[tokio::test]
    async fn refresh_transparent_utxos_detects_a_receive_and_surfaces_the_balance() {
        // §8 (Recv-2b end-to-end money path): a transparent UTXO paying the wallet's OWN receive
        // address, returned by the poll, is validated + put + surfaces in `BalanceSnapshot.transparent`
        // — the whole detection chain through the REAL engine. Also asserts the refresh queried the
        // wallet's own receive address (not some other).
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let (w, addr, taddr) = synced_wallet_with_taddr(dir.path(), &vault).await;
        // #387: floor-shape the aux (see strip_restore_seed) — this test pins the
        // MINIMAL scoped poll set (index-0 alone).
        strip_restore_seed(&w.inner);

        let record = crate::transparent::TransparentUtxoRecord {
            txid: vec![0x07; 32],
            index: 0,
            script: script_paying(&taddr),
            value_zat: 50_000,
            height: 281_000,
        };
        let mut src = FakeUtxoSource::ok(vec![record]);
        let out = w
            .refresh_transparent_utxos(&mut src)
            .await
            .expect("refresh");
        assert_eq!(out.put, 1, "the receive UTXO is put");
        assert_eq!(out.rejected, 0, "nothing rejected");
        assert_eq!(
            src.last_addresses,
            vec![addr],
            "the poll queries the wallet's OWN receive address"
        );

        let bal = w.balance().await.expect("balance");
        assert_eq!(
            bal.transparent.zat(),
            50_000,
            "the detected transparent UTXO surfaces in BalanceSnapshot.transparent"
        );
        w.close().await.expect("close");
    }

    #[tokio::test]
    async fn refresh_transparent_utxos_is_idempotent_across_polls() {
        // §8 (money safety): re-polling the same unspent UTXO is an idempotent upsert — the balance
        // does NOT double. (Reliable detection over an unstable link means the same poll may repeat.)
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let (w, _addr, taddr) = synced_wallet_with_taddr(dir.path(), &vault).await;

        let record = crate::transparent::TransparentUtxoRecord {
            txid: vec![0x09; 32],
            index: 1,
            script: script_paying(&taddr),
            value_zat: 75_000,
            height: 281_000,
        };
        let mut src = FakeUtxoSource::ok(vec![record]);
        w.refresh_transparent_utxos(&mut src).await.expect("poll 1");
        w.refresh_transparent_utxos(&mut src).await.expect("poll 2");

        let bal = w.balance().await.expect("balance");
        assert_eq!(
            bal.transparent.zat(),
            75_000,
            "the same UTXO across two polls counts ONCE (idempotent upsert), never doubled"
        );
        w.close().await.expect("close");
    }

    #[tokio::test]
    async fn refresh_transparent_utxos_rejects_a_foreign_address_utxo() {
        // THE M2 lying-endpoint defense, end-to-end: a structurally-valid UTXO paying a DIFFERENT
        // address (not ours) is rejected at validation — never put, so the balance stays zero. A
        // phantom balance of unspendable funds can never appear.
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let (w, _addr, _taddr) = synced_wallet_with_taddr(dir.path(), &vault).await;

        let foreign = zcash_transparent::address::TransparentAddress::PublicKeyHash([0x99; 20]);
        let record = crate::transparent::TransparentUtxoRecord {
            txid: vec![0x0A; 32],
            index: 0,
            script: script_paying(&foreign),
            value_zat: 1_000_000,
            height: 281_000,
        };
        let mut src = FakeUtxoSource::ok(vec![record]);
        let out = w
            .refresh_transparent_utxos(&mut src)
            .await
            .expect("refresh");
        assert_eq!(out.put, 0, "a foreign-address UTXO is never put");
        assert_eq!(out.rejected, 1, "it is counted as rejected");

        let bal = w.balance().await.expect("balance");
        assert_eq!(
            bal.transparent.zat(),
            0,
            "a UTXO we do not own never inflates the transparent balance"
        );
        w.close().await.expect("close");
    }

