    #[tokio::test]
    async fn sweep_ephemeral_funds_attempts_a_funded_economic_ephemeral() {
        // §3.2i-2 2e-2b-v-2 ORCHESTRATION over a funded ephemeral: a 50_000-zat return on a reserved
        // ephemeral — BELOW the 0.001-ZEC convenience shield threshold (so the automatic surface leaves
        // it stranded) but ABOVE the ZIP-317 fee — is ENUMERATED (wide window) and ATTEMPTED: propose
        // returns Some at the economic floor, so the per-ephemeral disposition is swept XOR failed,
        // NEVER a silent `Nothing`. The POSITIVE swept+recovered path needs a provable note-commitment
        // tree — proven at the send.rs money core with the REAL prover
        // (`sweep_recovers_below_the_shield_threshold…`); over the FakeChain harness (which cannot build
        // a spendable provable tree — the funded end-to-end is device-/harness-gated, like EVERY
        // wallet-level real-prove) the sign is COUNT+SKIP-isolated as `failed`. This pins the
        // money-SAFETY at the wallet layer: a non-swept ephemeral recovers NOTHING + leaves no
        // half-finished tally, and a per-ephemeral fault never propagates or panics.
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let (w, _addr, _taddr) = synced_wallet_with_taddr(dir.path(), &vault).await;
        let eph = reserve_one_ephemeral(&w).await;

        let record = crate::transparent::TransparentUtxoRecord {
            txid: vec![0x51; 32],
            index: 0,
            script: script_paying(&eph),
            value_zat: 50_000,
            height: 281_000,
        };
        let probe = FakeEphemeralProbe::returning(eph, vec![record]);
        let broadcaster = FakeBroadcaster::accepting();

        let summary = w
            .sweep_ephemeral_funds_with(&probe, &broadcaster)
            .await
            .expect("sweep completes without propagating a per-ephemeral fault");
        assert_eq!(
            summary.scanned, 1,
            "the one reserved ephemeral is enumerated (wide window)"
        );
        assert_eq!(summary.truncated, 0, "well within the cap");
        assert_eq!(
            summary.swept + summary.failed,
            1,
            "a funded + economic ephemeral is ATTEMPTED — swept XOR failed, never a silent Nothing",
        );
        // §5.4 + money honesty (robust whether the harness can prove the sign or not): funds are
        // claimed ONLY on a real swept+ACCEPTED tx; a non-swept ephemeral recovers nothing.
        if summary.swept == 1 {
            assert!(
                summary.recovered_zat > 0 && summary.recovered_zat < 50_000,
                "recovered = gross − fee, got {}",
                summary.recovered_zat,
            );
            assert_eq!(
                broadcaster.call_count(),
                1,
                "one sweep tx broadcast on the accepted path"
            );
        } else {
            assert_eq!(
                summary.recovered_zat, 0,
                "a non-swept ephemeral recovers nothing (honest)"
            );
        }
        w.close().await.expect("close");
    }

