    // ── R12 §4.5: the wallet's doors and the pass under REAL store faults ────────
    //
    // An open wallet holds two connections to its WAL file (the engine's and the
    // aux store's), and in WAL each keeps a SHARED lock for as long as it is open —
    // so no other connection can ever take the lock that refuses readers. The
    // fixture swaps both for fresh keyed connections that have not read the file
    // (`test_support`, with the short `R12_BUSY_WAIT`) and only then takes the
    // lock. This reaches into `Inner` from test code; no production knob is added.

    /// Swap the open wallet's engine and aux connections for unread ones, then hold
    /// the lock that refuses every reader (drop the returned connection to release).
    fn lock_the_wallet_file_under(w: &Wallet, dir: &std::path::Path) -> rusqlite::Connection {
        let path = dir.join(crate::constants::WALLET_DB_FILE_NAME);
        let mut db = w.inner.db.lock().expect("wallet db mutex poisoned");
        let mut aux = w.inner.aux_db.lock().expect("wallet aux-db mutex poisoned");
        let engine =
            crate::test_support::wallet_conn_that_has_not_read(&path, &db.db_key, w.inner.network);
        let aux_conn = crate::test_support::keyed_connection_that_has_not_read(&path, &db.db_key);
        db.db = engine;
        *aux = aux_conn;
        crate::test_support::hold_the_wallet_file_locked(&path, &db.db_key)
    }

    /// R12 §4.5 test 2 — the wallet door: `scanned_tip` (the first store read of
    /// every pass, via `evaluate_consensus`) under a held lock is `StoreBusy`, never
    /// the blind `StoreCorrupt`, and reads once the lock is gone.
    #[tokio::test]
    async fn scanned_tip_under_a_held_lock_is_store_busy_not_corruption() {
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let w = wallet_with_chain_account(dir.path(), &vault).await;
        let blocker = lock_the_wallet_file_under(&w, dir.path());

        let got = w.scanned_tip().await;
        assert!(
            matches!(got, Err(WalletError::StoreBusy)),
            "R12: a held lock at `scanned_tip` must reach the pass as StoreBusy, never the \
             blind StoreCorrupt; got {got:?}"
        );

        drop(blocker);
        assert_eq!(
            w.scanned_tip()
                .await
                .expect("released, the same door reads"),
            None,
            "a wallet that never scanned has no scanned tip — and the lock damaged nothing"
        );
        w.close().await.expect("close");
    }

    /// **R12 §4.5 test 5 — the pass.** Two consecutive passes that meet a held lock
    /// at an every-pass door (`scanned_tip`, the first store read `evaluate_consensus`
    /// makes) publish `Stalled { StorageUnavailable }` — "retrying" — and never
    /// `Internal`, the restore-from-your-recovery-phrase copy R10's gate reserves for
    /// a store that IS corrupt. Through the shipped pass body (`controller_over`, the
    /// real `LightdSyncEngine::run_pass`, the R10 loop gate), not a fake engine. RED
    /// before the sweep: the blind door says StoreCorrupt twice and the loop
    /// publishes `Internal`. Real time: the loop's one 1 s backoff between passes.
    #[tokio::test]
    async fn two_passes_that_meet_a_held_lock_publish_storage_unavailable_never_internal() {
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let w = wallet_with_chain_account(dir.path(), &vault).await;
        let blocker = lock_the_wallet_file_under(&w, dir.path());

        let ctl = w.controller_over(ScriptedPassClient::honest(FIX_TIP));
        let mut rx = ctl.subscribe();
        ctl.start();
        let first_stall = tokio::time::timeout(std::time::Duration::from_secs(60), async {
            loop {
                rx.changed().await.expect("the status channel stays open");
                let status = rx.borrow().clone();
                if let SyncStatus::Stalled { reason } = status {
                    return reason;
                }
            }
        })
        .await
        .expect("the loop publishes a stall within the bound (R10: after the second pass)");
        ctl.stop().await;
        drop(blocker);

        assert_eq!(
            first_stall,
            StallReason::StorageUnavailable,
            "R12 + R10: a held lock on two passes in a row is the transient \
             StorageUnavailable ('retrying'), never Internal — the restore copy is for a \
             store that is corrupt, and this one is only busy"
        );
        w.close().await.expect("close");
    }

    /// Make the engine's next write to `transparent_received_outputs` fail with a
    /// REAL `SQLITE_FULL`: the engine connection is swapped for one whose
    /// `max_page_count` is the file's current size, and a trigger on that table
    /// writes a 1 MiB ballast row first — so SQLite itself raises the full disk
    /// from the engine's own `put_received_transparent_utxo` (`transparent.rs`).
    fn fill_the_disk_at_the_next_utxo_write(w: &Wallet, dir: &std::path::Path) {
        let path = dir.join(crate::constants::WALLET_DB_FILE_NAME);
        let mut db = w.inner.db.lock().expect("wallet db mutex poisoned");
        let conn = crate::test_support::keyed_connection_that_has_not_read(&path, &db.db_key);
        conn.execute_batch(
            "CREATE TABLE r12_ballast (b BLOB NOT NULL);
             CREATE TRIGGER r12_fill BEFORE INSERT ON transparent_received_outputs
             BEGIN INSERT INTO r12_ballast VALUES (zeroblob(1048576)); END;",
        )
        .expect("fixture: the ballast trigger");
        let pages: i64 = conn
            .query_row("PRAGMA page_count", [], |r| r.get(0))
            .expect("page count");
        let ceiling: i64 = conn
            .query_row(&format!("PRAGMA max_page_count = {pages}"), [], |r| {
                r.get(0)
            })
            .expect("set the page ceiling");
        assert_eq!(
            ceiling, pages,
            "fixture: the ceiling is the file's current size"
        );
        // The fixture proves itself: the ballast write the trigger makes is a real
        // SQLITE_FULL on this connection (read off the raw rusqlite code), so a door
        // that then reports anything else is the door's classification, not the fixture.
        match conn.execute("INSERT INTO r12_ballast VALUES (zeroblob(1048576))", []) {
            Err(rusqlite::Error::SqliteFailure(e, _))
                if e.code == rusqlite::ErrorCode::DiskFull => {}
            other => panic!("fixture: the ballast write must be SQLITE_FULL, got {other:?}"),
        }
        db.db = zcash_client_sqlite::WalletDb::from_connection(
            conn,
            w.inner.network.consensus(),
            zcash_client_sqlite::util::SystemClock,
            rand_core::OsRng,
        );
    }

    /// **R12 §4.2 / §4.5 test 8 (b).** A full disk on a sweep item ABORTS the run
    /// with `DiskFull`: `DiskFull` joins the sweep's hard-fault list (a full disk
    /// does not self-resolve on re-run, and failing every item silently never
    /// tells the user why). The fault is real — SQLite's `SQLITE_FULL` from the
    /// engine's UTXO write at `recognise_ephemeral_outputs` — and nothing is
    /// broadcast. RED before the sweep: that door mapped it blind to StoreCorrupt.
    #[tokio::test]
    async fn a_full_disk_on_a_sweep_item_aborts_the_run_with_disk_full() {
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let (w, _addr, _taddr) = synced_wallet_with_taddr(dir.path(), &vault).await;
        let eph = reserve_one_ephemeral(&w).await;
        let record = crate::transparent::TransparentUtxoRecord {
            txid: vec![0x52; 32],
            index: 0,
            script: script_paying(&eph),
            value_zat: 50_000,
            height: 281_000,
        };
        let probe = FakeEphemeralProbe::returning(eph, vec![record]);
        let broadcaster = FakeBroadcaster::accepting();
        fill_the_disk_at_the_next_utxo_write(&w, dir.path());

        let got = w.sweep_ephemeral_funds_with(&probe, &broadcaster).await;
        assert!(
            matches!(got, Err(WalletError::DiskFull)),
            "R12 §4.2: a full disk on a sweep item aborts the run with DiskFull — not a silent \
             per-item `failed`, and never StoreCorrupt; got {got:?}"
        );
        assert_eq!(broadcaster.call_count(), 0, "nothing was broadcast");
        w.close().await.expect("close");
    }

    // ── §3.2i-2 2e-2b-vi (#315 slice 2): the Mechanism-A reclaim WIRING ──
    //
    // The pure deadness gate / highest-dead selection / mint-request are unit-tested in
    // `reclaim.rs`; the ENGINE mechanism (a mined self-mint on the highest leaked index reopens the
    // whole window) is proven at the send.rs money core (`self_mint_on_the_highest_leaked…`). These
    // pin the METHOD WIRING — enumerate → deadness gate → mint attempt — over a real `Wallet`. The
    // fully-successful `Minted` path (a real propose+sign+broadcast) needs a spendable provable
    // shielded tree, which the FakeChain harness cannot build (the same limitation the sweep's
    // positive path notes); so the funded arm is covered by the send.rs core + the device proof,
    // and here an unfunded dead target surfaces the honest `InsufficientFunds`.

    #[tokio::test]
    async fn reclaim_requires_a_signing_key() {
        // Structural pre-check (mirrors the sweep): a wallet that cannot derive a signing key
        // (a portless `None` wallet) can reclaim nothing — `SeedRequired` up front, before any
        // enumerate, never a silent no-op that hides a bricked window.
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let w =
            create_none_then_reopen_with_port(dir.path(), &vault, FR12_SENTINEL_SEED, None).await;
        let broadcaster = FakeBroadcaster::accepting();
        match w.reclaim_ephemeral_slots_with(&broadcaster).await {
            Err(WalletError::SeedRequired) => {}
            other => panic!("expected SeedRequired for a portless None wallet, got {other:?}"),
        }
        assert_eq!(broadcaster.call_count(), 0, "nothing minted without a key");
        w.close().await.expect("close");
    }

