    #[tokio::test]
    async fn reclaim_selects_a_dead_target_and_attempts_the_mint() {
        // The dead-target WIRING: reserve an ephemeral, then advance the tip PAST the deadness
        // margin so the reservation is provably dead. The reclaim then enumerates it, the deadness
        // gate PASSES, it is selected as the highest-dead target, and the mint is ATTEMPTED (propose
        // reached). Over the FakeChain harness the wallet holds NO spendable shielded notes, so the
        // propose surfaces the honest `InsufficientFunds` (the user needs funds to self-mint) — which
        // PROPAGATES. This pins enumerate → deadness-gate-passes → target-selected → mint-attempted
        // without needing a provable tree (the funded `Minted` arm is the send.rs core + device proof).
        use crate::sync::CancelToken;
        use crate::sync::testing::FakeChain;
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let (w, _addr, _taddr) = synced_wallet_with_taddr(dir.path(), &vault).await;
        let _eph = reserve_one_ephemeral(&w).await; // exposed at 281_000
        // Advance the chain tip comfortably past the deadness margin (141 blocks) so the reservation
        // is provably dead (its tx0, had one existed, is past-expiry AND buried).
        let dead_tip = 281_000 + crate::constants::EPHEMERAL_RECLAIM_DEADNESS_BLOCKS as u64 + 10;
        let mut client = FakeChain::to_tip(dead_tip);
        w.sync_once(&mut client, &CancelToken::new(), NOOP_PROGRESS)
            .await
            .expect("advance the tip");
        let broadcaster = FakeBroadcaster::accepting();
        match w.reclaim_ephemeral_slots_with(&broadcaster).await {
            Err(WalletError::InsufficientFunds { .. }) => {}
            other => panic!(
                "a provably-dead target must be selected + the mint attempted; an unfunded wallet \
                 surfaces InsufficientFunds, got {other:?}"
            ),
        }
        assert_eq!(
            broadcaster.call_count(),
            0,
            "the mint never signed (no funds) — nothing broadcast",
        );
        w.close().await.expect("close");
    }

    #[tokio::test]
    async fn reclaim_broadcast_accepted_is_minted() {
        // review A2/H2 — the POST-SIGN OUTCOME SELECTION the FakeChain harness cannot reach
        // through the funded sign path (every method test stops at InsufficientFunds). Drive the
        // extracted broadcast leg directly with a persisted-mint stand-in (fake items) + an ACCEPTING
        // endpoint ⇒ Minted (an honest "initiated"), and the endpoint IS hit exactly once.
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let (w, _addr, _taddr) = synced_wallet_with_taddr(dir.path(), &vault).await;
        let items = vec![(TxId::from_display_order([0x99; 32]), vec![0xAB; 64])];
        let amount = crate::constants::EPHEMERAL_RECLAIM_MINT_ZAT;
        let broadcaster = FakeBroadcaster::accepting();
        let out = w
            .finish_reclaim_broadcast(items, amount, &broadcaster)
            .await
            .expect("broadcast leg");
        assert_eq!(
            out,
            crate::reclaim::ReclaimOutcome::Minted {
                amount_zat: amount as i64
            },
            "endpoint acceptance ⇒ Minted",
        );
        assert_eq!(broadcaster.call_count(), 1, "the mint was broadcast once");
        w.close().await.expect("close");
    }

    #[tokio::test]
    async fn reclaim_broadcast_miss_is_not_broadcast() {
        // review A2/H2 — a broadcast that is NOT accepted (here a transport MISS: the endpoint is
        // never reached, `submit` returns Err) ⇒ NotBroadcast, never Minted. For a single-item reclaim
        // broadcast this is outcome-identical to a reached-but-rejected submit (both count accepted==0).
        // The persisted mint self-heals via expiry, so a re-run re-mints (money-safe).
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let (w, _addr, _taddr) = synced_wallet_with_taddr(dir.path(), &vault).await;
        let items = vec![(TxId::from_display_order([0x77; 32]), vec![0xCD; 64])];
        let amount = crate::constants::EPHEMERAL_RECLAIM_MINT_ZAT;
        let broadcaster = FakeBroadcaster::rejecting();
        let out = w
            .finish_reclaim_broadcast(items, amount, &broadcaster)
            .await
            .expect("broadcast leg");
        assert_eq!(
            out,
            crate::reclaim::ReclaimOutcome::NotBroadcast {
                amount_zat: amount as i64
            },
            "a broadcast miss ⇒ NotBroadcast (never Minted)",
        );
        assert_eq!(broadcaster.call_count(), 1, "the endpoint WAS attempted");
        w.close().await.expect("close");
    }

    #[tokio::test]
    async fn reclaim_broadcast_skips_a_closed_gate() {
        // review A2/H2 — the pre-broadcast open-gate RE-CHECK (a close()/wipe landing DURING the
        // ~seconds prove between the entry gate and broadcast). A closed gate ⇒ NotBroadcast AND the
        // endpoint is NEVER hit — the signed mint stays persisted and self-heals via expiry.
        use crate::lifecycle::LifecyclePhase;
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let (w, _addr, _taddr) = synced_wallet_with_taddr(dir.path(), &vault).await;
        // Simulate a close landing during the prove: flip the shared lifecycle to Closing.
        w.inner
            .lifecycle
            .transition(LifecyclePhase::Closing)
            .expect("Open → Closing");
        let items = vec![(TxId::from_display_order([0x55; 32]), vec![0xEF; 64])];
        let amount = crate::constants::EPHEMERAL_RECLAIM_MINT_ZAT;
        let broadcaster = FakeBroadcaster::accepting();
        let out = w
            .finish_reclaim_broadcast(items, amount, &broadcaster)
            .await
            .expect("broadcast leg");
        assert_eq!(
            out,
            crate::reclaim::ReclaimOutcome::NotBroadcast {
                amount_zat: amount as i64
            },
            "a gate closed during the prove ⇒ NotBroadcast",
        );
        assert_eq!(
            broadcaster.call_count(),
            0,
            "a closed gate is re-checked BEFORE broadcast — the endpoint is never hit",
        );
        // Already Closing — let the handle drop (close() would be an invalid Closing→Closing edge).
    }

    #[tokio::test]
    async fn reclaim_single_flight_no_ops_a_concurrent_call() {
        // review A3/H1 — the CORE-level single-flight so the fee-safety doesn't rest on the Dart
        // latch. With a reclaim already in flight (the flag held), a call that WOULD otherwise mint on
        // a provably-dead target no-ops (NothingToReclaim) and signs nothing. Contrast:
        // `reclaim_selects_a_dead_target_and_attempts_the_mint` (same setup, flag CLEAR) reaches
        // propose and surfaces InsufficientFunds — so a NothingToReclaim here proves the short-circuit.
        use crate::sync::CancelToken;
        use crate::sync::testing::FakeChain;
        use std::sync::atomic::Ordering;
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let (w, _addr, _taddr) = synced_wallet_with_taddr(dir.path(), &vault).await;
        let _eph = reserve_one_ephemeral(&w).await; // exposed at 281_000
        let dead_tip = 281_000 + crate::constants::EPHEMERAL_RECLAIM_DEADNESS_BLOCKS as u64 + 10;
        let mut client = FakeChain::to_tip(dead_tip);
        w.sync_once(&mut client, &CancelToken::new(), NOOP_PROGRESS)
            .await
            .expect("advance the tip");
        // Simulate a reclaim already in flight (another caller holds the single-flight).
        w.inner.reclaim_in_flight.store(true, Ordering::Release);
        let broadcaster = FakeBroadcaster::accepting();
        let out = w
            .reclaim_ephemeral_slots_with(&broadcaster)
            .await
            .expect("reclaim");
        assert_eq!(
            out,
            crate::reclaim::ReclaimOutcome::NothingToReclaim,
            "a concurrent reclaim holds the single-flight — this call no-ops before any mint work",
        );
        assert_eq!(
            broadcaster.call_count(),
            0,
            "no redundant mint while another reclaim is in flight",
        );
        assert!(
            w.inner.reclaim_in_flight.load(Ordering::Acquire),
            "the CAS-fail path must NOT clear a flag it never set — the simulated in-flight holder \
             still owns the single-flight after the no-op",
        );
        w.inner.reclaim_in_flight.store(false, Ordering::Release);
        w.close().await.expect("close");
    }

    // ── §3.2i-2 2e-2b-ii: the stranded SURFACE (list_stranded) + skip-funded + reap ──

    /// Reserve an ephemeral and RECOGNISE (put) a UTXO of `value_zat` at `height` on it via the
    /// isolated detect (a distinct `txid_tag` per call so two ephemerals never collide on the same
    /// outpoint). The shared setup for the list_stranded surface tests.
    async fn recognise_ephemeral_with_funds(
        w: &Wallet,
        txid_tag: u8,
        value_zat: i64,
        height: u64,
    ) -> zcash_transparent::address::TransparentAddress {
        let eph = reserve_one_ephemeral(w).await;
        let record = crate::transparent::TransparentUtxoRecord {
            txid: vec![txid_tag; 32],
            index: 0,
            script: script_paying(&eph),
            value_zat,
            height,
        };
        let probe = FakeEphemeralProbe::returning(eph, vec![record]);
        let summary = w
            .detect_ephemeral_utxos(&probe, &sync::CancelToken::new())
            .await
            .expect("detect");
        assert_eq!(summary.detected, 1, "the ephemeral UTXO is recognised");
        eph
    }

