    // ── FR-23-b (#361): the parked-authorizer drain ─────────────────────────────────────────
    // The verb signs an ALREADY-COMMITTED queued row at a user-present moment. These pin the
    // GUARDS and the honest outcome mapping; the sign body itself is the drain's own proven core
    // (`send::prepare_queued`, exercised over a funded engine harness in `send.rs`).

    #[tokio::test]
    async fn authorize_parked_send_pins_created_at_against_rowid_reuse() {
        // The `(id, created_at)` pin is the SAME identity fence `cancel_parked_send` /
        // `retry_parked_send` carry: SQLite rowids are reused after a delete, so a stale id the
        // user tapped must never authorize a DIFFERENT send. A miss is the idempotent `NotFound`
        // — never an error, and never a signature.
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let (w, _addr, _taddr) = synced_wallet_with_taddr(dir.path(), &vault).await;
        let id = w
            .queue_send(one_payment(Some(40_000)))
            .await
            .expect("queue");
        let parked = w.list_parked_sends().await.expect("list");
        assert_eq!(parked.len(), 1);
        let outcome = w
            .authorize_parked_send(id.value(), parked[0].created_at + 1)
            .await
            .expect("authorize");
        assert_eq!(
            outcome,
            crate::parked::ParkedAuthorization::NotFound,
            "a created_at mismatch authorizes NOTHING"
        );
        assert_eq!(
            w.list_parked_sends().await.expect("re-list").len(),
            1,
            "the row is untouched — still parked, still cancellable"
        );
        w.close().await.expect("close");
    }

    #[tokio::test]
    async fn authorize_parked_send_refuses_a_deposit_tagged_row() {
        // Surface alignment (mirrors cancel/retry): `list_parked_sends` EXCLUDES deposit rows, so
        // this verb refuses one even when handed its real `(id, created_at)`. The FR-23-a
        // sign-failure zombie's user-paced exit is the swap surface's own concern — not a hole
        // punched through the parked list.
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let (w, _addr, _taddr) = synced_wallet_with_taddr(dir.path(), &vault).await;
        let id = w
            .queue_deposit_send(
                transparent_test_addr(),
                Zatoshis::new(250_000).expect("amount"),
                1_900_000_000,
                None,
            )
            .await
            .expect("queue deposit");
        let created_at = {
            let guard = w.inner.aux_db.lock().expect("aux db");
            let rows = crate::intent_store::list_queued(&guard).expect("list");
            assert_eq!(rows.len(), 1);
            rows[0].created_at
        };
        let outcome = w
            .authorize_parked_send(id.value(), created_at)
            .await
            .expect("authorize");
        assert_eq!(
            outcome,
            crate::parked::ParkedAuthorization::NotFound,
            "a deposit row is not authorizable through the PARKED surface"
        );
        // Scoped, not `drop(guard)`: clippy's `await_holding_lock` reasons about the
        // guard's LEXICAL scope and does not credit an explicit drop, so the block is
        // what keeps the lint honest across the `close().await` below.
        {
            let guard = w.inner.aux_db.lock().expect("aux db");
            assert_eq!(
                crate::intent_store::list_queued(&guard)
                    .expect("list")
                    .len(),
                1,
                "the deposit stays durably queued — the refusal touched nothing"
            );
        }
        w.close().await.expect("close");
    }

    #[tokio::test]
    async fn authorize_parked_send_leaves_an_unsendable_row_durably_queued() {
        // The honesty arm that matters most: on a wallet with nothing spendable the authorization
        // resolves `StillQueued` — NOT an error and NOT a signature. The host's copy rule hangs
        // off exactly this ("still waiting", never "failed"): phrasing it as a failure invites the
        // user to re-enter the payment, which is a DOUBLE-PAY.
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let (w, _addr, _taddr) = synced_wallet_with_taddr(dir.path(), &vault).await;
        let id = w
            .queue_send(one_payment(Some(40_000)))
            .await
            .expect("queue");
        let parked = w.list_parked_sends().await.expect("list");
        let outcome = w
            .authorize_parked_send(id.value(), parked[0].created_at)
            .await
            .expect("authorize");
        assert_eq!(
            outcome,
            crate::parked::ParkedAuthorization::StillQueued,
            "nothing spendable ⇒ still waiting, not a fault"
        );
        let after = w.list_parked_sends().await.expect("re-list");
        assert_eq!(after.len(), 1, "the committed send is STILL parked");
        assert_eq!(after[0].id, id.value(), "…the same row, not a new one");
        w.close().await.expect("close");
    }

