    #[tokio::test]
    async fn queued_single_step_send_is_visible_and_cancellable_after_a_kill_and_reopen() {
        // #331, the exact previously-broken shape: offline-queue a SINGLE-STEP send, the process
        // dies (bare drop — no awaited close), the app relaunches still-offline. The committed
        // spend MUST be on the parked surface (pre-#331 it was on NO surface — the user re-enters
        // the payment and both drain on reconnect: a double pay) and cancellable from the
        // surfaced (id, created_at).
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let w = Wallet::create_with_vault(
            cfg(dir.path(), Network::Test, SeedPersistence::SealedKeychain),
            raw_seed(),
            Arc::clone(&vault),
        )
        .await
        .expect("create");
        let id = w
            .queue_send(one_payment(Some(250_000)))
            .await
            .expect("queue_send");
        drop(w); // the app-kill path

        let reopened = Wallet::open_with_vault(
            cfg(dir.path(), Network::Test, SeedPersistence::SealedKeychain),
            Arc::clone(&vault),
        )
        .await
        .expect("reopen after a bare drop");
        // NO sync edge has run — the read is a pure cold pull, the relaunch shape.
        let parked = reopened.list_parked_sends().await.expect("list");
        assert_eq!(
            parked.len(),
            1,
            "the committed spend is VISIBLE after the relaunch"
        );
        assert_eq!(parked[0].id, id.value());
        assert_eq!(parked[0].kind, crate::parked::ParkedSendKind::SingleStep);
        assert_eq!(parked[0].amount_zat, 250_000);
        assert!(
            !parked[0].sending,
            "an untouched queued row is not mid-signature"
        );

        // #400 R2 — THE SAME KILL, ONE STEP LATER. `mark_submitting` commits the claim before the
        // unbounded ZK prove, so an OOM kill during proving (the archetypal mobile case, and since
        // FR-23-b reachable by a user TAP) leaves the row `Submitting`. That row used to be on NO
        // surface at all — not here, not in the in-flight reader, not in activity — which is the
        // #331 double-pay shape this very test exists to close, one state further along.
        {
            let mut guard = reopened.inner.aux_db.lock().expect("aux db");
            assert!(
                crate::intent_store::mark_submitting(&mut guard, id, &[]).expect("claim"),
                "the row was still Queued"
            );
        }
        let parked = reopened.list_parked_sends().await.expect("list");
        assert_eq!(
            parked.len(),
            1,
            "a claimed-but-unrecorded spend is STILL visible"
        );
        assert!(
            parked[0].sending,
            "…and it is flagged mid-signature, so the host renders PREPARING and offers nothing"
        );
        assert_eq!(parked[0].amount_zat, 250_000);
        // Put it back so the cancel assertions below still describe a Queued row.
        {
            let mut guard = reopened.inner.aux_db.lock().expect("aux db");
            crate::intent_store::reset_to_queued(&mut guard, id).expect("reset");
        }

        // ... and cancellable — the escape hatch that closes the double-pay window.
        assert!(
            reopened
                .cancel_parked_send(parked[0].id, parked[0].created_at)
                .await
                .expect("cancel"),
            "the surfaced (id, created_at) cancels the queued single-step send"
        );
        assert!(
            reopened.list_parked_sends().await.expect("list").is_empty(),
            "cancelled ⇒ gone from the surface (and the queue — nothing drains later)"
        );
        reopened.close().await.expect("close");
    }

