    #[tokio::test]
    async fn cancel_parked_send_removes_it_from_the_parked_surface() {
        // The v-4a end-to-end: queue a TEX (it parks + surfaces), read its (id, created_at) the way the
        // host does, then cancel by that identity ⇒ the parked surface goes empty. A mismatched
        // created_at cancels NOTHING (the rowid-reuse identity pin); a re-cancel is a no-op (idempotent).
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let (w, _addr, _taddr) = synced_wallet_with_taddr(dir.path(), &vault).await;
        let id = w.queue_send(tex_payment(70_000)).await.expect("queue TEX");
        let parked = w.list_parked_sends().await.expect("list");
        assert_eq!(parked.len(), 1, "the queued TEX parks + surfaces");
        // The host passes back the ParkedSend's OWN (id, created_at) — the production flow. Pin that the
        // surfaced id round-trips from queue_send, then drive cancel from the surfaced values.
        let parked_id = parked[0].id;
        let created_at = parked[0].created_at;
        assert_eq!(
            parked_id,
            id.value(),
            "the surfaced id is the queued send's id"
        );

        // A mismatched created_at is a no-op — the parked send survives (the identity pin).
        assert!(
            !w.cancel_parked_send(parked_id, created_at + 1)
                .await
                .expect("mismatch"),
            "a wrong created_at cancels nothing"
        );
        assert_eq!(
            w.list_parked_sends().await.expect("list").len(),
            1,
            "the parked send survives a mismatched-identity cancel"
        );

        // The matching (id, created_at) cancels it ⇒ the surface goes empty.
        assert!(
            w.cancel_parked_send(parked_id, created_at)
                .await
                .expect("cancel"),
            "the matching identity cancels the parked send"
        );
        assert!(
            w.list_parked_sends().await.expect("list").is_empty(),
            "the parked surface is empty after cancel"
        );
        // Idempotent: re-cancelling the now-absent send is a no-op false.
        assert!(
            !w.cancel_parked_send(parked_id, created_at)
                .await
                .expect("again"),
            "re-cancelling an absent send is a no-op false"
        );
        w.close().await.expect("close");
    }

