    #[tokio::test]
    async fn list_stranded_surfaces_the_recoverable_amount_from_the_engine_not_an_intent_row() {
        // The money path AND the decoupling invariant (ADR-0535 Decision 2): a recognised ephemeral
        // UTXO is surfaced as its recoverable amount — read from the ENGINE balance with NO intent row
        // present (the surface does not depend on the Stranded row, so reaping the row never un-surfaces
        // funds). Two values pinned: a buried UTXO and a tip-height (shallow) UTXO BOTH surface their
        // full economically-recoverable amount (`total` never hides ECONOMIC funds by depth — dust ≤
        // marginal fee is excluded).
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let (w, _addr, _taddr) = synced_wallet_with_taddr(dir.path(), &vault).await;
        let _buried = recognise_ephemeral_with_funds(&w, 0xA1, 40_000, 280_500).await;
        let _shallow = recognise_ephemeral_with_funds(&w, 0xB2, 15_000, 281_000).await;
        let mut stranded = w.list_stranded().await.expect("list");
        stranded.sort_by_key(|s| s.recoverable_zat);
        assert_eq!(stranded.len(), 2, "both recognised ephemerals surface");
        assert_eq!(
            stranded[0].recoverable_zat, 15_000,
            "the shallow amount surfaces in full"
        );
        assert!(
            !stranded[0].is_final,
            "the tip-height (shallow) amount is NOT reorg-final"
        );
        assert_eq!(
            stranded[1].recoverable_zat, 40_000,
            "the buried amount surfaces in full"
        );
        assert!(
            stranded[1].is_final,
            "the 500-block-buried amount IS reorg-final"
        );
        w.close().await.expect("close");
    }

