    #[tokio::test]
    async fn detect_skips_re_probing_an_already_recognised_ephemeral() {
        // §3.2i-2 skip-funded / ADR-0535 Decision 5: once an ephemeral's funds are recognised, the
        // detect does NOT open a circuit for it again (`list_stranded` already surfaces it). The
        // second pass SKIPS it — no probe — and the skip is counted distinctly (a fully-skipped pass
        // is healthy, not a truncation).
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let (w, _addr, _taddr) = synced_wallet_with_taddr(dir.path(), &vault).await;
        let eph = reserve_one_ephemeral(&w).await;
        let record = crate::transparent::TransparentUtxoRecord {
            txid: vec![0x5e; 32],
            index: 0,
            script: script_paying(&eph),
            value_zat: 40_000,
            height: 280_500,
        };
        let probe = FakeEphemeralProbe::returning(eph, vec![record]);
        let first = w
            .detect_ephemeral_utxos(&probe, &sync::CancelToken::new())
            .await
            .expect("detect");
        assert_eq!((first.polled, first.skipped, first.detected), (1, 0, 1));
        // Pass 2: the now-funded ephemeral is SKIPPED — no new circuit.
        let second = w
            .detect_ephemeral_utxos(&probe, &sync::CancelToken::new())
            .await
            .expect("re-detect");
        assert_eq!(second.scope_size, 1, "still in the in-window scope");
        assert_eq!(
            second.polled, 0,
            "no circuit opened — it is already recognised"
        );
        assert_eq!(second.skipped, 1, "skipped as funded");
        assert_eq!(
            probe.polled_count(),
            1,
            "across both passes the funded ephemeral was queried exactly once"
        );
        w.close().await.expect("close");
    }

    #[tokio::test]
    async fn detect_backs_off_a_cold_ephemeral_after_probing_it_once() {
        // #334 §3.2i-2 2e-2b-vi: a persistently-COLD in-window ephemeral (probed, returned nothing) is
        // NOT re-probed on the very next pass — the per-address backoff DEFERS it (the 60 s floor is far
        // longer than the sub-second gap between two passes). The deferral is counted honestly
        // (`deferred`), never a truncation, and no second circuit is opened. (The window ELAPSING is
        // pinned with a paused clock in the ephemeral_detect unit tests; here we pin the wiring.)
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let (w, _addr, _taddr) = synced_wallet_with_taddr(dir.path(), &vault).await;
        let _eph = reserve_one_ephemeral(&w).await;
        // Cold: the fake returns empty for every address (no canned records).
        let probe = FakeEphemeralProbe::new();
        let first = w
            .detect_ephemeral_utxos(&probe, &sync::CancelToken::new())
            .await
            .expect("detect");
        assert_eq!(
            (
                first.scope_size,
                first.polled,
                first.skipped,
                first.deferred,
                first.detected,
            ),
            (1, 1, 0, 0, 0),
            "pass 1 probes the cold ephemeral (no backoff entry yet)"
        );
        // Pass 2, immediately after: the cold ephemeral is DEFERRED by the backoff, not re-probed.
        let second = w
            .detect_ephemeral_utxos(&probe, &sync::CancelToken::new())
            .await
            .expect("re-detect");
        assert_eq!(
            (
                second.scope_size,
                second.polled,
                second.skipped,
                second.deferred,
            ),
            (1, 0, 0, 1),
            "pass 2 defers it — in scope, not skipped-funded, backed off"
        );
        assert_eq!(
            probe.polled_count(),
            1,
            "across both passes the cold ephemeral was queried exactly once"
        );
        w.close().await.expect("close");
    }

    /// Build ONE terminal `Stranded` row in the WALLET's aux store (Queued → Submitting → Sent →
    /// Stranded) with `tx0` as the first recorded txid — the reap-wiring test input.
    async fn insert_stranded_aux_row(w: &Wallet, tx0: [u8; 32]) -> QueuedSendId {
        let inner = Arc::clone(&w.inner);
        run_blocking(move || {
            let mut g = inner.aux_db.lock().expect("aux db mutex poisoned");
            let id = crate::intent_store::enqueue(&mut g, "zcash:strand", 0, None, None)?;
            crate::intent_store::mark_submitting(
                &mut g,
                id,
                &[crate::intent_store::NoteClaim {
                    txid: [9; 32],
                    protocol: crate::intent_store::PROTO_ORCHARD,
                    output_index: 0,
                }],
            )?;
            crate::intent_store::mark_sent_multi(&mut g, id, &[tx0])?;
            assert!(
                crate::intent_store::mark_stranded(&mut g, id)?,
                "Sent→Stranded"
            );
            Ok::<_, WalletError>(id)
        })
        .await
        .expect("insert stranded aux row")
    }

    async fn count_stranded_rows(w: &Wallet) -> usize {
        let inner = Arc::clone(&w.inner);
        run_blocking(move || {
            let g = inner.aux_db.lock().expect("aux db mutex poisoned");
            crate::intent_store::list_stranded_intents(&g)
        })
        .await
        .expect("list stranded intents")
        .len()
    }

