    #[tokio::test]
    async fn reap_leaves_a_stranded_row_whose_tx0_is_not_yet_buried() {
        // The wiring + FAIL-SAFE: a Stranded row whose tx0 the engine has NOT recorded as mined
        // (`get_tx_height == None` ⇒ `should_reap(None) == false`) is NEVER reaped — the row is kept
        // for the next pass, so a row is never dropped before its funding is irreversible. (The
        // positive "tx0 buried ⇒ reaped" path needs a truly-mined wallet tx, which the FakeChain
        // harness cannot produce — a harness limitation (not a production gate; the strand machinery is
        // live post-gate-removal); the burial boundary itself is pinned by `stranded::should_reap`.)
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let (w, _addr, _taddr) = synced_wallet_with_taddr(dir.path(), &vault).await;
        // tx0 is a txid the engine never mined (a put-received UTXO would not set get_tx_height
        // either; here it is simply unknown) ⇒ the burial read is None ⇒ fail-safe keep.
        let _id = insert_stranded_aux_row(&w, [0xEE; 32]).await;
        assert_eq!(
            count_stranded_rows(&w).await,
            1,
            "the strand row is present"
        );
        let reaped = w
            .reap_stranded_rows(&sync::CancelToken::new())
            .await
            .expect("reap");
        assert_eq!(reaped, 0, "an un-mined tx0 is never reaped (fail-safe)");
        assert_eq!(
            count_stranded_rows(&w).await,
            1,
            "the row is kept for the next pass — never dropped before burial"
        );
        w.close().await.expect("close");
    }

    // ── inc-2d-shield (Recv-3): the public `propose_shield` over the live wallet ─────

    /// A synced live wallet whose receive t-address holds ONE spendable transparent UTXO of
    /// `value_zat` (detected through the real Recv-2b path). The default ZIP-315 policy
    /// allows zero-conf shielding, so a tip-height UTXO is immediately shieldable.
    async fn synced_wallet_with_transparent_funds(
        dir: &std::path::Path,
        vault: &Arc<dyn KeychainPort>,
        value_zat: i64,
    ) -> Wallet {
        let (w, _addr, taddr) = synced_wallet_with_taddr(dir, vault).await;
        let record = crate::transparent::TransparentUtxoRecord {
            txid: vec![0x21; 32],
            index: 0,
            script: script_paying(&taddr),
            value_zat,
            height: 281_000,
        };
        let mut src = FakeUtxoSource::ok(vec![record]);
        let out = w
            .refresh_transparent_utxos(&mut src)
            .await
            .expect("put the funding transparent UTXO");
        assert_eq!(out.put, 1, "the funding transparent UTXO is detected + put");
        w
    }

    #[tokio::test]
    async fn shield_proposal_over_threshold_round_trips() {
        // §8 (Recv-3 public API): a transparent balance ABOVE `SHIELDING_THRESHOLD_ZAT`,
        // detected by the live wallet, yields a `propose_shield` proposal — gross = the funds,
        // net = gross − fee (THE shield money invariant), landing SHIELDED with NO transparent
        // recipient (privacy-positive), behind a valid one-shot token (the SAME token `send`
        // consumes — so the host reuses the §3.2h send path unchanged).
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let w = synced_wallet_with_transparent_funds(dir.path(), &vault, 500_000).await;

        let dto = w
            .propose_shield()
            .await
            .expect("propose_shield")
            .expect("Some over the threshold");
        assert!(dto.is_shield, "the DTO is tagged as a shield");
        assert!(
            !dto.has_transparent_recipient,
            "a shield is privacy-positive — its output is SHIELDED, never transparent"
        );
        assert_eq!(
            dto.total_zat, 500_000,
            "gross = the detected transparent funds"
        );
        assert!(dto.fee_zat > 0, "a real ZIP-317 fee is charged");
        assert_eq!(
            dto.change_zat,
            dto.total_zat - dto.fee_zat,
            "net shielded = gross − fee (the shield money invariant)"
        );
        assert!(
            dto.proposal_id > 0,
            "a real one-shot token id (never the invalid 0 sentinel)"
        );
        let out = dto
            .steps
            .first()
            .expect("one step")
            .recipients
            .first()
            .expect("one self-output");
        assert_ne!(
            out.pool,
            send::OutputPool::Transparent,
            "the shield output lands in a SHIELDED pool"
        );
        assert_eq!(
            out.amount_zat, dto.change_zat,
            "the self-output value = the net shielded"
        );
        w.close().await.expect("close");
    }

