    #[test]
    fn should_refresh_transparent_only_on_chain_activity() {
        // The Recv-2b poll-gate: run after a pass that ADVANCED (batches) or REORGED, never on a
        // no-op caught-up pass (mobile battery/data) and never on a cancelled pass.
        let advanced = sync::SyncPass {
            batches: 2,
            ..sync::SyncPass::default()
        };
        let reorged = sync::SyncPass {
            reorgs: 1,
            ..sync::SyncPass::default()
        };
        let noop = sync::SyncPass::default();
        let cancelled_active = sync::SyncPass {
            batches: 2,
            cancelled: true,
            ..sync::SyncPass::default()
        };
        assert!(
            should_refresh_transparent(&advanced),
            "a scanned batch ⇒ poll"
        );
        assert!(should_refresh_transparent(&reorged), "a reorg ⇒ poll");
        assert!(
            !should_refresh_transparent(&noop),
            "a no-op caught-up pass ⇒ skip the redundant RPC"
        );
        assert!(
            !should_refresh_transparent(&cancelled_active),
            "a cancelled pass ⇒ no extra I/O even if it had scanned"
        );
    }

    #[tokio::test]
    async fn utxo_scan_event_is_5_4_clean() {
        // §8 (§5.4 teeth): the `wallet.utxo_scan` success event carries ONLY counts
        // (`utxos`/`rejected`) + a literal `outcome` — never an address/amount/txid/script.
        // Drive a REAL refresh emitting both a put (1) and a reject (1) so both count fields fire,
        // capture every `zec_wallet_core` field, and assert the §5.4 allowlist + value scan pass.
        use crate::tracing_guard::{CaptureLayer, CapturedEvents, assert_5_4_clean};
        use tracing_subscriber::prelude::*;

        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let (w, _addr, taddr) = synced_wallet_with_taddr(dir.path(), &vault).await;

        crate::tracing_guard::force_wallet_callsites_enabled();
        let sink = CapturedEvents::default();
        let subscriber = tracing_subscriber::registry().with(CaptureLayer::new(sink.clone()));
        let _guard = tracing::subscriber::set_default(subscriber);

        let ours = crate::transparent::TransparentUtxoRecord {
            txid: vec![0x11; 32],
            index: 0,
            script: zcash_transparent::address::Script::from(taddr.script()).0.0,
            value_zat: 40_000,
            height: 281_000,
        };
        let foreign = crate::transparent::TransparentUtxoRecord {
            txid: vec![0x12; 32],
            index: 0,
            script: zcash_transparent::address::Script::from(
                zcash_transparent::address::TransparentAddress::PublicKeyHash([0x99; 20]).script(),
            )
            .0
            .0,
            value_zat: 9_000,
            height: 281_000,
        };
        let mut src = FakeUtxoSource::ok(vec![ours, foreign]);
        let out = w
            .refresh_transparent_utxos(&mut src)
            .await
            .expect("refresh");
        assert_eq!((out.put, out.rejected), (1, 1), "one put + one rejected");

        let fields = sink.fields();
        // The success event fired with the count fields + the literal outcome.
        let names: std::collections::HashSet<&str> =
            fields.iter().map(|(n, _)| n.as_str()).collect();
        for required in ["utxos", "rejected", "set_size", "outcome"] {
            assert!(
                names.contains(required),
                "wallet.utxo_scan is missing {required:?}; captured {fields:?}"
            );
        }
        // The TEETH: every captured field name is allowlisted and no value is a secret.
        assert_5_4_clean(&fields);
        w.close().await.expect("close");
    }

    #[tokio::test]
    async fn view_export_event_is_5_4_clean() {
        // §8 (§5.4 teeth) + #397 HARD-D: the ONE sanctioned UFVK egress emits
        // an OUTCOME-ONLY `wallet.view_export` event — the exported `uview…`
        // string must never reach a captured field name or value (the
        // FORBIDDEN `uview` token is the tripwire). Drive the REAL export on
        // a created wallet under capture; belt beyond the token scan: no
        // captured value carries the artifact or any interior fragment of it
        // (a fragment would dodge the prefix token).
        use crate::tracing_guard::{CaptureLayer, CapturedEvents, assert_5_4_clean};
        use tracing_subscriber::prelude::*;

        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let w = Wallet::create_with_vault(
            cfg(dir.path(), Network::Main, SeedPersistence::SealedKeychain),
            SeedSource::raw_bytes(vec![0x24u8; 32]).expect("seed"),
            Arc::clone(&vault),
        )
        .await
        .expect("create");

        crate::tracing_guard::force_wallet_callsites_enabled();
        let sink = CapturedEvents::default();
        let subscriber = tracing_subscriber::registry().with(CaptureLayer::new(sink.clone()));
        let _guard = tracing::subscriber::set_default(subscriber);

        let exported = w.export_ufvk().await.expect("export");
        assert!(exported.starts_with("uview1"), "mainnet artifact");

        let fields = sink.fields();
        // The success event fired outcome-only.
        assert!(
            fields
                .iter()
                .any(|(n, v)| n == "outcome" && v.contains("ok")),
            "wallet.view_export success outcome missing; captured {fields:?}"
        );
        // The TEETH: allowlist + FORBIDDEN value scan (incl. the `uview` token).
        assert_5_4_clean(&fields);
        // BELT: neither the whole artifact nor an interior window of it (which
        // carries no `uview` prefix) appears in any captured value.
        let interior = &exported[20..44];
        assert!(
            fields
                .iter()
                .all(|(_, v)| !v.contains(&exported) && !v.contains(interior)),
            "a captured value carries the export artifact"
        );
        w.close().await.expect("close");
    }

