    #[tokio::test]
    async fn the_replay_cursor_stamps_the_fully_scanned_frontier_not_the_scan_max() {
        // §8 (R1 — the backgrounded-mid-restore miss): with a pending
        // LOWER scan range outstanding (the priority-order restore shape), the
        // replay cursor must stamp the fully-scanned frontier (start − 1), NOT
        // `MAX(blocks.height)` — a scan-max cursor would suppress replay of
        // arrivals in ranges never diffed.
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let (w, _addr, _taddr) = synced_wallet_with_taddr(dir.path(), &vault).await;
        {
            let guard = w.inner.aux_db.lock().expect("aux db");
            guard
                .execute(
                    "INSERT INTO scan_queue (block_range_start, block_range_end, priority) \
                     VALUES (280_500, 280_600, 20)",
                    [],
                )
                .expect("insert a pending lower range");
        }
        let (sink, mut rx) = incoming_sink(None);
        w.watch_incoming_funds(None, sink).await.expect("subscribe");
        let replay = rx.recv().await.expect("replay");
        assert_eq!(
            replay.cursor, "w1:280499",
            "the cursor claims only the fully-scanned frontier"
        );
        w.close().await.expect("close");
    }

    #[tokio::test]
    async fn a_real_detect_fault_conservative_fires_floored_and_latches_the_session_floor() {
        // §8 (S1+S2, the kill-proven pin): drive detect_incoming's REAL Err
        // arm — not the emit shape — by breaking the read path itself (DROP the
        // view the diff queries; a throwaway test wallet). Asserts the fold's
        // fault contract end-to-end: count-0 conservative-fire with the span
        // set, cursor stamped BELOW the uncounted span, the §5.4 field set
        // capture-verified on the FAULT arm, and the SESSION FLOOR latched: a
        // LATER Live emit cannot advance the cursor past the faulted span
        // (S2 — removing the floor latch fails the later-emit assert below,
        // probe-verified; the old emit-shape pin let the stamp mutant survive
        // the full suite, the audit finding).
        use crate::tracing_guard::{CaptureLayer, CapturedEvents, assert_5_4_clean};
        use tracing_subscriber::prelude::*;

        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let (w, _addr, _taddr) = synced_wallet_with_taddr(dir.path(), &vault).await;

        // Break the real read path the diff uses.
        {
            let guard = w.inner.aux_db.lock().expect("aux db");
            guard
                .execute_batch("DROP VIEW v_transactions")
                .expect("drop the view the detect diff queries");
        }

        crate::tracing_guard::force_wallet_callsites_enabled();
        let sink = CapturedEvents::default();
        let subscriber = tracing_subscriber::registry().with(CaptureLayer::new(sink.clone()));
        let guard = tracing::subscriber::set_default(subscriber);

        w.detect_incoming(281_000, 281_005).await;
        drop(guard);

        let ev = w.inner.incoming_tx.borrow().clone();
        assert_eq!(ev.kind, IncomingFundsEventKind::Live);
        assert_eq!(ev.new_tx_count, 0, "conservative-fire: count unknowable");
        assert_eq!(ev.span_from_height, Some(281_000));
        assert_eq!(ev.span_to_height, Some(281_004));
        assert_eq!(
            ev.cursor, "w1:280999",
            "the fault stamp stays BELOW the uncounted span"
        );

        // The §5.4 teeth on the FAULT arm (previously only the detected arm
        // was capture-driven): same field names, payload-free code outcome.
        let fields = sink.fields();
        let names: std::collections::HashSet<&str> =
            fields.iter().map(|(n, _)| n.as_str()).collect();
        for required in ["span_from", "span_to", "count", "outcome"] {
            assert!(
                names.contains(required),
                "the fault arm is missing {required:?}; captured {fields:?}"
            );
        }
        assert_5_4_clean(&fields);

        // The SESSION FLOOR: a later (would-be higher) Live emit stays clamped.
        w.emit_incoming_live(1, (281_010, 281_010), 281_020);
        let later = w.inner.incoming_tx.borrow().clone();
        assert_eq!(
            later.cursor, "w1:280999",
            "no later event may claim the faulted span (the sticky floor)"
        );
        assert_eq!(
            later.total_tx_detected, 1,
            "the later detection still counts — only the WATERMARK is floored"
        );
        w.close().await.expect("close");
    }

    #[tokio::test]
    async fn incoming_detect_read_fault_never_advances_the_watermark_past_the_span() {
        // §8 (security LOW-2, money-visibility): the conservative-fire arm's
        // cursor must stamp BELOW the uncounted span, so a host that persists it
        // and dies before pulling still replays the span from history. Pinned at
        // the emit layer (the arm's one behavioral delta from the detected path):
        // an emit with watermark `lo - 1` yields a cursor that REPLAYS the span.
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let (w, _addr, taddr) = synced_wallet_with_taddr(dir.path(), &vault).await;
        strip_restore_seed(&w.inner);

        // A real arrival inside the span the fault arm would cover.
        let record = crate::transparent::TransparentUtxoRecord {
            txid: vec![0x09; 32],
            index: 0,
            script: script_paying(&taddr),
            value_zat: 70_000,
            height: 281_000,
        };
        let mut src = FakeUtxoSource::ok(vec![record]);
        w.refresh_transparent_utxos(&mut src)
            .await
            .expect("refresh");

        // The fault-arm emit shape: count 0, span set, watermark = lo - 1.
        w.emit_incoming_live(0, (281_000, 281_000), 280_999);
        let cursor = w.inner.incoming_tx.borrow().cursor.clone();
        assert_eq!(cursor, "w1:280999", "the watermark stays BELOW the span");

        // A subscriber persisting that cursor replays the arrival — the span was
        // delayed, never swallowed.
        let (sink, mut rx) = incoming_sink(None);
        w.watch_incoming_funds(Some(&cursor), sink)
            .await
            .expect("subscribe with the fault-arm cursor");
        let replay = rx.recv().await.expect("replay");
        assert_eq!(
            replay.new_tx_count, 1,
            "the uncounted span replays from history"
        );
        w.close().await.expect("close");
    }

    #[tokio::test]
    async fn sync_once_scans_a_multi_batch_chain_to_completion() {
        // §8 (end-to-end, §3.2g iv-d-2b-ii): the driver loop over the REAL scanner +
        // real keyed DB + real cache (FakeChain, NO gRPC server). A span one block
        // longer than SYNC_BATCH_BLOCKS scans in TWO batches to completion; a second
        // pass is a clean no-op (up to date). Proves the suggest→batch→download→scan→
        // delete→re-suggest loop terminates with real progress recorded.
        use crate::sync::CancelToken;
        use crate::sync::testing::FakeChain;
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let w = wallet_with_chain_account(dir.path(), &vault).await;

        // tip FIX_TIP ⇒ scan range [FIX_BASE, FIX_TIP+1) = one batch + 1 block ⇒ 2 batches.
        let mut client = FakeChain::to_tip(u64::from(FIX_TIP));
        let cancel = CancelToken::new();
        // Record the live samples: a clean (reorg-free) pass must stamp every one
        // `rewound == false` (§2.5 `Scanning.rewound`, #317). The rewound=TRUE arm is
        // unproducible against hand-built FakeChain blocks (the probe-confirmed
        // continuity-error limitation — see `sync_summary_refreshes_on_reorg_even_when_
        // throttled`); it is pinned at the controller seam and rides the GA reorg e2e.
        let seen = Arc::new(Mutex::new(Vec::<sync::ScanProgress>::new()));
        let sink = Arc::clone(&seen);
        let recorder = move |p: sync::ScanProgress| sink.lock().expect("lock").push(p);
        let pass = w
            .sync_once(&mut client, &cancel, &recorder)
            .await
            .expect("sync");
        assert_eq!(pass.batches, 2, "one batch + 1 block ⇒ 2 batches");
        assert_eq!(pass.reorgs, 0, "no reorg on a clean chain");
        assert!(!pass.cancelled);
        {
            let samples = seen.lock().expect("lock");
            assert!(!samples.is_empty(), "a scanning pass emits live samples");
            assert!(
                samples.iter().all(|p| !p.rewound),
                "a reorg-free pass never stamps rewound",
            );
        }
        // the two inclusive wire ranges: [FIX_BASE,FIX_TIP-1] then [FIX_TIP,FIX_TIP]
        assert_eq!(
            *client.ranges.lock().expect("ranges"),
            vec![
                (u64::from(FIX_BASE), u64::from(FIX_TIP) - 1),
                (u64::from(FIX_TIP), u64::from(FIX_TIP))
            ],
            "forward batches from the range start, clamped to SYNC_BATCH_BLOCKS"
        );

        let mut client2 = FakeChain::to_tip(u64::from(FIX_TIP));
        let again = w
            .sync_once(&mut client2, &cancel, NOOP_PROGRESS)
            .await
            .expect("re-sync");
        assert_eq!(again.batches, 0, "already up to date ⇒ no batches scanned");
        assert!(
            client2.ranges.lock().expect("ranges").is_empty(),
            "an up-to-date pass downloads nothing"
        );
        w.close().await.expect("close");
    }

    #[tokio::test]
    async fn sync_once_per_range_span_is_observable_and_5_4_clean() {
        // §8 (observability + §5.4, iv-d-3-b-iii-B-2-d): the engine pass emits a
        // per-range `wallet.sync { from, to, blocks, outcome }` SPAN, and EVERY field
        // it carries rides the §5.4 allowlist — absolute heights + counts only, never
        // a secret. Drives the REAL scanner over FakeChain (2 batches) under the shared
        // capture-guard and asserts (a) the span carried the range + a resolved outcome,
        // (b) the whole captured field set is §5.4-clean, (c) the guard has TEETH (a
        // balance/amount would trip it). NOTE: `#[tokio::test]` is current-thread, so the
        // thread-local `set_default` subscriber sees the span created on the async task.
        use crate::sync::CancelToken;
        use crate::sync::testing::FakeChain;
        use crate::tracing_guard::{
            CaptureLayer, CapturedEvents, assert_5_4_clean, first_violation,
        };
        use tracing_subscriber::prelude::*;

        // Keep `zec_wallet_core` callsites enabled so this capture test is deterministic
        // under parallel execution (a thread-local `set_default` subscriber is invisible
        // to tracing's global interest cache — see the helper's doc).
        crate::tracing_guard::force_wallet_callsites_enabled();
        let sink = CapturedEvents::default();
        let subscriber = tracing_subscriber::registry().with(CaptureLayer::new(sink.clone()));
        let _guard = tracing::subscriber::set_default(subscriber);

        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let w = wallet_with_chain_account(dir.path(), &vault).await;
        // tip FIX_TIP ⇒ [FIX_BASE, FIX_TIP+1) = one batch + 1 block ⇒ 2 batches ⇒ 2 spans.
        let mut client = FakeChain::to_tip(u64::from(FIX_TIP));
        let cancel = CancelToken::new();
        let pass = w
            .sync_once(&mut client, &cancel, NOOP_PROGRESS)
            .await
            .expect("sync");
        assert_eq!(pass.batches, 2, "two batches ⇒ two wallet.sync spans");

        let fields = sink.fields();
        // (a) The span carried the per-range context + a resolved outcome.
        let names: std::collections::HashSet<&str> =
            fields.iter().map(|(n, _)| n.as_str()).collect();
        for required in ["from", "to", "blocks", "outcome"] {
            assert!(
                names.contains(required),
                "wallet.sync span is missing the {required:?} field; captured {fields:?}"
            );
        }
        // The clean multi-batch path resolves every batch as `advance`, and the first
        // batch's absolute start height (FIX_BASE) is logged verbatim (§5.4-allowed).
        assert!(
            fields.iter().any(|(n, v)| n == "outcome" && v == "advance"),
            "expected an `advance` outcome on the clean chain; captured {fields:?}"
        );
        assert!(
            fields
                .iter()
                .any(|(n, v)| n == "from" && v == &FIX_BASE.to_string()),
            "expected the batch start height FIX_BASE on the span; captured {fields:?}"
        );

        // (b) Nothing the span (or any zec_wallet_core tracing on this path) carries is a
        //     secret, and every field name is allowlisted.
        assert_5_4_clean(&fields);

        // (c) The guard has TEETH: a hypothetical `tracing::debug!(?balance)` — the kind
        //     of leak the B-2-c security INFO forbids — is rejected by the same policy.
        //     (BalanceSnapshot / WalletState are never Debug-logged; this proves the
        //     guard would catch a regression that tried.)
        let leak = vec![(
            "balance".to_string(),
            "BalanceSnapshot { spendable: Zatoshis(123), transparent: Zatoshis(0) }".to_string(),
        )];
        assert!(
            first_violation(&leak).is_some(),
            "the §5.4 guard must reject a logged BalanceSnapshot/WalletState"
        );

        w.close().await.expect("close");
    }

    #[tokio::test]
    async fn the_batch_span_carries_its_phase_timings_and_nothing_a_wallet_could_be_named_by() {
        // SCAN-1 (§4o S1 — the capture row). Two batches over the fake chain under
        // the capture guard: every closed `wallet.sync` batch span carries
        // `anchor_ms`, `dl_ms`, `scan_ms` (integer milliseconds) and `chain_outputs`
        // (the batch's public shielded-output count — 0 on the empty fixture chain);
        // the FIRST batch — always a refresh, `summary_stale` starts AT the
        // threshold — carries `snap_ms` and the second (throttled) does not; the
        // span's field-NAME set is asserted EXACTLY; `received_notes` (the WALLET
        // fact beside the timings in the loop) is asserted ABSENT; and every
        // captured field on the path is §5.4-clean.
        //
        // HOW "every span" is asserted: the sink groups fields by the record that
        // carried them and tags each with the span/event NAME (`records_of`) — that
        // is as far as SCAN-1 extended it; it has no span id — so the per-batch
        // claim is made by COUNTING over the `wallet.sync` records:
        // count(anchor_ms) == count(dl_ms) == count(scan_ms) == count(chain_outputs)
        // == pass.batches, and count(snap_ms) == 1 — AND, because the sink keeps
        // capture order and the loop is sequential, the one `snap_ms` record is
        // asserted to PRECEDE the second batch's creation record (review,
        // item 4: an INVERTED gate records it on exactly the throttled batch and
        // would pass the count alone).
        //
        // WHAT IS NOT NON-VACUOUS HERE, and where it is guarded instead (
        // review, item 3): the fake chain answers instantly and its blocks carry no
        // outputs — upstream's `TreeSizeInvalid`/`TreeSizeMismatch` checks need
        // cumulative, frontier-consistent commitment-tree metadata for a block with
        // outputs (the fixture doc's "heavy upstream fixtures") — so `anchor_ms`,
        // `dl_ms` and `chain_outputs` are 0 in-process and their sum identity is
        // 0 == 0. The accumulator is therefore ONE pure fn, `SyncPass::absorb`,
        // unit-tested with non-zero values per field (`absorb_adds_every_phase…`);
        // this test proves the loop CALLS it through `scan_ms`, which the real
        // scanner makes non-zero (asserted > 0 below).
        //
        // Mutants this row was watched against (S6): each of `anchor_ms`, `dl_ms`,
        // `scan_ms`, `chain_outputs` no longer recorded in the loop → its count is
        // 0; `snap_ms` recorded on every batch (the `refresh_summary` gate dropped)
        // → its count is 2; the gate INVERTED → the order assertion; a wallet fact
        // recorded on the span (`received_notes`) → the exact-name set and the
        // ABSENT assertion; `absorb` no longer called → `scan_ms` sum 0.
        use crate::sync::CancelToken;
        use crate::sync::testing::FakeChain;
        use crate::tracing_guard::{CaptureLayer, CapturedEvents, assert_5_4_clean};
        use std::collections::BTreeSet;
        use tracing_subscriber::prelude::*;

        crate::tracing_guard::force_wallet_callsites_enabled();
        let sink = CapturedEvents::default();
        let subscriber = tracing_subscriber::registry().with(CaptureLayer::new(sink.clone()));
        let _guard = tracing::subscriber::set_default(subscriber);

        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let w = wallet_with_chain_account(dir.path(), &vault).await;
        // tip FIX_TIP ⇒ [FIX_BASE, FIX_TIP+1) = one batch + 1 block ⇒ 2 batches ⇒ 2 spans.
        let mut client = FakeChain::to_tip(u64::from(FIX_TIP));
        let cancel = CancelToken::new();
        let pass = w
            .sync_once(&mut client, &cancel, NOOP_PROGRESS)
            .await
            .expect("sync");
        assert_eq!(pass.batches, 2, "two batches ⇒ two wallet.sync spans");

        let records = sink.records_of("wallet.sync");
        let span_fields: Vec<&(String, String)> = records.iter().flatten().collect();
        let count = |name: &str| span_fields.iter().filter(|(n, _)| n == name).count();
        let batches = usize::try_from(pass.batches).expect("a small count");
        for name in ["anchor_ms", "dl_ms", "scan_ms", "chain_outputs"] {
            assert_eq!(
                count(name),
                batches,
                "every batch span carries {name}; wallet.sync records: {records:?}"
            );
        }
        assert_eq!(
            count("snap_ms"),
            1,
            "only the refresh batch (the first) carries snap_ms; records: {records:?}"
        );
        // …and it is the FIRST batch's: the snap_ms record comes before the second
        // batch's creation record (the second record carrying `from`).
        let has = |r: &Vec<(String, String)>, name: &str| r.iter().any(|(n, _)| n == name);
        let snap_at = records
            .iter()
            .position(|r| has(r, "snap_ms"))
            .expect("one snap_ms record");
        let second_from_at = records
            .iter()
            .enumerate()
            .filter(|(_, r)| has(r, "from"))
            .nth(1)
            .map(|(i, _)| i)
            .expect("two batch spans ⇒ two creation records");
        assert!(
            snap_at < second_from_at,
            "snap_ms (record {snap_at}) must be the FIRST batch's, before batch 2's creation \
             (record {second_from_at}); records: {records:?}"
        );
        // Integer milliseconds, and the fixture chain's outputs are exactly zero.
        for (n, v) in &span_fields {
            if n.ends_with("_ms") {
                v.parse::<u64>()
                    .unwrap_or_else(|_| panic!("{n} is not an integer millisecond count: {v:?}"));
            }
            if n == "chain_outputs" {
                assert_eq!(
                    v, "0",
                    "the empty fixture chain carries no shielded outputs"
                );
            }
        }
        let names: BTreeSet<&str> = span_fields.iter().map(|(n, _)| n.as_str()).collect();
        let want: BTreeSet<&str> = [
            "from",
            "to",
            "blocks",
            "outcome",
            "anchor_ms",
            "dl_ms",
            "scan_ms",
            "snap_ms",
            "chain_outputs",
        ]
        .into_iter()
        .collect();
        assert_eq!(
            names, want,
            "the wallet.sync span's field-name set is EXACTLY the range + outcome + the timings + outputs"
        );
        assert!(
            !sink.fields().iter().any(|(n, _)| n == "received_notes"),
            "received_notes is a WALLET fact and never rides a log"
        );
        // The pass sums are the sums of the batch fields (S3's identity, at the engine).
        let sum = |name: &str| -> u64 {
            span_fields
                .iter()
                .filter(|(n, _)| n == name)
                .map(|(_, v)| v.parse::<u64>().expect("an integer"))
                .sum()
        };
        assert_eq!(
            pass.anchor_ms,
            sum("anchor_ms"),
            "pass anchor_ms == Σ batch anchor_ms"
        );
        assert_eq!(pass.dl_ms, sum("dl_ms"), "pass dl_ms == Σ batch dl_ms");
        assert_eq!(
            pass.scan_ms,
            sum("scan_ms"),
            "pass scan_ms == Σ batch scan_ms"
        );
        assert_eq!(
            pass.snap_ms,
            sum("snap_ms"),
            "pass snap_ms == Σ batch snap_ms"
        );
        assert_eq!(
            pass.chain_outputs,
            sum("chain_outputs"),
            "pass chain_outputs == Σ batch chain_outputs"
        );
        // Non-vacuity for the identity above: the real scanner over 100 blocks is
        // never 0 ms, so a loop that stopped calling `absorb` sums to 0 here.
        assert!(
            pass.scan_ms > 0,
            "scan_ms is measured by the real scanner and absorbed into the pass: got 0"
        );
        assert!(
            pass.wall_ms >= pass.anchor_ms + pass.dl_ms + pass.scan_ms + pass.snap_ms,
            "the pass wall-clock covers its batches: wall {} vs phases {}",
            pass.wall_ms,
            pass.anchor_ms + pass.dl_ms + pass.scan_ms + pass.snap_ms
        );

        assert_5_4_clean(&sink.fields());
        w.close().await.expect("close");
    }

    #[tokio::test]
    async fn a_three_batch_pass_carries_anchor_ms_on_every_batch_and_lands_the_same_height() {
        // SCAN-2 (§4t, the implementer's pin (c)): through `sync_once` over
        // `FakeChain`, a pass of THREE consecutive batches — the first fetched,
        // the next two on the anchor DERIVED from the previous batch's blocks —
        // records `anchor_ms` and `dl_ms` on every batch span exactly once, keeps
        // the SCAN-1 sum identities, and lands the wallet's `block_max_scanned`
        // on the tip as the base did (a derived anchor is indistinguishable to
        // upstream, P2). The fetch COUNT is S2-1's, through the test author's
        // counter; this pin has none and says so — the three ranges it asserts
        // are the consecutive geometry the derivation needs.
        use crate::sync::CancelToken;
        use crate::sync::testing::FakeChain;
        use crate::tracing_guard::{CaptureLayer, CapturedEvents, assert_5_4_clean};
        use tracing_subscriber::prelude::*;

        crate::tracing_guard::force_wallet_callsites_enabled();
        let sink = CapturedEvents::default();
        let subscriber = tracing_subscriber::registry().with(CaptureLayer::new(sink.clone()));
        let _guard = tracing::subscriber::set_default(subscriber);

        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let w = wallet_with_chain_account(dir.path(), &vault).await;
        // [FIX_BASE, TIP3 + 1) = two full batches + 1 block ⇒ 3 batches.
        const TIP3: u32 = FIX_TIP + crate::constants::SYNC_BATCH_BLOCKS;
        let mut client = FakeChain::to_tip(u64::from(TIP3));
        let cancel = CancelToken::new();
        let pass = w
            .sync_once(&mut client, &cancel, NOOP_PROGRESS)
            .await
            .expect("sync");
        assert_eq!(pass.batches, 3, "two full batches + 1 block ⇒ 3 batches");
        assert!(
            pass.batches < TREE_STATE_RECONCILE_BATCHES,
            "below the cadence: this pass reconciles nothing (S2-1's 'zero when N is below \
             the cadence')"
        );
        let base = u64::from(FIX_BASE);
        assert_eq!(
            *client.ranges.lock().expect("ranges"),
            vec![
                (base, base + 99),
                (base + 100, base + 199),
                (base + 200, u64::from(TIP3))
            ],
            "three consecutive ranges — each starts where the previous ended"
        );
        let batches = batches_of(&sink.records_of("wallet.sync"));
        assert_eq!(batches.len(), 3, "three batch spans; records: {batches:?}");
        for (i, b) in batches.iter().enumerate() {
            for name in ["anchor_ms", "dl_ms", "scan_ms", "chain_outputs"] {
                assert_eq!(
                    b.iter().filter(|(n, _)| n == name).count(),
                    1,
                    "batch {i} carries {name} exactly once (a derived batch too); got {b:?}"
                );
            }
            assert!(
                b.iter().any(|(n, v)| n == "outcome" && v == "advance"),
                "batch {i} advanced; got {b:?}"
            );
        }
        let sum = |name: &str| -> u64 {
            batches
                .iter()
                .flatten()
                .filter(|(n, _)| n == name)
                .map(|(_, v)| v.parse::<u64>().expect("an integer"))
                .sum()
        };
        assert_eq!(
            pass.anchor_ms,
            sum("anchor_ms"),
            "pass == Σ batch anchor_ms"
        );
        assert_eq!(pass.dl_ms, sum("dl_ms"), "pass == Σ batch dl_ms");
        assert_eq!(pass.scan_ms, sum("scan_ms"), "pass == Σ batch scan_ms");
        assert!(
            pass.wall_ms >= pass.anchor_ms + pass.dl_ms + pass.scan_ms + pass.snap_ms,
            "the pass wall-clock covers its batches"
        );
        let scanned = w
            .scanned_tip()
            .await
            .expect("read")
            .expect("three batches scanned");
        assert_eq!(
            scanned.value(),
            TIP3,
            "the wallet holds the tip — the same block_max_scanned the base landed"
        );
        assert_5_4_clean(&sink.fields());
        w.close().await.expect("close");
    }

    /// The `wallet.sync` records of one pass, split into batches at each span
    /// creation record (the one carrying `from`), in capture order.
    fn batches_of(records: &[Vec<(String, String)>]) -> Vec<Vec<(String, String)>> {
        let mut out: Vec<Vec<(String, String)>> = Vec::new();
        for r in records {
            if r.iter().any(|(n, _)| n == "from") {
                out.push(Vec::new());
            }
            if let Some(cur) = out.last_mut() {
                cur.extend(r.iter().cloned());
            }
        }
        out
    }

    fn outcome_of(batch: &[(String, String)]) -> &str {
        batch
            .iter()
            .find(|(n, _)| n == "outcome")
            .map(|(_, v)| v.as_str())
            .unwrap_or("<none>")
    }

    fn snaps_in(batch: &[(String, String)]) -> usize {
        batch.iter().filter(|(n, _)| n == "snap_ms").count()
    }

    /// The tip pass 1 of a reorg row scans to: 300 blocks above the birthday —
    /// four batches, so checkpoints (upstream creates one per batch END) exist
    /// well below any height a rewind can land on.
    const REORG_PASS1_TIP: u64 = FIX_BASE as u64 + 300;

    /// Pass 1 over the fixture chain to [`REORG_PASS1_TIP`]; then, under a fresh
    /// capture, a pass 2 against a fake that reveals `fork` and reaches `tip`; then
    /// pass 3 against the same fake (the fork stays revealed) — the recovery, which
    /// must be reorg-free: it proves the fork chains from what the wallet holds
    /// after the rewind. Returns pass 2, its `wallet.sync` batches, and pass 3.
    ///
    /// WHAT UPSTREAM DOES ON A REWIND, measured while this fixture was built
    /// `truncate_to_height` lands on the highest CHECKPOINTED height at or
    /// below the target (`select_truncation_height` — a batch end, so a target
    /// with no batch end at or below it is `RequestedRewindInvalid`), and TRIMS
    /// the scan queue above it without re-queuing (`trim_scan_queue_to`); this
    /// loop then finds nothing to suggest and the pass ends at the rewound batch —
    /// the re-scan across the fork is the NEXT pass's (`record_chain_tip`
    /// re-queues). Reported with the repair as a loop finding; the rows
    /// below assert what the loop does today and stay valid should a future loop
    /// re-queue inside the pass.
    async fn reorg_passes(
        fork: sync::testing::Fork,
        tip: u64,
    ) -> (sync::SyncPass, Vec<Vec<(String, String)>>, sync::SyncPass) {
        use crate::sync::CancelToken;
        use crate::sync::testing::FakeChain;
        use crate::tracing_guard::{CaptureLayer, CapturedEvents, assert_5_4_clean};
        use tracing_subscriber::prelude::*;

        crate::tracing_guard::force_wallet_callsites_enabled();
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let w = wallet_with_chain_account(dir.path(), &vault).await;
        let cancel = CancelToken::new();
        let mut original = FakeChain::to_tip(REORG_PASS1_TIP);
        let pass1 = w
            .sync_once(&mut original, &cancel, NOOP_PROGRESS)
            .await
            .expect("pass 1");
        assert_eq!(
            pass1.batches, 4,
            "pass 1 scans the fixture chain in four batches (a checkpoint at each end)"
        );

        let sink = CapturedEvents::default();
        let subscriber = tracing_subscriber::registry().with(CaptureLayer::new(sink.clone()));
        let guard = tracing::subscriber::set_default(subscriber);
        let mut forked = FakeChain::to_tip(tip);
        forked.fork = Some(fork);
        let pass2 = w
            .sync_once(&mut forked, &cancel, NOOP_PROGRESS)
            .await
            .expect("pass 2 (the reorg pass)");
        assert!(!pass2.cancelled);
        assert_5_4_clean(&sink.fields());
        let batches = batches_of(&sink.records_of("wallet.sync"));
        drop(guard); // pass 3 is not captured

        let pass3 = w
            .sync_once(&mut forked, &cancel, NOOP_PROGRESS)
            .await
            .expect("pass 3 (the recovery across the fork)");
        assert_eq!(
            pass3.reorgs, 0,
            "the fork's first block chains from what the wallet holds after the rewind, so the \
             recovery is reorg-free; pass 2 batches: {batches:?}"
        );
        assert!(!pass3.cancelled);
        assert_eq!(
            pass3.tip,
            Some(BlockHeight::new(
                u32::try_from(tip).expect("a fixture height")
            )),
            "the recovery reaches the forked tip"
        );
        w.close().await.expect("close");
        (pass2, batches, pass3)
    }

    #[tokio::test]
    async fn a_rewound_throttled_batch_records_exactly_one_snap_ms() {
        // SCAN-1 (review, item 5 — the loop-level reorg row the arch angle
        // asked for). Pass 2's fake reveals a fork AFTER its first `block_range`,
        // starting 4 blocks below the end of the range that call served: batch 1
        // (the pass's refresh batch) scans the original blocks clean; batch 2's
        // first block chains from a hash the wallet does not hold — upstream's
        // `PrevHashMismatch` — so `scan_batch` rewinds (upstream lands on the
        // checkpoint below: pass 1's last batch end) and the Rewind arm forces a
        // summary refresh, batch 2 having been throttled. Asserted: the rewound
        // batch is the second, carries `outcome=rewind` and EXACTLY ONE `snap_ms`;
        // the refresh batch carries exactly one; any later batch none; one reorg;
        // the pass sums are the batch fields summed; the recovery pass is clean.
        // Mutants: the Rewind arm's refresh no longer folded into `phases` → the
        // rewound batch has 0; the fork fixture serving no fork → no rewind batch.
        use crate::sync::testing::{Fork, ForkAt};
        let t = REORG_PASS1_TIP;
        let rewind = u64::from(crate::constants::REWIND_DISTANCE_BLOCKS);
        assert!(
            rewind > 5,
            "the rewind must land below the fork's first block"
        );
        let (pass, batches, _recovery) = reorg_passes(
            Fork {
                at: ForkAt::BelowFirstRangeEnd(4),
                after_ranges: 1,
            },
            t + 200,
        )
        .await;
        assert_eq!(
            pass.reorgs, 1,
            "one revealed fork ⇒ one rewind; batches: {batches:?}"
        );
        assert!(
            batches.len() >= 2,
            "the refresh batch, then the rewound one; got {batches:?}"
        );
        assert_eq!(outcome_of(&batches[0]), "advance");
        assert_eq!(snaps_in(&batches[0]), 1, "the refresh batch: one snap_ms");
        assert_eq!(outcome_of(&batches[1]), "rewind", "batches: {batches:?}");
        assert_eq!(
            snaps_in(&batches[1]),
            1,
            "the rewound THROTTLED batch: exactly one snap_ms (the forced refresh); batches: {batches:?}"
        );
        // Today the pass ends at the rewound batch (upstream trims the queue —
        // see `reorg_passes`); a loop that re-queued in-pass would add clean,
        // throttled advances here, and this row stays valid for it.
        for b in &batches[2..] {
            assert_eq!(
                outcome_of(b),
                "advance",
                "the re-scan across the fork is clean"
            );
            assert_eq!(snaps_in(b), 0, "a throttled advance carries no snap_ms");
        }
        let sum: u64 = batches
            .iter()
            .flatten()
            .filter(|(n, _)| n == "snap_ms")
            .map(|(_, v)| v.parse::<u64>().expect("ms"))
            .sum();
        assert_eq!(pass.snap_ms, sum, "pass snap_ms == Σ batch snap_ms");
    }

    #[tokio::test]
    async fn a_rewound_refresh_batch_records_exactly_one_snap_ms_not_two() {
        // SCAN-1 (review, item 5 — the double-record shape). The fork is
        // revealed on pass 2's FIRST `block_range`, at T−4 (inside what pass 1
        // scanned), so batch 1 is both the pass's refresh batch AND the rewound
        // one: its first block, T+1, no longer chains from the wallet's T; the
        // scan closure attempts the refresh (in-lock, post-rewind) and the Rewind
        // arm must not attempt a second — `summary_stale` is 0 — so the span
        // carries `snap_ms` ONCE, never a duplicate key. Any later batch carries
        // none (today there is none: the pass ends at the rewound batch, see
        // `reorg_passes`; the recovery pass re-scans across the fork cleanly).
        // Mutant: `snap_ms` recorded in the closure AND in the Rewind arm again
        // (the shape this row was written against) with the arm's gate loosened
        // → 2 here.
        use crate::sync::testing::{Fork, ForkAt};
        let t = REORG_PASS1_TIP;
        let rewind = u64::from(crate::constants::REWIND_DISTANCE_BLOCKS);
        assert!(
            rewind > 5,
            "the rewind must land below the fork's first block"
        );
        let (pass, batches, _recovery) = reorg_passes(
            Fork {
                at: ForkAt::Height((t + 1) - rewind / 2),
                after_ranges: 0,
            },
            t + 100,
        )
        .await;
        assert_eq!(
            pass.reorgs, 1,
            "one revealed fork ⇒ one rewind; batches: {batches:?}"
        );
        assert!(!batches.is_empty(), "the rewound batch; got {batches:?}");
        assert_eq!(outcome_of(&batches[0]), "rewind", "batches: {batches:?}");
        assert_eq!(
            snaps_in(&batches[0]),
            1,
            "a batch that is refresh AND rewind carries snap_ms exactly once; batches: {batches:?}"
        );
        for b in &batches[1..] {
            assert_eq!(
                outcome_of(b),
                "advance",
                "the re-scan across the fork is clean"
            );
            assert_eq!(snaps_in(b), 0, "a throttled advance carries no snap_ms");
        }
    }

    // ── REQ-1 (§4q, INC-025): a rewound pass re-queues before it can read the
    //    queue as empty, and the cache follows the height upstream landed on ────
    //
    // Every row below drives the SHIPPED path — `sync_once` (R-1, R-3) or the
    // production pass body under a real `SyncController` (R-2, R-4) — over the
    // SCAN-1 revealed-fork fixture (`sync::testing::Fork`). No production code is
    // planted, no `#[cfg(test)]` door is added: the mid-pass observation rides the
    // progress reporter `sync_once` already takes, and everything else is read
    // through surfaces the wallet already has (`scanned_tip`, `snapshot`,
    // `BlockCache::tip_height`).
    //
    // What INC-025 says goes wrong, in the loop's own terms: `scan_batch`'s reorg
    // arm truncates the wallet DB and upstream TRIMS the scan queue to the
    // truncation point without re-queuing the rewound span, so the next
    // `next_batch` reads `None` and the pass returns "up to date with the recorded
    // tip" — a tip the wallet no longer holds. Every row here asserts a property
    // that a pass which re-queued in-pass satisfies and a pass that ended at the
    // rewound batch does not.
    //
    // §4q Q-R2, ANSWERED: the `Fork` fixture reveals ONE fork and only one, so a
    // reorg-STORM row through `sync_once` cannot be written against it and is OWED
    // to the next round (the pure-accounting storm rows,
    // `sync::tests::reorg_storm_trips_past_the_consecutive_bound` and
    // `classify_batch_accounts_progress_and_bounds_a_reorg_oscillation`, stay the
    // only cover — and they DO kill P-R4's mutant, a `reorgs_since_progress` reset
    // on every `Advance`). `FakeChain::revealed_fork` (`sync.rs`) filters ONE
    // `Option<Fork>` by the number of ranges served and returns one `from`
    // forever, and `forked_block(h, from)` tags every forked height with the SAME
    // `forked_id`, so once the wallet has rewound below `from` the fork links from
    // what it holds and no second continuity error is producible. THE SEAM a storm
    // row would need, named from the receiving code and deliberately NOT built
    // here: `FakeChain.fork` becomes a sequence (`Vec<Fork>`), `revealed_fork`
    // returns the currently-revealed one, and `forked_id`/`forked_block` take a
    // generation so each successive fork presents a block whose `prev_hash`
    // mismatches what the wallet holds after the previous rewind — the mapping
    // closure in `FakeChain::block_range` being the one call site that changes.
    // BUILT AT (§4q-R RR-3), at that mapping closure and in that shape:
    // `sync::testing::ForkStorm`, driven by
    // `a_fork_advance_fork_server_cannot_hold_one_pass_past_the_absolute_cap`
    // below. This paragraph is kept as the record of why the storm row was owed
    // rather than written in the round above; the "NOT built here" is about that
    // round, and is no longer true of the tree.

    /// One `ScanProgress` a pass reported, paired with the wallet DB's
    /// `block_max_scanned` READ AT THAT INSTANT — the mid-pass observation §4q R-3
    /// needs ("the rewind batch's recorded rewind height equals the DB's
    /// `block_max_scanned` right after the rewind"), and the only one that means
    /// the same thing before and after the repair: after it, the pass no longer
    /// ends at the rewound batch, so a post-pass read can no longer see the
    /// height upstream landed on.
    ///
    /// Deadlock-free by the loop's own structure, not by luck: `sync_once` reports
    /// ONLY from the async task and ONLY outside its per-batch db-lock sections
    /// (the intra-batch download ticks are the lock-free phase; the Advance /
    /// Rewind / up-to-date reports each run after `run_blocking` returned and the
    /// lock was released), so this blocking read never contends with the pass's
    /// own writer.
    #[derive(Debug, Clone, Copy, PartialEq, Eq)]
    struct PassSample {
        /// `ScanProgress::frontier`. On the post-rewind sample this is the
        /// `BatchAction::Rewind { rewind_height }` the loop truncated the CACHE
        /// to — the value INC-025's second clause is about.
        frontier: u32,
        /// Whether the pass had rewound by the time of this sample.
        rewound: bool,
        /// `block_max_scanned` at the instant of the sample; `None` = nothing scanned.
        db_scanned: Option<u32>,
    }

    /// The measured shape of ONE reorg pass over the SCAN-1 fixture geometry.
    /// A SIBLING of [`reorg_passes`], deliberately not folded into it: it adds the
    /// three observations INC-025 is about (the DB height the reorg pass ENDS on,
    /// the samples it reported mid-pass, and what the cache still holds), and it
    /// must be able to observe a FAILED pass — §4q P-R3's belt makes a rewind that
    /// leaves the queue empty an honest `Err`, which `reorg_passes`'s `expect`
    /// cannot survive.
    struct ReorgPassRun {
        /// Pass 2 — the reorg pass itself.
        pass: Result<sync::SyncPass, WalletError>,
        /// Its `wallet.sync` records split per batch, in capture order.
        batches: Vec<Vec<(String, String)>>,
        /// Every progress sample the reorg pass reported, with the DB height at
        /// the moment of each.
        samples: Vec<PassSample>,
        /// `block_max_scanned` through the wallet's own reader, after the reorg pass.
        scanned_after: Option<BlockHeight>,
        /// The highest block the disposable cache still holds after the pass.
        cache_tip_after: Option<u64>,
        /// Pass 3 over the same (still forked) endpoint — `reorg_passes`'s
        /// "recovery" pass, kept as the CONTROL: once the reorg pass re-queues
        /// in-pass there is nothing left for this one to scan.
        recovery: Result<sync::SyncPass, WalletError>,
    }

    /// Drive the [`reorg_passes`] geometry and MEASURE it: pass 1 to
    /// [`REORG_PASS1_TIP`] over the honest chain, then the reorg pass against a
    /// fake that reveals `fork` and reaches `tip` — captured, and reported through
    /// a recorder that reads the DB at every sample — then the recovery pass.
    async fn reorg_pass_over(fork: sync::testing::Fork, tip: u64) -> ReorgPassRun {
        use crate::sync::CancelToken;
        use crate::sync::testing::FakeChain;
        use crate::tracing_guard::{CaptureLayer, CapturedEvents, assert_5_4_clean};
        use tracing_subscriber::prelude::*;

        crate::tracing_guard::force_wallet_callsites_enabled();
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let w = wallet_with_chain_account(dir.path(), &vault).await;
        let cancel = CancelToken::new();
        let mut original = FakeChain::to_tip(REORG_PASS1_TIP);
        let pass1 = w
            .sync_once(&mut original, &cancel, NOOP_PROGRESS)
            .await
            .expect("pass 1");
        assert_eq!(
            pass1.batches, 4,
            "the fixture's own precondition (`reorg_passes`): pass 1 scans the chain in four \
             batches, so a checkpoint exists at each batch end and a rewind has somewhere to land"
        );
        let scanned_before = w.scanned_tip().await.expect("scanned tip");
        assert_eq!(
            scanned_before,
            Some(BlockHeight::new(
                u32::try_from(REORG_PASS1_TIP).expect("a fixture height")
            )),
            "the fixture's own precondition: pass 1 left the wallet AT the honest tip"
        );

        // The recording reporter: every sample, plus the DB height at that instant.
        let inner = Arc::clone(&w.inner);
        let samples: Mutex<Vec<PassSample>> = Mutex::new(Vec::new());
        let record = |p: sync::ScanProgress| {
            use zcash_client_backend::data_api::WalletRead;
            let db_scanned = {
                let guard = inner.db.lock().expect("wallet db mutex poisoned");
                guard
                    .db
                    .block_max_scanned()
                    .expect("block_max_scanned reads")
                    .map(|meta| u32::from(meta.block_height()))
            };
            samples
                .lock()
                .expect("samples mutex poisoned")
                .push(PassSample {
                    frontier: p.frontier.value(),
                    rewound: p.rewound,
                    db_scanned,
                });
        };
        let report: &(dyn Fn(sync::ScanProgress) + Sync) = &record;

        let sink = CapturedEvents::default();
        let subscriber = tracing_subscriber::registry().with(CaptureLayer::new(sink.clone()));
        let guard = tracing::subscriber::set_default(subscriber);
        let mut forked = FakeChain::to_tip(tip);
        forked.fork = Some(fork);
        let pass = w.sync_once(&mut forked, &cancel, report).await;
        assert_5_4_clean(&sink.fields());
        let batches = batches_of(&sink.records_of("wallet.sync"));
        drop(guard); // the recovery pass is not captured

        let scanned_after = w.scanned_tip().await.expect("scanned tip");
        let cache_tip_after = w.inner.cache.tip_height().await.expect("cache tip");
        let recovery = w.sync_once(&mut forked, &cancel, NOOP_PROGRESS).await;
        let samples = samples.lock().expect("samples mutex poisoned").clone();
        w.close().await.expect("close");
        ReorgPassRun {
            pass,
            batches,
            samples,
            scanned_after,
            cache_tip_after,
            recovery,
        }
    }

    /// The index of the FIRST batch whose span resolved `outcome = "rewind"`.
    fn first_rewind_batch(batches: &[Vec<(String, String)>]) -> Option<usize> {
        batches.iter().position(|b| outcome_of(b) == "rewind")
    }

    /// A batch span's `from` — the first height of the range it scanned.
    fn from_of(batch: &[(String, String)]) -> Option<u64> {
        batch
            .iter()
            .find(|(n, _)| n == "from")
            .and_then(|(_, v)| v.parse::<u64>().ok())
    }

    /// A short, printable rendering of the captured batches: `outcome@from`.
    fn batch_shape(batches: &[Vec<(String, String)>]) -> Vec<String> {
        batches
            .iter()
            .map(|b| {
                format!(
                    "{}@{}",
                    outcome_of(b),
                    from_of(b).map_or_else(|| "?".to_owned(), |f| f.to_string())
                )
            })
            .collect()
    }

    /// **§4q R-1 (INC-025) — DEFECT row, RED at the base.** The reorg pass must
    /// finish the job it started: after it rewinds it must re-queue the rewound
    /// span and re-scan ACROSS the fork before it can read the queue as empty.
    ///
    /// Asserted, on the SCAN-1 geometry (`BelowFirstRangeEnd(4)`, revealed after
    /// the first range, tip `REORG_PASS1_TIP + 200`):
    /// 1. `pass.reorgs == 1` — one revealed fork, one rewind;
    /// 2. at least one `outcome = "advance"` batch AFTER the `rewind` batch — the
    ///    re-scan is INSIDE this pass (the ordering is the whole clause: batch 1
    ///    is an `advance` too, so a count that does not filter on position passes
    ///    at the base);
    /// 3. the pass ends with the DB's `block_max_scanned == tip`, read through
    ///    [`Wallet::scanned_tip`] — the wallet's own reader, NEVER `pass.tip`,
    ///    which is set at the pass head and never lowered (that is exactly the
    ///    number the incident says lies);
    /// 4. the CONTROL: the next pass then has nothing to do (`batches == 0`).
    ///
    /// At the base clauses 2, 3 and 4 all fail for INC-025's reason: upstream's
    /// `trim_scan_queue_to` left the queue empty, so the pass ended at the rewound
    /// batch. Killer mutants: §4q P-R1's `update_chain_tip` call removed (2, 3, 4
    /// red); the re-queue made conditional on anything the fixture does not
    /// satisfy (same). SELF-MUTANT, measured at authoring time: with the
    /// "after the rewind" filter dropped — counting advances anywhere in the pass
    /// — clause 2 goes GREEN at the base (batch 1 is `advance@280301`) and the row
    /// falls through to clause 3, which reds with `block_max_scanned = 280,391`
    /// against a tip of 280,500. The position filter is what makes clause 2 see
    /// the incident at all.
    #[tokio::test]
    async fn a_rewound_pass_rescans_across_the_fork_before_it_ends() {
        use crate::sync::testing::{Fork, ForkAt};
        let tip = REORG_PASS1_TIP + 200;
        let run = reorg_pass_over(
            Fork {
                at: ForkAt::BelowFirstRangeEnd(4),
                after_ranges: 1,
            },
            tip,
        )
        .await;
        let pass = match &run.pass {
            Ok(p) => p,
            Err(e) => panic!(
                "the reorg pass must COMPLETE on this honest single-fork geometry (one fork, a \
                 rewind that lands on a checkpoint pass 1 wrote); got Err({e:?}); batches {:?}",
                batch_shape(&run.batches)
            ),
        };
        assert_eq!(
            pass.reorgs,
            1,
            "one revealed fork ⇒ exactly one rewind; batches {:?}",
            batch_shape(&run.batches)
        );

        let rewind_at = first_rewind_batch(&run.batches).unwrap_or_else(|| {
            panic!(
                "the geometry must produce a rewound batch; batches {:?}",
                batch_shape(&run.batches)
            )
        });
        let advances_after = run.batches[rewind_at + 1..]
            .iter()
            .filter(|b| outcome_of(b) == "advance")
            .count();
        assert!(
            advances_after >= 1,
            "INC-025: the pass rewound at batch {rewind_at} and then ENDED — the rewound span was \
             never re-queued, so `next_batch` read the trimmed queue as empty and the loop \
             returned 'up to date with the recorded tip'. Expected ≥ 1 advance AFTER the rewind \
             (the re-scan across the fork, inside THIS pass); got {advances_after}; batches {:?}",
            batch_shape(&run.batches)
        );

        assert_eq!(
            run.scanned_after.map(BlockHeight::value),
            Some(u32::try_from(tip).expect("a fixture height")),
            "INC-025, the money clause: the pass may only end when the wallet HOLDS the tip. The \
             DB's block_max_scanned is what the wallet holds; `pass.tip` (here {:?}) is the tip \
             recorded at the pass head and never lowered, which is why it is not read here. \
             batches {:?}",
            pass.tip,
            batch_shape(&run.batches)
        );

        let recovery = match &run.recovery {
            Ok(p) => p,
            Err(e) => panic!("the recovery pass must complete; got Err({e:?})"),
        };
        assert_eq!(
            recovery.batches, 0,
            "the CONTROL: once the reorg pass re-scans across the fork itself, the next pass has \
             nothing to scan — `reorg_passes`'s third pass exists only because today it does not"
        );
        assert_eq!(
            recovery.reorgs, 0,
            "and the recovery meets no second fork (the forked chain links from what the wallet \
             now holds)"
        );
    }

    /// The rewind as the loop RECORDED it against the rewind as the DB TOOK it:
    /// the first post-rewind progress sample's frontier (what `BatchAction::Rewind`
    /// carried, what the cache was truncated to, what the host was told) beside
    /// `block_max_scanned` read at that same instant, and the target ceiling
    /// derived from the rewound batch's own `from` — a value the repair cannot
    /// move, so the geometry stays checkable after it.
    fn rewind_as_recorded_and_as_taken(run: &ReorgPassRun) -> (u64, u64, u64) {
        let rewind_at = first_rewind_batch(&run.batches).unwrap_or_else(|| {
            panic!(
                "the geometry must produce a rewound batch; batches {:?}",
                batch_shape(&run.batches)
            )
        });
        let from = from_of(&run.batches[rewind_at]).expect("a batch span carries `from`");
        // `rewind_target` is `detection − REWIND_DISTANCE_BLOCKS` and detection is
        // at or above the batch start, so this is a CEILING on our target.
        let target_ceiling =
            from.saturating_sub(u64::from(crate::constants::REWIND_DISTANCE_BLOCKS));
        let sample = run
            .samples
            .iter()
            .find(|s| s.rewound)
            .copied()
            .unwrap_or_else(|| {
                panic!(
                    "the Rewind arm reports the rewound position; samples {:?}",
                    run.samples
                )
            });
        let landed = sample
            .db_scanned
            .expect("the wallet has scanned blocks by the time it rewinds");
        (
            u64::from(sample.frontier),
            u64::from(landed),
            target_ceiling,
        )
    }

    /// **§4q R-3 (INC-025) — DEFECT row, RED at the base.** `ScanOutcome::Reorg`
    /// must carry the height upstream LANDED on, not the height we asked for.
    ///
    /// `truncate_to_height` (`zcash_client_sqlite-0.22.0/src/wallet.rs:4145`)
    /// resolves the request through `select_truncation_height` (`:4091`) and then
    /// truncates to the RESOLVED height — it passes that height into
    /// `truncate_to_height_internal` (`:4321`) and returns it. The reorg arm
    /// discards the return (`sync.rs`, `if let Err(e) = db.truncate_to_height(…)`),
    /// so `rewind_height` stays OUR target: the value the loop truncates the CACHE
    /// to and reports as the wallet's position, while the DB sits wherever
    /// upstream could actually land.
    ///
    /// **THE GEOMETRY, and why it is the refresh one.** This row drives the fork
    /// of `a_rewound_refresh_batch_records_exactly_one_snap_ms_not_two` — revealed
    /// on pass 2's FIRST `block_range`, inside what pass 1 scanned — so the rewind
    /// happens with only pass 1's blocks and checkpoints in the DB, and the target
    /// does not qualify. Measured at the base: the rewound batch starts at
    /// 280,301, the target is 280,291, and `block_max_scanned` immediately after
    /// the rewind is **280,199** — 92 blocks lower. The sibling geometry
    /// (`BelowFirstRangeEnd(4)`, revealed after pass 2's first batch has committed)
    /// lands exactly ON its target and CANNOT see this defect; it is kept as the
    /// control row below, so the difference between the two is recorded in the tree
    /// rather than rediscovered. Reading one geometry and generalising to the
    /// family is exactly the error that control exists to stop.
    ///
    /// Killer mutant: §4q P-R2's `landed` replaced by the target (this row reds).
    /// Documented limit: the cache clause is a GUARD, not a live killer — this loop
    /// keeps at most one batch resident and deletes each advanced range, so after a
    /// rewind the cache is empty and "holds no block above the DB" is satisfied by
    /// an empty cache. It becomes load-bearing the day the loop reads ahead past
    /// one batch.
    #[tokio::test]
    async fn the_cache_is_truncated_to_the_height_upstream_landed_on() {
        use crate::sync::testing::{Fork, ForkAt};
        let t = REORG_PASS1_TIP;
        let rewind = u64::from(crate::constants::REWIND_DISTANCE_BLOCKS);
        let run = reorg_pass_over(
            Fork {
                at: ForkAt::Height((t + 1) - rewind / 2),
                after_ranges: 0,
            },
            t + 100,
        )
        .await;
        let (recorded, landed, target_ceiling) = rewind_as_recorded_and_as_taken(&run);

        assert!(
            landed < target_ceiling,
            "THE GEOMETRY: this row needs a target upstream CANNOT land on. The rewound batch \
             starts at {}, so the target is at most {target_ceiling}; upstream left the DB at \
             {landed}. If those are equal this fixture is the sibling geometry and cannot see the \
             defect — re-cut the row, never relax it. batches {:?}",
            target_ceiling + u64::from(crate::constants::REWIND_DISTANCE_BLOCKS),
            batch_shape(&run.batches)
        );

        assert_eq!(
            recorded,
            landed,
            "INC-025's second clause: the rewind is RECORDED at {recorded} — our target, because \
             `truncate_to_height`'s return is discarded — while upstream truncated the DB to \
             {landed}. That recorded height is what the CACHE was truncated to and what the host \
             was told the wallet's position is: {} blocks of chain the wallet does not hold. \
             samples {:?}",
            recorded.saturating_sub(landed),
            run.samples
        );

        assert!(
            run.cache_tip_after.is_none_or(|h| h <= landed),
            "and the cache must hold no block above the height the DB landed on ({landed}): cache \
             tip {:?}",
            run.cache_tip_after
        );
    }

    /// **The CONTROL for the row above, and the reason it names its geometry.**
    /// The same invariant — the recorded rewind height is the height the DB
    /// actually took — on the `BelowFirstRangeEnd(4)` fork of
    /// `a_rewound_throttled_batch_records_exactly_one_snap_ms`, where pass 2's
    /// first batch commits BEFORE the fork is revealed. Measured at the base
    /// the rewound batch starts at 280,401, the target is 280,391, and
    /// upstream lands exactly there — so on this geometry, and only on this one,
    /// "our target" and "the height upstream landed on" are the same number and
    /// no mutation of the reorg arm can separate them. GREEN at the base and green
    /// after the repair; it is here so that a future reader measuring only this
    /// fork does not conclude the defect is unreachable (it was,, and the
    /// refresh geometry refuted it).
    #[tokio::test]
    async fn a_rewound_pass_whose_target_is_itself_reachable_records_that_same_height() {
        use crate::sync::testing::{Fork, ForkAt};
        let run = reorg_pass_over(
            Fork {
                at: ForkAt::BelowFirstRangeEnd(4),
                after_ranges: 1,
            },
            REORG_PASS1_TIP + 200,
        )
        .await;
        let (recorded, landed, target_ceiling) = rewind_as_recorded_and_as_taken(&run);
        assert_eq!(
            landed,
            target_ceiling,
            "the control's own geometry: on this fork upstream lands ON the target ({landed} vs a \
             ceiling of {target_ceiling}). If it stops doing so, this row has become a second \
             copy of the defect row and the two must be re-cut together. batches {:?}",
            batch_shape(&run.batches)
        );
        assert_eq!(
            recorded, landed,
            "the invariant, on the geometry that cannot distinguish target from landing: the \
             recorded rewind height must still be the height the DB holds. samples {:?}",
            run.samples
        );
        assert!(
            run.cache_tip_after.is_none_or(|h| h <= landed),
            "and the cache holds no block above it: cache tip {:?}",
            run.cache_tip_after
        );
    }

    /// The same fork driven through the PRODUCTION pass body under a real
    /// [`SyncController`] (`controller_over` — the T0-1b S2 seam), ABOVE the
    /// bundled row so the pass grades `AtOrAboveBundle` and `emit_synced`'s M2
    /// stamp gate is OPEN. That gate is why the incident is a durable claim and
    /// not just a wrong live status, so a fixture below the row would not be the
    /// incident. Returns everything the two surface rows need.
    struct ControllerReorgRun {
        /// The reorg pass, as the controller saw it.
        pass: Result<sync::SyncPass, WalletError>,
        /// The status the controller PUBLISHED for it.
        status: SyncStatus,
        /// The durable stamp before and after the reorg pass.
        stamp_before: Option<crate::state::SyncStamp>,
        stamp_after: Option<crate::state::SyncStamp>,
        /// `block_max_scanned` after the reorg pass.
        scanned_after: Option<BlockHeight>,
        /// The tip the forking endpoint served the reorg pass.
        tip: u32,
    }

    /// Pass 1: an honest server at `H` (a real scan; the wallet reaches `H` and,
    /// the grade being at-or-above, the stamp lands at `H`). Pass 2: the same
    /// chain 200 blocks on, forked 4 blocks below the end of the first range it
    /// serves — the SCAN-1 geometry, on the shipped pass body.
    async fn controller_reorg_run() -> ControllerReorgRun {
        use crate::sync::testing::{Fork, ForkAt};
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let h = h_above_the_row();
        let w = wallet_with_account_at(dir.path(), &vault, u64::from(h) - 250).await;

        let ctl = w.controller_over(ScriptedPassClient::honest(h));
        let first = ctl.once().await.expect("pass 1");
        assert!(
            first.batches > 0,
            "precondition: the wallet is driven to H by a REAL scan"
        );
        assert_eq!(
            w.scanned_tip().await.expect("scanned"),
            Some(BlockHeight::new(h)),
            "precondition: after pass 1 the wallet HOLDS H"
        );
        let stamp_before = w.snapshot().await.expect("snap").last_synced;
        assert_eq!(
            stamp_before.map(|s| s.height),
            Some(BlockHeight::new(h)),
            "precondition: this fixture's server grades at or above the row, so M2's stamp gate \
             is OPEN and pass 1 stamped H — the gate being open is what makes the reorg pass's \
             stamp a durable claim rather than a live-status glitch"
        );

        let tip = h + 200;
        let mut forking = ScriptedPassClient::honest(tip);
        forking.chain.fork = Some(Fork {
            at: ForkAt::BelowFirstRangeEnd(4),
            after_ranges: 1,
        });
        let ctl2 = w.controller_over(forking);
        let rx2 = ctl2.subscribe();
        let pass = ctl2.once().await;
        let status = rx2.borrow().clone();
        let scanned_after = w.scanned_tip().await.expect("scanned");
        let stamp_after = w.snapshot().await.expect("snap").last_synced;
        w.close().await.expect("close");
        ControllerReorgRun {
            pass,
            status,
            stamp_before,
            stamp_after,
            scanned_after,
            tip,
        }
    }

    // ── §4u REW-1 (the REQ-1-R fold review's row 1): a fork on every pass climbs
    //    the ladder and is reported as the endpoint's; one honest reorg is not ──
    //
    // Both rows below run the LOOP (`start()`, never `once()`) of one controller
    // over the production engine — the ladder and the streak are `run_loop`'s
    // own — on the paused clock (`start_paused`). That clock is safe under the
    // engine: tokio inhibits auto-advance for the life of every `spawn_blocking`
    // task on the current-thread runtime, so a DB section cannot let the clock
    // jump into the watchdog, and the only time that passes is the loop's own
    // sleeps — the gap between two pass-head tip fetches IS the sleep the loop
    // chose (`FakeChain::pass_heads`, the engine-side twin of the controller
    // tests' `call_times`). The endpoint is `controller_reorg_run`'s: an honest
    // server at `H` for pass 1 under its own controller, then a second client
    // over the same wallet — for RW-4 one whose chain forks at EVERY pass head
    // (`sync::testing::PassForks`, built for that row because a `ForkStorm` is
    // keyed to range starts over a fixed tip and is spent inside one pass: a
    // controller over a storm chain rewinds once and is then up to date). The
    // status family: `honest` above the row serves no roots, which reads
    // `Withheld` — a report, so a clean pass's terminal is `UpToDateDegraded`,
    // never a stall (`…reports_a_tip_pinned_below_the_wallets_own_height_as_behind`
    // says why `current` cannot serve a second pass over this chain).

    /// §4u's streak length, READ FROM THE SHIPPED CONSTANT — the twin of the
    /// one in `sync_controller::tests`. Both were spelled `6` locally while the
    /// halves were blind (`constants.rs` did not carry it at the split base);
    /// **the join reconciled both**, so a maintainer decision on the number moves
    /// these rows with the code. A local copy that is never reconciled is a
    /// second source of truth — the REQ-1-R fold review's row 11.
    const EXPECTED_REWINDING_STREAK: usize =
        crate::constants::MAX_CONSECUTIVE_REWINDING_PASSES as usize;

    /// A status the loop publishes when a pass has ENDED — the up-to-date
    /// family, a stall, the behind claim — as opposed to the live `Scanning`
    /// samples a pass emits while it runs (and the `Idle` / `Connecting` a
    /// channel starts on).
    fn is_pass_terminal(status: &SyncStatus) -> bool {
        !matches!(
            status,
            SyncStatus::Idle | SyncStatus::Connecting { .. } | SyncStatus::Scanning { .. }
        )
    }

    fn is_up_to_date_family(status: &SyncStatus) -> bool {
        matches!(
            status,
            SyncStatus::UpToDate { .. } | SyncStatus::UpToDateDegraded { .. }
        )
    }

    fn is_endpoint_misbehaving(status: &SyncStatus) -> bool {
        matches!(
            status,
            SyncStatus::Stalled {
                reason: StallReason::EndpointMisbehaving
            }
        )
    }

    /// Run `ctl`'s loop until it has published a terminal for `passes` passes,
    /// then stop it. Returns the LAST terminal of every pass, in order — the
    /// loop's last word on that pass, whichever way an implementation orders a
    /// stall behind a terminal: two terminals published for one pass land on
    /// the same virtual instant (nothing but the loop's own sleeps moves this
    /// clock), and consecutive passes are at least the initial rung apart.
    /// Fails rather than hangs if the loop goes silent for a day of virtual
    /// time (a dead loop task idles the runtime, and the paused clock then
    /// jumps straight to this bound).
    async fn loop_pass_terminals(ctl: &SyncController, passes: usize) -> Vec<SyncStatus> {
        let mut sub = ctl.subscribe();
        let mut per_pass: Vec<(tokio::time::Instant, SyncStatus)> = Vec::new();
        ctl.start();
        while per_pass.len() < passes {
            tokio::time::timeout(std::time::Duration::from_secs(24 * 3600), sub.changed())
                .await
                .unwrap_or_else(|_| {
                    panic!(
                        "the loop went silent after {} of {passes} passes; terminals so far {:?}",
                        per_pass.len(),
                        per_pass.iter().map(|(_, s)| s).collect::<Vec<_>>()
                    )
                })
                .expect("status stream alive");
            let status = sub.borrow_and_update().clone();
            if !is_pass_terminal(&status) {
                continue;
            }
            let now = tokio::time::Instant::now();
            match per_pass.last_mut() {
                Some((at, last)) if *at == now => *last = status,
                _ => per_pass.push((now, status)),
            }
        }
        // The last pass's last word: let the loop finish whatever it publishes
        // after the terminal that completed the count (a yielded task is not
        // idle, so the next pass cannot start meanwhile), then fold it in.
        for _ in 0..8 {
            tokio::task::yield_now().await;
        }
        if sub.has_changed().unwrap_or(false) {
            let status = sub.borrow_and_update().clone();
            if is_pass_terminal(&status)
                && let Some((at, last)) = per_pass.last_mut()
                && *at == tokio::time::Instant::now()
            {
                *last = status;
            }
        }
        ctl.stop().await;
        per_pass.into_iter().map(|(_, s)| s).collect()
    }

    /// The gaps between consecutive pass-head tip fetches, in whole seconds —
    /// spacing `i` (0-based) is the sleep the loop chose after pass `i + 1` (a
    /// pass takes no virtual time; see the section comment).
    fn pass_spacings_secs(heads: &[tokio::time::Instant]) -> Vec<u64> {
        heads.windows(2).map(|w| (w[1] - w[0]).as_secs()).collect()
    }

    /// The controller's PASS-level `wallet.sync` records, in order — one per
    /// pass: the clean-pass span, the watchdog arm, or the fault arm.
    ///
    /// Matched on a field only the CONTROLLER's own record carries (match
    /// the distinguishing FIELD). The two that qualify, and every site that
    /// emits them:
    /// - `batches` — `emit_synced`'s pass span (`sync_controller.rs:568`) and
    ///   the watchdog arm (`:460`);
    /// - `backoff_secs` — the fault arm (`:493`).
    ///
    /// It must NOT be written as the ABSENCE of a batch field: the engine's
    /// per-batch records carry `outcome` ALONE (`[("outcome", "rewind")]`,
    /// `[("outcome", "advance")]` — the resolved span fields, not a new span),
    /// so "has no `from`, has an `outcome`" admits all of them. Measured: on
    /// RW-4's run that form matched 29 records where 8 passes ran — three batch
    /// records per forking pass rode in with them. `loop_start` / `loop_stop`
    /// (`:321`, `:339`) carry `outcome` alone too and are excluded by the same
    /// test, with no need to name their values.
    ///
    /// **The streak report is excluded BY NAME, and that exclusion was added at
    /// the join** — it is the one place the two blind halves collided. The
    /// implementer's streak warn (`sync_controller.rs:954`) is a `wallet.sync`
    /// record that carries `backoff_secs`, so the field test above admits it and
    /// the count came out 10 where 8 passes ran: two extra, one for each pass
    /// past the streak threshold. Neither half was wrong on its own — the test
    /// half matched the only distinguishing fields that existed when it was
    /// written, and the implementer minted a second pass-level record for a
    /// reason the contract asked for. `outcome == "rewinding_streak"` is that
    /// record's own value and is what separates them.
    fn pass_level_events(records: &[Vec<(String, String)>]) -> Vec<Vec<(String, String)>> {
        records
            .iter()
            .filter(|r| {
                r.iter().any(|(n, _)| n == "batches" || n == "backoff_secs")
                    && !r
                        .iter()
                        .any(|(n, v)| n == "outcome" && v == "rewinding_streak")
            })
            .cloned()
            .collect()
    }

    fn field_u64(record: &[(String, String)], name: &str) -> Option<u64> {
        record
            .iter()
            .find(|(n, _)| n == name)
            .and_then(|(_, v)| v.parse().ok())
    }

    /// The number of forking passes RW-4 drives: enough for the streak to be
    /// reached and seen to hold one pass past it, AND for the ladder to have
    /// climbed past the poll interval where the row can see it. The ladder is
    /// `sync_controller::next_backoff`'s — double from `SYNC_BACKOFF_INITIAL_SECS`,
    /// capped at `SYNC_BACKOFF_MAX_SECS`, the shape pinned by
    /// `next_backoff_doubles_then_caps_at_max` — and under the `Err` arm's own
    /// order (sleep, then climb) the sleep after pass `j` reads the rung after
    /// `j − 1` climbs, so the first sleep above the poll interval is the one
    /// after pass `climbs + 1`, and the row needs `climbs + 2` pass heads to
    /// read it.
    fn rw4_forking_passes() -> usize {
        use crate::constants::{
            POLL_INTERVAL_SECS, SYNC_BACKOFF_INITIAL_SECS, SYNC_BACKOFF_MAX_SECS,
        };
        // A CONST assertion: all three are compile-time constants, so this is a
        // shape check on `constants.rs`, not a runtime one — a constant re-tuned
        // out of this shape must break the BUILD of the row that derives its
        // pass count from it, not one run of it.
        const {
            assert!(
                SYNC_BACKOFF_INITIAL_SECS <= POLL_INTERVAL_SECS
                    && POLL_INTERVAL_SECS < SYNC_BACKOFF_MAX_SECS,
                "the row's derivation assumes the ladder starts at or below the poll interval \
                 and can climb past it"
            );
        }
        let mut rung = SYNC_BACKOFF_INITIAL_SECS;
        let mut climbs = 0;
        while rung <= POLL_INTERVAL_SECS {
            rung = (rung * 2).min(SYNC_BACKOFF_MAX_SECS);
            climbs += 1;
        }
        (climbs + 2).max(EXPECTED_REWINDING_STREAK + 1)
    }

    /// Pass 1 of both §4u rows, `controller_reorg_run`'s: an honest server at
    /// `H` under its own controller, a REAL scan to `H` (the precondition every
    /// later rewind needs — checkpoints below `H` to land on).
    async fn synced_to_h_above_the_row(
        dir: &std::path::Path,
        vault: &Arc<dyn KeychainPort>,
    ) -> (Wallet, u32) {
        let h = h_above_the_row();
        let w = wallet_with_account_at(dir, vault, u64::from(h) - 250).await;
        let ctl = w.controller_over(ScriptedPassClient::honest(h));
        let first = ctl.once().await.expect("pass 1");
        assert!(
            first.batches > 0,
            "precondition: the wallet is driven to H by a REAL scan"
        );
        assert_eq!(
            w.scanned_tip().await.expect("scanned"),
            Some(BlockHeight::new(h)),
            "precondition: after pass 1 the wallet HOLDS H"
        );
        (w, h)
    }

    /// **§4u RW-4 — DEFECT row, RED at the base.** Through the production
    /// engine: a server that forks on every pass climbs the ladder and, at the
    /// streak, is reported as the endpoint's.
    ///
    /// After pass 1, ONE controller's LOOP over a client whose chain forks at
    /// every pass head for [`rw4_forking_passes`] passes — each: one continuity
    /// error at the first block above what the wallet holds, one rewind, a clean
    /// re-scan to a tip one batch further on — and then goes honest; run until
    /// the first clean pass after the storm. Asserted:
    /// 1. (receipts) the fixture forked once per forking pass, and the engine
    ///    rewound exactly once per forking pass — one `outcome = "rewind"` batch
    ///    span each — so every forking pass is a REWINDING pass that completed;
    /// 2. the spacing between pass heads is never below the poll interval, never
    ///    decreases while the forks continue, and the last one — after the
    ///    `climbs + 2`-th forking pass — is ABOVE the poll interval: the ladder
    ///    climbed across passes (at the base every spacing is 20 s);
    /// 3. the pass events' `backoff_secs`, where a pass event carries one, are
    ///    non-decreasing in pass order — the log agrees with the clock (at the
    ///    base no pass event carries the field, every pass completes, so clause
    ///    2 is what reds; this one checks whatever the built loop logs);
    /// 4. the status the loop leaves standing after the
    ///    `EXPECTED_REWINDING_STREAK`-th forking pass, and after the next, is
    ///    `Stalled { EndpointMisbehaving }`, and every earlier forking pass ends
    ///    on the up-to-date family (at the base every pass does);
    /// 5. a clean pass DECAYS the streak by one (the REW-1 fold review's row 1),
    ///    so the badge stands through the first clean passes after the storm and
    ///    the up-to-date family returns only on the one that takes the count
    ///    below the report — which also stamps the tip the chain settled on.
    #[tokio::test(start_paused = true)]
    async fn a_fork_per_pass_server_climbs_the_ladder_and_is_reported() {
        use crate::constants::{POLL_INTERVAL_SECS, SYNC_BATCH_BLOCKS};
        use crate::sync::testing::PassForks;
        use crate::tracing_guard::{CaptureLayer, CapturedEvents, assert_5_4_clean};
        use tracing_subscriber::prelude::*;

        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let (w, h) = synced_to_h_above_the_row(dir.path(), &vault).await;

        let forking_passes = rw4_forking_passes();
        let streak = EXPECTED_REWINDING_STREAK;
        let mut forking = ScriptedPassClient::honest(h);
        forking.chain.pass_forks = Some(PassForks {
            tip_step: u64::from(SYNC_BATCH_BLOCKS),
            max_passes: forking_passes,
        });
        let forks = Arc::clone(&forking.chain.pass_fork_heights);
        let heads = Arc::clone(&forking.chain.pass_heads);

        crate::tracing_guard::force_wallet_callsites_enabled();
        let sink = CapturedEvents::default();
        let subscriber = tracing_subscriber::registry().with(CaptureLayer::new(sink.clone()));
        let guard = tracing::subscriber::set_default(subscriber);
        // A clean pass DECAYS the streak by one since the REW-1 fold review's row
        // 1, so the badge needs this many clean passes after the storm to fall
        // below the report — derived from the two counts, never typed.
        let clean_to_clear = forking_passes - streak + 1;
        let ctl = w.controller_over(forking);
        let terminals = loop_pass_terminals(&ctl, forking_passes + clean_to_clear).await;
        drop(guard);
        assert_5_4_clean(&sink.fields());
        let stamp = w.snapshot().await.expect("snap").last_synced;
        w.close().await.expect("close");

        // 1. the receipts.
        let forks = forks.lock().expect("forks").clone();
        assert_eq!(
            forks.len(),
            forking_passes,
            "precondition: the fixture forked at every pass head for {forking_passes} passes; \
             forks {forks:?}"
        );
        let batches = batches_of(&sink.records_of("wallet.sync"));
        let rewinds = batches.iter().filter(|b| outcome_of(b) == "rewind").count();
        assert_eq!(
            rewinds,
            forking_passes,
            "precondition: the production engine rewound exactly once per forking pass; \
             batches {:?}",
            batch_shape(&batches)
        );
        let heads = heads.lock().expect("heads").clone();
        assert!(
            heads.len() > forking_passes,
            "harness: {} pass heads for {} passes",
            heads.len(),
            forking_passes + clean_to_clear
        );
        assert_eq!(
            terminals.len(),
            forking_passes + clean_to_clear,
            "harness: one terminal per pass; {terminals:?}"
        );
        // The pass-level filter matches a REAL line, and exactly one per pass.
        // A filter never measured against a real instance is the defect (a
        // watcher armed on a line nobody prints); without this receipt every
        // clause below that reads `events` grades vacuously.
        let all_sync = sink.records_of("wallet.sync");
        let events = pass_level_events(&all_sync);
        assert_eq!(
            events.len(),
            forking_passes + clean_to_clear,
            "precondition: the pass-level filter must reduce the `wallet.sync` records to exactly \
             one per pass — it matched {} of {} records. A filter that matches nothing would \
             grade the log clause below vacuously. Matched: {events:?}",
            events.len(),
            all_sync.len()
        );

        // 2. the ladder, on the clock.
        let spacings = pass_spacings_secs(&heads[..forking_passes + 1]);
        assert!(
            spacings.iter().all(|&s| s >= POLL_INTERVAL_SECS),
            "§4u: a rewinding pass never polls FASTER than a clean one; spacings {spacings:?} s"
        );
        assert!(
            spacings.windows(2).all(|w| w[1] >= w[0]),
            "§4u: the ladder never comes back down while the forks continue; spacings \
             {spacings:?} s"
        );
        let last = *spacings.last().expect("spacings");
        assert!(
            last > POLL_INTERVAL_SECS,
            "§4u RW-4: {forking_passes} consecutive passes over the production engine each met \
             a fork, rewound once and completed, and the loop's inter-pass spacing never left \
             the poll interval — spacings {spacings:?} s — because `Ok` resets the ladder \
             whatever the pass rewound: a fork-per-pass endpoint is met again every \
             {POLL_INTERVAL_SECS} s from the 1 s rung, forever. Expected the spacing after pass \
             {forking_passes} above {POLL_INTERVAL_SECS} s"
        );

        // 3. the ladder, as logged — and NOT vacuously. Clause 2 has just
        // established that the loop's ladder climbed on the clock, so the pass
        // events must say so too: §4u RW-4 asks for exactly that ("the
        // `wallet.sync` events' `backoff_secs` climb across passes"). Under a
        // fork-per-pass server every pass COMPLETES — there is no `Err` arm in
        // this run at all — so the clause is satisfiable only if the pass span
        // of a rewinding `Ok` pass carries `backoff_secs`. That field is already
        // named on the pass-level span by the controller's own module doc
        // (`sync_controller.rs:38`, `{batches, reorgs, outcome, backoff_secs}`)
        // while the shipped loop emits it on the `Err` arm alone (`:493`), so
        // this is what the row asks the implementer for, and it is named as such
        // in the round's report. An EMPTY `logged` fails the climb clause — the
        // whole point: a ladder logged only on a stall is invisible to an
        // operator watching a server that rewinds every pass and never stalls.
        let logged: Vec<u64> = events
            .iter()
            .filter_map(|e| field_u64(e, "backoff_secs"))
            .collect();
        // SCOPED AT THE JOIN to the FORKING passes, and re-scoped here to
        // the `clean_to_clear` honest passes that now end the run. The fixture
        // serves `forking_passes` forks and then goes honest, and a clean pass
        // POLLS whatever the ladder stands on — so its `backoff_secs` is the poll
        // interval and is SUPPOSED to come back down. Measured: logged
        // [20, 20, 20, 20, 20, 32, 64, 20, 20] — monotone across the seven
        // forking passes, then one 20 per honest pass. Grading those last values
        // as a regression would have made the row demand that a clean pass keep
        // climbing, which is the opposite of §4u's rule. The tail is asserted
        // below instead, as the poll it is. (What the clean pass does to the
        // LADDER since the REW-1 fold review's row 1 is step it down one rung,
        // not reset it — invisible here, because the sleep it takes is the poll
        // either way; `sync_controller`'s RW-2 control is where that is graded.)
        let (forking, honest) = logged.split_at(logged.len().saturating_sub(clean_to_clear));
        assert!(
            forking.windows(2).all(|w| w[1] >= w[0]),
            "the logged ladder agrees with the clock's: `backoff_secs` never comes back down \
             while the forks continue; logged over the forking passes {forking:?} (the honest \
             tail is {honest:?}), pass events {events:?}"
        );
        assert_eq!(
            honest,
            vec![POLL_INTERVAL_SECS; clean_to_clear],
            "and every honest pass that ends the run POLLS — a clean pass sleeps the poll \
             interval whatever the ladder stands on (§4u); logged {logged:?}"
        );
        let logged_climbed = match (forking.first(), forking.last()) {
            (Some(first), Some(last)) => last > first,
            _ => false,
        };
        assert!(
            logged_climbed,
            "§4u RW-4: the clock says the ladder climbed (spacings {spacings:?} s) and the log \
             does not — `backoff_secs` read {logged:?} across the {} pass-level records of this \
             run. Every pass here rewound and COMPLETED, so a rung that is only logged on the \
             `Err` arm never reaches the log at all, and an operator reading it cannot see the \
             endpoint being backed off. The rewinding pass's own span must carry the rung. Pass \
             events {events:?}",
            events.len()
        );

        // 4. / 5. the streak, on the surface.
        for (i, terminal) in terminals[..streak - 1].iter().enumerate() {
            assert!(
                is_up_to_date_family(terminal),
                "before the streak is reached a rewinding pass ends on its terminal; after pass \
                 {} the loop left {terminal:?}. All: {terminals:?}",
                i + 1
            );
        }
        assert!(
            is_endpoint_misbehaving(&terminals[streak - 1]),
            "§4u RW-4: after {streak} consecutive rewinding passes over the production engine \
             the status the loop leaves standing must be Stalled {{ EndpointMisbehaving }} — \
             the streak is the endpoint's — and it left {:?}. Terminals after each pass: \
             {terminals:?}",
            terminals[streak - 1]
        );
        assert!(
            is_endpoint_misbehaving(&terminals[streak]),
            "one more rewinding pass keeps the stall standing; after pass {} the loop left {:?}",
            streak + 1,
            terminals[streak]
        );
        for k in 0..clean_to_clear - 1 {
            assert!(
                is_endpoint_misbehaving(&terminals[forking_passes + k]),
                "§4u RW-4, the REW-1 fold review's row 1: clean pass {} of {clean_to_clear} \
                 after the storm only DECAYS the streak (to {}), so the badge still stands — a \
                 clean pass is free, so clearing on one handed a forking endpoint the badge back \
                 for nothing. Got {:?}. All: {terminals:?}",
                k + 1,
                forking_passes - k - 1,
                terminals[forking_passes + k]
            );
        }
        let after_storm = &terminals[forking_passes + clean_to_clear - 1];
        assert!(
            is_up_to_date_family(after_storm),
            "clean pass {clean_to_clear} after the storm decays the streak below the report, so \
             the up-to-date family returns; got {after_storm:?}. All: {terminals:?}"
        );
        let settled = h + u32::try_from(forks.len()).expect("a fixture count") * SYNC_BATCH_BLOCKS;
        assert_eq!(
            stamp.map(|s| s.height),
            Some(BlockHeight::new(settled)),
            "the clean pass after the storm stamps the tip the chain settled on"
        );
    }

    /// **§4u RW-5 (the engine half) — CONTROL, green at the base and under the
    /// rule.** One honest reorg through the production engine is forgiven by
    /// the next clean pass: `controller_reorg_run`'s single `Fork` (R-1's
    /// geometry — revealed after the first range, tip `H + 200`) under one
    /// controller's LOOP, then two honest passes over the same chain (the fork
    /// stays revealed and links from what the wallet holds after its rewind —
    /// `reorg_passes`'s recovery pass). Asserted: exactly one rewind batch in
    /// the run; every pass ends on the up-to-date family and none is ever
    /// `EndpointMisbehaving`; the wallet holds and the stamp names `H + 200`;
    /// every spacing is exactly the poll interval (the one rewinding pass
    /// sleeps `max(POLL, rung)` with the rung far below it, and the clean pass
    /// resets whatever it climbed). The controller half — the ladder reset
    /// itself, on the fake engine — is
    /// `sync_controller::tests::one_honest_reorg_is_forgiven_by_the_next_clean_pass`.
    #[tokio::test(start_paused = true)]
    async fn one_honest_reorg_is_forgiven_by_the_next_clean_pass() {
        use crate::constants::POLL_INTERVAL_SECS;
        use crate::sync::testing::{Fork, ForkAt};
        use crate::tracing_guard::{CaptureLayer, CapturedEvents, assert_5_4_clean};
        use tracing_subscriber::prelude::*;

        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let (w, h) = synced_to_h_above_the_row(dir.path(), &vault).await;

        let tip = h + 200;
        let mut forking = ScriptedPassClient::honest(tip);
        forking.chain.fork = Some(Fork {
            at: ForkAt::BelowFirstRangeEnd(4),
            after_ranges: 1,
        });
        let heads = Arc::clone(&forking.chain.pass_heads);

        crate::tracing_guard::force_wallet_callsites_enabled();
        let sink = CapturedEvents::default();
        let subscriber = tracing_subscriber::registry().with(CaptureLayer::new(sink.clone()));
        let guard = tracing::subscriber::set_default(subscriber);
        let ctl = w.controller_over(forking);
        let terminals = loop_pass_terminals(&ctl, 3).await;
        drop(guard);
        assert_5_4_clean(&sink.fields());
        let stamp = w.snapshot().await.expect("snap").last_synced;
        let scanned = w.scanned_tip().await.expect("scanned");
        w.close().await.expect("close");

        let batches = batches_of(&sink.records_of("wallet.sync"));
        let rewinds = batches.iter().filter(|b| outcome_of(b) == "rewind").count();
        assert_eq!(
            rewinds,
            1,
            "precondition: one revealed fork ⇒ one rewind, in the first pass; batches {:?}",
            batch_shape(&batches)
        );
        assert_eq!(
            terminals.len(),
            3,
            "harness: one terminal per pass; {terminals:?}"
        );
        assert!(
            terminals.iter().all(is_up_to_date_family),
            "one honest reorg then clean passes: every pass ends on the up-to-date family; \
             terminals {terminals:?}"
        );
        assert!(
            !terminals.iter().any(is_endpoint_misbehaving),
            "one honest reorg is never `EndpointMisbehaving`; terminals {terminals:?}"
        );
        assert_eq!(
            scanned,
            Some(BlockHeight::new(tip)),
            "the wallet holds the forked tip after the run"
        );
        assert_eq!(
            stamp.map(|s| s.height),
            Some(BlockHeight::new(tip)),
            "the stamp names the tip the passes reached"
        );
        let heads = heads.lock().expect("heads").clone();
        assert!(
            heads.len() >= 3,
            "harness: {} pass heads for 3 passes",
            heads.len()
        );
        let spacings = pass_spacings_secs(&heads[..3]);
        assert_eq!(
            spacings,
            vec![POLL_INTERVAL_SECS; 2],
            "one honest reorg then a clean pass: every sleep is the poll interval; got \
             {spacings:?} s"
        );
    }

    /// **§4q R-2 (INC-025) — DEFECT row, RED at the base.** The durable claim.
    ///
    /// Through the shipped controller: after a pass that rewound, an up-to-date
    /// terminal may name only the height the wallet HOLDS, and a stamp the pass
    /// WRITES may name only that same height. A pass that instead stalls on §4q
    /// P-R3's belt makes no claim at all — it must leave the stamp exactly as it
    /// found it. Every arm of the match is one of those three honest shapes, so
    /// the row cannot pass by the pass failing for some unrelated reason.
    ///
    /// At the base: the pass returns `Ok` at the pass-head tip, the controller
    /// publishes an up-to-date terminal at `H + 200` and `record_synced` writes
    /// the stamp there, while `block_max_scanned` sits at the rewind. Killer
    /// mutants: §4q P-R1's `update_chain_tip` removed; the belt's stall softened
    /// to an `Ok`.
    ///
    /// SCOPE, stated so the row is not read as broader than it is: the stamp
    /// PASS 1 wrote (at `H`) also names a height above the wallet's own once the
    /// rewind lands, and this row does not fail on it — a surviving older stamp
    /// is a different, smaller honesty gap that INC-025 does not name and §4q
    /// does not repair. The clause here is about the claim the REWOUND PASS makes.
    #[tokio::test]
    async fn a_rewound_pass_does_not_stamp_the_full_tip_while_the_wallet_is_below_it() {
        let run = controller_reorg_run().await;
        let scanned = run.scanned_after.map(BlockHeight::value);
        match &run.pass {
            Ok(p) => {
                assert!(
                    p.reorgs >= 1,
                    "precondition: the forking endpoint must make the pass REWIND, or this row \
                     measures an ordinary pass; got reorgs = {}",
                    p.reorgs
                );
                // The DURABLE claim first — it is the one that survives a relaunch,
                // and it is the one INC-025 is filed about.
                if run.stamp_after != run.stamp_before {
                    assert_eq!(
                        run.stamp_after.map(|s| s.height.value()),
                        scanned,
                        "INC-025, the DURABLE half: this pass wrote a NEW stamp ({:?} → {:?}) \
                         while block_max_scanned is {scanned:?}. The stamp survives a relaunch, \
                         so a rewound pass may stamp only the height the wallet holds — the \
                         window INC-025 measures does not close until the NEXT pass re-queues, \
                         and the stamp outlives it. status {:?}",
                        run.stamp_before,
                        run.stamp_after,
                        run.status
                    );
                }
                let terminal_tip = match &run.status {
                    SyncStatus::UpToDate { tip }
                    | SyncStatus::UpToDateLimited { tip }
                    | SyncStatus::UpToDateDegraded { tip, .. } => Some(tip.value()),
                    _ => None,
                };
                if let Some(t) = terminal_tip {
                    assert_eq!(
                        Some(t),
                        scanned,
                        "INC-025, the LIVE half: the controller published an up-to-date terminal \
                         at {t} while the wallet holds {scanned:?} — 'as of block {t}' rendered \
                         from a chain the wallet no longer has above the rewind. An up-to-date \
                         terminal may name only the height block_max_scanned reports. status {:?}",
                        run.status
                    );
                }
            }
            Err(WalletError::Sync {
                stall: StallReason::ChainReorg,
            }) => {
                assert_eq!(
                    run.stamp_after, run.stamp_before,
                    "§4q P-R3's belt: a pass that stalls on the reorg makes NO claim, so it \
                     writes no stamp"
                );
            }
            Err(other) => panic!(
                "the reorg pass must either complete or stall on the reorg belt; got {other:?} \
                 (status {:?})",
                run.status
            ),
        }
    }

    /// **§4q R-4 (INC-025) — the BELT row, RED at the base.** A rewind that
    /// leaves the queue empty must STALL, never stamp.
    ///
    /// The belt is unreachable while §4q P-R1's re-queue holds, so this row is
    /// written as the fail-closed disjunction the loop must satisfy in every
    /// build: a pass that rewound and returned `Ok` HAS re-queued, so it holds the
    /// tip; a pass that could not must return `Err(Sync { ChainReorg })`, publish
    /// `Stalled { ChainReorg }` and leave the stamp untouched. There is no third
    /// honest shape, and "returned Ok while the wallet sits below the tip it
    /// reported" is precisely the base's shape.
    ///
    /// ITS KILLER, named: §4q P-R1's `db.update_chain_tip(recorded_tip)` call
    /// removed from the reorg arm, with the belt in place — the pass then finds
    /// the queue empty after the rewind and must take the `Err` branch. With
    /// BOTH removed (the base) the row reds on the `Ok` branch, which is the
    /// finding §4q R-6 asks the implementer to record: the belt is what makes a
    /// silently-empty re-queue loud instead of durable.
    #[tokio::test]
    async fn a_rewind_that_leaves_the_queue_empty_stalls_instead_of_stamping() {
        let run = controller_reorg_run().await;
        let scanned = run.scanned_after.map(BlockHeight::value);
        match &run.pass {
            Ok(p) => {
                assert!(
                    p.reorgs >= 1,
                    "precondition: the forking endpoint must make the pass REWIND; got reorgs = {}",
                    p.reorgs
                );
                assert_eq!(
                    scanned,
                    Some(run.tip),
                    "INC-025: the pass returned Ok — 'up to date with the recorded tip' — with \
                     block_max_scanned at {scanned:?} and the tip at {}. A rewound pass may only \
                     end Ok when it re-queued the rewound span and scanned it; a pass that read \
                     the trimmed queue as empty must stall (§4q P-R3), never report a tip it \
                     does not hold. status {:?}, stamp {:?}",
                    run.tip,
                    run.status,
                    run.stamp_after
                );
            }
            Err(WalletError::Sync {
                stall: StallReason::ChainReorg,
            }) => {
                assert!(
                    matches!(
                        run.status,
                        SyncStatus::Stalled {
                            reason: StallReason::ChainReorg
                        }
                    ),
                    "the belt's stall reaches the SURFACE as a reorg stall; got {:?}",
                    run.status
                );
                assert_eq!(
                    run.stamp_after, run.stamp_before,
                    "and it writes NO stamp — the whole point of stalling instead of stamping"
                );
            }
            Err(other) => panic!(
                "a rewind that leaves the queue empty stalls with Sync {{ ChainReorg }}; got \
                 {other:?} (status {:?})",
                run.status
            ),
        }
    }

    // ── §4q-R (REQ-1-R): the belt is REACHABLE and says so, the exit checks the
    //    DB, one pass cannot be kept alive by forks, and the log tells the true
    //    depth ──────────────────────────────────────────────────────────────────
    //
    // The REQ-1 fold review found that the belt R-4 could only reach through a
    // plant (row 8) has a reachable geometry (row 1), that P-R4's storm bound is a
    // number the ENDPOINT picks (row 2), that the in-lock re-queue runs the
    // INC-024 birthday guard's precondition on a lowered `max_scanned` (row 3),
    // and that `wallet.reorg_rewind`'s `depth` is fabricated from a constant
    // (row 5). Every row below drives one of those through the SHIPPED path —
    // `sync_once`, or the production pass body under a real `SyncController` —
    // and none of them plants anything: the geometries are reached with the
    // fixture knobs the tree already has plus ONE additive fake-endpoint mode
    // (`sync::testing::ForkStorm`, the repeated fork §4q-run owed as row 1).
    //
    // THE GEOMETRY THE FIRST FOUR SHARE, and why it needed no new seam. Row 1
    // needs a queued range ABOVE the tip the pass records. `next_batch` takes
    // whatever `suggest_scan_ranges` returns with no clamp to that tip, and
    // upstream's `update_chain_tip` early-returns when `new_tip < max_scanned`
    // (`scanning.rs`, the "caller has caught the chain mid-reorg" arm — read at
    // source), so the range survives the pass head untouched. A range like that
    // is what a CANCELLED pass leaves behind: the app backgrounds mid-sync, the
    // wallet keeps the queue, and the next pass meets an endpoint whose reported
    // tip has DROPPED below what this wallet already holds — a peer switch, a
    // resharded server, or a hostile one. The cancel is driven through the
    // progress reporter `sync_once` already takes (`report` fires on every
    // committed batch, outside the db lock), so pass 1 stops at a chosen
    // frontier with NO test door in the wallet: [`leftover_range_run`].

    /// The measured shape of a pass whose queue held a range ABOVE the tip it
    /// recorded — §4q-R's rows RR-1, RR-2 and RR-5 (the fold review's rows 1, 4
    /// and 3). A SIBLING of [`reorg_pass_over`], not a widening of it: that
    /// helper's pass 1 runs to completion (its rows are about a wallet AT the
    /// honest tip), and this one's is deliberately abandoned part-way.
    struct LeftoverRun {
        /// Pass 2 — the pass whose first batch sat above the recorded tip.
        pass: Result<sync::SyncPass, WalletError>,
        /// Its `wallet.sync` records split per batch, in capture order.
        batches: Vec<Vec<(String, String)>>,
        /// `block_max_scanned` through the wallet's own reader, before pass 2.
        scanned_before: Option<BlockHeight>,
        /// … and after it.
        scanned_after: Option<BlockHeight>,
        /// Whether pass 2 logged the belt's `outcome = "rewind_left_queue_empty"`.
        belt_line: bool,
        /// The tip pass 2's endpoint reported (`pass.tip`'s expected value).
        tip: u32,
    }

    /// Drive it: an account whose birthday is `birthday_anchor + 1`; pass 1 over
    /// an honest chain 300 blocks above `scan_to`, CANCELLED (through the
    /// progress reporter) the moment a committed batch reaches `scan_to`, so the
    /// wallet holds `scan_to - 1` and the queue still holds everything above it;
    /// then pass 2 against an endpoint reporting `reported_tip` — BELOW what the
    /// wallet holds — that has forked at `scan_to - 1`, so the leftover range's
    /// first block no longer chains from the block the wallet holds under it.
    ///
    /// The fixture asserts its own preconditions, because every row here is
    /// about what happens AFTER them: pass 1 really was cancelled, it really
    /// left the wallet at `scan_to - 1`, and `reported_tip` really is below that
    /// (which is what makes the pass head's `update_chain_tip` early-return and
    /// the leftover range survive — the finding's precondition, not an incidental
    /// property of these numbers).
    async fn leftover_range_run(
        birthday_anchor: u64,
        scan_to: u64,
        reported_tip: u64,
    ) -> LeftoverRun {
        use crate::sync::CancelToken;
        use crate::sync::testing::{FakeChain, Fork, ForkAt};
        use crate::tracing_guard::{CaptureLayer, CapturedEvents, assert_5_4_clean};
        use tracing_subscriber::prelude::*;

        assert!(
            reported_tip < scan_to - 1,
            "the fixture's own precondition: pass 2's endpoint must report a tip BELOW the height \
             the wallet holds ({reported_tip} vs {}), or the pass head's update_chain_tip does \
             not early-return and the leftover range does not survive",
            scan_to - 1
        );
        crate::tracing_guard::force_wallet_callsites_enabled();
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let w = wallet_with_account_at(dir.path(), &vault, birthday_anchor).await;

        // Pass 1, abandoned at `scan_to`: the reporter flips the pass's own
        // cancel token the first time a committed batch reports that frontier.
        // `sync_once` reports from the async task with no db lock held and polls
        // the token between batches, so the stop lands at a batch BOUNDARY and
        // the geometry is deterministic — not a race.
        let cancel = CancelToken::new();
        let flag = cancel.clone();
        let cancel_at = move |p: sync::ScanProgress| {
            if u64::from(p.frontier.value()) >= scan_to {
                flag.cancel();
            }
        };
        let report: &(dyn Fn(sync::ScanProgress) + Sync) = &cancel_at;
        let mut original = FakeChain::to_tip(scan_to + 300);
        let pass1 = w
            .sync_once(&mut original, &cancel, report)
            .await
            .expect("pass 1");
        assert!(
            pass1.cancelled,
            "the fixture's own precondition: pass 1 is ABANDONED part-way, so the queue keeps the \
             range above the wallet's frontier"
        );
        let scanned_before = w.scanned_tip().await.expect("scanned tip");
        assert_eq!(
            scanned_before.map(BlockHeight::value),
            Some(u32::try_from(scan_to - 1).expect("a fixture height")),
            "the fixture's own precondition: pass 1 stopped at the chosen frontier"
        );

        let sink = CapturedEvents::default();
        let subscriber = tracing_subscriber::registry().with(CaptureLayer::new(sink.clone()));
        let guard = tracing::subscriber::set_default(subscriber);
        let mut forked = FakeChain::to_tip(reported_tip);
        forked.fork = Some(Fork {
            // The fork starts at the last block the wallet holds, so the first
            // block of the leftover range carries a parent hash the wallet does
            // not have — upstream's `PrevHashMismatch`, the continuity error
            // `scan_batch` classifies as a reorg.
            at: ForkAt::Height(scan_to - 1),
            after_ranges: 0,
        });
        let live = CancelToken::new();
        let pass = w.sync_once(&mut forked, &live, NOOP_PROGRESS).await;
        let fields = sink.fields();
        assert_5_4_clean(&fields);
        let belt_line = fields
            .iter()
            .any(|(n, v)| n == "outcome" && v == "rewind_left_queue_empty");
        let batches = batches_of(&sink.records_of("wallet.sync"));
        drop(guard);
        let scanned_after = w.scanned_tip().await.expect("scanned tip");
        w.close().await.expect("close");
        LeftoverRun {
            pass,
            batches,
            scanned_before,
            scanned_after,
            belt_line,
            tip: u32::try_from(reported_tip).expect("a fixture height"),
        }
    }

    /// What an under-claiming pass must look like at the up-to-date exit, given
    /// the run: `Ok`, `pass.tip` naming what the ENDPOINT claimed, the wallet
    /// holding at least that much, and no belt line. Shared by the two RR-1 rows
    /// so the strict and the boundary geometry are graded by ONE statement of
    /// the property (the difference between them is the geometry, not the rule).
    fn assert_under_claim_not_stall(run: &LeftoverRun, what: &str) {
        let pass = match &run.pass {
            Ok(p) => p,
            Err(e) => panic!(
                "§4q-R P-RR1/P-RR2 ({what}): the endpoint is BEHIND this wallet's own scan — it \
                 reported tip {} while the wallet held {:?} — so the rewind landed at or above \
                 that tip and the re-queue upstream would refuse is skipped, not stalled on. The \
                 pass must end as the UNDER-CLAIM it is. Got Err({e:?}); belt line logged: {}; \
                 batches {:?}; the wallet now holds {:?}",
                run.tip,
                run.scanned_before.map(BlockHeight::value),
                run.belt_line,
                batch_shape(&run.batches),
                run.scanned_after.map(BlockHeight::value)
            ),
        };
        assert_eq!(
            pass.reorgs,
            1,
            "the fixture's non-vacuity: this pass must REWIND (a fork inside the leftover range), \
             or it is not the geometry the finding names; batches {:?}",
            batch_shape(&run.batches)
        );
        assert_eq!(
            pass.tip.map(BlockHeight::value),
            Some(run.tip),
            "`pass.tip` names what the ENDPOINT claimed, never what the wallet holds"
        );
        assert!(
            run.scanned_after.is_some_and(|h| h.value() >= run.tip),
            "the exit's rule (§4q-R P-RR2): `Ok` requires block_max_scanned >= pass.tip. The \
             wallet holds {:?} against a claimed tip of {}. batches {:?}",
            run.scanned_after.map(BlockHeight::value),
            run.tip,
            batch_shape(&run.batches)
        );
        assert!(
            !run.belt_line,
            "and NOTHING may log `outcome = \"rewind_left_queue_empty\"` here: the queue was left \
             empty because the endpoint is behind this wallet, which is the safe direction, not a \
             re-queue that silently did nothing. batches {:?}",
            batch_shape(&run.batches)
        );
    }

    /// **§4q-R RR-1 (fold review row 1) — DEFECT row, RED at the base.** A fork
    /// in a queued range ABOVE the recorded tip ends the pass as an UNDER-CLAIM,
    /// never as a stall.
    ///
    /// The reachability the fold's three "cannot fire" claims deny, driven:
    /// pass 1 is abandoned at 280,300 (the app backgrounds mid-sync), leaving
    /// `[280,300, 280,601)` queued above a wallet holding 280,299; pass 2's
    /// endpoint reports 280,100 — BELOW what this wallet already holds, which a
    /// peer switch or a hostile server produces — so the pass head's
    /// `update_chain_tip` early-returns and the leftover range is still there.
    /// Its first batch forks, the rewind lands at **280,290** (measured at the
    /// base), and 280,290 is ABOVE the recorded tip: upstream's own
    /// `new_tip < max_scanned` early return then makes the in-lock re-queue a
    /// no-op, `trim_scan_queue_to` has emptied the queue, and the belt reads a
    /// rewind followed by an empty queue.
    ///
    /// AT THE BASE this returns `Err(Sync { ChainReorg })` and logs
    /// `outcome = "rewind_left_queue_empty"` — the line documented as impossible
    /// — on a wallet that lost no block it needed and had published `UpToDate`.
    /// The repair (§4q-R P-RR1/P-RR2) tests `recorded_tip <= landed` in the arm,
    /// skips the re-queue, and lets the exit's DB read pass it: the wallet holds
    /// 280,290 ≥ the 280,100 the endpoint claimed, so the pass is `Ok` and the
    /// claim is an under-claim, which is the safe direction.
    ///
    /// Killer mutants: the `recorded_tip <= landed` test inverted or dropped
    /// (the belt fires again → this row reds on clause 1); the exit reading the
    /// FLAG instead of the DB (same).
    #[tokio::test]
    async fn a_fork_above_the_recorded_tip_ends_the_pass_as_an_under_claim_not_a_stall() {
        let run = leftover_range_run(279_999, REORG_PASS1_TIP, REORG_PASS1_TIP - 200).await;
        assert_under_claim_not_stall(&run, "the endpoint's tip strictly below the landing");
        // The geometry's own receipt, so a future reader can see WHY the base
        // stalled: the wallet ends ABOVE the tip it was told about.
        assert!(
            run.scanned_after.is_some_and(|h| h.value() > run.tip),
            "this geometry's landing is STRICTLY above the recorded tip (the boundary case is the \
             sibling row); wallet holds {:?} against tip {}",
            run.scanned_after.map(BlockHeight::value),
            run.tip
        );
    }

    /// **§4q-R RR-1, the boundary (gate 7) — DEFECT row, RED at the base.** The
    /// arm's new test is `recorded_tip <= landed`; this is the `==` cell.
    ///
    /// The same abandoned-pass geometry with the endpoint reporting **280,290**
    /// — exactly the height the rewind lands on (measured at the base).
    /// Upstream's early return does NOT fire on equality (`new_tip < max_scanned`
    /// is false), so at the base the re-queue is made, queues the empty range
    /// `[280,291, 280,291)`, and the belt stalls the pass anyway — the same
    /// false alarm reached through the other side of upstream's comparison. The
    /// repair must treat equality as the under-claim it is: the wallet holds
    /// EXACTLY the tip the endpoint claimed.
    ///
    /// Kept as a separate row rather than a case of the one above because the
    /// two reach the same exit through different upstream branches, and a repair
    /// that wrote `recorded_tip < landed` would pass that row and fail this one.
    #[tokio::test]
    async fn a_fork_landing_exactly_on_the_recorded_tip_ends_the_pass_as_an_under_claim() {
        let run = leftover_range_run(279_999, REORG_PASS1_TIP, REORG_PASS1_TIP - 10).await;
        assert_under_claim_not_stall(&run, "the endpoint's tip exactly at the landing");
        assert_eq!(
            run.scanned_after.map(BlockHeight::value),
            Some(run.tip),
            "the BOUNDARY this row exists for: the wallet holds exactly the tip the endpoint \
             claimed, so `block_max_scanned >= pass.tip` holds with equality and `recorded_tip <= \
             landed` holds with equality. batches {:?}",
            batch_shape(&run.batches)
        );
    }

    /// **§4q-R RR-2 (fold review row 4) — the exit's rule, at the one boundary
    /// this tree can reach. GREEN at the base; the DEFECT half is a DOCUMENTED
    /// GAP, and this row is what the adjudicator plants against.**
    ///
    /// The rule §4q-R P-RR2 states is about the DB, not about the flag: at the
    /// up-to-date exit, either `block_max_scanned >= pass.tip` and the pass is
    /// `Ok`, or the pass stalls `Sync { ChainReorg }` — whatever the last batch
    /// action was. The base's belt reads a FLAG that ANY `Advance` clears, so a
    /// rewind → advance → empty-queue pass is graded `Ok` without anything
    /// looking at what the wallet holds. This row drives exactly that shape —
    /// the endpoint reports 280,295, above the 280,290 the rewind lands on, so
    /// the in-lock re-queue DOES fire, the pass advances `[280,291, 280,296)`,
    /// the flag is cleared, and the queue then empties — and grades the exit by
    /// the DB.
    ///
    /// **Why it is green at the base, stated so it is not read as a miss.** The
    /// `<` half of the predicate — an empty queue with the wallet BELOW the tip
    /// — is not reachable from any fixture in this tree, and the reason is
    /// structural, not a gap in the fixtures: at that exit the pass head either
    /// queued up to the tip (so the pass scanned to it) or early-returned
    /// because `max_scanned > tip` (so the wallet is above it); a rewind's
    /// re-queue lands the same way — it early-returns only when `landed >
    /// recorded_tip`, which is the ABOVE case. The only path to "empty queue
    /// below the tip" is a re-queue that did nothing while `landed <
    /// recorded_tip`, which is the state upstream cannot produce today and which
    /// the belt exists for. THE PLANT this row is written for, named for the
    /// adjudicator: the arm's `update_chain_tip` re-queue removed AND the exit
    /// still allowed to return `Ok` (the flag read, or the DB read dropped) —
    /// then this same geometry rewinds, finds the survivor range below the
    /// landing, advances into it, and exits `Ok` at 280,290 against a claimed
    /// 280,295. THE SEAM that would let a test build it without a plant, named
    /// from the receiving code: a way to leave a GAP in the wallet's scan queue
    /// below the landing — there is none in `sync::testing` (a `FakeChain` can
    /// only shape what is SERVED, and the queue is upstream's own table), so it
    /// would be a write into the wallet DB from the test, which is a production
    /// door this round does not own.
    #[tokio::test]
    async fn an_empty_queue_below_the_tip_stalls_whatever_the_last_action_was() {
        let run = leftover_range_run(279_999, REORG_PASS1_TIP, REORG_PASS1_TIP - 5).await;
        match &run.pass {
            Ok(p) => {
                assert_eq!(
                    p.reorgs,
                    1,
                    "the fixture's non-vacuity: the pass must have REWOUND; batches {:?}",
                    batch_shape(&run.batches)
                );
                let rewind_at = first_rewind_batch(&run.batches).unwrap_or_else(|| {
                    panic!(
                        "the geometry must produce a rewound batch; batches {:?}",
                        batch_shape(&run.batches)
                    )
                });
                assert!(
                    run.batches[rewind_at + 1..]
                        .iter()
                        .any(|b| outcome_of(b) == "advance"),
                    "the fixture's non-vacuity: an ADVANCE must follow the rewind — that is the \
                     shape the belt's flag cannot see, and the whole point of grading this exit \
                     by the DB instead. batches {:?}",
                    batch_shape(&run.batches)
                );
                assert!(
                    run.scanned_after.is_some_and(|h| h.value() >= run.tip),
                    "§4q-R P-RR2: a pass may end `Ok` at the up-to-date exit only when the \
                     wallet HOLDS the tip it reports. It holds {:?} against pass.tip {}. batches \
                     {:?}",
                    run.scanned_after.map(BlockHeight::value),
                    run.tip,
                    batch_shape(&run.batches)
                );
                assert!(
                    !run.belt_line,
                    "and a pass that ends `Ok` logged no stall line; batches {:?}",
                    batch_shape(&run.batches)
                );
            }
            Err(WalletError::Sync {
                stall: StallReason::ChainReorg,
            }) => {
                assert!(
                    run.scanned_after.is_some_and(|h| h.value() < run.tip),
                    "the other half of the same rule: a pass may stall the reorg belt only when \
                     the wallet is BELOW the tip. It holds {:?} against pass.tip {}",
                    run.scanned_after.map(BlockHeight::value),
                    run.tip
                );
            }
            Err(other) => panic!(
                "the up-to-date exit has exactly two honest shapes — `Ok` at or above the tip, or \
                 `Sync {{ ChainReorg }}` below it; got {other:?}; batches {:?}",
                batch_shape(&run.batches)
            ),
        }
    }

    /// **§4q-R RR-5 (fold review row 3) — the INC-024 invariant, DEFECT row, RED
    /// at the base.** A tip below the wallet's birthday never reaches the reorg
    /// re-queue with an inverted range.
    ///
    /// The guard `birthday_beyond_tip` ABSTAINS when the wallet has scanned past
    /// the endpoint's tip (`scanned_past_tip`), justified by upstream's own
    /// early return — which the reorg arm's `update_chain_tip` call runs AFTER
    /// lowering `max_scanned`, so that justification is not obviously still true
    /// there. The invariant §4q-R P-RR5 states is what makes it true: `landed`
    /// is a `blocks` row and every `blocks` row is at or above the birthday, so
    /// a tip below the birthday makes `landed > tip` and upstream's early return
    /// fires before anything can build an inverted `ScanRange`.
    ///
    /// Driven, not asserted from the doc: a wallet whose birthday is 280,300,
    /// abandoned at 280,500, meeting an endpoint that reports 280,100 — BELOW
    /// its birthday. The row pins the precondition (the guard really does
    /// abstain on this geometry — otherwise the pass would return before the arm
    /// and the row would be measuring nothing), that no panic reaches this test,
    /// and the invariant itself at the values the run measured. At the base the
    /// pass reds on the SAME belt as RR-1 (the landing, 280,490, is above the
    /// reported tip), which is the honest reading: this geometry is a special
    /// case of the reachable one, with the birthday added.
    #[tokio::test]
    async fn a_tip_below_the_birthday_never_reaches_the_reorg_requeue() {
        let birthday = REORG_PASS1_TIP; // the account is imported at anchor + 1
        let reported_tip = REORG_PASS1_TIP - 200;
        let scanned_before = REORG_PASS1_TIP + 199;
        assert!(
            !sync::birthday_beyond_tip(
                Some(u32::try_from(birthday).expect("a fixture height")),
                u32::try_from(reported_tip).expect("a fixture height"),
                Some(u32::try_from(scanned_before).expect("a fixture height")),
            ),
            "the row's precondition (the fold review's row 3): on THIS geometry the birthday \
             guard ABSTAINS — the wallet has scanned past the endpoint's tip — so the pass runs \
             on and the reorg arm IS reached with a tip below the birthday. If the guard ever \
             refuses this geometry first, this row is a control and must say so."
        );

        let run = leftover_range_run(birthday - 1, REORG_PASS1_TIP + 200, reported_tip).await;
        // Reaching this line at all is half the row: `update_chain_tip` asserts
        // (a panic, not an error) on an inverted ScanRange, and the arm calls it
        // with the pass-head tip after lowering `max_scanned`.
        assert_eq!(
            run.scanned_before.map(BlockHeight::value),
            Some(u32::try_from(scanned_before).expect("a fixture height")),
            "the fixture's own precondition, and the third argument the guard was asked about"
        );
        // The INVARIANT first: it is a property of upstream's truncate, true at
        // the base and after the repair, and it is what the arm's comment will
        // claim — so it is graded here whether or not the belt below fires.
        let landed = run
            .scanned_after
            .map(BlockHeight::value)
            .expect("the wallet holds blocks after the rewind");
        assert!(
            u64::from(landed) >= birthday,
            "§4q-R P-RR5, the invariant itself: `landed` is a `blocks` row, so it is at or above \
             the wallet birthday ({landed} vs {birthday})"
        );
        assert!(
            u64::from(landed) > reported_tip + 1,
            "…and therefore strictly above `tip + 1` ({landed} vs {}), which is exactly what \
             makes upstream's early return fire and the INC-024 assert unreachable from the arm",
            reported_tip + 1
        );
        // …and then the pass's own shape, which is where the base fails.
        assert_under_claim_not_stall(&run, "a tip below the wallet's birthday");
    }

    /// §4q-R P-RR3's constant — the ABSOLUTE per-pass rewind cap. At the
    /// blind-split stage the test half spelled this as
    /// `3 × MAX_SCAN_REORGS_PER_PASS` because `constants.rs` did not carry it
    /// yet; the fold was meant to reconcile the copy and did not — the
    /// fold's code reviewer caught the second source of truth, and the row
    /// now reads the shipped constant itself, so a maintainer decision on the
    /// number moves the row with it.
    const EXPECTED_TOTAL_REORG_CAP: u32 = crate::constants::MAX_TOTAL_REORGS_PER_PASS;

    /// How many forks the storm endpoint serves before it goes honest — the
    /// fixture's HARD bound (§4q-R RR-3: "bound the fixture so a runaway base
    /// cannot hang the row"). Two above the cap: one so a pass that respects the
    /// cap meets its `+ 1`th rewind and stalls, one of headroom so an
    /// implementer's off-by-one in either direction is still SEEN by the row
    /// rather than hidden by a fixture that ran out of forks.
    const STORM_FORKS_SERVED: usize = EXPECTED_TOTAL_REORG_CAP as usize + 2;

    /// The reorg pass over the fork-advance-fork endpoint: pass 1 honest to
    /// [`REORG_PASS1_TIP`], then ONE pass against a chain that reveals a new
    /// fork every time the wallet climbs `advance_blocks` above the last one.
    /// Returns the pass and its captured batches.
    ///
    /// The tip is chosen from the fixture's own cycle: each fork costs the
    /// wallet ~191 blocks of frontier (one rewind batch and two advances,
    /// measured at the base), so 200 per generation with one generation of
    /// slack is enough for every fork to be served AND for the pass to reach the
    /// tip once the endpoint goes honest. A tip that is too low would end the
    /// pass early for a FIXTURE reason, which is why the row asserts the rewind
    /// count it saw rather than only the outcome.
    async fn fork_storm_pass() -> (
        Result<sync::SyncPass, WalletError>,
        Vec<Vec<(String, String)>>,
    ) {
        use crate::sync::CancelToken;
        use crate::sync::testing::{FakeChain, ForkStorm};
        use crate::tracing_guard::{CaptureLayer, CapturedEvents, assert_5_4_clean};
        use tracing_subscriber::prelude::*;

        crate::tracing_guard::force_wallet_callsites_enabled();
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let w = wallet_with_chain_account(dir.path(), &vault).await;
        let cancel = CancelToken::new();
        let mut original = FakeChain::to_tip(REORG_PASS1_TIP);
        let pass1 = w
            .sync_once(&mut original, &cancel, NOOP_PROGRESS)
            .await
            .expect("pass 1");
        assert_eq!(
            pass1.batches, 4,
            "the fixture's own precondition (`reorg_passes`): pass 1 scans the chain in four \
             batches, so a checkpoint exists at each batch end and every rewind has somewhere to \
             land"
        );

        let sink = CapturedEvents::default();
        let subscriber = tracing_subscriber::registry().with(CaptureLayer::new(sink.clone()));
        let guard = tracing::subscriber::set_default(subscriber);
        let mut storm = FakeChain::to_tip(REORG_PASS1_TIP + (STORM_FORKS_SERVED as u64 + 1) * 200);
        storm.storm = Some(ForkStorm {
            advance_blocks: 100,
            max_generations: STORM_FORKS_SERVED,
        });
        let pass = w.sync_once(&mut storm, &cancel, NOOP_PROGRESS).await;
        assert_5_4_clean(&sink.fields());
        let batches = batches_of(&sink.records_of("wallet.sync"));
        drop(guard);
        w.close().await.expect("close");
        (pass, batches)
    }

    /// The longest run of CONSECUTIVE `outcome = "rewind"` batches — the number
    /// the per-epoch bound [`MAX_SCAN_REORGS_PER_PASS`] actually reads (it is
    /// reset by any batch that sets a new high-water frontier), so a row can say
    /// WHICH bound ended a pass instead of guessing.
    fn longest_rewind_run(batches: &[Vec<(String, String)>]) -> usize {
        let mut best = 0;
        let mut run = 0;
        for b in batches {
            if outcome_of(b) == "rewind" {
                run += 1;
                best = best.max(run);
            } else {
                run = 0;
            }
        }
        best
    }

    /// **§4q-R RR-3 (fold review row 2) — DEFECT row, RED at the base.** A
    /// fork-advance-fork endpoint cannot hold ONE pass past the absolute cap.
    ///
    /// P-R4's bound is a number the ENDPOINT picks: `reorgs_since_progress`
    /// resets on any batch that sets a new high water, so a server that pays one
    /// advance for every fork never trips [`MAX_SCAN_REORGS_PER_PASS`] and is
    /// bounded only by the tip it chose for itself — each cycle a DB truncate, a
    /// queue rewrite, a `note_rewind` and a re-download from the landing. This
    /// row is that server: [`sync::testing::ForkStorm`] reveals a new branch each
    /// time a requested range starts 100 blocks above the last fork, and the
    /// wallet's own recovery is what earns the next one.
    ///
    /// Asserted:
    /// 1. the pass ends `Err(Sync { ChainReorg })` — a bounded pass, honestly
    ///    stalled, not a pass the endpoint decides the length of;
    /// 2. it did so within `EXPECTED_TOTAL_REORG_CAP + 1` rewinds (the cap held);
    /// 3. after MORE rewinds than the per-epoch bound alone allows, and
    /// 4. with no run of consecutive rewinds long enough for that epoch bound to
    ///    have been what stopped it — clauses 3 and 4 together say the ABSOLUTE
    ///    cap is what ended this pass, which is the only thing the row is about.
    ///
    /// AT THE BASE the pass runs on: it takes all **32** rewinds the fixture will
    /// serve — 70 batches — then reaches the tip and returns `Ok`. The fixture's
    /// own bound is what ends it, and on a real endpoint nothing would. (5.7 s,
    /// measured at the base the real scanner over those 70 batches. The
    /// cost is bounded by [`STORM_FORKS_SERVED`], never by the endpoint — which
    /// is the whole point of that constant.)
    ///
    /// Killer mutant: §4q-R P-RR3's cap removed. The storm CONTROL
    /// `sync::tests::classify_batch_accounts_progress_and_bounds_a_reorg_oscillation`
    /// stays green: it grades the per-epoch counter, which this geometry never
    /// trips.
    #[tokio::test]
    async fn a_fork_advance_fork_server_cannot_hold_one_pass_past_the_absolute_cap() {
        let (pass, batches) = fork_storm_pass().await;
        let rewinds = batches.iter().filter(|b| outcome_of(b) == "rewind").count();
        let epoch_bound = crate::constants::MAX_SCAN_REORGS_PER_PASS as usize;

        match &pass {
            Err(WalletError::Sync {
                stall: StallReason::ChainReorg,
            }) => {}
            Ok(p) => panic!(
                "§4q-R P-RR3: a fork-advance-fork endpoint kept this pass alive for {rewinds} \
                 rewinds — {} batches, each rewind a DB truncate, a queue rewrite and a \
                 re-download from the landing — and the pass then ended Ok at {:?}. The per-epoch \
                 bound never fires (every fork is paid for with an advance that sets a new high \
                 water), so with no ABSOLUTE per-pass cap the length of this pass is the \
                 endpoint's choice; the fixture stopped forking after {STORM_FORKS_SERVED} \
                 generations, a real endpoint would not. Expected Err(Sync {{ ChainReorg }}) by \
                 rewind {}.",
                p.batches,
                p.tip,
                EXPECTED_TOTAL_REORG_CAP + 1
            ),
            Err(other) => panic!(
                "the pass must end on the reorg stall, not on {other:?}; {rewinds} rewinds in \
                 {} batches",
                batches.len()
            ),
        }
        assert!(
            rewinds <= EXPECTED_TOTAL_REORG_CAP as usize + 1,
            "the cap bounds the pass: {rewinds} rewinds against a cap of \
             {EXPECTED_TOTAL_REORG_CAP}"
        );
        assert!(
            rewinds > epoch_bound + 1,
            "the row's non-vacuity: this pass must survive PAST what the per-epoch bound alone \
             allows ({epoch_bound} + 1), or the stall it asserts is the old bound firing and the \
             absolute cap is untested; got {rewinds} rewinds"
        );
        assert!(
            longest_rewind_run(&batches) <= epoch_bound,
            "and the per-epoch bound cannot have been what stopped it: that counter needs \
             {} rewinds with no new high water between them, and the longest run here is {}. \
             batches {:?}",
            epoch_bound + 1,
            longest_rewind_run(&batches),
            batch_shape(&batches)
        );
    }

    /// The repeated-fork SEAM's own receipt (§4q-run owed row 1, built this
    /// round): a pure check on what the endpoint SERVES, with no wallet, no
    /// scanner and no db — so that a future failure of the row above can be read
    /// as "the loop changed" and not "the fake stopped forking".
    ///
    /// Three properties, each one the storm row depends on:
    /// 1. a new generation appears only after the wallet climbs `advance_blocks`
    ///    above the last fork (the ADVANCE between two forks, which is what keeps
    ///    the per-epoch counter reset), and never more than `max_generations` of
    ///    them;
    /// 2. every generation's branch is DISTINCT at the height that separates them
    ///    — the block above a new fork carries a parent hash that is not the one
    ///    the previous generation gave, which is the continuity error;
    /// 3. the branches are MONOTONE: revealing a fork at `F` leaves every block
    ///    below `F` byte-identical, so a wallet re-scanning across an OLDER fork
    ///    after a rewind meets no error the fixture did not mean (the property
    ///    that makes the geometry one rewind per generation instead of a
    ///    downward cascade).
    #[test]
    fn a_fork_storm_endpoint_serves_one_new_branch_per_generation() {
        use crate::sync::testing::{storm_block, storm_id};

        // (1) as `FakeChain::storm_forks` computes it, on a range sequence
        //     shaped like the loop's: a first range, a rewound re-scan below it,
        //     then a climb.
        let forks_after = |starts: &[u64], advance: u64, max: usize| -> Vec<u64> {
            let mut forks: Vec<u64> = Vec::new();
            for &start in starts {
                if forks.len() >= max {
                    break;
                }
                if forks.last().is_none_or(|&f| start >= f + advance) {
                    forks.push(start - 1);
                }
            }
            forks
        };
        assert_eq!(
            forks_after(&[280_301, 280_200, 280_300, 280_400], 100, 8),
            vec![280_300, 280_399],
            "a fork on the first range, then NOT on the two recovery ranges below it, then one \
             on the range that finally climbs 100 above it"
        );
        assert_eq!(
            forks_after(&[280_301, 280_400, 280_500, 280_600], 100, 2).len(),
            2,
            "and never more than the fixture's own bound"
        );

        // (2) the branches differ where it matters: the block ABOVE a new fork
        //     no longer chains from what the previous generation served.
        let gen1 = [280_300u64];
        let gen2 = [280_300u64, 280_399];
        assert_ne!(
            storm_block(280_400, &gen2).prev_hash,
            storm_block(280_400, &gen1).prev_hash,
            "the continuity error itself: block 280,400's parent hash changes when the second \
             fork is revealed, so a wallet holding 280,399 from generation 1 rejects it"
        );
        assert_eq!(
            storm_block(280_400, &gen2).prev_hash,
            storm_id(280_399, &gen2),
            "…and the served stream is internally consistent: the parent hash is the id THIS \
             generation gives 280,399"
        );

        // (3) monotone below the new fork — every earlier height is untouched.
        for h in [280_000u64, 280_299, 280_300, 280_398] {
            assert_eq!(
                storm_block(h, &gen2).hash,
                storm_block(h, &gen1).hash,
                "revealing a fork at 280,399 must not change block {h}: a wallet re-scanning \
                 across the OLDER fork after a rewind would meet a continuity error the fixture \
                 never intended, and cascade"
            );
        }
        assert_ne!(
            storm_id(280_399, &gen1),
            storm_id(280_399, &gen2),
            "at the new fork's own height the branch DOES change (non-vacuity for the loop above)"
        );
        assert_ne!(
            storm_id(280_300, &gen1),
            sync::testing::block_id(280_300),
            "and a forked height is never the honest chain's id"
        );
    }

    /// The REFRESH fork of [`the_cache_is_truncated_to_the_height_upstream_landed_on`]
    /// — revealed on pass 2's FIRST `block_range`, inside what pass 1 scanned —
    /// named once so RR-4's two runs are driving the SAME geometry by
    /// construction and not by two copies of a literal.
    fn refresh_fork() -> sync::testing::Fork {
        sync::testing::Fork {
            at: sync::testing::ForkAt::Height(
                (REORG_PASS1_TIP + 1) - u64::from(crate::constants::REWIND_DISTANCE_BLOCKS) / 2,
            ),
            after_ranges: 0,
        }
    }

    /// The `wallet.reorg_rewind` records of one reorg pass driven through the
    /// PRODUCTION pass body under a real [`SyncController`] — the only place that
    /// event is emitted (`sync_controller::emit_synced`), so a row about the log
    /// line has to run the controller and not `sync_once`.
    ///
    /// A SIBLING of [`controller_reorg_run`] rather than a widening of it: that
    /// helper's geometry (a wallet anchored above the bundled row, the
    /// `BelowFirstRangeEnd` fork) is the one on which upstream lands exactly ON
    /// its target, so it cannot tell a true depth from the constant product —
    /// the very collision the §4q run record names. This one runs the refresh
    /// geometry over the same fixture chain [`reorg_pass_over`] uses, so the two
    /// runs are comparable, and it leaves the R-2/R-4 rows' helper untouched.
    async fn controller_refresh_rewind_log()
    -> (Vec<Vec<(String, String)>>, Vec<Vec<(String, String)>>) {
        use crate::tracing_guard::{CaptureLayer, CapturedEvents, assert_5_4_clean};
        use tracing_subscriber::prelude::*;

        crate::tracing_guard::force_wallet_callsites_enabled();
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let w = wallet_with_chain_account(dir.path(), &vault).await;
        let ctl = w.controller_over(ScriptedPassClient::honest(
            u32::try_from(REORG_PASS1_TIP).expect("a fixture height"),
        ));
        let first = ctl.once().await.expect("pass 1");
        assert_eq!(
            first.batches, 4,
            "the fixture's own precondition: the controller's pass 1 scans the same four batches \
             `reorg_pass_over`'s does, so the two runs rewind from the same place"
        );
        assert_eq!(
            w.scanned_tip().await.expect("scanned tip"),
            Some(BlockHeight::new(
                u32::try_from(REORG_PASS1_TIP).expect("a fixture height")
            )),
            "…and leaves the wallet AT the honest tip: this is the pre-rewind frontier the depth \
             is measured from"
        );

        let sink = CapturedEvents::default();
        let subscriber = tracing_subscriber::registry().with(CaptureLayer::new(sink.clone()));
        let guard = tracing::subscriber::set_default(subscriber);
        let mut forking = ScriptedPassClient::honest(
            u32::try_from(REORG_PASS1_TIP + 100).expect("a fixture height"),
        );
        forking.chain.fork = Some(refresh_fork());
        let ctl2 = w.controller_over(forking);
        let pass = ctl2.once().await;
        assert_5_4_clean(&sink.fields());
        let rewind_records = sink.records_of("wallet.reorg_rewind");
        let batches = batches_of(&sink.records_of("wallet.sync"));
        drop(guard);
        assert!(
            pass.as_ref().is_ok_and(|p| p.reorgs == 1),
            "the fixture's own precondition: the reorg pass rewinds exactly once and completes \
             (the log line is only emitted for a pass that returns Ok); got {:?}, batches {:?}",
            pass.as_ref().map(|p| (p.batches, p.reorgs)),
            batch_shape(&batches)
        );
        w.close().await.expect("close");
        (rewind_records, batches)
    }

    /// **§4q-R RR-4 (fold review row 5) — DEFECT row, RED at the base.**
    /// `wallet.reorg_rewind`'s `depth` is the blocks the wallet ACTUALLY rewound.
    ///
    /// At the base the field is `pass.reorgs × REWIND_DISTANCE_BLOCKS`
    /// (`sync_controller.rs`) — a number computed from a constant, not measured
    /// — while the fold that shipped it watched one rewind land 92 blocks below
    /// its 10-block target. On this geometry the three candidate readings are
    /// three different numbers, and the row checks that they are before it
    /// compares any of them: the truth (pre-rewind frontier − landed = **101**),
    /// the target reading (**92**), and the constant product (**10**). A
    /// diagnostic that is off by an order of magnitude about how much chain a
    /// wallet dropped is worse than no diagnostic — it is the number an operator
    /// would use to decide whether a reorg was ordinary or an attack.
    ///
    /// HOW IT IS MEASURED, since no surface carries `landed` out of a completed
    /// pass: two runs over the SAME geometry ([`refresh_fork`]) on the same
    /// fixture chain — [`reorg_pass_over`], whose recording reporter reads the DB
    /// at the post-rewind sample (the seam §4q R-3 already relies on), and the
    /// controller twin, which is where the log line is emitted. The rewound
    /// batch's `from` is captured in BOTH and asserted equal, so "the same
    /// geometry" is measured, not assumed.
    ///
    /// Killer mutant: §4q-R P-RR4's depth reverted to the product. SELF-MUTANT,
    /// baked in as the two `assert_ne!`s below rather than run by hand: with the
    /// pre-rewind height read replaced by the TARGET the expected value becomes
    /// 92, which this geometry separates from both 101 and 10 — so a repair that
    /// logged the target instead of the frontier is red here too.
    #[tokio::test]
    async fn the_reorg_rewind_log_carries_the_blocks_actually_rewound() {
        // (a) the same geometry through `sync_once`, to MEASURE where upstream
        //     landed (the DB height at the post-rewind progress sample).
        let measured = reorg_pass_over(refresh_fork(), REORG_PASS1_TIP + 100).await;
        let (_recorded, landed, target_ceiling) = rewind_as_recorded_and_as_taken(&measured);
        let measured_from = first_rewind_batch(&measured.batches)
            .and_then(|i| from_of(&measured.batches[i]))
            .expect("the rewound batch carries `from`");

        // (b) the same geometry under the controller, where the log line is.
        let (rewind_records, batches) = controller_refresh_rewind_log().await;
        let logged_from = first_rewind_batch(&batches)
            .and_then(|i| from_of(&batches[i]))
            .expect("the rewound batch carries `from`");
        assert_eq!(
            logged_from,
            measured_from,
            "the two runs must rewind at the same batch, or the height measured in one is not \
             the height the other logged about; {:?} vs {:?}",
            batch_shape(&batches),
            batch_shape(&measured.batches)
        );

        // The pre-rewind frontier: the DB's `block_max_scanned` before the
        // truncate, which is the rewound batch's own `from - 1` (§4q-R P-RR4
        // names both readings; on this geometry they are the same number, and
        // the fixture asserts pass 1 left the wallet exactly there).
        let pre_rewind = logged_from - 1;
        let true_depth = pre_rewind - landed;
        let product = u64::from(crate::constants::REWIND_DISTANCE_BLOCKS); // one rewind
        assert_ne!(
            true_depth, product,
            "THE GEOMETRY: this row needs a rewind whose real depth is not the constant product, \
             or it cannot see the defect. Pre-rewind {pre_rewind}, landed {landed}."
        );
        assert_ne!(
            true_depth,
            pre_rewind - target_ceiling,
            "…and not the depth to the TARGET either (the self-mutant: the pre-rewind height read \
             replaced by the target). Target ceiling {target_ceiling}, landed {landed}."
        );

        let logged: Vec<u64> = rewind_records
            .iter()
            .filter_map(|r| {
                r.iter()
                    .find(|(n, _)| n == "depth")
                    .and_then(|(_, v)| v.parse::<u64>().ok())
            })
            .collect();
        assert_eq!(
            logged.len(),
            1,
            "one rewind ⇒ exactly one `wallet.reorg_rewind` line carrying one depth; got \
             {rewind_records:?}"
        );
        assert_eq!(
            logged[0],
            true_depth,
            "§4q-R P-RR4: `depth` must be the blocks this wallet actually rewound — the DB's \
             pre-rewind block_max_scanned ({pre_rewind}) less the height upstream landed on \
             ({landed}) = {true_depth}. It logged {}, which is `pass.reorgs × \
             REWIND_DISTANCE_BLOCKS` — a number fabricated from a constant while the wallet \
             dropped {true_depth} blocks. batches {:?}",
            logged[0],
            batch_shape(&batches)
        );
    }

    #[tokio::test]
    async fn sync_once_cancelled_mid_download_records_a_cancelled_span_outcome() {
        // §8 (observability under the MOBILE-BACKGROUNDING edge, iv-d-3-b-iii-B-2-d): a
        // cancel flipped DURING batch 1's download must resolve that range's
        // `wallet.sync` span as `outcome = "cancelled"` — not left dangling, never
        // mislabelled an `advance` — so a host's trace honestly shows the batch was
        // abandoned, never a phantom completion (the unstable-network/backgrounding
        // truth, §2.5). Reuses the deterministic download-gate. The `advance` outcome is
        // covered above; `rewind` is driven by the revealed-fork FakeChain since an earlier revision
        // (`a_rewound_throttled_batch_records_exactly_one_snap_ms` — a real upstream
        // `PrevHashMismatch`); `stall_reorg` still rides the pure-accounting layer.
        use crate::sync::CancelToken;
        use crate::sync::testing::FakeChain;
        use crate::tracing_guard::{CaptureLayer, CapturedEvents, assert_5_4_clean};
        use tracing_subscriber::prelude::*;

        // Keep `zec_wallet_core` callsites enabled so this capture test is deterministic
        // under parallel execution (a thread-local `set_default` subscriber is invisible
        // to tracing's global interest cache — see the helper's doc).
        crate::tracing_guard::force_wallet_callsites_enabled();
        let sink = CapturedEvents::default();
        let subscriber = tracing_subscriber::registry().with(CaptureLayer::new(sink.clone()));
        let _guard = tracing::subscriber::set_default(subscriber);

        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let w = wallet_with_chain_account(dir.path(), &vault).await;

        let (started_tx, started_rx) = tokio::sync::oneshot::channel::<(u64, u64)>();
        let (release_tx, release_rx) = tokio::sync::oneshot::channel::<()>();
        let mut client = FakeChain::to_tip(281_000);
        client.download_gate = Some((started_tx, release_rx));
        let cancel = CancelToken::new();

        let sync_fut = w.sync_once(&mut client, &cancel, NOOP_PROGRESS);
        let gate_fut = async {
            started_rx.await.expect("batch 1 download started");
            cancel.cancel(); // honored at the next block (per-block poll)
            release_tx.send(()).expect("release batch 1");
        };
        let (pass, ()) = tokio::join!(sync_fut, gate_fut);
        assert!(pass.expect("sync").cancelled, "the pass stopped on cancel");

        let fields = sink.fields();
        assert!(
            fields
                .iter()
                .any(|(n, v)| n == "outcome" && v == "cancelled"),
            "the abandoned batch's span must resolve outcome=cancelled; captured {fields:?}"
        );
        // And the cancelled-path span is just as §5.4-clean as the happy path.
        assert_5_4_clean(&fields);
        w.close().await.expect("close");
    }

    #[tokio::test]
    async fn sync_once_span_pins_batch_ranges_and_resolves_every_outcome() {
        // §8 (observability boundary, iv-d-3-b-iii-B-2-d-1): the span's numeric fields
        // are exact at the SINGLE-BLOCK batch boundary, `blocks` is never 0 (an
        // invariant — `next_batch` filters empty ranges so `from < end`), and EVERY
        // batch on the clean path resolves an outcome (no dangling Empty). The 2-batch
        // one-batch-plus-1-block chain gives a full batch + a 1-block batch.
        use crate::sync::CancelToken;
        use crate::sync::testing::FakeChain;
        use crate::tracing_guard::{CaptureLayer, CapturedEvents, assert_5_4_clean};
        use tracing_subscriber::prelude::*;

        // Keep `zec_wallet_core` callsites enabled so this capture test is deterministic
        // under parallel execution (a thread-local `set_default` subscriber is invisible
        // to tracing's global interest cache — see the helper's doc).
        crate::tracing_guard::force_wallet_callsites_enabled();
        let sink = CapturedEvents::default();
        let subscriber = tracing_subscriber::registry().with(CaptureLayer::new(sink.clone()));
        let _guard = tracing::subscriber::set_default(subscriber);

        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let w = wallet_with_chain_account(dir.path(), &vault).await;
        let mut client = FakeChain::to_tip(u64::from(FIX_TIP));
        let cancel = CancelToken::new();
        let pass = w
            .sync_once(&mut client, &cancel, NOOP_PROGRESS)
            .await
            .expect("sync");
        assert_eq!(pass.batches, 2);

        let fields = sink.fields();
        let has = |n: &str, v: &str| fields.iter().any(|(fn_, fv)| fn_ == n && fv == v);
        // Batch 1: [FIX_BASE, FIX_TIP) = one full batch. Batch 2: [FIX_TIP, FIX_TIP+1) = 1.
        assert!(
            has("from", &FIX_BASE.to_string())
                && has("to", &FIX_TIP.to_string())
                && has("blocks", &crate::constants::SYNC_BATCH_BLOCKS.to_string())
        );
        assert!(
            has("from", &FIX_TIP.to_string())
                && has("to", &(FIX_TIP + 1).to_string())
                && has("blocks", "1"),
            "the single-block final batch span must carry blocks=1 (half-open to=from+1); captured {fields:?}"
        );
        // `blocks` is never 0 (the half-open-range invariant) — a regression in
        // `next_batch` emitting a zero-width range would surface here.
        assert!(
            !fields.iter().any(|(n, v)| n == "blocks" && v == "0"),
            "blocks must never be 0; captured {fields:?}"
        );
        // Every advancing batch resolved its outcome — no batch left a dangling Empty.
        let advances = fields
            .iter()
            .filter(|(n, v)| n == "outcome" && v == "advance")
            .count();
        assert_eq!(
            advances, pass.batches as usize,
            "each of the {} batches must resolve outcome=advance; captured {fields:?}",
            pass.batches
        );
        assert_5_4_clean(&fields);
        w.close().await.expect("close");
    }

    #[tokio::test]
    async fn sync_once_network_fault_records_an_error_span_outcome() {
        // §8 (THE flaky-mobile observability case, iv-d-3-b-iii-B-2-d-1): a link drop
        // DURING batch 2's download must resolve THAT batch's span as `outcome=error`
        // (not a dangling Empty) — so a host's trace attributes the failure to the
        // specific height range, while batch 1 (committed before the fault) reads
        // `advance`. The errored-path span stays §5.4-clean. Reuses the deterministic
        // `block_range_err_at` fault the resume test uses. This pins the production
        // contract that the network-fault `?` paths record `error` before propagating
        // (symmetric with the `stall_reorg` arm).
        use crate::sync::CancelToken;
        use crate::sync::testing::FakeChain;
        use crate::tracing_guard::{CaptureLayer, CapturedEvents, assert_5_4_clean};
        use tracing_subscriber::prelude::*;

        // Keep `zec_wallet_core` callsites enabled so this capture test is deterministic
        // under parallel execution (a thread-local `set_default` subscriber is invisible
        // to tracing's global interest cache — see the helper's doc).
        crate::tracing_guard::force_wallet_callsites_enabled();
        let sink = CapturedEvents::default();
        let subscriber = tracing_subscriber::registry().with(CaptureLayer::new(sink.clone()));
        let _guard = tracing::subscriber::set_default(subscriber);

        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let w = wallet_with_chain_account(dir.path(), &vault).await;
        // Fault when batch 2's download is OPENED (start == 281_000); batch 1 commits.
        let mut faulty = FakeChain::to_tip(281_000);
        faulty.block_range_err_at = Some(281_000);
        let cancel = CancelToken::new();
        let r = w.sync_once(&mut faulty, &cancel, NOOP_PROGRESS).await;
        assert!(
            matches!(r, Err(WalletError::Sync { .. })),
            "a mid-sync link drop is typed Sync; got {r:?}"
        );

        let fields = sink.fields();
        // Batch 1 (committed before the fault) → advance; batch 2 (the faulting range,
        // from=281_000) → error.
        assert!(
            fields.iter().any(|(n, v)| n == "outcome" && v == "advance"),
            "batch 1 committed before the fault and must read advance; captured {fields:?}"
        );
        assert!(
            fields.iter().any(|(n, v)| n == "outcome" && v == "error"),
            "the faulting batch's span must resolve outcome=error; captured {fields:?}"
        );
        assert!(
            fields.iter().any(|(n, v)| n == "from" && v == "281000"),
            "the faulting batch's range (from=281_000) is on the span; captured {fields:?}"
        );
        // The error-path span carries no secret either.
        assert_5_4_clean(&fields);
        w.close().await.expect("close");
    }

