    #[tokio::test]
    async fn sync_once_releases_the_db_lock_between_batches() {
        // §8 (THE iv-d-2a deferral — the per-batch lock-release proof, deterministic
        // via a one-shot download gate + `join!`, NO wall clock): while batch 1 is in
        // its LOCK-FREE download phase (between `next_batch`'s locked suggest and
        // `scan_batch`'s locked scan), a concurrent `try_lock` of the db mutex MUST
        // succeed — proving the scan loop does NOT hold the db lock across batches
        // (so a per-batch scan can never park a UI `current_address` DB read). A
        // regression (lock held across the loop) makes `try_lock` return `WouldBlock`
        // ⇒ a CLEAN assertion failure, never a hang.
        use crate::sync::CancelToken;
        use crate::sync::testing::FakeChain;
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let w = wallet_with_chain_account(dir.path(), &vault).await;

        let (started_tx, started_rx) = tokio::sync::oneshot::channel::<(u64, u64)>();
        let (release_tx, release_rx) = tokio::sync::oneshot::channel::<()>();
        let mut client = FakeChain::to_tip(u64::from(FIX_TIP));
        client.download_gate = Some((started_tx, release_rx));
        let cancel = CancelToken::new();

        let sync_fut = w.sync_once(&mut client, &cancel, NOOP_PROGRESS);
        let gate_fut = async {
            let range = started_rx.await.expect("batch 1 download started");
            // The db lock MUST be free in the download phase — try_lock (non-blocking)
            // succeeds, and a real read goes through, then the lock releases.
            {
                let guard = w
                    .inner
                    .db
                    .try_lock()
                    .expect("db lock is FREE during the lock-free download phase");
                let _ = account::account_default_address(&guard.db, Network::Test)
                    .expect("a concurrent DB read goes through between batches");
            }
            release_tx.send(()).expect("release batch 1");
            range
        };
        let (pass, range1) = tokio::join!(sync_fut, gate_fut);
        let pass = pass.expect("sync");
        assert_eq!(
            range1,
            (u64::from(FIX_BASE), u64::from(FIX_TIP) - 1),
            "the interleave happened during batch 1's download"
        );
        assert_eq!(
            pass.batches, 2,
            "the sync completes after the lock-check interleave"
        );
        w.close().await.expect("close");
    }

    #[tokio::test]
    async fn sync_once_cancel_mid_download_aborts_promptly_and_resumes_cleanly() {
        // §8 (§3.2g iv-d-3-b obligations 1 + 3 — the mobile-backgrounding case): cancel
        // is flipped DURING batch 1's download (the lock-free phase). The download now
        // honors it at the NEXT block (not parked until the batch boundary) — batch 1
        // ABORTS with NOTHING cached and NOTHING scanned, so the pass is `cancelled`
        // with 0 batches. No torn cache / no partial commit: a fresh uncancelled pass
        // then re-scans the FULL chain from scratch (the aborted batch left no durable
        // progress). The prompt mid-download cancel is the d-3-b improvement over
        // between-batch-only cancellation (the "completed batch is durable" property is
        // covered by the network-fault test below). Deterministic via the gate + join!.
        use crate::sync::CancelToken;
        use crate::sync::testing::FakeChain;
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let w = wallet_with_chain_account(dir.path(), &vault).await;

        let (started_tx, started_rx) = tokio::sync::oneshot::channel::<(u64, u64)>();
        let (release_tx, release_rx) = tokio::sync::oneshot::channel::<()>();
        let mut client = FakeChain::to_tip(u64::from(FIX_TIP));
        client.download_gate = Some((started_tx, release_rx));
        let cancel = CancelToken::new();

        let sync_fut = w.sync_once(&mut client, &cancel, NOOP_PROGRESS);
        let gate_fut = async {
            started_rx.await.expect("batch 1 download started");
            cancel.cancel(); // flip mid-download; honored at the next block (per-block poll)
            release_tx.send(()).expect("release batch 1");
        };
        let (pass, ()) = tokio::join!(sync_fut, gate_fut);
        let pass = pass.expect("sync");
        assert!(
            pass.cancelled,
            "the pass stopped on cooperative cancellation"
        );
        assert_eq!(
            pass.batches, 0,
            "batch 1 aborted mid-download (prompt cancel) and never committed"
        );

        // No partial commit: a fresh, uncancelled pass re-scans the FULL chain — the
        // aborted batch left no durable progress (nothing cached, nothing scanned).
        let mut client2 = FakeChain::to_tip(u64::from(FIX_TIP));
        let cancel2 = CancelToken::new();
        let resume = w
            .sync_once(&mut client2, &cancel2, NOOP_PROGRESS)
            .await
            .expect("resume");
        assert_eq!(
            resume.batches, 2,
            "the aborted batch left no durable progress ⇒ the full 2-batch chain re-scans cleanly"
        );
        w.close().await.expect("close");
    }

    #[tokio::test]
    async fn sync_once_reports_progress_during_and_after_each_batch() {
        // §8 (§3.2g iv-d-3-b obligation 2, end-to-end): a multi-batch sync_once feeds
        // the reporter ScanProgress samples both INTRA-batch (during download — the
        // watchdog re-arm) and per committed batch. For this SINGLE-RANGE contiguous
        // chain the frontier ascends to the tip (the engine derives the authoritative
        // monotonic UI percent from the wallet summary; this test pins the wiring +
        // the per-range advance, not a global percent — the frontier is NOT a global
        // percent across a multi-priority-range plan, see ScanProgress). Asserts an
        // intra-batch sample strictly inside batch 1 (proving the download-phase
        // reporting is wired, not just the per-batch reports) and the final frontier
        // at the tip.
        use crate::money::BlockHeight;
        use crate::sync::testing::FakeChain;
        use crate::sync::{CancelToken, ScanProgress};
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let w = wallet_with_chain_account(dir.path(), &vault).await;

        let seen = Arc::new(Mutex::new(Vec::<ScanProgress>::new()));
        let sink = Arc::clone(&seen);
        let report = move |p: ScanProgress| sink.lock().expect("lock").push(p);

        // tip FIX_TIP ⇒ a single contiguous range [FIX_BASE, FIX_TIP+1), 2 batches.
        let mut client = FakeChain::to_tip(u64::from(FIX_TIP));
        let cancel = CancelToken::new();
        let pass = w
            .sync_once(&mut client, &cancel, &report)
            .await
            .expect("sync");
        assert_eq!(pass.batches, 2);

        // Read + assert inside a block so the std MutexGuard drops before the await.
        {
            let seen = seen.lock().expect("lock");
            // Intra-batch wiring: at least one sample lands STRICTLY inside batch 1's
            // span (FIX_BASE, FIX_TIP) — only the download-phase reporting produces
            // these (the per-batch reports land at the batch end == FIX_TIP / clamped).
            assert!(
                seen.iter().any(|p| p.frontier > BlockHeight::new(FIX_BASE)
                    && p.frontier < BlockHeight::new(FIX_TIP)),
                "an intra-batch download sample fired inside batch 1: {seen:?}"
            );
            // For this single contiguous range the frontier is non-decreasing.
            for win in seen.windows(2) {
                assert!(
                    win[1].frontier >= win[0].frontier,
                    "for a contiguous single-range plan the frontier ascends"
                );
            }
            assert_eq!(
                seen.last().expect("≥ 1 sample").frontier,
                BlockHeight::new(FIX_TIP),
                "the final sample frontier is at the tip"
            );
        }
        w.close().await.expect("close");
    }

    #[tokio::test]
    async fn sync_once_reports_the_authoritative_summary_percent_and_spendable() {
        // §8 (§3.2g iv-d-3-b-iii, end-to-end over the REAL scanner + real keyed DB, NO
        // gRPC): sync_once stamps each committed-batch report with the AUTHORITATIVE
        // wallet-summary percent + spendable signal (read AFTER the scan commits), NOT a
        // coarse frontier/tip. Asserts: (1) the percent is MONOTONIC non-decreasing across
        // the pass (§2.5 — never range position); (2) spendable_ready is false on a
        // note-free chain (the honest signal); (3) the final reported summary EQUALS a
        // direct progress_snapshot read — proving the engine forwards the audited
        // get_wallet_summary verbatim, never a guess. (A fractional mid-sync percent over a
        // chain WITH a detectable note rides the GA reorg/note-detection e2e — hand-built
        // FakeChain blocks mint no notes; the denominator-0 → 1.0 path is exercised here +
        // the fractional math in account::scan_percent's unit test.)
        use crate::sync::testing::FakeChain;
        use crate::sync::{CancelToken, ScanProgress};
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let w = wallet_with_chain_account(dir.path(), &vault).await;

        let seen = Arc::new(Mutex::new(Vec::<ScanProgress>::new()));
        let sink = Arc::clone(&seen);
        let report = move |p: ScanProgress| sink.lock().expect("lock").push(p);

        let mut client = FakeChain::to_tip(u64::from(FIX_TIP));
        let cancel = CancelToken::new();
        let pass = w
            .sync_once(&mut client, &cancel, &report)
            .await
            .expect("sync");
        assert_eq!(pass.batches, 2);

        // A direct authoritative read AFTER the pass — the source of truth the engine
        // forwards (nothing mutates the DB between the final report and this read).
        let direct = {
            let inner = Arc::clone(&w.inner);
            run_blocking(move || {
                let guard = inner.db.lock().expect("db mutex");
                account::progress_snapshot(&guard.db)
            })
            .await
            .expect("read")
        };

        {
            let seen = seen.lock().expect("lock");
            assert!(!seen.is_empty(), "the pass reported progress");
            // (1) absent a reorg the percent never regresses (§2.5 monotonic — never
            //     range position). This clean FakeChain takes no rewind; the reorg case
            //     (a rewind lowers the percent to the honest post-rewind truth — the
            //     Rewind-arm refresh) rides the GA reorg/note-detection e2e.
            for win in seen.windows(2) {
                assert!(
                    win[1].summary.percent >= win[0].summary.percent - 1e-6,
                    "summary percent is monotonic non-decreasing (no reorg): {seen:?}"
                );
            }
            // (2) no notes minted on the FakeChain ⇒ never spendable (the honest signal).
            assert!(
                seen.iter().all(|p| !p.summary.spendable_ready),
                "a note-free chain never reports spendable funds"
            );
            // (3) the LAST committed-batch report carries the SAME summary as a direct
            //     read — the engine forwards the audited summary verbatim, not a guess.
            //     A fully-scanned wallet (account + recorded tip) MUST have summary data,
            //     so this branch is load-bearing, not skipped.
            let direct = direct.expect("a fully-scanned wallet has a wallet summary");
            let last = seen.last().expect("≥1 sample");
            assert!(
                (last.summary.percent - direct.percent).abs() < 1e-6
                    && last.summary.spendable_ready == direct.spendable_ready,
                "the final reported summary == a direct progress_snapshot read: \
                 reported {:?} vs direct {direct:?}",
                last.summary
            );
            // Over a note-free FakeChain the window has zero shielded notes ⇒ the
            // denominator-0 → 1.0 path: a fully-scanned note-free wallet reads 100%.
            assert_eq!(
                direct.percent, 1.0,
                "a fully-scanned note-free chain reads 100% (denominator-0 path)"
            );
        }
        w.close().await.expect("close");
    }

    // ── operational 3-lens (iii-A): money / mobile / the carry mechanism ──────
    // The maintainer's distinct adversarial pass on the committed authoritative-progress
    // change. The pre-commit review verified CORRECTNESS; these close real-world
    // COVERAGE gaps that the note-free `FakeChain` left (the prior monotonicity check
    // is satisfied by a CONSTANT 1.0 stream, so several honesty regressions would ship
    // green). All deterministic (real scanner + keyed DB, NO gRPC, NO wall clock).

    #[tokio::test]
    async fn sync_once_emits_zero_percent_and_not_spendable_before_the_first_commit() {
        // §8 (MONEY honesty): a fresh wallet's first (possibly hours-long) sync must
        // read 0% / NOT spendable until a batch durably commits — never a premature
        // "funds ready" badge or a >0% bar before any scan lands. The first emitted
        // sample is a batch-1 DOWNLOAD tick, stamped with the carried `{0.0, false}`
        // default; every pre-first-commit sample carries it. (A regression that seeded
        // the carry non-zero — e.g. an eager pre-loop summary read on a wallet with
        // residual durable progress — would flash a stale bar; the constant-1.0
        // monotonicity check could not catch it. This pins it.)
        use crate::money::BlockHeight;
        use crate::sync::testing::FakeChain;
        use crate::sync::{CancelToken, ProgressSnapshot, ScanProgress};
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let w = wallet_with_chain_account(dir.path(), &vault).await;

        let seen = Arc::new(Mutex::new(Vec::<ScanProgress>::new()));
        let sink = Arc::clone(&seen);
        let report = move |p: ScanProgress| sink.lock().expect("lock").push(p);

        // tip FIX_TIP ⇒ batch 1 [FIX_BASE,FIX_TIP) (a full batch ⇒ download ticks),
        // batch 2 [FIX_TIP,FIX_TIP+1) (1 block). Pre-first-commit = frontier < FIX_TIP.
        let mut client = FakeChain::to_tip(u64::from(FIX_TIP));
        let cancel = CancelToken::new();
        w.sync_once(&mut client, &cancel, &report)
            .await
            .expect("sync");

        {
            let seen = seen.lock().expect("lock");
            assert!(!seen.is_empty(), "the pass reported progress");
            assert_eq!(
                seen[0].summary,
                ProgressSnapshot::default(),
                "the FIRST sample (a pre-commit download tick) is the {{0.0,false}} default"
            );
            // EVERY sample before the first batch commits (frontier strictly inside
            // batch 1) reads 0% / not-spendable — no premature funds-ready signal.
            for p in seen
                .iter()
                .filter(|p| p.frontier < BlockHeight::new(FIX_TIP))
            {
                assert_eq!(
                    p.summary.percent, 0.0,
                    "a pre-first-commit sample must read 0%: {p:?}"
                );
                assert!(
                    !p.summary.spendable_ready,
                    "a fresh wallet never reports spendable before a commit: {p:?}"
                );
            }
        }
        w.close().await.expect("close");
    }

    #[tokio::test]
    async fn sync_once_carries_the_committed_summary_across_the_next_batch_download() {
        // §8 (the CARRY MECHANISM — the new `ScanCtx.summary` plumbing this increment
        // introduced; mobile-UX + money): once a batch commits and the percent rises,
        // the NEXT batch's intra-download ticks must carry that committed value forward
        // — the bar must not snap back to 0% while the next batch downloads (a visible
        // 100%→0%→100% flicker). A 3-batch chain is REQUIRED: the prior 2-batch tests
        // had a single-block batch 2 (no download tick), so this path was never
        // exercised. Batch-1 ticks carry the default 0.0; batch-2 ticks carry batch-1's
        // COMMITTED 1.0 (note-free ⇒ denominator-0 ⇒ 1.0) — proving the carry, not a
        // reset. A broken carry (always passing `default` into `ScanCtx`) makes the
        // batch-2 ticks read 0.0 and FAILS here while leaving every commit report green.
        use crate::money::BlockHeight;
        use crate::sync::testing::FakeChain;
        use crate::sync::{CancelToken, ScanProgress};
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let w = wallet_with_chain_account(dir.path(), &vault).await;

        let seen = Arc::new(Mutex::new(Vec::<ScanProgress>::new()));
        let sink = Arc::clone(&seen);
        let report = move |p: ScanProgress| sink.lock().expect("lock").push(p);

        // tip FIX_TIP + one more full batch ⇒ 3 batches:
        // [FIX_BASE,FIX_TIP) [FIX_TIP,TIP3) [TIP3,TIP3+1).
        // The MIDDLE batch [FIX_TIP,TIP3) has download ticks (a full batch).
        const TIP3: u32 = FIX_TIP + crate::constants::SYNC_BATCH_BLOCKS;
        let mut client = FakeChain::to_tip(u64::from(TIP3));
        let cancel = CancelToken::new();
        let pass = w
            .sync_once(&mut client, &cancel, &report)
            .await
            .expect("sync");
        assert_eq!(pass.batches, 3, "two full batches + 1 block ⇒ 3 batches");

        {
            let seen = seen.lock().expect("lock");
            // batch-1 download ticks (frontier strictly inside batch 1) carry the
            // DEFAULT 0.0 (nothing committed yet).
            let b1: Vec<_> = seen
                .iter()
                .filter(|p| {
                    p.frontier > BlockHeight::new(FIX_BASE)
                        && p.frontier < BlockHeight::new(FIX_TIP)
                })
                .collect();
            assert!(!b1.is_empty(), "batch 1 produced download ticks: {seen:?}");
            assert!(
                b1.iter().all(|p| p.summary.percent == 0.0),
                "batch-1 download ticks carry the 0.0 default (pre-commit): {b1:?}"
            );
            // batch-2 download ticks (frontier strictly inside batch 2) carry batch-1's
            // COMMITTED summary (1.0), NOT a reset to default — the carry-forward.
            let b2: Vec<_> = seen
                .iter()
                .filter(|p| {
                    p.frontier > BlockHeight::new(FIX_TIP) && p.frontier < BlockHeight::new(TIP3)
                })
                .collect();
            assert!(
                !b2.is_empty(),
                "batch 2 produced download ticks (the carry path): {seen:?}"
            );
            assert!(
                b2.iter().all(|p| (p.summary.percent - 1.0).abs() < 1e-6),
                "batch-2 download ticks carry batch-1's COMMITTED summary forward (1.0), \
                 not a reset to 0.0: {b2:?}"
            );
        }
        w.close().await.expect("close");
    }

    // ── ADR-0532: the deep-restore summary THROTTLE (O(n²) → O(n)) ─────────
    // `sync_once`'s authoritative `get_wallet_summary()` read is now refreshed at most
    // once per SYNC_SUMMARY_REFRESH_BATCHES committed batches (it is O(scanned-set), so an
    // every-batch read made deep recovery O(n²)), with FORCED refreshes on (1) the first
    // committed batch, (2) a reorg/Rewind, and (3) reaching the tip.

    #[tokio::test]
    async fn sync_summary_is_throttled_not_read_every_batch() {
        // §8 (ADR-0532 — the O(n²)→O(n) deep-restore fix): the authoritative
        // `get_wallet_summary()` read is THROTTLED to once per SYNC_SUMMARY_REFRESH_BATCHES
        // committed batches, not every batch. Over a chain of > SYNC_SUMMARY_REFRESH_BATCHES
        // batches the read must run strictly fewer times than the batch count.
        //
        // OBSERVABILITY NOTE (why not a raw call count): the in-loop read COUNT is not
        // directly observable through the public API on this harness — the note-free
        // FakeChain mints no shielded notes, so EVERY `progress_snapshot` reads the SAME
        // constant {percent 1.0, not-spendable} (the denominator-0 path), and the upstream
        // `WalletDb` hides its rusqlite `Connection` (no per-connection trace hook); a
        // global call counter would race the other parallel `sync_once` tests. So the
        // throttle is proven by its DETERMINISTIC observable SIGNATURE: because the TAIL
        // batches are throttled (`summary_stale > 0` at the tip), the up-to-date `None`
        // arm fires the forced tail-refresh — an EXTRA report at the exact tip BEYOND the
        // last batch's own report. Under a "read every batch" regression `summary_stale`
        // would be 0 at the tip and that forced refresh would NOT fire (exactly ONE tip
        // report), so the `>= 2 reports at the tip` assertion fails. The per-batch report
        // still advances the scanned height while carrying the (constant) committed summary
        // — the throttle's promise that "blocks left" decrements every batch and the
        // percent does not jitter. The end-to-end O(n) speed-up itself is the ADR's
        // on-device re-measurement validation task.
        use crate::money::BlockHeight;
        use crate::sync::testing::FakeChain;
        use crate::sync::{CancelToken, ScanProgress};
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let w = wallet_with_chain_account(dir.path(), &vault).await;

        // Birthday anchor 279_999 ⇒ scan range [FIX_BASE, tip+1). Pick the tip so the pass
        // splits into SYNC_SUMMARY_REFRESH_BATCHES + 1 forward batches (> the throttle
        // window) with a 3-block LAST batch (3 mod 5 ∉ {0,1} ⇒ no intra-batch download tick
        // lands on the tip with PROGRESS_REPORT_BLOCKS = 5, keeping the tip-report count
        // clean): total = SYNC_SUMMARY_REFRESH_BATCHES full batches + 3 blocks
        // ⇒ tip = FIX_BASE + total - 1.
        const TIP: u32 =
            FIX_BASE + SYNC_SUMMARY_REFRESH_BATCHES * crate::constants::SYNC_BATCH_BLOCKS + 2;
        let mut client = FakeChain::to_tip(u64::from(TIP));
        let cancel = CancelToken::new();
        let seen = Arc::new(Mutex::new(Vec::<ScanProgress>::new()));
        let sink = Arc::clone(&seen);
        let report = move |p: ScanProgress| sink.lock().expect("lock").push(p);

        let pass = w
            .sync_once(&mut client, &cancel, &report)
            .await
            .expect("sync");
        assert_eq!(
            pass.batches,
            SYNC_SUMMARY_REFRESH_BATCHES + 1,
            "tip {TIP} splits into SYNC_SUMMARY_REFRESH_BATCHES+1 forward batches"
        );
        assert!(
            pass.batches > SYNC_SUMMARY_REFRESH_BATCHES,
            "the chain must EXCEED the throttle window for the throttle to engage (boundary)"
        );

        {
            let seen = seen.lock().expect("lock");
            assert!(!seen.is_empty(), "the pass reported progress");
            let tip = BlockHeight::new(TIP);

            // THE THROTTLE SIGNATURE: the forced tail-refresh fires only because
            // `summary_stale > 0` at the tip — i.e. the tail batches were NOT re-read. So
            // there are >= 2 reports landing exactly on the tip (the last batch's own
            // report + the forced refresh). A read-every-batch regression fires exactly 1.
            let at_tip = seen.iter().filter(|p| p.frontier == tip).count();
            assert!(
                at_tip >= 2,
                "a throttled tail forces an extra tip refresh ⇒ >= 2 reports at the tip; \
                 got {at_tip} (read-every-batch would fire exactly 1): {seen:?}"
            );

            // Per-batch progress is preserved: the scanned height never regresses and
            // reaches the tip ("blocks left" decrements every batch even while throttled).
            for win in seen.windows(2) {
                assert!(
                    win[1].frontier >= win[0].frontier,
                    "the scanned height advances monotonically across the throttled pass: {seen:?}"
                );
            }
            assert_eq!(
                seen.last().expect("≥1 sample").frontier,
                tip,
                "the final sample lands on the exact tip"
            );

            // The CARRY: once batch 1 commits the real percent, every later report (the
            // throttled batches 2..9 download ticks + their commits) carries that SAME
            // committed value — the percent does not re-read/jitter per batch. (Strictly
            // past the batch-1 boundary avoids the boundary report that mixes the pre-commit
            // 0.0 download tick with the 1.0 commit.)
            let first_commit = BlockHeight::new(280_000 + crate::constants::SYNC_BATCH_BLOCKS);
            for p in seen.iter().filter(|p| p.frontier > first_commit) {
                assert!(
                    (p.summary.percent - 1.0).abs() < 1e-6,
                    "throttled batches carry batch-1's committed summary forward, \
                     not a per-batch re-read jitter: {p:?}"
                );
            }
        }
        w.close().await.expect("close");
    }

    #[tokio::test]
    async fn sync_summary_refreshes_on_first_batch_and_at_tip() {
        // §8 (ADR-0532): the throttle FORCES a refresh at the two clean points where a
        // stale carry would lie — the FIRST committed batch (`summary_stale` inits AT the
        // threshold ⇒ the real initial percent, not the {0.0} pre-scan default carried
        // forward) and the TIP (the up-to-date arm lands the UI on the EXACT 100% + final
        // balance, not a ≤N-batch-stale percent). Note-free FakeChain ⇒ the authoritative
        // percent is 1.0 (denominator-0). A regression that throttled the FIRST batch
        // (`summary_stale` init 0, not the threshold) would defer the first non-zero
        // percent to the tip — failing assertion (1).
        use crate::money::BlockHeight;
        use crate::sync::testing::FakeChain;
        use crate::sync::{CancelToken, ScanProgress};
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let w = wallet_with_chain_account(dir.path(), &vault).await;

        // SYNC_SUMMARY_REFRESH_BATCHES + 1 batches (> the throttle window) — see the
        // throttle test for the tip derivation.
        const TIP: u32 =
            FIX_BASE + SYNC_SUMMARY_REFRESH_BATCHES * crate::constants::SYNC_BATCH_BLOCKS + 2;
        let mut client = FakeChain::to_tip(u64::from(TIP));
        let cancel = CancelToken::new();
        let seen = Arc::new(Mutex::new(Vec::<ScanProgress>::new()));
        let sink = Arc::clone(&seen);
        let report = move |p: ScanProgress| sink.lock().expect("lock").push(p);

        let pass = w
            .sync_once(&mut client, &cancel, &report)
            .await
            .expect("sync");
        assert_eq!(pass.batches, SYNC_SUMMARY_REFRESH_BATCHES + 1);

        // The authoritative read AFTER the pass — the source of truth the tip refresh
        // forwards (nothing mutates the DB between the final report and this read).
        let direct = {
            let inner = Arc::clone(&w.inner);
            run_blocking(move || {
                let guard = inner.db.lock().expect("db mutex");
                account::progress_snapshot(&guard.db)
            })
            .await
            .expect("read")
        }
        .expect("a fully-scanned wallet has a wallet summary");
        let balance = w.balance().await.expect("balance read");

        {
            let seen = seen.lock().expect("lock");
            let tip = BlockHeight::new(TIP);
            let first_commit = BlockHeight::new(280_000 + crate::constants::SYNC_BATCH_BLOCKS);

            // (1) FIRST committed batch refreshes: the first report carrying a non-zero
            //     (freshly-read) percent lands at the END of batch 1, NOT deferred to the
            //     tip. Every report before it carries the {0.0} pre-first-commit default.
            let first_nonzero = seen
                .iter()
                .find(|p| p.summary.percent > 0.0)
                .expect("the pass produced a committed (non-zero-percent) report");
            assert_eq!(
                first_nonzero.frontier, first_commit,
                "the FIRST batch refreshes the real initial percent at its commit, \
                 not deferred to the tip: {seen:?}"
            );
            assert!(
                (first_nonzero.summary.percent - 1.0).abs() < 1e-6,
                "batch 1's refreshed initial percent is the authoritative value (note-free ⇒ 1.0)"
            );
            for p in seen.iter().take_while(|p| p.frontier < first_commit) {
                assert_eq!(
                    p.summary.percent, 0.0,
                    "a pre-first-commit report carries the 0.0 default: {p:?}"
                );
                assert!(
                    !p.summary.spendable_ready,
                    "never spendable before the first commit: {p:?}"
                );
            }

            // (2) TIP refresh: the FINAL report lands on the EXACT tip with the
            //     authoritative summary (== a direct read) — the UI lands on exact 100% +
            //     a consistent (all-zero, not-spendable) balance.
            let last = seen.last().expect("≥1 sample");
            assert_eq!(
                last.frontier, tip,
                "the final report lands on the exact tip (100%)"
            );
            assert!(
                (last.summary.percent - direct.percent).abs() < 1e-6
                    && last.summary.spendable_ready == direct.spendable_ready,
                "the tip refresh forwards the authoritative summary verbatim: \
                 reported {:?} vs direct {direct:?}",
                last.summary
            );
            assert!(
                !direct.spendable_ready,
                "a note-free fully-scanned wallet is never spendable"
            );
            assert_eq!(
                balance,
                BalanceSnapshot::default(),
                "the all-zero balance is consistent with the not-spendable tip summary"
            );
        }
        w.close().await.expect("close");
    }

    #[tokio::test]
    async fn sync_summary_refreshes_on_reorg_even_when_throttled() {
        // §8 (ADR-0532 / spec §2.5 reorg-honesty): a rewind can LOWER the authoritative
        // percent, so the throttle MUST force a refresh on a reorg even when the batch
        // was throttled — never carrying the stale-HIGH pre-rewind value.
        //
        // DEFERRAL (honest — see harness investigation): a live continuity-error reorg
        // cannot be produced from hand-built FakeChain blocks (probe-confirmed across six
        // scenarios — see sync.rs::classify_batch's doc + the note on
        // `sync_once_cancelled_mid_download_records_a_cancelled_span_outcome`), and the
        // note-free harness yields a CONSTANT percent (denominator-0 ⇒ 1.0), so a percent
        // DROP across a rewind is doubly unproducible here. The end-to-end reorg-refresh
        // through `sync_once`'s Rewind arm therefore rides the GA reorg e2e. What IS
        // testable, and is asserted here:
        //   (a) the REAL production seam — a reorg within budget routes to
        //       BatchAction::Rewind, the arm that gates the forced refresh (classify_batch).
        //   (b) the throttle+reorg HONESTY INVARIANT at the unit level, over a faithful
        //       model of `sync_once`'s `summary_stale` state machine (wallet.rs ~1624-1830):
        //       a reorg landing on a THROTTLED batch (`summary_stale > 0`) forces a fresh
        //       read, so the reported percent is the POST-REWIND value, never the carried
        //       pre-rewind one. (And — modelled in production but not asserted here to avoid
        //       a tautology — a post-rewind read that yields None leaves `summary_stale`
        //       elevated so the NEXT batch force-refreshes, never latching a stale-high.)
        use crate::sync::{BatchAction, ScanOutcome, classify_batch};

        // (a) The real seam: a batch that hits a reorg within budget reaches the Rewind
        //     arm — the path where the forced post-rewind refresh lives.
        let mut high_water = 1_000u64;
        let mut reorgs_since_progress = 0u32;
        assert_eq!(
            classify_batch(
                ScanOutcome::Reorg {
                    rewind_height: 990,
                    requeued: true,
                    rewound_blocks: 10,
                },
                0,
                &mut high_water,
                &mut reorgs_since_progress,
                0,
            ),
            BatchAction::Rewind {
                rewind_height: 990,
                requeued: true,
                rewound_blocks: 10,
            },
            "a reorg within budget routes to the Rewind arm — the path that forces the \
             post-rewind refresh"
        );

        // (b) The honesty invariant over a faithful model of the throttle state machine.
        //     DB truth: a HIGH pre-rewind percent, then a LOWER post-rewind percent (§2.5).
        const PRE_REWIND: f32 = 0.90;
        const POST_REWIND: f32 = 0.40;

        // Replays the `summary_stale` transitions of one pass up to a reorg at
        // `reorg_at_batch`, returning the percent `sync_once` would REPORT for that batch.
        // Mirrors: init AT `threshold` (batch 1 refreshes) → reset to 0 on a refresh, +1 on
        // a throttled batch → on the reorg, a refresh batch already captured POST_REWIND
        // in-lock, a throttled batch (`summary_stale > 0`) forces the post-rewind read.
        fn reported_percent_at_reorg(reorg_at_batch: u32, threshold: u32) -> f32 {
            let mut summary_stale = threshold; // inits AT the threshold ⇒ batch 1 refreshes
            let mut summary = 0.0f32; // {0.0} pre-first-batch default
            for batch in 1..=reorg_at_batch {
                let is_reorg = batch == reorg_at_batch;
                let refresh = summary_stale >= threshold; // decided BEFORE the scan
                if !is_reorg {
                    if refresh {
                        summary = PRE_REWIND; // a clean refresh batch reads the (high) truth
                        summary_stale = 0;
                    } else {
                        summary_stale = summary_stale.saturating_add(1); // throttled: read skipped
                    }
                    continue;
                }
                // The Rewind arm.
                if refresh {
                    summary = POST_REWIND; // captured post-rewind IN-LOCK on a refresh batch
                    summary_stale = 0;
                } else {
                    summary_stale = summary_stale.saturating_add(1); // throttled this batch...
                    if summary_stale > 0 {
                        summary = POST_REWIND; // ...so the reorg forces the post-rewind read
                        summary_stale = 0;
                    }
                }
            }
            summary
        }

        // Throttled batches (2..=threshold+1) AND a mid-pass refresh batch (threshold+2) all
        // report the POST-REWIND value across a reorg — never the carried stale-high value.
        for reorg_at in 2..=(SYNC_SUMMARY_REFRESH_BATCHES + 2) {
            assert!(
                (reported_percent_at_reorg(reorg_at, SYNC_SUMMARY_REFRESH_BATCHES) - POST_REWIND)
                    .abs()
                    < 1e-6,
                "a reorg on batch {reorg_at} forces the post-rewind read — never the \
                 stale-high carry"
            );
        }
        // A reorg on the FIRST (refresh) batch is honest too (captured in-lock).
        assert!(
            (reported_percent_at_reorg(1, SYNC_SUMMARY_REFRESH_BATCHES) - POST_REWIND).abs() < 1e-6,
            "a reorg on the first (refresh) batch captures the post-rewind read in-lock"
        );
    }

    #[tokio::test]
    async fn sync_once_on_an_already_synced_wallet_emits_no_progress() {
        // §8 (MOBILE steady-state): an already-synced wallet polls every
        // POLL_INTERVAL_SECS. A no-op pass must emit ZERO `ScanProgress` — otherwise the
        // UI flickers Up-to-date → "Scanning 100%" → Up-to-date and re-asserts a
        // (possibly stale) spendable/percent every poll. The terminal status comes from
        // `engine.tip()` (the controller's `UpToDate`), never a spurious Scanning report.
        use crate::sync::testing::FakeChain;
        use crate::sync::{CancelToken, ScanProgress};
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let w = wallet_with_chain_account(dir.path(), &vault).await;

        // First, sync to completion (NOOP reporter — not the subject).
        let cancel = CancelToken::new();
        let mut client = FakeChain::to_tip(u64::from(FIX_TIP));
        let first = w
            .sync_once(&mut client, &cancel, NOOP_PROGRESS)
            .await
            .expect("first sync");
        assert_eq!(first.batches, 2);

        // A second pass over the now up-to-date wallet, with a RECORDING reporter.
        let seen = Arc::new(Mutex::new(Vec::<ScanProgress>::new()));
        let sink = Arc::clone(&seen);
        let report = move |p: ScanProgress| sink.lock().expect("lock").push(p);
        let mut client2 = FakeChain::to_tip(u64::from(FIX_TIP));
        let again = w
            .sync_once(&mut client2, &cancel, &report)
            .await
            .expect("re-sync");
        assert_eq!(again.batches, 0, "already up to date ⇒ no batches");
        assert!(
            seen.lock().expect("lock").is_empty(),
            "a steady-state poll emits ZERO Scanning samples — no UI flicker / stale re-flash"
        );
        w.close().await.expect("close");
    }

