    /// FR-29 stage 0 (ii) / ADR-0544 decision 3, at the DOOR: a config that pairs
    /// a plaintext loopback endpoint with a host dialer never opens a wallet — the
    /// create verb refuses typed (`InvalidEndpoint`), before any store exists, so
    /// no later dial can ship raw gRPC through the host's transport. The same
    /// endpoint under `Off` opens as before.
    #[tokio::test]
    async fn http_endpoint_under_a_host_dialer_is_refused_at_the_door() {
        use crate::config::TorRuntime;
        use crate::ports::testing::StubDialer;
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let mut config = cfg(dir.path(), Network::Test, SeedPersistence::SealedKeychain);
        config.endpoint = LightServerEndpoint::new("http://127.0.0.1:9067").expect("loopback");
        config.tor = TorPolicy::Required {
            runtime: TorRuntime::Dialer(Arc::new(StubDialer) as Arc<dyn crate::ports::NetDialer>),
        };
        assert!(
            matches!(
                Wallet::create_with_vault(config, raw_seed(), Arc::clone(&vault)).await,
                Err(WalletError::InvalidEndpoint { reason }) if reason.contains("TorPolicy::Off")
            ),
            "plaintext + host dialer is refused at the door"
        );
        assert!(
            std::fs::read_dir(dir.path()).expect("dir").next().is_none(),
            "refused at the door means no wallet store was created"
        );
        let mut off = cfg(dir.path(), Network::Test, SeedPersistence::SealedKeychain);
        off.endpoint = LightServerEndpoint::new("http://127.0.0.1:9067").expect("loopback");
        let w = Wallet::create_with_vault(off, raw_seed(), Arc::clone(&vault))
            .await
            .expect("Off + loopback plaintext is the development configuration");
        w.close().await.expect("close");
    }

