    /// FR-29 spec §3.4 / §0 A11 at the SHIPPED read (T5's wallet half): the
    /// wallet's `tor_state()` reads the host transport's descriptor SNAPSHOT
    /// from `TorPolicy::host_descriptor()` at each derivation — so a host's
    /// readiness/retire push moves the state the next time anyone reads it,
    /// with no wallet action. Ready over Tor → `Active { HostDialer { Tor,
    /// Supported } }`; the host's readiness push at 50 → `Bootstrapping { 0.5 }`;
    /// a clear → `Unavailable`; a fresh descriptor behind the same trampoline →
    /// `Active` again naming the new kind. Passing `None` instead of the
    /// snapshot at the call site would freeze the first reading as `Unavailable`.
    #[tokio::test]
    async fn host_retire_moves_tor_state_through_the_wallet_handle() {
        use crate::config::TorRuntime;
        use crate::net::host_dialer::testing::{ScriptedHostDialer, name};
        use crate::net::host_dialer::{
            HostDialer, HostTransportDescriptor, IsolationSupport, TransportExposure,
            TransportHealth,
        };
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let host = Arc::new(ScriptedHostDialer::ready());
        let mut config = cfg(dir.path(), Network::Test, SeedPersistence::SealedKeychain);
        config.tor = TorPolicy::Required {
            runtime: TorRuntime::HostDialer(Arc::clone(&host) as Arc<dyn HostDialer>),
        };
        let w = Wallet::create_with_vault(config, raw_seed(), Arc::clone(&vault))
            .await
            .expect("create");
        assert_eq!(
            w.tor_state(),
            TorState::Active {
                runtime: crate::state::TorRuntimeKind::HostDialer {
                    name: name("Tor"),
                    isolation: IsolationSupport::Supported,
                    exposure: TransportExposure::Hidden,
                }
            },
            "a ready registered host dialer reads Active naming the host's name, isolation and exposure"
        );
        host.set_descriptor(Some(HostTransportDescriptor {
            name: name("Tor"),
            readiness: 50,
            isolation: IsolationSupport::Supported,
            exposure: TransportExposure::Hidden,
            health: TransportHealth::Starting,
        }));
        assert_eq!(
            w.tor_state(),
            TorState::Bootstrapping {
                percent: Some(0.5),
                transport: Some(name("Tor"))
            },
            "the host's readiness push moves the state at the next read"
        );
        // The registrant declares its transport FAILED (ABI v3, ADR-0549): the
        // wallet reads Unavailable, never a bootstrap that cannot finish.
        host.set_descriptor(Some(HostTransportDescriptor {
            name: name("Tor"),
            readiness: 50,
            isolation: IsolationSupport::Supported,
            exposure: TransportExposure::Hidden,
            health: TransportHealth::Failed,
        }));
        assert_eq!(
            w.tor_state(),
            TorState::Unavailable {
                transport: Some(name("Tor"))
            },
            "a declared FAILURE reads Unavailable at the same readiness"
        );
        host.set_descriptor(None);
        assert_eq!(
            w.tor_state(),
            TorState::Unavailable { transport: None },
            "a clear (nothing registered) reads Unavailable"
        );
        host.set_descriptor(Some(HostTransportDescriptor {
            name: name("VLESS via Cloudflare"),
            readiness: 100,
            isolation: IsolationSupport::Unknown,
            exposure: TransportExposure::Unknown,
            health: TransportHealth::Ready,
        }));
        assert_eq!(
            w.tor_state(),
            TorState::Active {
                runtime: crate::state::TorRuntimeKind::HostDialer {
                    name: name("VLESS via Cloudflare"),
                    isolation: IsolationSupport::Unknown,
                    exposure: TransportExposure::Unknown,
                }
            },
            "a fresh descriptor behind the same trampoline reads Active naming the host's new name"
        );
        w.close().await.expect("close");
    }

    /// FR-29 spec §6.1 E12 (T21, the SHIPPED path): a custom `http://` loopback
    /// choice persisted under `Off` (the development configuration) meets a
    /// host-dialer policy at the next open. The wallet OPENS — on the default,
    /// with `ChoiceRefusedByTransport` and the choice kept — never on the
    /// plaintext endpoint (raw gRPC through the host's transport), never a
    /// stall. Re-opened under `Off`, the same row is honoured again.
    #[tokio::test]
    async fn a_persisted_plaintext_choice_under_a_host_dialer_falls_back_visibly_at_open() {
        use crate::config::TorRuntime;
        use crate::net::host_dialer::HostDialer;
        use crate::net::host_dialer::testing::ScriptedHostDialer;
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let loopback = "http://127.0.0.1:9067";
        let w = Wallet::create_with_vault(
            cfg(dir.path(), Network::Test, SeedPersistence::SealedKeychain),
            raw_seed(),
            Arc::clone(&vault),
        )
        .await
        .expect("create under Off");
        {
            let aux = w.inner.aux_db.lock().expect("aux db");
            sync_server::write(&aux, &custom(loopback), 1_760_000_000).expect("write the choice");
        }
        w.close().await.expect("close");

        // Re-open under a registered host dialer: the row cannot be carried.
        let host = Arc::new(ScriptedHostDialer::ready());
        let mut c = cfg(dir.path(), Network::Test, SeedPersistence::SealedKeychain);
        c.tor = TorPolicy::Required {
            runtime: TorRuntime::HostDialer(Arc::clone(&host) as Arc<dyn HostDialer>),
        };
        let w = Wallet::open_with_vault(c, Arc::clone(&vault))
            .await
            .expect("the wallet opens on the default — a refused choice is never a stall");
        let s = w.sync_server_status();
        assert_eq!(
            s.effective.as_str(),
            "https://zec.rocks:443",
            "the default is dialed, never the plaintext choice"
        );
        assert_eq!(
            s.fallback,
            Some(SyncServerFallback::ChoiceRefusedByTransport)
        );
        assert_eq!(
            s.choice,
            Some(custom(loopback)),
            "the choice is kept so the picker can name it"
        );
        w.close().await.expect("close");

        // The control: under `Off` the same row is honoured again.
        let w = Wallet::open_with_vault(
            cfg(dir.path(), Network::Test, SeedPersistence::SealedKeychain),
            Arc::clone(&vault),
        )
        .await
        .expect("re-open under Off");
        let s = w.sync_server_status();
        assert_eq!(s.effective.as_str(), loopback);
        assert_eq!(s.fallback, None);
        w.close().await.expect("close");
    }

