    #[tokio::test]
    #[cfg(feature = "swap")]
    async fn swap_dialer_preferred_fallback_flips_the_shared_tor_fell_back_latch() {
        // THE §3.2 m5 + INC-2D GATE property: the swap path rides the SAME wallet-level
        // transport AND fell-back latch as sync. A Preferred swap call that degrades to
        // clearnet flips the ONE `Inner.tor_posture` atomic `tor_state()` reads — so a
        // swap-path degradation surfaces in the transparency panel exactly like a sync
        // one, never hidden behind a stale Active. Build Preferred+FailingDialer, dial a
        // loopback via `swap_dialer` (the direct fallback SUCCEEDS), assert FellBack.
        use crate::config::TorRuntime;
        use crate::ports::testing::FailingDialer;
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let mut config = cfg(dir.path(), Network::Test, SeedPersistence::SealedKeychain);
        config.tor = TorPolicy::Preferred {
            runtime: TorRuntime::Dialer(Arc::new(FailingDialer) as Arc<dyn crate::ports::NetDialer>),
        };
        let w = Wallet::create_with_vault(config, raw_seed(), Arc::clone(&vault))
            .await
            .expect("create");
        w.tor_posture_for_test().spend_the_minute_for_test(); // ADR-0552's minute, spent
        assert_eq!(
            w.tor_state(),
            TorState::Active {
                runtime: crate::state::TorRuntimeKind::Dialer
            },
            "not degraded before any swap dial"
        );
        let dialer = w.swap_dialer().expect("Preferred resolves a dialer");
        // a live loopback for the clearnet fallback to reach so it SUCCEEDS (in-process)
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
            .await
            .expect("bind loopback");
        let addr = listener.local_addr().expect("addr");
        let accept = tokio::spawn(async move { listener.accept().await.map(|_| ()) });
        let r = dialer
            .dial(&addr.ip().to_string(), addr.port(), Some("swap/quote"))
            .await;
        assert!(
            r.is_ok(),
            "primary failed ⇒ the swap call fell back to clearnet"
        );
        let _ = accept.await;
        assert_eq!(
            w.tor_state(),
            TorState::FellBack,
            "the swap-path fallback flipped the SAME wallet-level latch tor_state() reads"
        );
        w.close().await.expect("close");
    }

    #[tokio::test]
    #[cfg(feature = "swap")]
    async fn swap_port_failure_logs_the_internal_code_5_4_clean() {
        // The carried -c-2-ii observability item: when a swap port collapses an internal
        // `WalletError` to its payload-free `SwapError`, it logs the internal cause as a
        // CODE (`RW-…-NNN`) — never a reason string / address / amount. Drive a REAL port
        // over a CLOSING wallet (so `require_open()` fails INSIDE the blocking op — the
        // `map_err(log_swap_port_error)` arm, not the upgrade-`None` `ok_or` arm — runs)
        // under the capture layer; assert §5.4-clean AND that a `code` field was emitted.
        use crate::lifecycle::LifecyclePhase;
        use crate::swap::IssuedQuoteStore;
        use crate::tracing_guard::{
            CaptureLayer, CapturedEvents, assert_5_4_clean, force_wallet_callsites_enabled,
        };
        use tracing_subscriber::prelude::*;

        force_wallet_callsites_enabled(); // keep callsites enabled under parallel capture
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let w = wallet_with_chain_account(dir.path(), &vault).await;
        // A LIVE weak (upgrades) — but a Closing wallet, so the inner op fails honestly.
        let port = WalletIssuedQuoteStore {
            inner: Arc::downgrade(&w.inner),
        };
        w.inner
            .lifecycle
            .transition(LifecyclePhase::Closing)
            .expect("→ Closing");

        let sink = CapturedEvents::default();
        let subscriber = tracing_subscriber::registry().with(CaptureLayer::new(sink.clone()));
        let _guard = tracing::subscriber::set_default(subscriber);
        let err = port
            .persist(crate::swap::IssuedQuoteRecord {
                refund: None,
                id: crate::swap::SwapId::new("q-closing"),
                provider_ref: "t1closing".into(),
                terms: test_quote_terms("t1closing", 100_000),
                deposit: None,
                destination: None,
                expires_at_wall: 1_900_000_000,
                binding: None,
            })
            .await
            .expect_err("a closing wallet cannot persist an issued quote");
        assert!(matches!(err, crate::error::SwapError::SwapStateUnavailable));

        let fields = sink.fields();
        assert_5_4_clean(&fields); // the boundary log leaks no secret
        assert!(
            fields
                .iter()
                .any(|(n, v)| n == "code" && v.starts_with("RW-")),
            "the internal cause was preserved as a payload-free RW-…-NNN code"
        );
        drop(w);
    }

