    #[tokio::test]
    async fn snapshot_carries_the_persisted_stamp_across_a_relaunch() {
        // §8 (#317): the stamp written by the REAL production adapter
        // (`LightdSyncEngine::record_synced` — weak upgrade + wall clock + aux
        // write, fail-open) is what `snapshot()` returns, INCLUDING after a
        // close + reopen — the cross-launch "as of block H, time" this exists for.
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let w = wallet_with_chain_account(dir.path(), &vault).await;
        let engine = LightdSyncEngine::dialed(Arc::downgrade(&w.inner));
        engine.record_synced(BlockHeight::new(2_100_000)).await;
        let snap = w.snapshot().await.expect("snapshot");
        let stamp = snap.last_synced.expect("stamp persisted");
        assert_eq!(stamp.height, BlockHeight::new(2_100_000));
        assert!(
            stamp.at > 0,
            "a real wall-clock `at`, not the pre-epoch fallback"
        );
        w.close().await.expect("close");

        // The relaunch read — a FRESH handle over the same store.
        let w = Wallet::open_with_vault(
            cfg(dir.path(), Network::Test, SeedPersistence::SealedKeychain),
            Arc::clone(&vault),
        )
        .await
        .expect("reopen");
        assert_eq!(
            w.snapshot().await.expect("snapshot").last_synced,
            Some(stamp),
            "the stamp survives a relaunch — no waiting for the first UpToDate",
        );
        w.close().await.expect("close");
    }

