        engine.record_synced(BlockHeight::new(2_100_000)).await;
        assert!(
            w.snapshot().await.expect("snap").ever_synced,
            "reaching tip sets everSynced",
        );
        w.close().await.expect("close");

        // The relaunch read — a FRESH handle over the same store.
        let w = Wallet::open_with_vault(
            cfg(dir.path(), Network::Test, SeedPersistence::SealedKeychain),
            Arc::clone(&vault),
        )
        .await
        .expect("reopen");
