    #[tokio::test]
    #[cfg(feature = "swap")]
    async fn rescan_clears_the_registration_marker_but_keeps_the_counter() {
        // #368 (the `rescan_clears_the_last_synced_stamp` sibling): the rebuild's fresh
        // engine DB holds NONE of the prior `get_address_for_index` registrations, so a
        // surviving marker would falsely assert the allocated indices registered — the
        // clear makes the next transparent refresh re-register the FULL range (healing
        // refund AND destination registrations across a rescan). The never-recycle
        // COUNTER itself must ride the copy untouched (ADR-0534 — losing it would
        // recycle a refund index, HARD-H).
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let w = wallet_with_chain_account(dir.path(), &vault).await;
        {
            let mut aux = w.inner.aux_db.lock().expect("aux mutex");
            // #387: device-local shape — this test's marker/counter continuity
            // expectations are floor-based.
            aux.execute("DELETE FROM refund_address_index", [])
                .expect("device-local shape");
            for _ in 0..2 {
                crate::refund_index::reserve_next_index(&mut aux).expect("reserve");
            }
            // drop the open-seeded bounds (#382) so the allocated range reads as
            // OWED — the pre-#368 upgrade shape this test simulates
            crate::refund_index::clear_registration(&aux).expect("simulate pre-#368 bounds");
        }
        // register the allocated range so the marker is non-zero pre-rescan
        w.backfill_swap_address_registrations()
            .await
            .expect("backfill");
        {
            let aux = w.inner.aux_db.lock().expect("aux mutex");
            assert_eq!(
                crate::refund_index::registered_up_to(&aux).expect("marker"),
                2,
                "marker caught the counter pre-rescan"
            );
        }
        let w = w
            .rescan_from_with_vault(None, Arc::clone(&vault))
            .await
            .expect("rescan");
        {
            let aux = w.inner.aux_db.lock().expect("aux mutex");
            assert_eq!(
                crate::refund_index::registered_up_to(&aux).expect("marker"),
                0,
                "the rebuild cleared the marker — the engine registrations died with the data DB"
            );
            assert_eq!(
                crate::refund_index::next_index_snapshot(&aux).expect("counter"),
                3,
                "the never-recycle counter itself rode the copy untouched"
            );
            // #382: the rebuild RE-SEEDED the bounds on the temp DB atomically with the
            // clear — a post-rescan DB never carries an unseeded row a live quote's
            // reserve→persist gap could race (the seed-race MED closure).
            assert_eq!(
                crate::refund_index::backfill_bounds(&aux).expect("bounds"),
                Some((0, 3)),
                "bounds re-seeded from the copied counter, marker 0"
            );
        }
        // the rebuilt wallet is ACCOUNT-LESS until the next sync's lazy provision
        // (`rescan_inner` step 7) — the backfill's no-account arm HOLDS the marker
        // (nothing can register yet) rather than falsely advancing it
        w.backfill_swap_address_registrations()
            .await
            .expect("account-less backfill is a safe no-op");
        {
            let aux = w.inner.aux_db.lock().expect("aux mutex");
            assert_eq!(
                crate::refund_index::registered_up_to(&aux).expect("marker"),
                0,
                "no account yet ⇒ the marker holds (never a false advance)"
            );
        }
        // the next sync re-imports account 0 (simulated here), THEN the backfill
        // re-registers on the FRESH engine and the marker re-catches the counter
        w.import_account(chain_birthday()).await.expect("re-import");
        w.backfill_swap_address_registrations()
            .await
            .expect("re-backfill");
        {
            let aux = w.inner.aux_db.lock().expect("aux mutex");
            assert_eq!(
                crate::refund_index::registered_up_to(&aux).expect("marker"),
                2,
                "post-rescan the marker re-caught the counter (registrations re-created)"
            );
        }
        w.close().await.expect("close");
    }

