    #[tokio::test]
    async fn snapshot_seq_is_strictly_monotonic_across_calls() {
        // §8: `seq` stamps each emission so a stale stream item can never beat a fresher
        // snapshot in the UI race (§3.3). Consecutive snapshots strictly increase — even
        // with no state change — so the host's latest-wins compare is always well-defined.
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let w = wallet_with_chain_account(dir.path(), &vault).await;
        let a = w.snapshot().await.expect("snapshot a");
        let b = w.snapshot().await.expect("snapshot b");
        let c = w.snapshot().await.expect("snapshot c");
        assert!(a.seq < b.seq && b.seq < c.seq, "seq is strictly monotonic");
        w.close().await.expect("close");
    }

    #[tokio::test]
    async fn snapshot_seq_is_unique_under_concurrency() {
        // §8 (testing-patterns — thread-safe types need a concurrent test): the `seq`
        // counter's whole purpose is a UNIQUE emission stamp; fire N concurrent snapshots
        // and assert every returned seq is distinct (a non-atomic bump would collide).
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let w = Arc::new(wallet_with_chain_account(dir.path(), &vault).await);
        let mut handles = Vec::new();
        for _ in 0..16 {
            let w = Arc::clone(&w);
            handles.push(tokio::spawn(async move {
                w.snapshot().await.expect("snapshot").seq
            }));
        }
        let mut seqs = Vec::new();
        for h in handles {
            seqs.push(h.await.expect("join"));
        }
        let unique: std::collections::HashSet<u64> = seqs.iter().copied().collect();
        assert_eq!(unique.len(), seqs.len(), "every concurrent seq is distinct");
        // Arc<Wallet> here is a TEST-only share (the handle is otherwise !Clone); drop all
        // refs before close. The spawned snapshots all completed (joined) above.
        let w = Arc::into_inner(w).expect("sole owner after joins");
        w.close().await.expect("close");
    }

    #[tokio::test]
    async fn snapshot_rejects_during_teardown() {
        // §8 (MOBILE lifecycle): unlike the lock-free `tor_state()`, `snapshot()` reads the
        // DB, so it MUST `require_open()` — a snapshot fired while the app is backgrounding
        // (Closing) rejects WalletBusy, never touches a half-torn-down DB. (Mirrors
        // `balance_rejects_on_a_closing_or_wiped_wallet`.)
        use crate::lifecycle::LifecyclePhase;
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let w = wallet_with_chain_account(dir.path(), &vault).await;
        w.inner
            .lifecycle
            .transition(LifecyclePhase::Closing)
            .expect("→ Closing");
        assert!(
            matches!(
                w.snapshot().await,
                Err(WalletError::WalletBusy {
                    phase: LifecyclePhase::Closing
                })
            ),
            "snapshot() on a closing wallet is WalletBusy",
        );
        drop(w);

        // ...and the Wiped arm (a wipe() racing an in-flight snapshot) ⇒ InvalidState. A
        // separate temp dir avoids the advisory-lock collision between the two handles.
        let dir2 = tempfile::tempdir().expect("tempdir2");
        let w2 = wallet_with_chain_account(dir2.path(), &vault).await;
        w2.inner
            .lifecycle
            .transition(LifecyclePhase::Closing)
            .expect("→ Closing");
        w2.inner
            .lifecycle
            .transition(LifecyclePhase::Wiped)
            .expect("→ Wiped");
        assert!(
            matches!(
                w2.snapshot().await,
                Err(WalletError::InvalidState {
                    phase: LifecyclePhase::Wiped
                })
            ),
            "snapshot() on a wiped wallet is InvalidState",
        );
        drop(w2);
    }

