    /// A test [`SyncStatusSink`] that forwards every emitted status to an mpsc channel
    /// (so a test awaits emissions deterministically — no sleeps) and reports closed on
    /// the `emit_limit`-th emit: `None` = unlimited (a host that keeps the subscription),
    /// `Some(n)` = the sink reports closed ON the nth emit (the host cancelled its Dart
    /// subscription after receiving n — the `paused` path); the nth value is still
    /// delivered first, matching the bridge `FrbStatusSink` (which forwards, then reads
    /// the `add` result).
    struct ChannelSink {
        tx: tokio::sync::mpsc::UnboundedSender<SyncStatus>,
        emitted: usize,
        emit_limit: Option<usize>,
    }
    impl SyncStatusSink for ChannelSink {
        fn emit(&mut self, status: SyncStatus) -> bool {
            // forward first (the value is delivered), then decide whether to continue
            let downstream_open = self.tx.send(status).is_ok();
            self.emitted += 1;
            // stop if the mpsc is gone OR we reached the simulated host-cancel limit
            downstream_open && self.emit_limit.is_none_or(|n| self.emitted < n)
        }
    }

    #[tokio::test]
    async fn watch_sync_status_streams_current_then_drains_final_and_ends_on_close() {
        // §8 (iii-B-2-d-2-b — the live SyncStatus stream END TO END, wallet→controller→
        // pump→sink, over a REAL close): the sink sees the CURRENT status first (Idle —
        // sync not started). At teardown close() stops the controller FIRST — emitting
        // one final Idle (sync_controller stop()) the pump DRAINS — THEN drops the last
        // `Arc<Inner>`, dropping the watch Sender. The pump, owning only the INDEPENDENT
        // receiver (never an `Arc<Inner>`), then ends and drops the sink — so close() is
        // never blocked (the pump pins nothing) and the Dart stream closes cleanly. The
        // status TRANSITIONS ride the sync_controller tests over a fake engine: driving
        // start_sync here would dial the real endpoint, a network attempt barred from a
        // unit test.
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let w = Wallet::create_with_vault(
            cfg(dir.path(), Network::Main, SeedPersistence::SealedKeychain),
            raw_seed(),
            Arc::clone(&vault),
        )
        .await
        .expect("create");

        let (tx, mut rx) = tokio::sync::mpsc::unbounded_channel();
        w.watch_sync_status(ChannelSink {
            tx,
            emitted: 0,
            emit_limit: None,
        });

        // current-first: a subscriber sees the live status immediately (mobile resume).
        assert_eq!(
            rx.recv().await,
            Some(SyncStatus::Idle),
            "the current status streams first"
        );

        w.close().await.expect("close");

        // close() emits a final Idle (stop()), which the pump drains, then drops Inner →
        // the Sender drops → the pump ends and drops the sink → the mpsc closes (None).
        assert_eq!(
            rx.recv().await,
            Some(SyncStatus::Idle),
            "the final teardown status is drained, not lost"
        );
        assert_eq!(
            rx.recv().await,
            None,
            "the pump ends and drops the sink when the wallet tears down (never blocks close)"
        );
    }

    #[tokio::test]
    async fn status_pump_delivers_changes_and_stops_when_the_sink_reports_cancelled() {
        // The pump in ISOLATION (a hand-made watch, no wallet): it delivers the current
        // value then each change, and STOPS the instant the sink reports closed (the host
        // cancelled its Dart subscription on `paused`) — proven by a later change never
        // arriving. (The teardown-EOF + final-drain path rides the integration test
        // above; coalescing latest-wins is the watch channel's own contract + the e2e.)
        let (status_tx, status_rx) = watch::channel(SyncStatus::Idle);
        let (tx, mut rx) = tokio::sync::mpsc::unbounded_channel();
        // the host cancels ON the 2nd emit (after the current value + one change)
        spawn_status_pump(
            status_rx,
            ChannelSink {
                tx,
                emitted: 0,
                emit_limit: Some(2),
            },
        );

        // current-first
        assert_eq!(rx.recv().await, Some(SyncStatus::Idle));
        // a change is delivered
        let up = SyncStatus::UpToDate {
            tip: BlockHeight::new(281_000),
        };
        status_tx.send(up.clone()).expect("send change");
        assert_eq!(rx.recv().await, Some(up));

        // the sink reported cancelled on the 2nd emit ⇒ the pump stops and drops the sink.
        // Even a change queued AFTER the cancel is never delivered — the pump is gone (the
        // send may also fail, having lost its only receiver; either way nothing reaches
        // the sink). Awaiting the mpsc drives the pump to completion and observes close.
        let _ = status_tx.send(SyncStatus::Stalled {
            reason: StallReason::Internal,
        });
        assert_eq!(
            rx.recv().await,
            None,
            "no status reaches the sink after the host cancelled"
        );
    }

    #[tokio::test]
    async fn status_pump_emits_the_latest_value_to_a_late_subscriber() {
        // §8 (iii-B-2-d-2-b — the MOBILE-RESUME contract, §3.3): a host re-subscribing
        // after a background gap must see the CURRENT status immediately — the LATEST,
        // never a stale initial. Here the watch already holds a post-Idle value when the
        // pump attaches; its FIRST emit is that latest value, so the UI re-renders
        // correctly on resume without waiting for the next change.
        let (status_tx, status_rx) = watch::channel(SyncStatus::Idle);
        // sync advanced BEFORE this subscriber attaches (the background gap)
        let up = SyncStatus::UpToDate {
            tip: BlockHeight::new(281_000),
        };
        status_tx
            .send(up.clone())
            .expect("send the pre-subscribe advance");

        let (tx, mut rx) = tokio::sync::mpsc::unbounded_channel();
        spawn_status_pump(
            status_rx,
            ChannelSink {
                tx,
                emitted: 0,
                emit_limit: Some(1),
            },
        );

        assert_eq!(
            rx.recv().await,
            Some(up),
            "a late subscriber sees the latest current status, not a stale initial Idle"
        );
        assert_eq!(rx.recv().await, None, "then the single-emit sink closes");
    }

    // ── ADR-0536 #392: the incoming-funds stream (replay + edges + teardown) ──

    /// The incoming analogue of [`ChannelSink`] — forwards every event to an mpsc so a
    /// test awaits deterministically; reports closed on the `emit_limit`-th emit.
    struct IncomingChannelSink {
        tx: tokio::sync::mpsc::UnboundedSender<IncomingFundsEvent>,
        emitted: usize,
        emit_limit: Option<usize>,
    }
    impl IncomingFundsSink for IncomingChannelSink {
        fn emit(&mut self, event: IncomingFundsEvent) -> bool {
            let downstream_open = self.tx.send(event).is_ok();
            self.emitted += 1;
            downstream_open && self.emit_limit.is_none_or(|n| self.emitted < n)
        }
    }

    fn incoming_sink(
        emit_limit: Option<usize>,
    ) -> (
        IncomingChannelSink,
        tokio::sync::mpsc::UnboundedReceiver<IncomingFundsEvent>,
    ) {
        let (tx, rx) = tokio::sync::mpsc::unbounded_channel();
        (
            IncomingChannelSink {
                tx,
                emitted: 0,
                emit_limit,
            },
            rx,
        )
    }

    #[tokio::test]
    async fn watch_incoming_funds_replays_baseline_then_forwards_edges_and_ends_on_teardown() {
        // §8 (ADR-0536 gate-8, end to end wallet→channel→pump→sink): a `None` cursor
        // gets the count-0 baseline Replay FIRST (handing the host a cursor to
        // persist), each emitted edge forwards with the tear-free cumulative total,
        // a MemoRefresh keeps counts + the last stamped watermark, and teardown ends
        // the stream without blocking close (the pump owns only the receiver).
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let w = Wallet::create_with_vault(
            cfg(dir.path(), Network::Main, SeedPersistence::SealedKeychain),
            raw_seed(),
            Arc::clone(&vault),
        )
        .await
        .expect("create");

        let (sink, mut rx) = incoming_sink(None);
        w.watch_incoming_funds(None, sink)
            .await
            .expect("subscribe with no cursor");

        let replay = rx.recv().await.expect("the Replay comes first");
        assert_eq!(replay.kind, IncomingFundsEventKind::Replay);
        assert_eq!(replay.new_tx_count, 0, "None cursor = from-now baseline");
        assert_eq!(replay.total_tx_detected, 0);
        assert_eq!(
            replay.cursor, "w1:0",
            "nothing scanned yet ⇒ the zero watermark"
        );
        assert!(replay.span_from_height.is_none());

        // A live edge forwards with the cumulative total + the batch watermark.
        w.emit_incoming_live(2, (100, 120), 130);
        let live = rx.recv().await.expect("live edge");
        assert_eq!(live.kind, IncomingFundsEventKind::Live);
        assert_eq!(live.new_tx_count, 2);
        assert_eq!(live.total_tx_detected, 2);
        assert_eq!(live.span_from_height, Some(100));
        assert_eq!(live.span_to_height, Some(120));
        assert_eq!(live.cursor, "w1:130");

        // The memo-refresh nudge: counts + watermark carried, kind flips, no span.
        w.emit_incoming_memo_refresh();
        let memo = rx.recv().await.expect("memo refresh");
        assert_eq!(memo.kind, IncomingFundsEventKind::MemoRefresh);
        assert_eq!(memo.new_tx_count, 0);
        assert_eq!(
            memo.total_tx_detected, 2,
            "the cumulative total never rewinds"
        );
        assert_eq!(memo.cursor, "w1:130", "the last stamped watermark is kept");
        assert!(memo.span_from_height.is_none());

        // A second subscriber replays against the CURRENT state: its Replay carries
        // the live total as its baseline (replay never advances the counter).
        let (sink2, mut rx2) = incoming_sink(None);
        w.watch_incoming_funds(None, sink2)
            .await
            .expect("second subscriber");
        let replay2 = rx2.recv().await.expect("second Replay");
        assert_eq!(replay2.kind, IncomingFundsEventKind::Replay);
        assert_eq!(
            replay2.total_tx_detected, 2,
            "the Replay baseline carries the wallet-open cumulative total"
        );

        // Teardown: close() consumes the handle → the last `Arc<Inner>` drops → the
        // channel Sender drops → both pumps end and drop their sinks (never blocking
        // close — they own only receivers).
        w.close().await.expect("close");
        assert_eq!(rx.recv().await, None, "the stream ends at teardown");
        assert_eq!(rx2.recv().await, None, "every subscriber's stream ends");
    }

