    #[tokio::test]
    async fn an_edge_racing_the_replay_is_forwarded_never_swallowed() {
        // §8 (arch review HIGH): an edge emitted AFTER `subscribe()` but
        // BEFORE the pump task's first poll must be FORWARDED — the historical
        // pump opened with `borrow_and_update()`, which marked exactly this
        // edge seen without forwarding: a silently swallowed arrival. This is
        // deterministic here: the spawned pump cannot run until this test
        // yields, so the emit below lands precisely in that window. (The
        // timeout turns the mutant's forever-pending `changed()` into a clean
        // failure instead of a hang.)
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let w = Wallet::create_with_vault(
            cfg(dir.path(), Network::Main, SeedPersistence::SealedKeychain),
            raw_seed(),
            Arc::clone(&vault),
        )
        .await
        .expect("create");

        let (sink, mut rx) = incoming_sink(None);
        w.watch_incoming_funds(None, sink).await.expect("subscribe");
        // The race window: no await between subscribe returning and this emit.
        w.emit_incoming_live(1, (50, 50), 60);

        let replay = rx.recv().await.expect("replay first");
        assert_eq!(replay.kind, IncomingFundsEventKind::Replay);
        let raced = tokio::time::timeout(std::time::Duration::from_secs(5), rx.recv())
            .await
            .expect("the raced edge must arrive (a swallow pends forever)")
            .expect("stream open");
        assert_eq!(raced.kind, IncomingFundsEventKind::Live);
        assert_eq!(raced.new_tx_count, 1, "duplicate-or-new, NEVER lost");
        w.close().await.expect("close");
    }

