    #[tokio::test]
    #[cfg(feature = "swap")]
    async fn enable_swap_derives_real_fresh_never_recycled_refund_addresses() {
        // TWO OutOfZec quotes through a REAL wallet: the service populates refundTo with
        // the wallet's OWN fresh external-scope t-addr, the durable counter advances 0 → 1,
        // and the addresses match the audited derivation byte-for-byte — never recycled.
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let w = Wallet::create_with_vault(
            cfg(dir.path(), Network::Main, SeedPersistence::SealedKeychain),
            raw_seed(),
            Arc::clone(&vault),
        )
        .await
        .expect("create");
        // #368: the refund mint engine-registers via `get_address_for_index`,
        // so the account must exist (the destination-source posture since IZ-1a).
        w.import_account(chain_birthday()).await.expect("import");
        w.enable_swap(echoing_out_provider(100_000))
            .expect("enable swap");
        let svc = w.swap().expect("swap enabled");
        let q0 = svc
            .quote(out_of_zec_request(100_000))
            .await
            .expect("quote 0");
        let q1 = svc
            .quote(out_of_zec_request(100_000))
            .await
            .expect("quote 1");
        // raw_seed() is [0x24; 32] — derive the expected external-scope t-addrs
        // independently. #387: a raw-seed create is restore-shaped, so allocations
        // start AT the breadth.
        let base = crate::refund_index::RESTORE_BACKFILL_BREADTH;
        let expect0 =
            crate::derivation::derive_transparent_refund_address(Network::Main, &[0x24; 32], base)
                .expect("derive 0");
        let expect1 = crate::derivation::derive_transparent_refund_address(
            Network::Main,
            &[0x24; 32],
            base + 1,
        )
        .expect("derive 1");
        assert_eq!(
            q0.refund_to.as_deref(),
            Some(expect0.as_str()),
            "first swap refunds to the first post-restore external index (index 0 is \
             the receive address, ADR-0528; the breadth is #387's)"
        );
        assert_eq!(
            q1.refund_to.as_deref(),
            Some(expect1.as_str()),
            "second swap refunds to the FRESH next index — the never-recycle counter, \
             end-to-end"
        );
        assert_ne!(
            q0.refund_to, q1.refund_to,
            "two swaps NEVER share a refund address (HARD-H privacy property)"
        );
        w.close().await.expect("close");
    }

    #[tokio::test]
    #[cfg(feature = "swap")]
    async fn execute_outofzec_queues_a_real_deadline_tagged_deposit_through_the_outbox() {
        // The §4.4 deposit leg: execute drives a REAL deposit into the wallet's offline-first
        // outbox (no network, no signing here), tagged with the quote's wall deadline so the
        // resubmission machinery excludes a dead quote.
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let w = Wallet::create_with_vault(
            cfg(dir.path(), Network::Main, SeedPersistence::SealedKeychain),
            raw_seed(),
            Arc::clone(&vault),
        )
        .await
        .expect("create");
        // #368: the refund mint engine-registers via `get_address_for_index`,
        // so the account must exist (the destination-source posture since IZ-1a).
        w.import_account(chain_birthday()).await.expect("import");
        w.enable_swap(echoing_out_provider(100_000))
            .expect("enable swap");
        let svc = w.swap().expect("swap enabled");
        let quote = svc.quote(out_of_zec_request(100_000)).await.expect("quote");
        // before execute: the outbox holds no deposit
        {
            let guard = w.inner.aux_db.lock().expect("aux db");
            assert!(
                crate::intent_store::list_queued(&guard)
                    .expect("list")
                    .is_empty(),
                "nothing queued before execute"
            );
        }
        let id = svc
            .execute(&quote)
            .await
            .expect("execute drives the deposit");
        // S8: the returned id is the SDK-minted execution identity the DTO carried —
        // never the provider's own handle (`q-wire`, kept as `provider_ref`).
        assert_eq!(id, quote.id, "execute returns the quote's SDK-minted id");
        // after execute: EXACTLY ONE deposit intent, carrying the quote's wall deadline (§4.4).
        // Scoped so the (sync) aux-db guard is dropped before the `close().await`.
        {
            let guard = w.inner.aux_db.lock().expect("aux db");
            let queued = crate::intent_store::list_queued(&guard).expect("list");
            assert_eq!(
                queued.len(),
                1,
                "exactly one deposit queued through the wallet outbox"
            );
            // #367: the returned quote's expires_at is the ACTIONABLE deadline;
            // the durable tag is the full clamped wall deadline one execute
            // margin past it.
            let tag = quote.expires_at + crate::constants::DEPOSIT_EXECUTE_MARGIN_SECS;
            assert_eq!(
                queued[0].deposit_deadline,
                Some(i64::try_from(tag).expect("deadline fits")),
                "the deposit carries the quote deadline tag"
            );
        }
        w.close().await.expect("close");
    }

