        // reopen the SAME wallet (same dir + vault) and reconstruct swap
        let w2 = Wallet::open_with_vault(
            cfg(dir.path(), Network::Main, SeedPersistence::SealedKeychain),
            Arc::clone(&vault),
        )
        .await
        .expect("reopen");
