    #[tokio::test]
    #[cfg(feature = "swap")]
    async fn a_reserve_in_its_persist_gap_is_never_swept_by_the_backfill() {
        // #382 — the seed-race pin, in the EXACT race shape: a counter reserve
        // whose issued-quote row has NOT persisted yet (lock-queued / mid provider
        // RTT) is invisible to `arm_backfill`'s live-quote `NOT EXISTS` — pre-#382 a
        // backfill whose lazy seed snapshotted AFTER the reserve swept that index
        // into a one-window poll (privacy-envelope violation + a benign twin on
        // execute). With the ceiling seeded at OPEN, the reserve is ≥ the ceiling BY
        // CONSTRUCTION and nothing is swept, no exclusion needed.
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let w = wallet_with_chain_account(dir.path(), &vault).await;
        // #387: floor-shape the aux (this test models a device-created wallet; the
        // race property is breadth-independent).
        strip_restore_seed(&w.inner);
        {
            let mut aux = w.inner.aux_db.lock().expect("aux mutex");
            // the reserve committed; the issued row deliberately NEVER persists
            crate::refund_index::reserve_next_index(&mut aux).expect("reserve");
        }
        w.backfill_swap_address_registrations()
            .await
            .expect("pass during the persist gap");
        assert_eq!(
            swap_dest_count(&w.inner),
            0,
            "the in-gap reserve is post-ceiling — never swept into the poll"
        );
        {
            let aux = w.inner.aux_db.lock().expect("aux mutex");
            assert_eq!(
                crate::refund_index::registered_up_to(&aux).expect("marker"),
                0,
                "the marker never chased the live counter"
            );
        }
        w.close().await.expect("close");
    }

    #[tokio::test]
    #[cfg(feature = "swap")]
    async fn backfill_refuses_a_ceiling_above_the_counter_typed() {
        // #382 hardening — the bounds cross-check: a tampered in-range ceiling above
        // the counter would mint+poll up to a whole pass of NEVER-allocated
        // addresses; the work path refuses it fail-closed BEFORE any engine mint.
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let w = wallet_with_chain_account(dir.path(), &vault).await;
        {
            let aux = w.inner.aux_db.lock().expect("aux mutex");
            // #387: drop the restore-burned counter too — the tamper shape needs
            // ceiling(9) ABOVE the counter snapshot (floor, 1), not below the breadth.
            aux.execute("DELETE FROM refund_address_index", [])
                .expect("device-local shape");
            crate::refund_index::clear_registration(&aux).expect("drop the open seed");
            crate::refund_index::seed_backfill_bounds(&aux, 9).expect("tampered ceiling");
        }
        assert!(
            matches!(
                w.backfill_swap_address_registrations().await,
                Err(WalletError::StoreCorrupt)
            ),
            "ceiling(9) > counter(1) is typed corruption, never a sweep"
        );
        assert_eq!(
            swap_dest_count(&w.inner),
            0,
            "fail-closed: nothing was minted or armed"
        );
        w.close().await.expect("close");
    }

    #[tokio::test]
    #[cfg(feature = "swap")]
    async fn late_refund_past_the_lapsed_watch_is_detected_and_pins_refunded() {
        // #382 — THE converged HIGH, end-to-end on the real engine: an OutOfZec
        // record whose watch LAPSED AND was PRUNED (the >48 h-absence shape — the
        // watch died before its first poll, the home row pre-#382 delisted, the
        // Refunded re-arm unreachable) is re-armed by the NEXT refresh pass's own
        // set build, its late refund UTXO is polled and engine-put
        // (balance-visible), the funded transition pins `Refunded` from the CHAIN,
        // and the home row lists the truth — without the tracking card ever being
        // opened. The exact sequence the fixed promise ("shows up in your balance
        // after the wallet next syncs") now guarantees for ANY absence length.
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let (w, _addr, _taddr) = synced_wallet_with_taddr(dir.path(), &vault).await;
        // #387: floor-shape the aux — this test's hand-built index-1 state (the mint,
        // the derived refund, the staged UTXO) must match the quote flow's reserve,
        // which under the restore shape would start at the breadth instead.
        strip_restore_seed(&w.inner);
        // Engine-register index 1 exactly like the quote-time refund mint does…
        let request = crate::derivation::swap_destination_address_request().expect("request");
        {
            let inner = Arc::clone(&w.inner);
            run_blocking(move || {
                let mut guard = inner.db.lock().expect("wallet db mutex poisoned");
                account::mint_swap_destination(&mut guard.db, Network::Test, 1, request)
            })
            .await
            .expect("mint")
            .expect("index 1 conforms");
        }
        // …with the raw BIP44 refundTo the provider was handed (the #368 KAT pins
        // the two derivations byte-equal).
        let refund_addr =
            crate::derivation::derive_transparent_refund_address(Network::Test, &[0x24; 32], 1)
                .expect("raw refund address");
        // The executed-swap shape, ALREADY LAPSED: home row + watch columns +
        // detection row all carry a bound 10 000 s in the past.
        let now = test_now_unix();
        {
            let mut aux = w.inner.aux_db.lock().expect("aux mutex");
            crate::swap_record_store::insert_with_watch(
                &mut aux,
                &crate::swap_record_store::InFlightSwap {
                    swap_id: "swap-late".to_owned(),
                    out_of_zec: true,
                    created_at: now - 200_000,
                    deposit_deadline: Some(now - 190_000),
                    expires_at_wall: now - 10_000,
                    outcome: None,
                },
                now - 200_000,
                "t1swaplate",
                Some((refund_addr.as_str(), 1)),
            )
            .expect("executed-swap shape");
            // a prior pass's prune already REAPED the lapsed watch row — the worst case
            crate::swap_destination_store::prune_expired(&mut aux, now).expect("prune");
            assert!(
                crate::swap_destination_store::active(&aux, now)
                    .expect("active")
                    .is_empty(),
                "the watch is dead and pruned before its first poll — the pre-#382 hole"
            );
        }
        // The late refund sits on-chain; the NEXT refresh pass must find it.
        let receiver = crate::derivation::transparent_receiver_from_stored_address(
            Network::Test,
            &refund_addr,
        )
        .expect("decodes");
        let mut src = FakeUtxoSource::ok(vec![crate::transparent::TransparentUtxoRecord {
            txid: vec![0x0c; 32],
            index: 0,
            script: script_paying(&receiver),
            value_zat: 45_000,
            height: 281_000,
        }]);
        let out = w
            .refresh_transparent_utxos(&mut src)
            .await
            .expect("refresh");
        assert_eq!(
            out.put, 1,
            "the late refund UTXO was engine-put — visible money"
        );
        assert!(
            src.last_addresses.contains(&refund_addr),
            "the same pass RESURRECTED the pruned watch into its own poll set"
        );
        {
            let aux = w.inner.aux_db.lock().expect("aux mutex");
            let active = crate::swap_destination_store::active(&aux, now).expect("active");
            assert_eq!(active.len(), 1, "the re-armed watch row is live");
            assert!(
                active[0].funded,
                "…and marked funded by the put attribution"
            );
        }
        let rows = w.list_in_flight_swaps().await.expect("list");
        let row = rows
            .iter()
            .find(|r| r.swap_id == "swap-late")
            .expect("the unresolved row lists past its lapse bound");
        assert_eq!(
            row.outcome,
            Some(crate::swap_record_store::SwapOutcome::Refunded),
            "the CHAIN observation pinned Refunded — no card open required"
        );
        // Convergence: the pinned row stops re-arming (unresolved_watches is empty)…
        {
            let aux = w.inner.aux_db.lock().expect("aux mutex");
            assert!(
                crate::swap_record_store::unresolved_watches(&aux)
                    .expect("watches")
                    .is_empty(),
                "a pinned row leaves the re-arm set"
            );
        }
        // …and the funded row exits through the normal funded→empty retire —
        // DEBOUNCED since #386: below the consecutive-empty threshold it stays.
        let mut empty_src = FakeUtxoSource::ok(Vec::new());
        for _ in 1..crate::swap_destination_store::RETIRE_AFTER_EMPTY_PASSES {
            w.refresh_transparent_utxos(&mut empty_src)
                .await
                .expect("below-threshold empty pass");
            let aux = w.inner.aux_db.lock().expect("aux mutex");
            assert!(
                !crate::swap_destination_store::active(&aux, now)
                    .expect("active")
                    .is_empty(),
                "one empty pass alone must not retire (the #386 debounce)"
            );
        }
        w.refresh_transparent_utxos(&mut empty_src)
            .await
            .expect("post-shield threshold pass");
        {
            let aux = w.inner.aux_db.lock().expect("aux mutex");
            assert!(
                crate::swap_destination_store::active(&aux, now)
                    .expect("active")
                    .is_empty(),
                "funded-then-empty retired the watch — the set shrinks back to index-0"
            );
        }
        w.close().await.expect("close");
    }

    #[tokio::test]
    #[cfg(feature = "swap")]
    async fn a_backfill_twin_is_collapsed_at_the_real_execute_leaving_one_funded_row() {
        // #390 DUAL-ROW RULE: the exact former twin shape — a synthetic
        // `backfill:<index>` row (armed by a #390 deep-scan widen or the #368 backfill)
        // beside a record whose SAME index later EXECUTES — is now COLLAPSED at the real
        // execute: `arm_in_tx` deletes the same-index `backfill:` twin in its own txn, so
        // exactly ONE row per receiver survives.
        // Before #390 both rows lived and the poll had to dedupe the query + credit every
        // twin (else the synthetic id, sorting first as "backfill:…" < "swap-…", starved
        // the real swap's funded credit — and with it the chain-observed Refunded pin, a
        // backfill id having no record). #390 removes the twin at the source, so the poll
        // now sees the one real row: the query carries the address once, the row is
        // funded, and the pin reaches the real swap.
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let (w, _addr, _taddr) = synced_wallet_with_taddr(dir.path(), &vault).await;
        // #387: floor-shape the aux — this test hand-builds its index-1 rows and
        // asserts active() shape/order; the restore sweep's 63 synthetic rows
        // would drown them.
        strip_restore_seed(&w.inner);
        // Engine-register index 1 so the put is accepted (the quote-mint shape).
        let request = crate::derivation::swap_destination_address_request().expect("request");
        {
            let inner = Arc::clone(&w.inner);
            run_blocking(move || {
                let mut guard = inner.db.lock().expect("wallet db mutex poisoned");
                account::mint_swap_destination(&mut guard.db, Network::Test, 1, request)
            })
            .await
            .expect("mint")
            .expect("index 1 conforms");
        }
        let refund_addr =
            crate::derivation::derive_transparent_refund_address(Network::Test, &[0x24; 32], 1)
                .expect("raw refund address");
        let now = test_now_unix();
        {
            let mut aux = w.inner.aux_db.lock().expect("aux mutex");
            // A synthetic backfill twin at index 1 — armed first (a widen/backfill pass),
            // then superseded by the real execute below (the #390 dual-row rule).
            crate::swap_destination_store::mark_executed(
                &mut aux,
                "backfill:1",
                &refund_addr,
                1,
                now + 100_000,
            )
            .expect("arm the synthetic twin");
            // The REAL swap: home row + watch columns + its own detection row.
            crate::swap_record_store::insert_with_watch(
                &mut aux,
                &crate::swap_record_store::InFlightSwap {
                    swap_id: "swap-real".to_owned(),
                    out_of_zec: true,
                    created_at: now - 1_000,
                    deposit_deadline: Some(now - 500),
                    expires_at_wall: now + 100_000,
                    outcome: None,
                },
                now - 1_000,
                "t1swapreal",
                Some((refund_addr.as_str(), 1)),
            )
            .expect("the real swap's row");
        }
        // The refund lands on-chain at the shared receiver.
        let receiver = crate::derivation::transparent_receiver_from_stored_address(
            Network::Test,
            &refund_addr,
        )
        .expect("decodes");
        let mut src = FakeUtxoSource::ok(vec![crate::transparent::TransparentUtxoRecord {
            txid: vec![0x0d; 32],
            index: 0,
            script: script_paying(&receiver),
            value_zat: 45_000,
            height: 281_000,
        }]);
        let out = w
            .refresh_transparent_utxos(&mut src)
            .await
            .expect("refresh");
        assert_eq!(out.put, 1, "the refund UTXO was engine-put once");
        let dupes = src
            .last_addresses
            .iter()
            .filter(|a| **a == refund_addr)
            .count();
        assert_eq!(dupes, 1, "the one surviving row carries its address ONCE");
        assert_eq!(
            src.last_addresses.len(),
            2,
            "index-0 + the one surviving refund address"
        );
        {
            let aux = w.inner.aux_db.lock().expect("aux mutex");
            let active = crate::swap_destination_store::active(&aux, now).expect("active");
            assert_eq!(
                active.len(),
                1,
                "the #390 dual-row rule collapsed the backfill twin at the real execute"
            );
            assert_eq!(
                active[0].swap_id, "swap-real",
                "the surviving row is the REAL swap's, not the synthetic twin"
            );
            assert!(active[0].funded, "the surviving row got the funded credit");
        }
        let rows = w.list_in_flight_swaps().await.expect("list");
        assert_eq!(
            rows.iter()
                .find(|r| r.swap_id == "swap-real")
                .expect("the real row lists")
                .outcome,
            Some(crate::swap_record_store::SwapOutcome::Refunded),
            "the chain pin reached the REAL swap (the only row after the #390 collapse)"
        );
        w.close().await.expect("close");
    }

    #[tokio::test]
    #[cfg(feature = "swap")]
    async fn dismissed_and_retired_records_stop_rearming() {
        // #382 (b)'s two convergence exits, review fold (latch shape since #385):
        // (A) a DISMISSED record leaves the re-arm source, so its watch is never
        // resurrected; (B) a RETIRED leg (funded → emptied = delivered + shielded)
        // latches the record's `watch_served` flag ATOMICALLY with the retire, ending
        // the retire→resurrect churn — the record keeps LISTING unpinned (its outcome
        // is honestly unconfirmed), the poll set shrinks, and the watch COLUMNS
        // survive (the card-visit re-arm heal, #385).
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let (w, _addr, _taddr) = synced_wallet_with_taddr(dir.path(), &vault).await;
        // #387: floor-shape the aux — the hand-built index-1 environment below must
        // not share active() with the restore sweep's synthetic rows.
        strip_restore_seed(&w.inner);
        let request = crate::derivation::swap_destination_address_request().expect("request");
        {
            let inner = Arc::clone(&w.inner);
            run_blocking(move || {
                let mut guard = inner.db.lock().expect("wallet db mutex poisoned");
                account::mint_swap_destination(&mut guard.db, Network::Test, 1, request)
            })
            .await
            .expect("mint")
            .expect("index 1 conforms");
        }
        let watch_addr =
            crate::derivation::derive_transparent_refund_address(Network::Test, &[0x24; 32], 1)
                .expect("raw address");
        let now = test_now_unix();
        let record = |id: &str, out_of_zec: bool| crate::swap_record_store::InFlightSwap {
            swap_id: id.to_owned(),
            out_of_zec,
            created_at: now - 200_000,
            deposit_deadline: Some(now - 190_000),
            expires_at_wall: now - 10_000,
            outcome: None,
        };
        // (A) dismissed: the lapsed unresolved record is removed by the user.
        {
            let mut aux = w.inner.aux_db.lock().expect("aux mutex");
            crate::swap_record_store::insert_with_watch(
                &mut aux,
                &record("swap-gone", true),
                now - 200_000,
                "t1swapgone",
                Some((watch_addr.as_str(), 1)),
            )
            .expect("record A");
        }
        assert!(w.dismiss_swap_record("swap-gone").await.expect("dismiss"));
        let mut empty = FakeUtxoSource::ok(Vec::new());
        w.refresh_transparent_utxos(&mut empty)
            .await
            .expect("pass after dismiss");
        {
            let aux = w.inner.aux_db.lock().expect("aux mutex");
            assert!(
                crate::swap_destination_store::active(&aux, now)
                    .expect("active")
                    .is_empty(),
                "a dismissed record's watch is never resurrected"
            );
        }
        // (B) retired: an IntoZec delivery lands (no chain pin — deliveries are not
        // refunds), is shielded away (polls empty), and the leg must CONVERGE.
        {
            let mut aux = w.inner.aux_db.lock().expect("aux mutex");
            crate::swap_record_store::insert_with_watch(
                &mut aux,
                &record("swap-delivered", false),
                now - 200_000,
                "0xswapdelivered",
                Some((watch_addr.as_str(), 1)),
            )
            .expect("record B");
        }
        let receiver =
            crate::derivation::transparent_receiver_from_stored_address(Network::Test, &watch_addr)
                .expect("decodes");
        let mut funded = FakeUtxoSource::ok(vec![crate::transparent::TransparentUtxoRecord {
            txid: vec![0x0e; 32],
            index: 0,
            script: script_paying(&receiver),
            value_zat: 45_000,
            height: 281_000,
        }]);
        w.refresh_transparent_utxos(&mut funded)
            .await
            .expect("delivery pass");
        let rows = w.list_in_flight_swaps().await.expect("list");
        assert_eq!(
            rows.iter()
                .find(|r| r.swap_id == "swap-delivered")
                .expect("listed")
                .outcome,
            None,
            "an IntoZec delivery never chain-pins (a funded destination is not a refund)"
        );
        // #386: the retire is debounced — drive the full consecutive-empty run. The
        // below-threshold passes also prove the re-arm keeps the funded row (streak
        // intact) rather than churning it.
        for _ in 1..crate::swap_destination_store::RETIRE_AFTER_EMPTY_PASSES {
            w.refresh_transparent_utxos(&mut empty)
                .await
                .expect("below-threshold empty pass");
            let aux = w.inner.aux_db.lock().expect("aux mutex");
            assert!(
                !crate::swap_destination_store::active(&aux, now)
                    .expect("active")
                    .is_empty(),
                "below the debounce threshold the funded leg stays watched"
            );
        }
        w.refresh_transparent_utxos(&mut empty)
            .await
            .expect("shielded-away threshold pass (retires)");
        w.refresh_transparent_utxos(&mut empty)
            .await
            .expect("post-retire pass (must not resurrect)");
        {
            let aux = w.inner.aux_db.lock().expect("aux mutex");
            assert!(
                crate::swap_destination_store::active(&aux, now)
                    .expect("active")
                    .is_empty(),
                "the retired leg is NOT resurrected — the served latch ended the churn"
            );
            assert!(
                crate::swap_record_store::unresolved_watches(&aux)
                    .expect("watches")
                    .is_empty(),
                "the retired record left the re-arm source"
            );
            assert!(
                crate::swap_record_store::watch_of(&aux, "swap-delivered")
                    .expect("watch_of")
                    .is_some(),
                "the watch COLUMNS survive the latch (#385) — the card-visit re-arm heal remains"
            );
        }
        let rows = w.list_in_flight_swaps().await.expect("list");
        assert!(
            rows.iter()
                .any(|r| r.swap_id == "swap-delivered" && r.outcome.is_none()),
            "the record still LISTS honestly unconfirmed — only the watch converged"
        );
        w.close().await.expect("close");
    }

    // ── rescan_from: post-restore recovery at an earlier birthday (ADR-0534) ──────
    //
    // NOTE on note DETECTION: `FakeChain` serves shape-valid but note-FREE blocks (a
    // detectable note needs heavy upstream test-dependency fixtures — the GA-blocking
    // device e2e's job, per the `sync::testing` harness note). So these tests pin the
    // money-safety PROPERTY that `rescan_lowers_birthday_and_finds_older_notes` is
    // about — the scan FLOOR (the imported account birthday) drops to include the older
    // height, so an older note between the new and old birthday is now in scan range —
    // rather than asserting a decoded balance.

    /// Read the imported account's birthday height from the DB (the scan floor). The
    /// account MUST exist (a `provision_account`/`import_account` ran first).
    async fn account_birthday_height(w: &Wallet) -> u32 {
        use zcash_client_backend::data_api::WalletRead;
        let inner = Arc::clone(&w.inner);
        run_blocking(move || {
            let guard = inner.db.lock().expect("wallet db mutex poisoned");
            let id = account::primary_account_id(&guard.db)?.ok_or(WalletError::StoreCorrupt)?;
            let b = guard
                .db
                .get_account_birthday(id)
                .map_err(|_| WalletError::StoreCorrupt)?;
            Ok(u32::from(b))
        })
        .await
        .expect("read account birthday")
    }

    #[tokio::test]
    async fn rescan_lowers_birthday_and_finds_older_notes() {
        // §8 (ADR-0534 headline): provision HIGH (skipping any older note), then
        // `rescan_from(lower)` — the next sync re-imports account 0 at the LOWER birthday
        // through the audited `resolve_birthday`, so the scan floor drops and an older
        // note below the original birthday is now scanned (the funds become findable).
        use crate::sync::testing::FakeChain;
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let w = Wallet::create_with_vault(
            cfg(dir.path(), Network::Test, SeedPersistence::SealedKeychain),
            raw_seed(),
            Arc::clone(&vault),
        )
        .await
        .expect("create");

        // Provision at a HIGH birthday — older notes below it would be skipped.
        let mut chain = FakeChain::to_tip(350_000);
        w.provision_account(&mut chain, Some(BlockHeight::new(320_000)))
            .await
            .expect("provision high");
        let high = account_birthday_height(&w).await;

        // Recover from an EARLIER birthday — no seed re-entry, seals untouched.
        let w = w
            .rescan_from_with_vault(Some(BlockHeight::new(290_000)), Arc::clone(&vault))
            .await
            .expect("rescan to a lower birthday");
        assert!(
            !w.account_exists().await.expect("account_exists"),
            "rescan reset the data DB — the old high-birthday account is gone"
        );
        assert_eq!(
            w.inner.birthday,
            Some(BlockHeight::new(290_000)),
            "the new birthday is retained for the next provision"
        );

        // The next sync re-imports at the LOWER birthday via resolve_birthday.
        let mut chain2 = FakeChain::to_tip(350_000);
        w.provision_account(&mut chain2, w.inner.birthday)
            .await
            .expect("re-provision at the lower birthday");
        let low = account_birthday_height(&w).await;
        assert!(
            low < high,
            "rescan lowered the scan floor ({low} < {high}) — older notes are now in range",
        );
        w.close().await.expect("close");
    }

    #[tokio::test]
    async fn rescan_preserves_sealed_seed_and_addresses() {
        // §8 (ADR-0534): the seed + addresses are byte-identical across a rescan, and the
        // seal artifacts on disk are never mutated (the seed cannot be lost). A GENERATED
        // wallet (so it has a mnemonic to reveal).
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let w = Wallet::create_with_vault(
            cfg(dir.path(), Network::Test, SeedPersistence::SealedKeychain),
            SeedSource::generate(),
            Arc::clone(&vault),
        )
        .await
        .expect("create generated");

        let ua_before = w.current_address().await.expect("ua").encoded().to_owned();
        let taddr_before = w.current_transparent_address().await.expect("taddr before");
        let mnemonic_before: Vec<String> = w
            .reveal_mnemonic()
            .expect("reveal")
            .iter()
            .map(|w| w.as_str().to_owned())
            .collect();
        let seal_path = |name: &str| dir.path().join(name);
        let seed_seal_before =
            std::fs::read(seal_path(crate::constants::SEED_SEAL_FILE_NAME)).expect("seed seal");
        let dbkey_seal_before =
            std::fs::read(seal_path(crate::constants::DBKEY_SEAL_FILE_NAME)).expect("dbkey seal");
        let wrap_before =
            std::fs::read(seal_path(crate::constants::WRAP_ARTIFACT_FILE_NAME)).expect("wrap");

        let w = w
            .rescan_from_with_vault(None, Arc::clone(&vault))
            .await
            .expect("rescan full history");

        assert_eq!(
            w.current_address().await.expect("ua").encoded(),
            ua_before,
            "the default UA is byte-identical after a rescan",
        );
        assert_eq!(
            w.current_transparent_address().await.expect("taddr after"),
            taddr_before,
            "the transparent address is byte-identical after a rescan",
        );
        let mnemonic_after: Vec<String> = w
            .reveal_mnemonic()
            .expect("reveal")
            .iter()
            .map(|w| w.as_str().to_owned())
            .collect();
        assert_eq!(
            mnemonic_after, mnemonic_before,
            "reveal_mnemonic is unchanged across a rescan",
        );
        // the seal artifacts on disk are byte-identical — the vault/seed were never touched
        assert_eq!(
            std::fs::read(seal_path(crate::constants::SEED_SEAL_FILE_NAME)).expect("seed seal"),
            seed_seal_before,
            "the seed seal must never be mutated by a rescan",
        );
        assert_eq!(
            std::fs::read(seal_path(crate::constants::DBKEY_SEAL_FILE_NAME)).expect("dbkey seal"),
            dbkey_seal_before,
        );
        assert_eq!(
            std::fs::read(seal_path(crate::constants::WRAP_ARTIFACT_FILE_NAME)).expect("wrap"),
            wrap_before,
        );
        w.close().await.expect("close");
    }

    #[tokio::test]
    async fn rescan_full_history_equals_activation() {
        // §8 (ADR-0534 / the §2.3 silent-loss guard): `rescan_from(None)` floors to
        // Sapling ACTIVATION via `freshly_generated = false`, NEVER ~tip. Provision HIGH
        // first, then rescan to full history → the re-import lands at activation + 1.
        use crate::sync::testing::FakeChain;
        const TESTNET_ACTIVATION: u32 = 280_000;
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let w = Wallet::create_with_vault(
            cfg(dir.path(), Network::Test, SeedPersistence::SealedKeychain),
            raw_seed(),
            Arc::clone(&vault),
        )
        .await
        .expect("create");

        let mut chain = FakeChain::to_tip(350_000);
        w.provision_account(&mut chain, Some(BlockHeight::new(320_000)))
            .await
            .expect("provision high");

        let w = w
            .rescan_from_with_vault(None, Arc::clone(&vault))
            .await
            .expect("rescan full history");
        assert_eq!(
            w.inner.birthday, None,
            "full-history rescan clears the birthday"
        );
        assert_eq!(
            w.inner.created_at, None,
            "an UNSTAMPED (restore-created) wallet stays unstamped across a \
             rescan — the rebuild must never forge a creation time"
        );

        let mut chain2 = FakeChain::to_tip(350_000);
        w.provision_account(&mut chain2, w.inner.birthday)
            .await
            .expect("re-provision full history");
        assert_eq!(
            account_birthday_height(&w).await,
            TESTNET_ACTIVATION + 1,
            "None floors to Sapling activation (a full scan), NEVER ~tip",
        );
        w.close().await.expect("close");
    }

    #[tokio::test]
    async fn generated_wallet_stamp_survives_reopen_and_bounds_provisioning() {
        // §8 (#356-F4 end-to-end): a Generate-create writes the creation stamp
        // (clamped to THIS binary's bundle-tail time — the write-time
        // clock-ahead cap); the stamp survives close → reopen; and the
        // account-less REOPEN — where `freshly_generated` is unknowable and
        // used to force the activation full scan — provisions
        // bounded-from-creation instead. The offline-create → deposit → late
        // first sync shape, driven across a simulated restart.
        use crate::provision::testing::FakeOracle;
        const TESTNET_ACTIVATION: u32 = 280_000;
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let w = Wallet::create_with_vault(
            cfg(dir.path(), Network::Test, SeedPersistence::SealedKeychain),
            SeedSource::generate(),
            Arc::clone(&vault),
        )
        .await
        .expect("create generated");
        let stamp = w.inner.created_at.expect("a Generate create stamps");
        assert!(
            stamp <= checkpoints::newest_checkpoint_time(Network::Test),
            "the write clamp caps the stamp at this binary's bundle tail"
        );
        w.close().await.expect("close");

        // Reopen BEFORE any sync — the wallet is still account-less and
        // `freshly_generated` re-defaults to the conservative false.
        let w = Wallet::open_with_vault(
            cfg(dir.path(), Network::Test, SeedPersistence::SealedKeychain),
            Arc::clone(&vault),
        )
        .await
        .expect("reopen");
        assert!(!w.inner.freshly_generated, "open defaults conservative");
        assert_eq!(
            w.inner.created_at,
            Some(stamp),
            "the stamp survives the restart"
        );

        // The (late) first sync: the stamp — not activation, not the sync-day
        // tip − lag — bounds the provisioned birthday.
        let mut oracle = FakeOracle::honest(Network::Test, 5_000_000);
        w.provision_account(&mut oracle, None)
            .await
            .expect("provision");
        let estimate = checkpoints::estimate_birthday(Network::Test, stamp).value();
        let got = account_birthday_height(&w).await;
        assert!(
            got > TESTNET_ACTIVATION + 1,
            "a stamped reopen must not fall to the activation full scan (got {got})"
        );
        assert!(
            got <= estimate + 1,
            "…and never lands above the creation estimate (got {got}, estimate {estimate})"
        );
        w.close().await.expect("close");
    }

    #[tokio::test]
    async fn rescan_preserves_the_creation_stamp_and_floor() {
        // §8 (#356-F4 × ADR-0534): the creation stamp RIDES the rescan rebuild
        // (its aux table is preserved and — unlike the sync stamp — its row is
        // NOT cleared), so a full-history `rescan_from(None)` of a GENERATED
        // wallet re-provisions at the bounded-from-creation floor: nothing can
        // predate the seed. The stamp-less sibling
        // (`rescan_full_history_equals_activation`) pins the restore
        // contract's activation floor — this is the deliberate contrast.
        use crate::provision::testing::FakeOracle;
        const TESTNET_ACTIVATION: u32 = 280_000;
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let w = Wallet::create_with_vault(
            cfg(dir.path(), Network::Test, SeedPersistence::SealedKeychain),
            SeedSource::generate(),
            Arc::clone(&vault),
        )
        .await
        .expect("create generated");
        let stamp = w.inner.created_at.expect("stamped");

        let mut chain = FakeOracle::honest(Network::Test, 5_000_000);
        w.provision_account(&mut chain, None)
            .await
            .expect("provision");

        let w = w
            .rescan_from_with_vault(None, Arc::clone(&vault))
            .await
            .expect("rescan full history");
        assert_eq!(
            w.inner.created_at,
            Some(stamp),
            "the creation stamp survives the rescan rebuild uncleared"
        );

        let mut chain2 = FakeOracle::honest(Network::Test, 5_000_000);
        w.provision_account(&mut chain2, w.inner.birthday)
            .await
            .expect("re-provision");
        assert!(
            account_birthday_height(&w).await > TESTNET_ACTIVATION + 1,
            "a generated wallet's full-history rescan re-floors at ~creation, not activation"
        );
        w.close().await.expect("close");
    }

    #[tokio::test]
    async fn rescan_none_persistence_is_seed_required() {
        // §8 (ADR-0534): a None-persistence wallet holds no seed at rest AND this one
        // has no seed port attached (`create_with_vault`, never `open_with_seed_port`),
        // so nothing can serve the re-import — rescan is rejected typed `SeedRequired`
        // up front. Since FR-43 the gate is "no seed SOURCE", not "no seed at rest":
        // the same wallet WITH a port rebuilds and re-imports through it. The seals +
        // DB are untouched (the rejected handle is gone, but the wallet re-opens).
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let w = Wallet::create_with_vault(
            cfg(dir.path(), Network::Test, SeedPersistence::None),
            raw_seed(),
            Arc::clone(&vault),
        )
        .await
        .expect("create none-persistence");

        match w.rescan_from_with_vault(None, Arc::clone(&vault)).await {
            Err(WalletError::SeedRequired) => {}
            Err(other) => panic!(
                "expected SeedRequired for a None-persistence wallet, got {}",
                other.code()
            ),
            Ok(_) => panic!("a None-persistence rescan must be rejected, not succeed"),
        }
        // the rejected rescan left the store intact — the wallet still opens
        let w2 = Wallet::open_with_vault(
            cfg(dir.path(), Network::Test, SeedPersistence::None),
            Arc::clone(&vault),
        )
        .await
        .expect("re-open after a rejected rescan (the store was untouched)");
        w2.close().await.expect("close");
    }

    #[tokio::test]
    async fn rescan_birthday_in_future_is_rejected_at_provision() {
        // §8 (ADR-0534): a birthday above the endpoint tip surfaces `BirthdayInFuture` — but
        // at the NEXT PROVISION, not in `rescan_from` itself, which does NO network I/O (it
        // just stores the height). The tip clamp is owned by `resolve_birthday`, so the name
        // pins WHERE the rejection happens (a stored future height is inert until sync).
        use crate::sync::testing::FakeChain;
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let w = Wallet::create_with_vault(
            cfg(dir.path(), Network::Test, SeedPersistence::SealedKeychain),
            raw_seed(),
            Arc::clone(&vault),
        )
        .await
        .expect("create");

        // Rescan stores a FUTURE birthday (no network call here) — above the
        // bundle's newest row, since T0-1c-R2 M3 clamps a below-row tip up to the
        // row and a birthday at or below it is never "in the future" …
        let row = crate::root_bind::newest_bundled_height(Network::Test);
        let w = w
            .rescan_from_with_vault(Some(BlockHeight::new(row + 50_000)), Arc::clone(&vault))
            .await
            .expect("rescan records the requested height");
        // … and the next sync's resolve_birthday rejects it against a tip above
        // the row but below the birthday.
        let mut chain = FakeChain::to_tip(u64::from(row) + 10_000);
        match w.provision_account(&mut chain, w.inner.birthday).await {
            Err(WalletError::BirthdayInFuture) => {}
            other => panic!("expected BirthdayInFuture for a height above the tip, got {other:?}"),
        }
        w.close().await.expect("close");
    }

    #[tokio::test]
    async fn rescan_preserves_pending_queued_sends_and_swap_state() {
        // §8 (ADR-0534 money-safety): a queued-send intent, the never-recycle refund
        // counter, and an issued-quote row (and, in a swap build, a swap_destination row)
        // all SURVIVE the rescan — the durable aux money state is not scan-derived, so it
        // is copied across the rebuild, never lost.
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let w = Wallet::create_with_vault(
            cfg(dir.path(), Network::Test, SeedPersistence::SealedKeychain),
            raw_seed(),
            Arc::clone(&vault),
        )
        .await
        .expect("create");
        // #387: floor-shape the aux — the cross-rescan reserve continuity below is
        // floor-based (see strip_restore_seed).
        strip_restore_seed(&w.inner);

        let id = w
            .queue_send(one_payment(Some(100_000)))
            .await
            .expect("queue");
        {
            let mut aux = w.inner.aux_db.lock().expect("aux db");
            assert_eq!(
                crate::refund_index::reserve_next_index(&mut aux).expect("reserve"),
                1,
                "first refund index is the floor",
            );
            // A LEGITIMATELY-CLAMPED live deadline (real now + 1 h — inside the 24 h
            // persist ceiling), so the row rides the rescan AND survives the reopened
            // wallet's open-time far-future sweep (W-swap-4-a-4) — a fixed far-future
            // constant here would be exactly the pre-clamp shape the sweep retires.
            let live_deadline = std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .map_or(0, |d| i64::try_from(d.as_secs()).unwrap_or(i64::MAX))
                .saturating_add(3_600);
            let quote = crate::issued_quote_store::StoredQuote {
                refund_address: None,
                refund_index: None,
                id: "q-keep".into(),
                deposit_address: Some("t1frozen".into()),
                deposit_amount_zat: Some(100_000),
                expires_at_wall: live_deadline,
                destination_address: None,
                destination_index: None,
                binding: None,
                provider_ref: Some("t1frozen".into()),
                term_deposit_address: Some("t1frozen".into()),
                term_deposit_memo: None,
                term_amount_in: Some("1.0".into()),
                term_min_amount_out: Some("41.5".into()),
                term_zec_side_zat: Some(100_000),
                term_refund_to: None,
                term_expires_at: Some(live_deadline),
            };
            crate::issued_quote_store::persist(&mut aux, &quote, 16, 1_700_000_000)
                .expect("persist issued quote");
            #[cfg(feature = "swap")]
            crate::swap_destination_store::upsert_quoted(
                &mut aux,
                "s-keep",
                "utest1dest",
                7,
                2_000_000_000,
            )
            .expect("upsert swap destination");
        }

        let w = w
            .rescan_from_with_vault(None, Arc::clone(&vault))
            .await
            .expect("rescan");

        {
            let aux = w.inner.aux_db.lock().expect("aux db");
            let queued = crate::intent_store::list_queued(&aux).expect("list");
            assert_eq!(queued.len(), 1, "the queued send survived the rescan");
            assert_eq!(queued[0].id, id, "same intent id (re-proposable by id)");
            assert_eq!(
                crate::issued_quote_store::count(&aux).expect("count"),
                1,
                "the in-flight issued quote survived the rescan",
            );
            #[cfg(feature = "swap")]
            assert_eq!(
                crate::swap_destination_store::count(&aux).expect("count"),
                1,
                "the swap destination detection row survived the rescan",
            );
        }
        {
            let mut aux = w.inner.aux_db.lock().expect("aux db");
            assert_eq!(
                crate::refund_index::reserve_next_index(&mut aux).expect("reserve"),
                2,
                "the refund counter survived — the next reserve is 2, never a recycled 1",
            );
        }
        w.close().await.expect("close");
    }

    #[tokio::test]
    async fn open_frees_capacity_held_by_pre_clamp_rows() {
        // §8 (W-swap-4-a-4 (2)): pre-clamp far-future issued-quote rows (the live ~72 h
        // provider echoes an OLDER build persisted un-clamped) stay executable and hold
        // `MAX_ISSUED_QUOTES` capacity for days — a wipe-only swap brick at 16. The
        // OPEN-TIME sweep frees them on the next launch, before any quote is attempted.
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let w = Wallet::create_with_vault(
            cfg(dir.path(), Network::Test, SeedPersistence::SealedKeychain),
            raw_seed(),
            Arc::clone(&vault),
        )
        .await
        .expect("create");

        // ~72 h out relative to the REAL clock the open-time sweep reads — beyond the
        // 24 h legitimacy ceiling no post-clamp build can write past.
        let far_future = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map_or(0, |d| i64::try_from(d.as_secs()).unwrap_or(i64::MAX))
            .saturating_add(259_200);
        {
            let mut aux = w.inner.aux_db.lock().expect("aux db");
            for i in 0..crate::constants::MAX_ISSUED_QUOTES {
                let quote = crate::issued_quote_store::StoredQuote {
                    refund_address: None,
                    refund_index: None,
                    id: format!("q-pre-{i}"),
                    deposit_address: Some("t1frozen".into()),
                    deposit_amount_zat: Some(100_000),
                    expires_at_wall: far_future,
                    destination_address: None,
                    destination_index: None,
                    binding: None,
                    provider_ref: Some("t1frozen".into()),
                    term_deposit_address: Some("t1frozen".into()),
                    term_deposit_memo: None,
                    term_amount_in: Some("1.0".into()),
                    term_min_amount_out: Some("41.5".into()),
                    term_zec_side_zat: Some(100_000),
                    term_refund_to: None,
                    term_expires_at: Some(far_future),
                };
                // `now = 0` (below the plausibility floor) disables the store's
                // far-future arm — exactly how an un-clamped pre-upgrade persist
                // landed these rows in the first place.
                crate::issued_quote_store::persist(
                    &mut aux,
                    &quote,
                    crate::constants::MAX_ISSUED_QUOTES,
                    0,
                )
                .expect("fabricate a pre-clamp row");
            }
            assert_eq!(
                crate::issued_quote_store::count(&aux).expect("count"),
                crate::constants::MAX_ISSUED_QUOTES,
                "the brick shape: capacity fully held by far-future rows",
            );
        }
        w.close().await.expect("close");

        let w = Wallet::open_with_vault(
            cfg(dir.path(), Network::Test, SeedPersistence::SealedKeychain),
            Arc::clone(&vault),
        )
        .await
        .expect("reopen");
        {
            let aux = w.inner.aux_db.lock().expect("aux db");
            assert_eq!(
                crate::issued_quote_store::count(&aux).expect("count"),
                0,
                "the open-time sweep freed every pre-clamp far-future row",
            );
        }
        w.close().await.expect("close");
    }

    #[tokio::test]
    async fn rescan_stops_sync_first_no_torn_scan() {
        // §8 (ADR-0534): rescan stops + joins the sync loop BEFORE rebuilding, then
        // replaces the data DB by ONE atomic rename — so a prior sync's scan state can
        // never leak torn into the rebuilt DB. Drive a REAL `sync_once` (populating scan
        // ranges + the block cache) before the rescan; the rebuilt wallet then has NO
        // account/scan-state and syncs cleanly at the new birthday. (The live background
        // stop+join is structural — `sync.stop().await` precedes any reset — and exercised
        // on-device; the unit harness drives `sync_once` directly, no background loop.)
        use crate::sync::CancelToken;
        use crate::sync::testing::FakeChain;
        // SMALL scan ranges (tip just above the activation-anchored birthday, ~1000
        // blocks — the existing sync-test scale) so the REAL scanner runs fast; the
        // no-torn-scan property is about the atomic rebuild, not the scan depth.
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let w = Wallet::create_with_vault(
            cfg(dir.path(), Network::Test, SeedPersistence::SealedKeychain),
            raw_seed(),
            Arc::clone(&vault),
        )
        .await
        .expect("create");

        let mut chain = FakeChain::to_tip(281_000);
        let cancel = CancelToken::new();
        // Provision near activation (frontier 280_000 ⇒ birthday 280_001) and run a REAL
        // scan pass — this populates scan ranges + the block cache (the torn-scan surface).
        w.provision_account(&mut chain, Some(BlockHeight::new(280_500)))
            .await
            .expect("provision near activation");
        w.sync_once(&mut chain, &cancel, NOOP_PROGRESS)
            .await
            .expect("a real scan pass populates scan ranges + the cache");
        assert!(
            w.account_exists().await.expect("exists"),
            "account present pre-rescan"
        );

        let w = w
            .rescan_from_with_vault(None, Arc::clone(&vault))
            .await
            .expect("rescan");
        assert!(
            !w.account_exists().await.expect("exists"),
            "the atomic rebuild dropped the account + all scan state cleanly (no torn read)",
        );

        // The rebuilt wallet syncs cleanly at the new (activation) birthday.
        let mut chain2 = FakeChain::to_tip(281_000);
        w.provision_account(&mut chain2, w.inner.birthday)
            .await
            .expect("re-provision after the clean rescan");
        w.sync_once(&mut chain2, &cancel, NOOP_PROGRESS)
            .await
            .expect("the rebuilt wallet scans cleanly at the new birthday");
        assert_eq!(
            account_birthday_height(&w).await,
            280_001,
            "re-imported at activation after the clean rescan",
        );
        w.close().await.expect("close");
    }

    #[tokio::test]
    async fn rescan_drains_a_transient_blocking_ref_instead_of_failing_busy() {
        // v-5c DEVICE-PROOF FINDING #2 — the intermittent `WalletAlreadyOpen` race. On
        // the device, a rescan triggered while a scan-batch was mid-flight failed 3×:
        // the pass's cancel race DROPS the engine future, DETACHING its in-flight
        // `spawn_blocking` section, whose closure still holds a strong `Arc<Inner>` —
        // so the old one-shot `try_unwrap` bailed `WalletBusy`, the straggler kept the
        // flock alive past the FFI's handle-out, and the host's recover-by-reopen
        // collided. Simulate the orphan EXACTLY as it manifests (a strong ref that
        // outlives `sync.stop().await` and drops when its bounded work completes) and
        // prove the rescan now QUIESCES — waits the straggler out — instead of failing.
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let w = Wallet::create_with_vault(
            cfg(dir.path(), Network::Test, SeedPersistence::SealedKeychain),
            raw_seed(),
            Arc::clone(&vault),
        )
        .await
        .expect("create");

        // The orphaned pass-blocking section: holds `Arc<Inner>` for ~150ms of "DB
        // work" on a real OS thread (like the detached `spawn_blocking`), then drops.
        let straggler = Arc::clone(&w.inner);
        let orphan = std::thread::spawn(move || {
            std::thread::sleep(std::time::Duration::from_millis(150));
            drop(straggler);
        });

        let w = w
            .rescan_from_with_vault(None, Arc::clone(&vault))
            .await
            .expect("the drain waits out the transient ref (pre-fix: instant WalletBusy)");
        orphan.join().expect("orphan thread");
        w.close().await.expect("close");
    }

    #[tokio::test]
    async fn close_quiesces_a_transient_blocking_ref_before_releasing_the_lock() {
        // The close() half of the v-5c finding #2 hardening: `sync.stop().await` joins
        // the LOOP but a cancel-orphaned `spawn_blocking` section can outlive it still
        // holding `Arc<Inner>` — so an un-quiesced close could return with the flock
        // alive, and a prompt close→open (any SDK consumer — most have no retrying
        // opener) would hit `WalletAlreadyOpen`. Simulate the straggler, close, and
        // prove the very next open succeeds — the stated db-closed-before-lock-freed
        // contract holds.
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let w = Wallet::create_with_vault(
            cfg(dir.path(), Network::Test, SeedPersistence::SealedKeychain),
            raw_seed(),
            Arc::clone(&vault),
        )
        .await
        .expect("create");

        let straggler = Arc::clone(&w.inner);
        let orphan = std::thread::spawn(move || {
            std::thread::sleep(std::time::Duration::from_millis(150));
            drop(straggler);
        });

        w.close().await.expect("close");
        // Immediately re-open — pre-quiesce this raced the straggler's held flock.
        let reopened = Wallet::open_with_vault(
            cfg(dir.path(), Network::Test, SeedPersistence::SealedKeychain),
            Arc::clone(&vault),
        )
        .await
        .expect("a prompt close→open never observes the straggler's lock");
        orphan.join().expect("orphan thread");
        reopened.close().await.expect("close reopened");
    }

    #[tokio::test(start_paused = true)]
    async fn rescan_quiesce_is_bounded_a_wedged_ref_fails_typed() {
        // The drain must stay BOUNDED: a ref that NEVER drops (a genuine leak/bug, not
        // the transient cancel-race) fails typed `WalletBusy` — never an FFI hang.
        // Paused tokio time auto-advances the drain's sleeps, so the wall-clock bound
        // elapses in virtual time and the test stays fast. After the typed failure the
        // seals/DB are untouched and, once the wedge releases, a plain re-open recovers
        // — the exact contract the host's recover-by-reopen (with its lock-release
        // retry) rides.
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let w = Wallet::create_with_vault(
            cfg(dir.path(), Network::Test, SeedPersistence::SealedKeychain),
            raw_seed(),
            Arc::clone(&vault),
        )
        .await
        .expect("create");

        let wedge = Arc::clone(&w.inner); // held across the whole drain — never drops
        // (`match`, not `expect_err` — `Wallet` deliberately implements no `Debug`.)
        let err = match w.rescan_from_with_vault(None, Arc::clone(&vault)).await {
            Ok(_) => panic!("a wedged ref must fail typed, never succeed"),
            Err(e) => e,
        };
        assert!(
            matches!(err, WalletError::WalletBusy { .. }),
            "typed WalletBusy (the FFI-safe failure), got {err:?}",
        );

        // Release the wedge ⇒ `Inner` drops ⇒ the flock frees ⇒ the host's
        // recover-by-reopen path succeeds against untouched seals + data DB.
        drop(wedge);
        let reopened = Wallet::open_with_vault(
            cfg(dir.path(), Network::Test, SeedPersistence::SealedKeychain),
            Arc::clone(&vault),
        )
        .await
        .expect("re-open recovers once the lingering ref releases");
        reopened.close().await.expect("close");
    }

    #[tokio::test(start_paused = true)]
    async fn close_quiesce_is_bounded_a_wedged_ref_returns_ok_and_frees_on_release() {
        // The close() twin of the rescan bound: close never fails and never hangs.
        // A ref that never drops runs the drain to its full QUIESCE_MAX; close then
        // returns Ok with the lock still held by the wedge (the documented residual,
        // logged as `wallet.close_quiesce_expired`), and the lock frees the moment the
        // wedge drops. Paused time auto-advances the drain's sleeps.
        let dir = tempfile::tempdir().expect("tempdir");
        let w = Wallet::create_with_vault(
            cfg(dir.path(), Network::Test, SeedPersistence::SealedKeychain),
            raw_seed(),
            test_vault(),
        )
        .await
        .expect("create");

        let wedge = Arc::clone(&w.inner); // held across the whole drain — never drops
        let started = tokio::time::Instant::now();
        w.close().await.expect("a wedged ref must not fail close");
        assert!(
            started.elapsed() >= Wallet::QUIESCE_MAX,
            "close gave up before its bound: {:?}",
            started.elapsed(),
        );
        assert!(
            matches!(
                WalletLock::acquire(dir.path()),
                Err(WalletError::WalletAlreadyOpen)
            ),
            "the wedge still holds the lock after close — the residual, never a silent free",
        );
        drop(wedge);
        WalletLock::acquire(dir.path()).expect("the lock frees the moment the wedge drops");
    }

    #[tokio::test]
    async fn rescan_emits_a_device_visible_event_with_outcome() {
        // device re-proof observability finding: the `wallet.rescan` SPAN alone
        // is INVISIBLE through the Android tracing bridge (events print; span closures
        // never do) — the device log carried no trace of a rescan at all, success or
        // failure. The span stays (test/structured consumers); this pins its
        // device-visible EVENT twin: a completed rescan emits `wallet.rescan` with the
        // same §5.4-minimal payload (bare from-height + payload-free outcome code).
        // The `message` field is the discriminator — the capture layer records span
        // fields too, but only an EVENT carries `message = "wallet.rescan"`.
        use crate::tracing_guard::{CaptureLayer, CapturedEvents};
        use tracing_subscriber::prelude::*;
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let w = Wallet::create_with_vault(
            cfg(dir.path(), Network::Test, SeedPersistence::SealedKeychain),
            raw_seed(),
            Arc::clone(&vault),
        )
        .await
        .expect("create");

        crate::tracing_guard::force_wallet_callsites_enabled();
        let sink = CapturedEvents::default();
        let subscriber = tracing_subscriber::registry().with(CaptureLayer::new(sink.clone()));
        let _guard = tracing::subscriber::set_default(subscriber);

        let w = w
            .rescan_from_with_vault(None, Arc::clone(&vault))
            .await
            .expect("rescan");
        let fields = sink.fields();
        assert!(
            fields
                .iter()
                .any(|(n, v)| n == "message" && v == "wallet.rescan"),
            "the wallet.rescan EVENT fired (the span alone never reaches a device log): {fields:?}",
        );
        assert!(
            fields.iter().any(|(n, v)| n == "outcome" && v == "ok"),
            "the event carries the payload-free outcome: {fields:?}",
        );
        crate::tracing_guard::assert_5_4_clean(&fields);
        w.close().await.expect("close");
    }

    #[tokio::test]
    async fn rescan_twice_lowers_progressively_and_preserves_aux() {
        // §8 (ADR-0534): the rescan is RE-RUNNABLE, not a one-shot. Two sequential rescans
        // each lower the floor, and the durable aux money state survives BOTH rebuilds — so
        // a user who narrows, then realizes their funds are older still, can keep going
        // earlier without ever losing the queued send / never-recycle refund counter.
        use crate::sync::testing::FakeChain;
        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let w = Wallet::create_with_vault(
            cfg(dir.path(), Network::Test, SeedPersistence::SealedKeychain),
            raw_seed(),
            Arc::clone(&vault),
        )
        .await
        .expect("create");
        // #387: floor-shape the aux — the double-rescan reserve continuity below is
        // floor-based (see strip_restore_seed).
        strip_restore_seed(&w.inner);

        // A durable aux row + refund reservation to track across BOTH rebuilds.
        let id = w
            .queue_send(one_payment(Some(100_000)))
            .await
            .expect("queue");
        {
            let mut aux = w.inner.aux_db.lock().expect("aux db");
            assert_eq!(
                crate::refund_index::reserve_next_index(&mut aux).expect("reserve"),
                1,
                "first refund index is the floor"
            );
        }

        // Provision HIGH, then rescan to a middle birthday, then to an even lower one.
        let mut chain = FakeChain::to_tip(350_000);
        w.provision_account(&mut chain, Some(BlockHeight::new(320_000)))
            .await
            .expect("provision high");
        let high = account_birthday_height(&w).await;

        let w = w
            .rescan_from_with_vault(Some(BlockHeight::new(300_000)), Arc::clone(&vault))
            .await
            .expect("rescan #1 (narrower)");
        let mut chain = FakeChain::to_tip(350_000);
        w.provision_account(&mut chain, w.inner.birthday)
            .await
            .expect("re-provision mid");
        let mid = account_birthday_height(&w).await;

        let w = w
            .rescan_from_with_vault(Some(BlockHeight::new(290_000)), Arc::clone(&vault))
            .await
            .expect("rescan #2 (earlier still)");
        let mut chain = FakeChain::to_tip(350_000);
        w.provision_account(&mut chain, w.inner.birthday)
            .await
            .expect("re-provision low");
        let low = account_birthday_height(&w).await;

        // Each rebuild moved the floor monotonically down (non-strict for the middle step,
        // so checkpoint rounding can't flake; strict across the two extremes).
        assert!(
            low <= mid && mid <= high && low < high,
            "two rescans lowered the scan floor progressively ({low} ≤ {mid} ≤ {high})",
        );

        // The durable aux survived BOTH rebuilds.
        {
            let aux = w.inner.aux_db.lock().expect("aux db");
            let queued = crate::intent_store::list_queued(&aux).expect("list");
            assert_eq!(queued.len(), 1, "the queued send survived two rescans");
            assert_eq!(queued[0].id, id, "same intent id after two rescans");
        }
        {
            let mut aux = w.inner.aux_db.lock().expect("aux db");
            assert_eq!(
                crate::refund_index::reserve_next_index(&mut aux).expect("reserve"),
                2,
                "the refund counter survived two rescans — never recycled to 1",
            );
        }
        w.close().await.expect("close");
    }

