    // ── RED BY RULING — the 2026-09-20 production-readiness review ────
    // `docs/plan/audit-2026-09-20-remediation.md` §2a: the bodies are the
    // review's probes (`docs/reviews/2026-09-20/probes/wallet.rs`), verbatim;
    // the names are this project's; `evals/standing_reds.txt` carries both.
    // Appended BELOW the child module so no cited line above moves. Each turns
    // green with exactly one fix: R04 with a stable custody identifier (§2c,
    // S2's subject); R02 with the durable rebroadcast obligation (§2b — the
    // maintainer's stage-order call).

    /// R04 — `keychain_namespace_for` derives the seal's keychain namespace
    /// from the ABSOLUTE `db_dir`, so relocating the container (an app update
    /// moving its sandbox, a scoped-storage move) opens as
    /// `KeystoreInconsistent`, while the same files under the ORIGINAL
    /// namespace open fine — the positive control that proves the DB, the seal
    /// and the custody key all survived the move.
    #[tokio::test]
    async fn a_relocated_wallet_directory_keeps_its_custody_identity() {
        let parent = tempfile::tempdir().unwrap();
        let a = parent.path().join("container-a/wallet");
        let b = parent.path().join("container-b/wallet");
        std::fs::create_dir_all(&a).unwrap();
        std::fs::create_dir_all(b.parent().unwrap()).unwrap();
        // S2 fold (the probe's PRECONDITION, pre-ruled — stage plan §3.1 row 1):
        // the review's body built one pre-built vault per PATH namespace
        // (`mk(keychain_namespace_for(&a|&b))`), the base tree's shape where the
        // path IS the custody. Under S2 the wallet asks for the namespace its
        // wrap artifact's header names, so the create, the relocated open and
        // the positive control all resolve per namespace over the same shared
        // keychain — the platform resolver's shape. The claim below is unmoved.
        struct PerNamespace(crate::keychain::testvault::SharedKeychain);
        impl VaultResolver for PerNamespace {
            fn vault_for<'a>(
                &'a self,
                namespace: &KeychainNamespace,
            ) -> Result<crate::keychain::ResolvedVault<'a>, WalletError> {
                Ok(crate::keychain::ResolvedVault::Owned(Arc::new(
                    SharedKeychainVault::new(VaultTier::Tee, namespace.as_str(), self.0.clone()),
                )))
            }
        }
        let keychain = SharedKeychainVault::shared();
        let resolver = || -> Arc<dyn VaultResolver> { Arc::new(PerNamespace(keychain.clone())) };
        let wallet = Wallet::create_resolving(
            cfg(&a, Network::Test, SeedPersistence::SealedKeychain),
            raw_seed(),
            resolver(),
        )
        .await
        .expect("create synthetic wallet");
        wallet.close().await.unwrap();
        std::fs::rename(&a, &b).unwrap();
        let relocated_error = Wallet::open_resolving(
            cfg(&b, Network::Test, SeedPersistence::SealedKeychain),
            resolver(),
            None,
            None,
        )
        .await
        .err();
        // Positive control proves the DB, seed seal, and custody key survived
        // the move — a second open at the new path, after the first wrote its
        // index there.
        let control = Wallet::open_resolving(
            cfg(&b, Network::Test, SeedPersistence::SealedKeychain),
            resolver(),
            None,
            None,
        )
        .await
        .expect("unchanged custody identity opens relocated files");
        control.close().await.unwrap();
        assert!(
            relocated_error.is_none(),
            "relocation must not change custody identity; got {relocated_error:?}"
        );
    }

    /// R02 — a signed transaction the wallet PERSISTED is never enrolled for
    /// retry: `resubmit_queued_sends` reads the intent stores, an ordinary send
    /// writes neither, and the UI maps every non-success of the ordinary path
    /// to "saved for retry" (`send_state.dart`). Persisting the bytes is not a
    /// delivery obligation today; §2b's R02 makes it one.
    #[tokio::test]
    async fn a_persisted_signed_send_is_retried_after_reopen_as_the_ui_promises() {
        use crate::config::TorRuntime;
        use crate::ports::testing::FailingDialer;
        use crate::test_support::HistoryHarness;
        use zcash_address::{ToAddress, ZcashAddress};
        use zcash_protocol::consensus::NetworkType;

        let mut donor = HistoryHarness::new();
        donor.mine_received(100_000);
        donor.mine_empty(10);
        donor.scan();
        let recipient = ZcashAddress::from_transparent_p2pkh(NetworkType::Regtest, [0x71; 20]);
        let txid = donor.create_send(recipient, 20_000);
        let (raw, expiry, observed, created): (Vec<u8>, u32, u32, Option<String>) = donor
            .read_conn()
            .query_row(
                "SELECT raw, expiry_height, min_observed_height, created FROM transactions WHERE txid = ?1",
                rusqlite::params![txid.as_ref()],
                |r| Ok((r.get(0)?, r.get(1)?, r.get(2)?, r.get(3)?)),
            )
            .unwrap();
        assert!(!raw.is_empty());
        assert!(created.is_some(), "wallet-created signed transaction");
        let dir = tempfile::tempdir().unwrap();
        let vault = test_vault();
        let config = || {
            let mut c = cfg(dir.path(), Network::Test, SeedPersistence::SealedKeychain);
            c.tor = TorPolicy::Required {
                runtime: TorRuntime::Dialer(Arc::new(FailingDialer)),
            };
            c
        };
        let w = Wallet::create_with_vault(config(), raw_seed(), vault.clone())
            .await
            .unwrap();
        {
            let aux = w.inner.aux_db.lock().unwrap();
            aux.execute(
                "INSERT INTO transactions (txid, raw, expiry_height, min_observed_height, created) VALUES (?1, ?2, ?3, ?4, ?5)",
                rusqlite::params![txid.as_ref(), raw, expiry, observed, created],
            )
            .unwrap();
            assert!(
                crate::intent_store::list_in_flight(&aux)
                    .unwrap()
                    .is_empty()
            );
            assert!(crate::intent_store::list_queued(&aux).unwrap().is_empty());
        }
        assert_eq!(w.raw_tx_bytes(txid).await.unwrap(), raw);
        let initial = w.broadcast_persisted(vec![txid]).await.unwrap();
        assert!(matches!(
            initial.as_slice(),
            [TxSubmitResult::GrpcFailure { .. }]
        ));
        w.close().await.unwrap();
        let w = Wallet::open_with_vault(config(), vault.clone())
            .await
            .unwrap();
        w.seed_current_consensus_for_test();
        assert_eq!(w.raw_tx_bytes(txid).await.unwrap(), raw);
        let before = w.dial_counts();
        let retry = w
            .resubmit_queued_sends(&sync::CancelToken::new())
            .await
            .unwrap();
        let after = w.dial_counts();
        w.close().await.unwrap();
        // The clause this replaces — `assert_eq!(before, after, "counterexample:
        // zero retry dials")` — asserted the DEFECT's witness, so no fix that
        // broadcasts could turn the probe green (stage S8 `obligation`
        // adjudication, ruling.md §4). The retry dials the private path once;
        // byte-equality of the retried bytes is row 1's, asserted on the loopback
        // endpoint by `delivery_obligation.rs`'s rows 2(i)/(ii).
        assert_eq!(
            after.private.unreachable,
            before.private.unreachable + 1,
            "the retry dialed the private path once"
        );
        assert_eq!(
            retry.attempted, 1,
            "persisted transaction was never selected for retry"
        );
    }

