    /// S7 C2: the two ALLOCATION paths burn the default UA's diversifier index. Seed
    /// `[0x00; 32]` has `d0 = 1` (pinned by `account::tests::a_swap_destination_never_
    /// takes_the_default_address_index`), and a fresh counter reserves 1 first — so a
    /// destination and a refund each land on index 2, never on `d0`.
    #[tokio::test]
    #[cfg(feature = "swap")]
    async fn a_quote_never_allocates_the_default_address_index() {
        async fn d0_wallet(dir: &std::path::Path) -> Wallet {
            let w = Wallet::create_with_vault(
                cfg(dir, Network::Test, SeedPersistence::SealedKeychain),
                SeedSource::raw_bytes(vec![0x00; 32]).expect("valid seed"),
                test_vault(),
            )
            .await
            .expect("create");
            w.import_account(chain_birthday()).await.expect("import");
            // the freshly-generated shape: counter absent, so the first reserve is 1
            strip_restore_seed(&w.inner);
            w
        }
        let dir = tempfile::tempdir().expect("tempdir");
        let w = d0_wallet(dir.path()).await;
        let (_, index) = fresh_destination_address_blocking(&w.inner).expect("destination");
        assert_eq!(index, 2, "the destination skipped d0 = 1");
        w.close().await.expect("close");

        let dir = tempfile::tempdir().expect("tempdir");
        let w = d0_wallet(dir.path()).await;
        let (_, index) = fresh_refund_address_blocking(&w.inner).expect("refund");
        assert_eq!(index, 2, "the refund skipped d0 = 1");
        w.close().await.expect("close");
    }

    /// S15-F1 phase A: `sync_once` times the tip fetch and the root ingestion
    /// apart, so a pass's pre-batch time has names. The fake serves each of the
    /// three pools' root streams after a 30 ms pause, so the roots phase is at
    /// least 90 ms, and answers the tip after the same pause: a field never
    /// assigned reads 0 and fails here.
    #[tokio::test]
    async fn sync_once_reports_the_tip_and_roots_phases() {
        use crate::sync::CancelToken;
        use crate::sync::testing::FakeChain;
        const PAUSE_MS: u64 = 30;

        let dir = tempfile::tempdir().expect("tempdir");
        let vault = test_vault();
        let w = wallet_with_chain_account(dir.path(), &vault).await;
        let mut client = FakeChain::to_tip(u64::from(FIX_TIP));
        client.roots_delay = Some(std::time::Duration::from_millis(PAUSE_MS));
        client.tip_delay = Some(std::time::Duration::from_millis(PAUSE_MS));
        let cancel = CancelToken::new();
        let pass = w
            .sync_once(&mut client, &cancel, NOOP_PROGRESS)
            .await
            .expect("sync");
        let pools = u64::try_from(sync::SUBTREE_ROOT_POOLS.len()).expect("small");
        assert!(
            pass.roots_ms >= PAUSE_MS * pools,
            "roots_ms covers every pool's root stream: got {} ms",
            pass.roots_ms
        );
        assert!(
            pass.tip_ms >= PAUSE_MS,
            "tip_ms covers the tip fetch: got {} ms",
            pass.tip_ms
        );
        assert!(
            pass.wall_ms
                >= pass.tip_ms
                    + pass.roots_ms
                    + pass.anchor_ms
                    + pass.dl_ms
                    + pass.scan_ms
                    + pass.snap_ms,
            "the pass wall-clock covers the tip, the roots and the batches: wall {} vs \
             tip {} + roots {} + batches",
            pass.wall_ms,
            pass.tip_ms,
            pass.roots_ms
        );
        w.close().await.expect("close");
    }

